  str_item_intro_3420136 = "Choose an Aurorian from the following 5-star Aurorian list to fight beside you: <color=#ffffff>Dawn, Bonacie, Allura, Pittman, Lola, Rouge, Momo&Anzu, May, Rainbow, Sadie, Brandy, Liqing, Matthieu, Anatoli, Jakine, Bopper, No. 33, Vergil</color>.",
  str_item_3420137 = "3-Year Recruitment Kit",
  str_item_intro_3420137 = [[
Choose an Aurorian from the following 6-star Aurorian list to fight beside you: <color=#ffffff>Tiare, Chen'ni, Algol, Istvan: Scarred Pith, Xuan Ji, Rebecca, Dantang, Zarya, Antony, Lorelei, Cena, Joshua, Schwartz: Almighty Clamor, Yingel, Leo, Hati, Tina, Leyn, Jeriah, Mu Yuebai, Zhong Xu, Vic, Axelia, Lilica, Minos, Pollux, Jeno, Fia, Carleen: Smoldering Soul, Nina, Barton: Deft Blades, Giles, Lenore, Azure, Yao, Amemori, Rinne, Florine, Ruby, Siobhan, Novio, Hedy, Bethel, Luke, Paloma, Gram, Revy, Smokey, Fleur, Beryl, Hiiro, Sinsa, Eve, Uriel, Carleen, Sharona, Sariel, Raphael, Connolly, Charon, Eicy, Victoria, Jona, Nikinis, Gabriel, Migard, Michael, Gronru, Irridon, Wrath.</color>.
Note: This kit will expire at 09:00, 16 August 2024 (UTC+0), 04:00, 16 August 2024 (UTC-5). Claim it on time, or it will be automatically converted into 3,000 Lumamber and sent to you via your in-game mailbox.]],
