  str_item_6001532 = "Your Starlight",
  str_item_intro_6000001 = "Stand By Me Medallion. As the years have gone by, the number of coins has grown to an alarming size. At this point, only a coin purse the size of a house could contain this much wealth.",
  str_item_intro_6000002 = "Stand By Me Medallion. It feels almost impossible to calculate this vast amount of accumulated wealth. Just the sight of it makes even the most avaricious Umbraton merchants dizzy to the point of fainting.",
  str_item_intro_6000101 = "Stand By Me Medallion. Congratulations! You've just dipped your toes in, but there's no telling what the future holds!",
  str_item_intro_6000102 = "Stand By Me Medallion. You're pretty capable of piloting the Colossus now! Your bond with the Fireflies appears to be getting stronger as well.",
  str_item_intro_6000103 = "Stand By Me Medallion. Clouds before you, and clouds all around you. Dip beneath them to see the vast world below, and the blue, cloud-dotted skies above.",
  str_item_intro_6000104 = "Stand By Me Medallion. You have traveled long and far as the Navigator of Soroz. One could even say that your true home lies in the boundless skies above Astra.",
  str_item_intro_6000201 = "Stand By Me Medallion. Bear the image of the land in your heart, and go where you please with a wave of your hand. All the world is within your reach.",
  str_item_intro_6000202 = "Stand By Me Medallion. After so many travels, the lay of the land must be deeply etched into your mind, yes? Can you see its mountains and rivers, even when you close your eyes?",
  str_item_intro_6000301 = "Stand By Me Medallion. The road ahead is sure to be long and arduous. Finding trustworthy companions from all walks of life will serve you well.",
  str_item_intro_6000302 = "Stand By Me Medallion. Throughout the course of your many travels, you have forged just as many new friendships with people all across the world. A stunning feat, indeed!",
  str_item_intro_6000303 = "Stand By Me Medallion. No matter where you go, you are always surrounded by close friends. Friends who will laugh and cry by your side, who will be there to face whatever adversities may come your way...",
  str_item_intro_6000401 = "Stand By Me Medallion. The sky seems to brighten a little more with every new ally who realizes their true potential. Perhaps this mysterious light is the power that unites you and your friends?",
  str_item_intro_6000402 = "Stand By Me Medallion. After your allies acquire the power of light, they hold the energy that brightens the sky within their hands as well.",
  str_item_intro_6000403 = "Stand By Me Medallion. Those blessed with the power of light shall come together and offer their strength to a child of destiny, so that their brilliance can reach even the darkest, most despondent corners of the world.",
  str_item_intro_6000501 = "Stand By Me Medallion. When two stars appear near one another, their sparkling light is a symbol of their trust, a sign that they will reflect each other's brilliance for ages to come.",
  str_item_intro_6000502 = "Stand By Me Medallion. As stars travel across the heavens, their paths converge, linking together and resonating like the hearts and thoughts of kindred spirits with similar beliefs.",
  str_item_intro_6000503 = "Stand By Me Medallion. Like constellations in the night sky, your allies shine with the light of absolute trust and unity. The bonds that connect you represent the convergence of your hopes and ideas.",
  str_item_intro_6000601 = "Stand By Me Medallion. Despite it being your first time seeing them, the seeds of understanding were already planted. Four hands, interlinked at the fingertips, represent the connection between two hearts.",
  str_item_intro_6000602 = "Stand By Me Medallion. Despite all those years spent underground, the exhilaration of flight was never once forgotten. Though this is only the first time, it is more than enough.",
  str_item_intro_6000603 = "Stand By Me Medallion. The sound of approaching footsteps not only denotes danger, but also the arrival of total destruction.",
  str_item_intro_6000604 = "Stand By Me Medallion. In the face of countless adversaries, he chose to end it all with an earth-shattering roar. It was not a desperate act of sacrifice, but a calculated and intentional strategy.",
  str_item_intro_6000605 = "Stand By Me Medallion. A message from your people! But what kind of past does that soft-spoken voice speak of?",
  str_item_intro_6000606 = "Stand By Me Medallion. Eternally residing in the blue skies above, it is the center of all civilization and a symbol of the light.",
  str_item_intro_6000607 = "Stand By Me Medallion. \"The future belongs not to the light, but to the darkness.\" In an instant, her smile contorted into something savage and wicked. Though of the same kin as you, she has long since lost her way.",
  str_item_intro_6000608 = "Stand By Me Medallion. The enemy smiles boastfully as their evil schemes come to fruition. In the darkest despair, a dandelion floats by on a gentle breeze. What does the future hold for us all? Or rather, is there even a future waiting for us?",
  str_item_intro_6000609 = "Stand By Me Medallion. There is a saying in Astra: \"One's choices far outweigh one's efforts.\" Many hesitate at the most crucial junctions of destiny; in the face of these decisions, they can only rely on their hearts, their intuition, and their friends.",
  str_item_intro_6000610 = "Stand By Me Medallion. A weapon that transforms light into a powerful beam of energy; none other but Lumopolis is capable of wielding it. Though its power comes at a steep price, the enemy's impending threat must be averted at all costs.",
  str_item_intro_6000611 = "Stand By Me Medallion. The black Colossus has been defeated, and both master and machine have crash-landed in a distant valley. Nevertheless, their defeat does not necessarily signify their demise...",
  str_item_intro_6000612 = "Stand By Me Medallion. Those who pursue power with singular intent are doomed to perish by it. When she cast herself into the darkness, it was her destiny to meet her end in the darkness, as well.",
  str_item_intro_6000613 = "Stand By Me Medallion. Lines are how mathematics expresses nature. The shell is a vessel of currency; continuity is not absolutely necessary.",
  str_item_intro_6000614 = "Stand By Me Medallion. The pair that once fought as comrades in wars have now gone their separate ways due to past differences.",
  str_item_intro_6000615 = "Stand By Me Medallion. She fell into an endless slumber under the Chord Link. When awakened, the power lying deep within her shall be unleashed.",
  str_item_intro_6000616 = "Stand By Me Medallion. The Caelestite finally has a place to call home in the shadow of the Obelisk of Return, but its presence also changes his destiny...",
  str_item_intro_6000617 = "Stand By Me Medallion. To explore the Eternal Night's territory, the Lumopolis Knights and officers of the Illumina Federation must join forces, because the dangers there are anything but ordinary.",
  str_item_intro_6000618 = "Stand By Me Medallion. This represents a great honor in the military exercise that many forces have participated in.",
  str_item_intro_6000619 = "Stand By Me Medallion. The thick gate block all intruders at the lowest level of the Undercity to protect important and valuable items from thieves and rascals.",
  str_item_intro_6000701 = "Stand By Me Medallion. This is not only the beginning, but a chance to rise above the rest. Those who are bold enough to always make the first move will be the ones who overcome adversity and reach the summit.",
  str_item_intro_6000702 = "Stand By Me Medallion. Though many obstacles may lie ahead, the struggle remains the same, and one must never stop striving to improve and reach greater heights. Could this be the power of ascension?",
  str_item_intro_6000703 = "Stand By Me Medallion. After reaching this peak, it is easy to look down upon the world below and rest on one's laurels. For the truly ambitious, however, this satisfaction is but a fleeting moment of joy on the journey to reach even greater heights...",
  str_item_intro_6000704 = "Stand By Me Medallion. Those who make it to the top are superior to most challengers, yet their hunger to conquer cannot be satiated, and their footsteps will never stop.",
  str_item_intro_6000705 = [[
Stand By Me Medallion. The peak has seen many battles;
Only on the peak does one rule a throne;
Only on the peak will one overlook the rest.]],
  str_item_intro_6000706 = "Stand By Me Medallion. Although this is just the first time, those who can achieve this are exceptional and greater than many.",
  str_item_intro_6000801 = [[
Stand By Me Medallion. Unexpected confinement, unexpected reunion;
high in the cage, those not willing to be trapped break the shackles.]],
  str_item_intro_6000802 = "Stand By Me Medallion. What does the cat crave? Other than its favorite canned food, that would be...",
  str_item_intro_6000803 = "Stand By Me Medallion. It's family to \"Holiday\" and helped her realize that the cafe is her home and where she belongs...",
  str_item_intro_6000804 = "Stand By Me Medallion. The palace is shut tight amid the snow and frost, but when that petite figure comes, eyes gazing up at the aurora, it shall open.",
  str_item_intro_6000901 = "Stand By Me Medallion. Fissures sprawl like cobwebs across the ground, and all signs pointing to a foul presence emerging from below...",
  str_item_intro_6000902 = "Stand By Me Medallion. The cavern is dark except for the light that gleams from those who enter. But it is not quiet here, for those who call it home await in welcome.",
  str_item_intro_6000903 = "Stand By Me Medallion. Is there an end to this? The thought frequently haunts the explorer's mind, though the hardy will have no fear and venture in once more.",
  str_item_intro_6001001 = "Stand By Me Medallion. Images can be wielded as weapons, illusions can cut like blades. Sometimes, sharp eyes are much more useful than brute strength.",
  str_item_intro_6001002 = "Stand By Me Medallion. Let it burn! Witness the blaze destroy the infidels!",
  str_item_intro_6001003 = "Stand By Me Medallion. The loud call heralds the presence of the enemy, and silence marks its demise and end.",
  str_item_intro_6001004 = "Stand By Me Medallion. Is the opponent or the void more terrifying? It appears the only way to vanquish it is to bind and trap it forever.",
  str_item_intro_6001005 = "Stand By Me Medallion. No mortal body, just a hovering awareness, though in the swelling light presence of swelling light, it can do nothing but disperse.",
  str_item_intro_6001006 = "Stand By Me Medallion. Fate's unfairness can drive one mad and turn to darkness. At that point, guns and blades are the only way to fight it.",
  str_item_intro_6001007 = "Stand By Me Medallion. When faced with endless pain and rage to the point of madness, ending it is the best gift.",
  str_item_intro_6001008 = "Stand By Me Medallion. The night is darkest before dawn breaks. Endure it, and the first ray of sunshine will soon light the path you walk.",
  str_item_intro_6001009 = "Stand By Me Medallion. Disembodied voices and unbearable noises intertwine to form the enemy's pain and hatred.",
  str_item_intro_6001010 = "Stand By Me Medallion. Can someone without a home be exiled? Maybe, but very few would know about it.",
  str_item_intro_6001011 = "Stand By Me Medallion. The crimson rock originated from a tainted target and, after breaking free, became the most beautiful gem.",
  str_item_intro_6001012 = "Stand By Me Medallion. Mortals have no value except their souls, which the gods fight over.",
  str_item_intro_6001013 = "Stand By Me Medallion. Not knights of Lumopolis, but their long-standing enemies. Their disguise has been broken—now all that remains is a battle to the end.",
  str_item_intro_6001101 = "Stand By Me Medallion. With every turn of the page, the marvelous text floods the eyes and stimulates the mind like the sound of a pleasant bell.",
  str_item_intro_6001102 = "Stand By Me Medallion. It's not disrespectful to sit on a book when you've learned everything in it.",
  str_item_intro_6001103 = "Stand By Me Medallion. Using books for a bed and pillow means one can also enjoy the worlds they contain in your dreams.",
  str_item_intro_6001201 = "Stand By Me Medallion. True gardeners tend to every seedling with their own hands. Though their hands and clothes are often dirtied by sweat and soil, to see each seedling reach maturity and bloom prosperously is one of their life's greatest joys.",
  str_item_intro_6001202 = "Stand By Me Medallion. When these curious plants grow and fill the space with their natural beauty, Cloud Gardens will look much more different in the setting sun's light.",
  str_item_intro_6001203 = "Stand By Me Medallion. Only a master could catch rare fish like these!",
  str_item_intro_6001204 = "Stand By Me Medallion. This is a grand occassion for all anglers, not just because of the festival itself, but because of the arrival of a certain master fisherman.",
  str_item_intro_6001205 = "Stand By Me Medallion. Without realizing it, you have accumulated a wealth of knowledge for building new structures. Soon, the empty space in that valley will not seem so desolate.",
  str_item_intro_6001206 = "Stand By Me Medallion. After having mastered the construction of so many structures, you are ready to transform Cloud Gardens into a prosperous town. As the master of Cloud Gardens, this duty falls to you alone.",
  str_item_intro_6001301 = "Stand By Me Medallion. Elysium, a place with a legendary past... After awakening the long-slumbering hero, what kind of bond will they share?",
  str_item_intro_6001302 = "Stand By Me Medallion. The oath from days long past is still intact, and the enemies of that time still pose a threat. Not even spoken promises can stop them from taking action.",
  str_item_intro_6001400 = "Stand By Me Medallion. Life is like a game, and adventures played out in your hands are equally exciting. Those who can clear stages with such tough conditions will surely also succeed in real life.",
  str_item_intro_6001401 = "Stand By Me Medallion. It documents without bias or concealment. It stores memories for you to peruse the good old days.",
  str_item_intro_6001402 = "A Stand By Me Medallion. A stage floating in the sky resounds with songs of praise that fall upon every corner of the continent like divine blessings. Between dreams and visions come the chords of love and healing.",
  str_item_intro_6001403 = "Stand By Me Medallion. An indispensable ally on the endless ocean. It is said that it not only guides ships along the right path, but also guides one through the maze of destiny...",
  str_item_intro_6001404 = "A Stand By Me Medallion. It is a gift, an expression of the heart, a form of communication. There is no need for words—simply giving it to your loved one is enough.",
  str_item_intro_6001405 = "Stand By Me Medallion. A bouquet of flowers reserved for a special day. When the appointed time comes, they are paraded in full bloom, filling the air with the intoxicating fragrance of love. Take a deep breath and enjoy this priceless moment.",
  str_item_intro_6001406 = "Stand By Me Medallion. Never leaving the detective's side, all a detective needs to do is reach out to it and it will render its services. With this, even the smallest clues can be discovered.",
  str_item_intro_6001407 = "Stand By Me Medallion. Memories of Family Day, fleeting illusions in a crystal's shine. Although these illusory events belong to an illusory realm of illusory people and things, everything seems so real, as if it had been experienced firsthand.",
  str_item_intro_6001408 = "Real people are trapped in a fabricated realm, which can't be broken by force or they would be stuck inside forever...",
  str_item_intro_6001409 = "Stand By Me Medallion. Represents the reclusive hermit in Denuo Valley, who scatters iridescent scales and glimmering particles while dancing elegantly, casting a spell of fascination on all who behold it...",
  str_item_intro_6001410 = "Stand By Me Medallion. Victory is not solely borne from warfare but is also deeply rooted in daily construction, growth, and continual development.",
  str_item_intro_6002001 = "Stand By Me Medallion. Does a guardian of good people and messenger of the gods truly exist? Or is it just a fantasy?",
  str_item_intro_6002002 = "Stand By Me Medallion. Make your preparations while the sun is still shining. In the light of the sun, never forget the threat of the darkness. In times of peace, never forget that the enemy could always be lurking in the shadows nearby.",
  str_item_intro_6002003 = "Stand By Me Medallion. A mysterious beast of legend from the far reaches of Northland, it is said to breathe flames of the coldest ice, and can freeze an entire village in one fell swoop.",
  str_item_intro_6002004 = "Stand By Me Medallion. There is a certain mirror somewhere in the world, one that will only reflect the visage of the viewer and no one else's. That reflection, however, is said to have a life and mind of its own...",
  str_item_intro_6002005 = "Stand By Me Medallion. They start off as common objects. Only in the hands of the wise do they gain the awareness and soul necessary to fulfill their purpose.",
  str_item_intro_6002006 = "Stand By Me Medallion. If steel is heavier than air, then why can it be made to fly? And if iron is heavier than water, then how can it be used to make ships? In the face of questions like these, knowledge and logic will serve you better than \"common sense.\"",
  str_item_intro_6002007 = "Stand By Me Medallion. Only gods can make bulky steel move at the speed of incorporeal sound.",
  str_item_intro_6002008 = "Stand By Me Medallion. The desert is boundless. Why one would roam here may never be known. Or that could be the sole intent, to roam.",
  str_item_intro_6002009 = "Stand By Me Medallion. Privilege comes with a price, no matter who you are. Even if that price is not paid at first, someday the debt you owe will come knocking.",
  str_item_intro_6002010 = "Stand By Me Medallion. Terrifying shrieks, allies' cheers... The allure of war lies not in conquest, strategy, or courage, but in the birth of another king upon the mass grave called \"victory.\"",
  str_item_intro_6002011 = "Stand By Me Medallion. A steel shell is not enough to transform an average individual into an indestructible fighter. What one needs is coordination, flexibility, and persistence.",
  str_item_intro_6002012 = "Stand By Me Medallion. Could there truly be such a thing as a bottle with no inside or outside? Without this distinction, there would be no space and thus no bottle to speak of. Perhaps the space is infinite, and requires no distinction? In any case, such an object belongs to the realm of the gods, for only they are capable of such creations.",
  str_item_intro_6002013 = "Stand By Me Medallion. Can a strip of paper have only a single side? The answer is hidden within the strip itself; all one needs to do is look at it in the right way. By doing so, one can also see the entire world in a different light...",
  str_item_intro_6002014 = "Stand By Me Medallion. Things can exist in even the smallest of spaces. When looking at this world in a bottle, does it ever occur to you that someone may be regarding your world in the same manner as well?",
  str_item_intro_6002015 = "Stand By Me Medallion. Many legends state that all living things were born from the same tree, a notion that invites ridicule from a number of people. Upon researching the origins of certain creatures, however, those people inevitably begin to doubt their previous statements...",
  str_item_intro_6002016 = "Stand By Me Medallion. If a single row of strings can produce scintillating sounds, what about two rows? Though that would also require a musician with exceptional skill and dexterity.",
  str_item_intro_6002017 = "Stand By Me Medallion. Its wheels are its body, so trampling is its primary attack. Pray that you don't have to face the rolling blades in a battle.",
  str_item_intro_6002018 = "Stand By Me Medallion. If strongholds could one day dominate the land like the legendary behemoth, they would be invincible.",
  str_item_intro_6002019 = "Stand By Me Medallion. When mortals think of \"nothingness,\" they lend it a sort of existence. Formless, it enters through their eyes, penetrating deep into their minds and creating a different kind of \"nothingness\" within.",
  str_item_intro_6002020 = "Stand By Me Medallion. Tireless, impervious. That would describe the mounts of those traversing the desert.",
  str_item_intro_6002021 = "Stand By Me Medallion. Games of strategy are enjoyed everywhere in the world. Those who hold high positions in their societies tend to see the rest of the world as a game of chess. Their games involve self-aware pawns and sentient chessboards. And so, many of these chess games are destined to be shattered entirely, as they have been all throughout history.",
  str_item_intro_6002022 = "Stand By Me Medallion. \"Fall into eternal destruction... Gaze upon the world once more, and let it serve as your final memory.\" This is what the creatures of darkness say to all living beings in the world.",
  str_item_intro_6002023 = "Stand By Me Medallion. Allegedly, the positions of the stars in the sky represent a mortal's destiny, so mankind built looming towers to observe the stars and foretell the future. Ironically, the future of this tower could not be predicted.",
  str_item_intro_6002024 = "Stand By Me Medallion. A ferocious beast with a strong body and swift movement. But what truly terrifies people is its cunning and poisonous tail spikes.",
  str_item_intro_6002025 = "Stand By Me Medallion. Like a messenger from hell, it came to this world filled with wrath. It belonged not to the netherworld, but the cycle of death and reincarnation.",
  str_item_intro_6001500 = [[
Stand By Me Medallion.
Soundscape broad, begonias in their prime. Lean in, hear echoes like a rhyme. Eastern winds carry the blossoms' chime. In the pavilions, a moment sublime.]],
  str_item_intro_6001507 = [[
Stand By Me Medallion.
In Northland, some snowflakes are freshly fallen and some have endured for eons. Which category does this medallion you hold belong to?]],
  str_item_intro_6001508 = [[
Stand By Me Medallion.
All the adventures we had will be cherished.]],
  str_item_intro_6001510 = [[
This untainted flower is so pure and beautiful.
Just like her.]],
  str_item_intro_6001511 = [[
Stand By Me Medallion.
With extraordinary wisdom, one can craft ships to link distant lands or forge weaponry to unleash chaos. At such moments, the true wisdom lies in one's choices.]],
  str_item_intro_6000620 = [[
Stand By Me Medallion.
A colossal combat mech forged by Illumina. It boasts a sturdy exterior and formidable firepower. As always, the vulnerabilities of such giants are often concealed beneath the surface...]],
  str_item_intro_6000621 = [[
Stand By Me Medallion.
A turret guarding the final line of defense, obliterating all incoming enemies.]],
  str_item_intro_6001512 = [[
Stand By Me Medallion.
Everyone wants it, but not everyone can bear its burden.]],
  str_item_intro_6001515 = [[
Stand By Me Medallion.
A machine that is filled with unknown dangers. No one knows how much longer it will continue to function, and it always makes scary hissing sounds in the middle of the night.]],
  str_item_intro_6001516 = [[
Stand By Me Medallion.
Aurorians and fiendlings, how are they different? Both munch on sweet sugar figurines under the Spring Festival fireworks, celebrating this auspicious occasion together.]],
  str_item_intro_6001517 = [[
Stand By Me Medallion.
Algol developed this bracelet to monitor health data such as heart rate, blood pressure, and blood oxygen saturation in real time, and uses this data to develop fitness plans for the wearer.]],
  str_item_intro_6001520 = [[
Stand By Me Medallion.
The duty of guardians carries a heavy weight, but they willingly embrace it, choosing to stay within the blizzard.]],
  str_item_intro_6001521 = [[
A Stand By Me Medallion.
Sacrifices must not be made simply for honor. "You may be heroes, but you are far more than just that."]],
  str_item_intro_6001524 = [[
Stand By Me Medallion.
"That was fun! Let's go again, let's go again!"]],
  str_item_intro_6001525 = [[
Stand By Me Medallion.
Inspiration flared up in my mind, making this a memorable moment for the record books.]],
  str_item_intro_6001526 = [[
Stand By Me Medallion.
"This power is not mine alone."]],
  str_item_intro_6001529 = [[
Stand By Me Medallion.
"It's been a while, my contractor. Though perilous, this journey leads to the truth."]],
  str_item_intro_6001530 = [[
Stand By Me Medallion.
Even though the prince never returned, his journey paved the way for his people's survival. No matter how much time passes, their hearts will always be united. Because of this, their descendants will one day, sooner or later, reunite on the continent.]],
  str_item_intro_6001531 = [[
Stand By Me Medallion.
She's been told that love is like a beautiful dream.]],
  str_item_intro_6001532 = [[
Stand By Me Medallion.
It's a rough journey, but in the end, it seems like you're just watching the happiness of others reuniting.
Still, for all your efforts to help the stars, how could we not give you our deepest gratitude?]],
  str_item_6100001 = "Stand By Me Commemorative Board",
  str_item_6100002 = "Stand By Me Battle Board",
  str_item_6100003 = "Stand By Me Obsidian Slab",
  str_item_6100004 = "Stand By Me Machinery Board",
  str_item_intro_6100001 = "Stand By Me Commemorative Board. A commemorative board that's well-suited for Cloud Gardens, where Stand By Me Medallions can be displayed.",
  str_item_intro_6100002 = "Stand By Me Commemorative Board. Although visuals on this board evoke a strong sense of war, it hasn't stopped anyone from putting their medals on it.",
  str_item_intro_6100003 = "Stand By Me Commemorative Board. This black-colored rock looks like it belongs in the wilderness. Who moved it here? At least the tiny bumps on it are great for keeping the medals in place.",
  str_item_intro_6100004 = "Stand By Me Commemorative Board. This background makes you feel like you're in a giant machine or a factory, and you can't resist the urge to arrange your medals neatly. But arranging them freely is also a possibility; maybe the spontaneity would feel special?",
