  str_item_intro_1400851 = "The Witness of Umbraton, who is always neutral no matter what. There is a large number of records in the case she carries with her at all times. She is said to be the Walking Archive of Umbraton.",
  str_item_intro_3000220 = "Action Points: Used to challenge special event stages. Automatically recovers over time.",
  str_item_intro_3000221 = "A rare mistletoe fruit. It is considered to be the symbol of hope and abundance by the Northland people. Used to exchange for gifts at the Cedar Market.",
  str_item_intro_3000001 = "Carrier of light manufactured using a special technique, essential for any type of expedition.",
  str_item_intro_3000002 = "Coins issued by Lumopolis. Bright and in abundance, they're recognized and traded throughout the continent.",
  str_item_intro_3000003 = [[
Gem obtained by polishing Lumocrystals.
Can be used to summon Aurorians, exchange for Special Star Flares, and Star Flares, as well as purchase Prism.]],
  str_item_intro_3000004 = "Insight from previous commands and warfare experiences. The higher the level, the better the connection with Colossus. Useful for learning more about Colossus.",
  str_item_intro_3000005 = [[
Fireflies recover automatically. Their recovery speed is affected by your Lumina Grid and can also be increased by smelting Colossus Patches in the Workshop.
These miniature constructs operate under the command of the Colossus' controller and are responsible for restoring and maintaining the Colossus' structural integrity.]],
  str_item_intro_3000006 = "Reading shown on the Luminameter. Everyone must vacate when it drops to 0, or danger is imminent.",
  str_item_intro_3000007 = "Fragments of ancient tomes found in Secret Territory. Certain agencies would be interested enough to purchase them.",
  str_item_intro_3000008 = "Points awarded for completing Daily Quests. Get extra rewards at certain totals.",
  str_item_intro_3000009 = "Proof of Achievements",
  str_item_intro_3000010 = "Aurorians will be closer to you",
  str_item_intro_3000011 = "Holy Dice",
  str_item_intro_3000012 = [[
A special structure found in the Resource Station. It can collect all kinds of resources for you.
(Use it during Consecutive Sweep to reduce the amount of Prism required to clear stages and obtain resources immediately)]],
  str_item_intro_3000013 = "A special substance created by the Colossus Workshop. Its working principle allegedly came from ancient technology. Use it to change the basic composition of certain items, transforming them into new items.",
  str_item_intro_3000014 = [[
Natural crystal imbued with Lumina.
You can use Lumocrystals in the store to buy gift packs and Aurorian outfits. Additionally, you can convert Lumocrystals into Lumamber for summoning Aurorians and restoring Prism.]],
  str_item_intro_3000015 = "Transparent gem found with the Heartstone. Emits intense fiery glow and may be traded for precious items in Star Gem Store.",
  str_item_intro_3000016 = "Star Gems of even higher rarity. Extremely valuable, very popular in the Star Store.",
  str_item_intro_3000017 = "The materials necessary to support the activities of the Colossus are distributed by the Lumina Grid, which provides power supply for the Colossus.",
  str_item_intro_3000018 = "Stone pieces found in various parts of Cloud Gardens that are supposed to be relics, but their exact function is unknown. The Chubbs do like these pieces and will exchange certain things for them.",
  str_item_intro_3000019 = "A very rare Star Gem that most people are unable to afford. It can only be traded in the Astral Store.",
  str_item_intro_3000021 = "A storage disk created by Soroz's bridge and the simulator. The Navigator can place memories inside to produce holograms in the Colossus's cloud disk.",
  str_item_intro_3000022 = "A rare and precious wood that is said to come from some exotic plant. It is popular among the upper echelons of society because of its rarity and its natural round, smooth shape. There is a special guild in Umbraton that buys it and uses it as a currency in niche locations.",
  str_item_intro_3000025 = "Rumored to contain the words of The Forsaken, the artifact remains undeciphered, leaving these claims as mere speculation. Still, its great condition makes it appealing to truth-seeking affiliations interested in acquiring it.",
  str_item_intro_3000026 = "Rumored to contain the words of The Forsaken, the artifact remains undeciphered, leaving these claims as mere speculation. Its fragmented state suggests that collecting multiple pieces may be necessary to attract potential buyers.",
  str_item_intro_3000029 = [[
Golden bookmark obtainable by the elites who have finished the Special Event Book.
Redeemable for rewards in the Event Book Store.]],
  str_item_intro_3000030 = [[
Bookmark obtainable by the players who have gone through the Special Event Book.
Redeemable for rewards in the Event Book Store.]],
  str_item_intro_3000031 = [[
Item obtainable by the players who have gone through the Special Event Book.
Redeemable for normal outfits in the Event Book Store.]],
  str_item_intro_3000032 = [[
Item obtainable by the players who have gone through the Special Event Book.
Redeemable for Colossus furniture in the Event Book Store.]],
  str_item_intro_3501001 = [[
An item used to refine equipment.
This mysterious substance creates a stronger bond between an item and its bearer, but it must be stored in a special container to prevent it from dispersing.]],
  str_item_intro_3000100 = [[
Device capable of emitting recruitment signals.
Can be used in recruitment to obtain Aurorians.]],
  str_item_intro_3000101 = [[
Device capable of emitting special recruitment signals.
Can be used in limited-time recruitment to obtain Aurorians.]],
  str_item_intro_3000110 = [[
Exclusive Halloween recruitment item. Allows you to recruit ten times from the special Halloween recruitment pool.
This is a limited-time item. After the Special Halloween Recruitment ends, this item will be converted into 3,000 Lumamber.]],
  str_item_intro_3000112 = "An exclusive Christmas recruitment item allows you to perform Recruitment ×10 from the Christmas Recruitment Pool.\nThis is a time-limited item and will be converted into Lumamber ×3,000 after the Christmas Recruitment ends.",
  str_item_intro_3000113 = [[
A collab exclusive recruitment item that can be used in the collab recruitment to recruit 10 times.
This item will expire, so please use it before 09:00, 26 January, 2022 (UTC+0) or else it will disappear. It will not be converted to another item when it expires.]],
  str_item_intro_3000114 = [[
