  str_item_intro_3000201 = "A small badge made by some members of Rediesel Wrench by modifying a nut. They believe this badge represents the desert's acknowledgment, so it is only issued to those who are acknowledged by Rediesel Wrench.",
  str_item_intro_3000211 = "A gift voucher that can be exchanged for special gifts at the Tir' Hotel's reception desk. The seal on it is said to be a portrait of the hotel's general manager.",
  str_item_intro_3000212 = "After completing quests in the Special Event Book, you'll earn a certain amount of Umbraton Contribution Points which can be used to unlock rewards. Umbraton always smiles upon adventurers who dare to dream.",
  str_item_intro_3000213 = "Action Points: Used to challenge certain event stages. Action Points automatically recover over time.",
  str_item_intro_3000214 = "Special food issued by the Courier Union to supplement the energy of its hard-working couriers. The flavor of each pack is a mystery until opened... Maybe you can try it sometime.",
  str_item_intro_3000215 = "Remodeling Progress (no details at present)",
  str_item_intro_3000217 = "Merit: A physical manifestation of one's military achievements, symbolizing a soldier's contribution to the Illumina Federation.",
  str_item_intro_3000219 = "Endure the pain of combat and demonstrate your might through sweat and blood in the Underground Arena! Let your glorious name resound through Umbraton!",
  str_item_intro_3000202 = [[
Event item. Can be used in the Daruma Smash draw event. Accumulate a certain amount to unlock Hiiro's exclusive storyline.
This fallen cloud blossom petal is a specialty of Cloud Mountain. The residents of Cloud Mountain believe it brings good luck.]],
  str_item_intro_3000224 = "Aurora Aeterna event item. Accumulate a certain amount to receive Scala Gloriari rewards.",
  str_item_intro_3000225 = [[
Dragon Maid's Break item used for prize drawing in Tohru's Kitchen.
The hot meal is almost ready, so get your plate!]],
  str_item_intro_3000226 = "A beverage that is uncommon in Astra and invigorates those who drink it.",
  str_item_intro_3000227 = "An old-looking coin, very different from the coins we see today.",
  str_item_intro_3000229 = "A token of honor for explorers and adventurers, it is usually acquired through extremely arduous efforts or by overcoming great adversity.",
  str_item_intro_3000236 = "Points rewarded for completing challenges. The quantity obtained varies with each difficulty level.",
  str_item_intro_3000238 = "During the festival, Cloud Islanders write words of blessings on this paper, wishing for happiness for the year.",
  str_item_intro_3000239 = "A staple popular in the Far East, it looks lovely and is easy to carry. Usually served with side dishes.",
  str_item_intro_3000240 = [[
Exclusive Fluffy Serendipity item. Look into the mirror to make a wish.
This is a limited-time item. When the Fluffy Serendipity - Wishing Mirror expires, this item will be converted into 100 Lumamber.]],
  str_item_intro_3000241 = "This silver coin is the principal currency on Cloud Island.",
  str_item_intro_3000242 = "A card containing records of each contestant's performance and bears the signatures of each checkpoint personnel.",
  str_item_intro_3000244 = "It has an unexplainable power that allows those trapped within to move freely and even break free of its bonds...",
  str_item_intro_3000245 = "The alleged product of certain spirit fragments in the warp. Some people are particularly interested in them.",
  str_item_intro_3000246 = "Information obtained after quantification and total evaluations. It can be used to outline a search perimeter.",
  str_item_intro_3000247 = "A Normal Signal picked up by the Portable Detector",
  str_item_intro_3000248 = "A Special Signal picked up by the Portable Detector",
  str_item_intro_3000253 = "The ticket is issued by the once powerful Andersen Association. You might be able to exchange it for something if you can find someone willing to endorse it.",
  str_item_intro_3000256 = "Points needed to attack bandit hideouts. Take them out and keep pressing forward!",
  str_item_intro_3000258 = "Scribbles of news, anecdotes, and gossips. If you want to know the whole story, just follow the pictures and look for yourself.",
  str_item_intro_3000259 = "At the Harbor Fair every year, Harbor City issues a special token to all its residents that can be used in place of money at the Street Fair.",
  str_item_intro_3000266 = [[
A new aquarium! It has all the equipment and aquatic creatures you can imagine, and it's never too crowded! Visit now in case you miss out!
An exclusive Day at the Aquarium item that can be used to make a wish at the aquarium. This is a limited-time item. When Day at the Aquarium event ends, this item will be converted into 100 Lumamber.]],
  str_item_intro_3000267 = "A Normal Signal picked up by the Portable Detector",
  str_item_intro_3000268 = "A Special Signal picked up by the Portable Detector",
  str_item_intro_3000270 = [[
According to a magician, these types of plain-looking cards have magical powers that allow him to transform into many things!
Obtained by consuming Prism and clearing the stage during the event.]],
  str_item_intro_3000271 = [[
Empty, reusable bullet shell casings that can be exchanged at the Supply Depot for supplies.
Obtained by using Prism to clear stages during the event.]],
  str_item_intro_3000275 = [[
This ticket will not only grant you a viewing of a certain famous actor's latest movie, but an in-person interview with them as well!
An exclusive Under the Spotlight event item that can be used to make wishes. This limited-time item will be converted into 100 Lumamber when the Under the Spotlight event ends.]],
  str_item_intro_3000276 = "Coin-like props made by Nina to add to the ghastly atmosphere of the haunted house. Can be used to exchange souvenirs.",
  str_item_intro_3000278 = [[
Parts that have been littered all over the place. Maybe they'll serve some use!
Obtained by using Prism to clear stages during the event.]],
  str_item_intro_3000280 = [[
Exclusive Fluffy Serendipity rerun item. Look into the mirror to make a wish.
This is a limited-time item. When the Fluffy Serendipity - Wishing Mirror rerun expires, this item will be converted into 100 Lumamber.]],
  str_item_intro_3000281 = "Touted as the work of a genius director, legend says that he laughed so hard watching his completed film for the first time that he died.",
  str_item_intro_3000282 = "It appears to be the script for a fantasy adventure. While some parts are quite romantic and imaginative, others are entirely too cliche.",
  str_item_intro_3000283 = "This script seems to be an adaptation of a true story. However, since no one knows the ultimate fate of the original protagonist, the ending has been left entirely up to the writer's artistic interpretation.",
  str_item_intro_3000284 = "A script that Jomu mysteriously slipped into your hands. He mentioned something about hefty compensation once \"everything is said and done.\"",
  str_item_intro_3000285 = "A script given to you by Lilica. Believing that you have directing potential, she entrusted you with the task of shooting a promotional video for it.",
  str_item_intro_3000286 = "A script given to you by Vivian. According to her, it is the Illumina Federation's latest attempt to bolster its recruitment efforts.",
  str_item_intro_3000288 = [[
A notebook filled with ideas that you and Bethlehem came up with while creating a dream.
Exclusive Sweet Melody's Embrace item. Required for making wishes during Sweet Melody's Embrace. This is a limited-time item. When Sweet Melody's Embrace comes to an end, this item will be converted into 100 Lumamber.]],
  str_item_intro_3000291 = "A record of things discovered during your journey. With this, you'll be able to recall a great deal of important information even after you return home.",
  str_item_intro_3000292 = "How could you possibly miss out on exclusive merch for the most popular idol on the whole continent?! Opportunists will definitely be looking to make a quick buck from diehard fans with such special merchandise.",
  str_item_intro_3000293 = "A traditional Northland item. On the eve of the winter festival, children hang stockings from their beds and write letters stating what they want the most. The next morning, the gifts they wish for appears in their stockings! As for who puts them there, who knows?",
  str_item_intro_3000294 = "This blank card seems to have some kind of magic power. Legend says if you write your wishes on it, they come true. Although it's difficult to believe such an outrageous claim, who would turn their nose up at a chance to receive such a blessing?",
  str_item_intro_3000297 = [[
This script received from an anonymous person seems to contain thrilling and romantic stories,
but the story in it seems familiar for some reason...]],
  str_item_intro_3000298 = "A script adapted from stories that are told around the world. You'll find stories about all sorts of danger and sinister things here.",
  str_item_intro_3000299 = [[
One of the most popular storybooks on Cloud Island right now. You received this from a mysterious person who crossed the ocean.
At first glance, it seems to be a story about sword fighting and an impending apocalypse...]],
  str_item_intro_3000300 = "A check from the Lin Guild. Can be cashed in for items at The Docks, according to the amount stated above.",
  str_item_intro_3000307 = "A peculiar-looking plaster fragment that seems to have fallen off a statue. Maybe there are some clues...",
  str_item_intro_3000311 = [[
Legend has it that if you toast others while drinking from this majestic glass, you'll stay sober all night long.
Exclusive Mesmerizing Eventide item. Use it during the event to make a wish! This is a limited-time item, and will be converted into 100 Lumamber when the Mesmerizing Eventide event ends.]],
  str_item_intro_3000313 = "The currency used in the Illumina Supply Center. It is the only proof of the transportation and deployment of supplies.",
  str_item_intro_3000321 = [[
These seem to be fragments of some curious crystal, containing even more curious water droplets.
Use: You can purchase the items you want in the Divination Room.
Source: Complete Main Story or Resource Raid stages that require Prism.]],
  str_item_intro_3000326 = [[
A coin that looks exquisite but somehow exudes a dangerous aura... Well, Ms. Rot said it could be exchanged for something, so it should be okay...
Source: Complete Ms. Rot's Quest.]],
  str_item_intro_3000330 = [[
Whether a flower bound by thorns blossoms or not depends entirely on the flower, not on what the world thinks of it. Exclusive Blooming Firethorn event item. 
Can be used to make a wish during the Blooming Firethorn event. This is a limited-time item, and will be converted to 100 Lumamber when the Blooming Firethorn event ends.]],
  str_item_intro_3000332 = "The work has piled up like mountains while guarding against the harassment of Eclipsites and monitoring the movements ahead... All these leave Wrath: Proud Fervor with no choice but to meticulously organize the meager manpower for a partial reconstruction of Twilight.",
  str_item_intro_3000334 = "Barton's Recognition Toward Wrath's Tactics",
  str_item_intro_3000335 = "Hiiro's Recognition Toward Wrath's Tactics",
  str_item_intro_3000336 = "Vivian's Recognition Toward Wrath's Tactics",
  str_item_intro_3000337 = "Sharona's Recognition Toward Wrath's Tactics",
  str_item_intro_3000353 = "Your wish will come true one day.",
  str_item_intro_3000354 = "Accumulate a certain number of Divergent Cocoons and redeem them for gifts in Exchange Center.",
  str_item_intro_3000356 = "Favored incense in the Ji Kingdom, meticulously designed with a delicately subtle fragrance.\n\"As the burning incense sends smoke to the sky, folks send offerings to the heavens and earth—Chen'ni understand this cultural practice. But there are always a few days each year when the smoke is so thick that Chen'ni can't open her eyes...\"",
  str_item_intro_3000361 = [[
It would take a lot of effort just to collect and sort the data that has been messed up due to the malfunction.
A new photo restoration stage unlocks after a certain amount is consumed.]],
  str_item_intro_3000366 = "An essential item for making the pact with specific Aurorians.",
  str_item_intro_3000367 = "A special lollipop from Umbraton that randomly changes flavors, providing endless surprises. In the scarcity of the desert, this candy's value is as good as gold.",
  str_item_intro_3000368 = [[
A supply kit prepared for all hardworking Navigators.
All your efforts and growth will be recorded and rewarded.]],
  str_item_intro_3000374 = "A nostalgic-looking game token rough to the touch. It's said that the best players only need one token to play all night long.",
  str_item_intro_3000376 = "Can be exchanged for daily commodity vouchers in Gannon City. Those who have made special contributions to Illumina can also use them to apply for personalized custom items.",
  str_item_intro_3000377 = "As legend has it, the saint's blood never flows in vain but remains eternal, like amber. Offering it to the truth is like presenting devotion to the Lord.",
  str_item_intro_3000381 = "Waking up from a grand dream, the dew condensed between leaves vanishes in an instant just like that beautiful dream you can't fall back into. Offer it to the mirage dragon in the dream for the possibility of getting a reward.",
  str_item_intro_3000383 = "Windelion's magic comes alive with Eraveil's colored paper. Its soft, durable texture is perfect for crafting unique decorations or Windelion dolls. It's a vessel for cherished memories and a spark for dreams yet to come.",
  str_item_intro_3100001 = [[
Used to level up Aurorians, +50% EXP for Forest Aurorians.
Green jasper. Meditate with it to recall memories of a battle and gain a modicum of EXP.]],
  str_item_intro_3100002 = [[
Used to level up Aurorians, +50% EXP for Forest Aurorians.
Valuable green jasper. Use it to replay scenes of battles in your head and gain moderate EXP.]],
  str_item_intro_3100003 = [[
Used to level up Aurorians, +50% EXP for Forest Aurorians.
Extremely valuable green jasper. Use it to relive a past battle and gain massive EXP.]],
