  str_item_intro_3100013 = [[
Used to level up Aurorians.
Ashwhite jasper with special energy. Any Aurorian can use it to gain a modicum of EXP.]],
  str_item_intro_3100014 = [[
Used to level up Aurorians.
Ashwhite jasper of greater value. Any Aurorian can use it to replay scenes of battles in their head and gain moderate EXP.]],
  str_item_intro_3100015 = [[
Used to level up Aurorians.
Very rare ash white jasper. Any Aurorian can use it to relive a past battle and gain massive EXP.]],
  str_item_intro_3210101 = [[
A basic ascension material that is used for Lumopolis Aurorians' ascension.
Kept in the Dawn Academy of Lumopolis and enhanced with unique magic, it can improve the power of Aurorians.]],
  str_item_intro_3210201 = [[
A basic ascension material that is used for Umbraton Aurorians' ascension.
Trendy special libation in Umbraton. Strong and smooth, it can improve the imbiber's power.]],
  str_item_intro_3210301 = [[
A basic ascension material that is used for Northland Aurorians' ascension.
Condensed pine dews that absorbed Northland's unique elements to grant great power to Northlanders.]],
  str_item_intro_3210401 = [[
A basic ascension material that is used for Rediesel Wrench Aurorians' ascension.
Special rediesel with a taste so pungent that only strong Rediesel Wrench members would dare try.]],
  str_item_intro_3210501 = [[
A basic ascension material that is used for Illumina Federation Aurorians' ascension.
Battle Archive of Illumina Federation that improves the reader's combat skills.]],
  str_item_intro_3210601 = [[
A basic ascension material that is used for True Order Aurorians' ascension.
Scrolls recording ancient knowledge. True Order members can improve themselves by deciphering it.]],
  str_item_intro_3210701 = [[
A basic ascension material that is used for Independent Aurorians' ascension.
Stories from various people of different backgrounds with confusing jargon. Independent readers will learn various tricks of survival.]],
  str_item_intro_3210801 = [[
A basic ascension material that is used for Longzhou Aurorians' ascension.
Produced by the Longzhou Apothecary, this superior pill increases physical strength and strengthens bones and muscles.]],
  str_item_intro_3210102 = [[
A regular ascension material that is used for Lumopolis Aurorians' ascension.
Kept in the Dawn Academy of Lumopolis, it is said to be crafted from the power of morning light and can greatly enhance the power of Aurorians.]],
  str_item_intro_3210202 = [[
A regular ascension material that is used for Umbraton Aurorians' ascension.
Refined version of Destiny Champagne I. Stronger and smoother for even greater improvement of power.]],
  str_item_intro_3210302 = [[
A regular ascension material that is used for Northland Aurorians' ascension.
Uncommon condensed pine frost. One of the crucial sources for Northland magic.]],
  str_item_intro_3210402 = [[
A regular ascension material that is used for the ascension of Rediesel Wrench Aurorians.
Usually found only in the heart of the Rediesel Desert, it improves the fighting abilities of Rediesel Wrench members.]],
  str_item_intro_3210502 = [[
A regular ascension material that is used for Illumina Federation Aurorians' ascension.
Battle Archive Illumina Federation compiled with considerable info that can greatly improve the reader's combat skills.]],
  str_item_intro_3210602 = [[
A regular ascension material that is used for True Order Aurorians' ascension.
Volume containing significant ancient knowledge. True Order members can greatly improve themselves by deciphering it.]],
  str_item_intro_3210702 = [[
A regular ascension material that is used for Independent Aurorians' ascension.
Tips from various people of different backgrounds for Independent readers to apply.]],
  str_item_intro_3210802 = [[
A regular ascension material that is used for Longzhou Aurorians' ascension.
This pill is refined by Longzhou cultivators with spiritual materials and is said to have the effect of cleansing the marrow in one's body.]],
  str_item_intro_3210103 = [[
An advanced ascension material that is used for Lumopolis Aurorians' ascension.
Kept in the Dawn Academy of Lumopolis and enhanced with unique magic, it can boost the power of Aurorians to another level.]],
  str_item_intro_3210203 = [[
An advanced ascension material that is used for Umbraton Aurorians' ascension.
The finest version of Destiny Champagne I, with an unbelievable taste for a significant power boost.]],
  str_item_intro_3210303 = [[
An advanced ascension material that is used for Northland Aurorians' ascension.
Supposedly the perfect dew crystal. Nicknamed "Tear of Northland", it provides formidable magic energy for Northlanders.]],
  str_item_intro_3210403 = [[
Advanced ascension material used for the ascension of Rediesel Wrench Aurorians.
The purest rediesel in semi-liquid form. Only the strongest of the Rediesel Wrench dare to go near it.]],
  str_item_intro_3210503 = [[
An advanced ascension material that is used for Illumina Federation Aurorians' ascension.
Battle Archive of Illumina Federation with massive details that can raise the reader's combat skills to yet another level.]],
  str_item_intro_3210603 = [[
An advanced ascension material that is used for True Order Aurorians' ascension.
Tome detailing ancient knowledge. True Order members can improve leaps and bounds by deciphering it.]],
  str_item_intro_3210703 = [[
An advanced ascension material that is used for Independent Aurorians' ascension.
Detailed accounts and wisdom from various people of different backgrounds to ensure excellent survivability.]],
  str_item_intro_3210803 = [[
An advanced ascension material that is used for Longzhou Aurorians' ascension.
The essence of heaven and earth has been infused into this pill by the secret masters of Longzhou, granting it the power to reconstruct their bodies, achieve a breakthrough, and greatly increase their cultivation.]],
  str_item_intro_3201011 = [[
A basic ascension material that is necessary for Water Aurorians' ascension.
Glowing powder mostly found in the soil near water. One of the raw materials for large-scale industrial processing.]],
  str_item_intro_3201012 = [[
A basic ascension material that is necessary for Water Aurorians' ascension.
Rare shining blue crystal particles.]],
  str_item_intro_3201013 = [[
A basic ascension material that is necessary for Water Aurorians' ascension.
Pure white magical powder refined through special Luminatics.]],
  str_item_intro_3201014 = [[
A basic ascension material that is necessary for Water Aurorians' ascension.
A mysterious substance transformed to rock by the sea, with a brittle texture and many pores.]],
  str_item_intro_3201021 = [[
A basic ascension material that is necessary for Fire Aurorians' ascension.
Glowing powder usually found in active geothermal areas. One of the raw materials for large-scale industrial processing.]],
  str_item_intro_3201022 = [[
