  str_item_intro_3204042 = [[
A premium ascension material that is necessary for Thunder Aurorians' ascension.
Cluster of rare golden crystals.]],
  str_item_intro_3204043 = [[
A premium material that is necessary for Thunder Aurorians' ascension.
Concentrated Thunder Potion II that greatly improves an Aurorian's might.]],
  str_item_intro_3204044 = [[
A premium ascension material that is necessary for Thunder Aurorians' ascension.
A magical material crafted from lightning-infused mercury. Dangerous, volatile, and powerful.]],
  str_item_intro_3205011 = [[
