  str_item_intro_3205013 = [[
An advanced ascension material that is necessary for Water Aurorian ascension.
A product refined from Water Potion III that significantly enhances an Aurorian's might.]],
  str_item_intro_3205014 = [[
An advanced ascension material that is necessary for Water Aurorian ascension.
A hard object made from deep-sea water. Beautiful, smooth, and extremely expensive.]],
  str_item_intro_3205021 = [[
An advanced ascension material that is necessary for Fire Aurorian ascension.
Metal composite made of processed Fire Flare Tiles and other substances. An industrial product of the highest grade.]],
  str_item_intro_3205022 = [[
An advanced ascension material that is necessary for Fire Aurorian ascension.
A rare gem crafted from many red crystals infused with Lumina.]],
  str_item_intro_3205023 = [[
An advanced ascension material that is necessary for Fire Aurorian ascension.
A product refined from Fire Potion III that significantly enhances an Aurorian's might.]],
  str_item_intro_3205024 = [[
An advanced ascension material that is necessary for Fire Aurorian ascension.
A hard, reddish silver nugget forged from volcanic rocks in intense fire. Extremely expensive.]],
  str_item_intro_3205031 = [[
An advanced ascension material that is necessary for Forest Aurorian ascension.
A metal composite made of processed Forest Flare Tiles and other substances. An industrial product of the highest grade.]],
  str_item_intro_3205032 = [[
An advanced ascension material that is necessary for Forest Aurorian ascension.
A rare gem crafted from many green crystals infused with Lumina.]],
  str_item_intro_3205033 = [[
An advanced ascension material that is necessary for Forest Aurorian ascension.
A product refined from Forest Potion III that significantly enhances an Aurorian's might.]],
  str_item_intro_3205034 = [[
An advanced ascension material that is necessary for Forest Aurorian ascension.
A silver nugget made by breaking down and refining rare plant seeds using a secret method. Extremely expensive.]],
  str_item_intro_3205041 = [[
An advanced ascension material that is necessary for Thunder Aurorian ascension.
A metal composite made of processed Thunder Flare Tiles and other substances. An industrial product of the highest grade.]],
  str_item_intro_3205042 = [[
An advanced ascension material that is necessary for Thunder Aurorian ascension.
A rare gem crafted from many yellow crystals infused with Lumina.]],
  str_item_intro_3205043 = [[
An advanced ascension material that is necessary for Thunder Aurorian ascension.
A product refined from Thunder Potion III that significantly enhances an Aurorian's might.]],
  str_item_intro_3205044 = [[
An advanced ascension material that is necessary for Thunder Aurorian ascension.
A magical material obtained by infusing silver with electric current. Incredibly hard, it contains the power of thunder.]],
  str_item_intro_3220000 = [[
Serves a special purpose in Aurorian Breakthrough.
A rare gem with unknown energy that imparts special powers in the hands of certain Aurorians whose potentials may be unlocked by mastering it.]],
  str_item_intro_3220001 = [[
Essential Breakthrough object for Nikinis.
Unique gem resembling a mirror. Close examination reveals the reflection of a young woman in white.]],
  str_item_intro_3220002 = [[
Essential Breakthrough object for Hiiro.
This very precious gem occasionally displays the image of a cherry-red dragon.]],
  str_item_intro_3220004 = [[
Essential Breakthrough object for Kuma & Pengy.
This gem gives off chills when Kuma and Pengy wear it, thus it is their favorite.]],
  str_item_intro_3220005 = [[
Essential Breakthrough object for Mia.
This gem seems to have trapped another side of Mia within... Perhaps it offers a glimpse into who she really is.]],
  str_item_intro_3220006 = [[
Essential Breakthrough object for Carleen.
This gem occasionally flashes a gloomy, pale outline of a glowing lance.]],
  str_item_intro_3220009 = [[
Essential Breakthrough object for Faust.
Gem with weird, twisted patterns that inspire panic, although Faust doesn't back off and is attracted to it instead.]],
  str_item_intro_3220010 = [[
Essential Breakthrough object for Louise.
A distinctive, bright gem that allegedly inspired Louise Carlisle to write countless stories.]],
  str_item_intro_3220011 = [[
Essential Breakthrough object for Sharona.
Look closely to see the blurry outline of a gigantic dragon wafting by.]],
  str_item_intro_3220012 = [[
Essential Breakthrough object for Nemesis.
Perfectly cut and hard gem with incredible power.]],
  str_item_intro_3220013 = [[
Essential Breakthrough object for Noah.
Extremely cold to the touch without causing frostbite or any damage. Noah's favorite.]],
  str_item_intro_3220014 = [[
Essential Breakthrough object for Schwartz.
White gemstone with intense glow. Schwartz feels it not only represents himself but also Lumopolis.]],
  str_item_intro_3220015 = [[
Hachi & Gin can see many different sights within this gem and derive extraordinary artistic inspiration from it.
Essential Breakthrough object for Hachi & Gin.]],
  str_item_intro_3220016 = [[
Essential Breakthrough object for Kafka.
Incredibly hard gem, rumored to have protected someone from a lethal attack.]],
  str_item_intro_3220017 = [[
Essential Breakthrough object for Rabbie.
Close examination reveals a perpetual jumping flame resembling a rabbit. Rabbie's lucky charm.]],
  str_item_intro_3220018 = [[
Essential Breakthrough object for Regina.
A sun-like gem that illuminates even the darkest corner, as well as taking Regina's music to the next level.]],
  str_item_intro_3220019 = [[
Essential Breakthrough object for Victoria.
This gem contains innumerable tear-shaped particles, supposedly blood from Victoria herself.]],
  str_item_intro_3220021 = [[
Essential Breakthrough object for Jola.
When Jola touches this gem, chain-shaped green ripples dance out on the rim.]],
  str_item_intro_3220023 = [[
Essential Breakthrough object for Connolly.
The condensation of a black waterdrop that morphs into an adamant gem in Connolly's hand.]],
  str_item_intro_3220024 = [[
Essential Breakthrough object for Benny and Curo.
This gem sparkles with red and black light, and you can even hear the sound of swords slashing and bullets if you get close to it.]],
  str_item_intro_3220025 = [[
Essential Breakthrough object for Charon.
As Charon's favorite, this gem sparkles with red and black stripes.]],
  str_item_intro_3220026 = [[
Essential Breakthrough object for Uriel.
Gem with occasional flashes of brownish and blackish flames. Very pretty to behold but also nihilistic...]],
  str_item_intro_3220027 = [[
Essential Breakthrough object for Michael.
Reportedly discovered in a severe thunderstorm, this gem grants its genuine owner great power.]],
  str_item_intro_3220028 = [[
Essential Breakthrough object for Raphael.
Transparent gem with marvelous power. When Raphael uses it, her healing ability would be boosted.]],
  str_item_intro_3220029 = [[
Essential Breakthrough object for Gabriel.
This gem emits a beautiful green glow when Gabriel activates it.]],
  str_item_intro_3220030 = [[
Essential Breakthrough object for Sinsa.
This gem emits intense heat at all times. Only Sinsa can wear it.]],
  str_item_intro_3220033 = [[
Essential Breakthrough object for Vice.
This gem shows wondrous flickers of different colors with each view as if flashing snippets of the past...]],
  str_item_intro_3220036 = [[
Essential Breakthrough object for Hydrad.
An ominous gem. Hydrad, however, is not afraid of it and even often brags that "It's just like me."]],
  str_item_intro_3220038 = [[
Essential Breakthrough object for Gronru.
It is rumored to contain many artificial elements, thus unlikely a product of nature but the vestige of ancient civilization.]],
  str_item_intro_3220040 = [[
Essential Breakthrough object for Joanie Boom.
Better not fiddle with this combustible gem, for safety's sake.]],
  str_item_intro_3220041 = [[
Essential Breakthrough object for Ms. Blanc.
A gem with an elegant glow that is soothing to behold. A perfect fit for any elegant lady.]],
  str_item_intro_3220042 = [[
Essential Breakthrough object for Barton.
This gem conceals red flame-of-war spots that only Barton can see. Or perhaps the manifestation of his deepest desire.]],
  str_item_intro_3220044 = [[
Essential Breakthrough object for Vivian.
A gem with an intense glow. A fantastic accessory for the sword hilt.]],
  str_item_intro_3220045 = [[
Essential Breakthrough object for Nails.
A certain someone called the incredibly sharp edge of this gem a representation of punishment...]],
  str_item_intro_3220046 = [[
Essential Breakthrough object for Keating.
Many "poems" would pop into Keating members' minds when they wear this gem.]],
  str_item_intro_3220048 = [[
Essential Breakthrough object for Dayna.
Dayna can learn more fighting skills with this gem.]],
  str_item_intro_3220054 = [[
Essential Breakthrough object for Nadine.
A white gem that always emits a soft, soothing glow.]],
  str_item_intro_3220055 = [[
Pittman often finds himself lost on the path to the truth, but this crystal brings him power and resolution.
Essential Breakthrough object for Pittman.]],
  str_item_intro_3220056 = [[
Essential Breakthrough object for Constantine.
This gem automatically records everything when Constantine hunts down Eclipsites and is Constantine's best partner.]],
  str_item_intro_3220057 = [[
Essential Breakthrough object for Philyshy.
This crystal sometimes releases a breath of darkness for one to see Philyshy's true nature when up close.]],
  str_item_intro_3220060 = [[
Essential Breakthrough object for Jona.
The melted bronze base of this crystal is forged from Jona's bullets and shows off her past feats.]],
  str_item_intro_3220061 = [[
Essential Breakthrough object for Chandra.
Upon close examination, inside this transparent gem is a swirl of dancing energy, as if it contains various emotions she collected.]],
  str_item_intro_3220062 = [[
Essential Breakthrough object for Sylva.
It is said that this gem was found in the depths of Windward Forest. It feels cool to the touch and represents Sylva the Forest Keeper.]],
  str_item_intro_3220064 = [[
Essential Breakthrough object for Wrath.
This hefty gem becomes light in Wrath's hand, enough to hover into the air...]],
  str_item_intro_3220065 = [[
When Tweety gazes into this crystal, she can see the vague image of her hometown, Cloud Mountain...
Essential Breakthrough object for Tweety.]],
  str_item_intro_3220067 = [[
Essential Breakthrough object for Alice.
This gem transforms into a heart shape and exudes a special vitality when Alice holds it.]],
  str_item_intro_3220068 = [[
Essential Breakthrough object for Wendy
This extremely light gem is also extremely tough, mirroring Wendy's personality.]],
  str_item_intro_3220070 = [[
Essential Breakthrough object for Leona.
Gaze into this crystal and hear the thundering roar of a dragon in your ears.]],
  str_item_intro_3220071 = [[
Essential Breakthrough object for Taki.
The scene of a giant fire-breathing dragon appears in this gem occasionally, which symbolizes Taki because this gem belongs only to him.]],
  str_item_intro_3220073 = [[
Essential Breakthrough object for Patty & Patsy.
This gem alternates between giving off crimson glows and sense of darkness.]],
  str_item_intro_3220075 = [[
Essential Breakthrough object for Odi.
You can hear faint statics when putting this gem to your ear. Perhaps it may be used for communication.]],
  str_item_intro_3220076 = [[
Essential Breakthrough object for Kleken.
A wondrous gem that shows different hues from different angles. Even more ever-changing in Kleken's hand.]],
  str_item_intro_3220077 = [[
Essential Breakthrough object for Bethlehem.
Clear and extremely chilly to the touch. It supposedly evolved from the first ice block in history, and only the Queen of the North can wear it.]],
  str_item_intro_3220078 = [[
Essential Breakthrough object for Robyn.
Emerald green gem rumored to ward off all things toxic for the wearer. Robyn's talisman.]],
  str_item_intro_3220079 = [[
Essential Breakthrough object for Michenny.
An impeccably square and balanced gem, perfect for maintaining the balance of scales.]],
  str_item_intro_3220081 = [[
Essential Breakthrough object for Brock.
This gem feels very hot to the touch, reflecting someone's everlasting vigor.]],
  str_item_intro_3220083 = [[
Essential Breakthrough object for Lilliam.
When this gem nears its true master, it exhibits electrical patterns.]],
  str_item_intro_3220084 = [[
Essential Breakthrough object for Istvan.
Blue flames occasionally dance around the rim of this gem. If you get close, you can almost hear it call out for the Shadowlord.]],
  str_item_intro_3220085 = [[
Essential Breakthrough object for Jane.
Stare at this black gem long enough and you may see writings for records...]],
  str_item_intro_3220086 = [[
Essential Breakthrough object for Uriah.
This white, elegant jade is in the shape of a flower.]],
  str_item_intro_3220087 = [[
Essential Breakthrough object for Beverly.
Spear-shaped lightning that looks just like Beverly's Lightning Spear flickers in this gem every now and then.]],
  str_item_intro_3220088 = [[
Essential Breakthrough object for Maggie.
This crystal sometimes flashes an odd yellow glow. Examine it up close and you can see the silhouette of a girl.]],
  str_item_intro_3220089 = [[
Essential Breakthrough object for Irridon.
This gem flashes occasional blue lightning and holds great power.]],
  str_item_intro_3220090 = [[
Essential Breakthrough object for Barbara.
Get close to this gem with a red base and you can hear noisy tunes playing.]],
  str_item_intro_3220091 = [[
Essential Breakthrough object for Chloe.
This white crystal seems to form teardrop-like condensations. Get close and you can hear gentle harp playing.]],
  str_item_intro_3220092 = [[
Essential Breakthrough object for Pact.
This gem is unbelievably hard, and supposedly never gets a scratch.]],
  str_item_intro_3220093 = [[
Essential Breakthrough object for Migard.
This gem that houses a mysterious energy seems like it was extracted from an artificial creature.]],
  str_item_intro_3220095 = [[
Essential Breakthrough object for Lester.
If you smell this gem, you'll feel like you're somewhere in the wilderness. Lester is able to use this to find the scent she likes.]],
  str_item_intro_3220096 = [[
Essential Breakthrough object for Sariel.
When Sariel holds this gem, it changes into the shape of a water droplet. This gem also grants Sariel immense power.]],
  str_item_intro_3220097 = [[
Essential Breakthrough object for Corax.
This gem feels as cold as ice and has extremely sharp edges. It can be used in place of knives.]],
  str_item_intro_3220098 = [[
Essential Breakthrough object for Cuscuta.
If you inspect this gem carefully, you'll see a withered black flower inside it.]],
  str_item_intro_3220099 = [[
Essential Breakthrough object for Areia.
The curse afflicting Areia seems to weaken when she looks at this gem...]],
  str_item_intro_3220100 = [[
Essential Breakthrough object for Sikare.
A starry sky is hidden in this gem. Some say that's the true source of Sikare's power.]],
  str_item_intro_3220101 = [[
Essential Breakthrough object for Ansia.
This has a wonderful brass luster and vibrates gently. The vibration is very close to the sound frequency of a certain wave band...]],
  str_item_intro_3220102 = [[
Essential Breakthrough object for Tessa.
Sporadic lightning flickers inside this gem at all times and bursts out if anyone approaches it. Only Tessa can hold it.]],
  str_item_intro_3220103 = [[
Essential Breakthrough object for Eicy.
If you stare into this gem, you'll see a frightening ray projected from it...]],
  str_item_intro_3220104 = [[
Essential Breakthrough object for Dawn.
This gem belongs to Dawn because it reflects the shadow of a white flower when she holds it and this flower is her spiritual sustenance.]],
  str_item_intro_3220105 = [[
Essential Breakthrough object for Eve.
Small arcs of lightning appear around this gem when Eve touches it. This is Eve's special power.]],
  str_item_intro_3220107 = "Regal Solamber",
  str_item_intro_3220108 = "Frostfire Solamber",
  str_item_intro_3220109 = "Mythos Solamber",
  str_item_intro_3220110 = "Requiem Solamber",
  str_item_intro_3220111 = [[
Essential Breakthrough object for Beryl.
This crystal turns blood red when held in Beryl's hands, becoming identical to the crystals on her body.]],
  str_item_intro_3220112 = [[
Essential Breakthrough object for Smokey.
This gem always seems to make nearby flammable objects combust inexplicably. This peculiar power only fades when it is in Smokey's hands.]],
  str_item_intro_3220113 = [[
Essential Breakthrough object for Bonacie.
When Bonacie touches this gem, a flood of inspiration fills her mind, allowing her to think up new and unforgettable movements.]],
  str_item_intro_3220114 = [[
Essential Breakthrough object for Genevieve.
Ever shining red, like a blazing flame, this gem sometimes makes whinnies...]],
  str_item_intro_3220115 = [[
When she wears this crystal, Naroxel can hear the voice of nature with perfect clarity, enhancing her ability to communicate with animals and plants.
Essential Breakthrough object for Naroxel.]],
  str_item_intro_3220116 = [[
Essential Breakthrough object for Fleur.
This gem can give Fleur plenty of design inspirations, bringing his "Mecha Manufacturing Plan" ever closer to realization.]],
  str_item_intro_3220117 = [[
When Gram holds this in his hand, he feels as though he has been whisked back to those days with the Stone Force, and his heart swells with emotion.
Essential Breakthrough object for Gram.]],
  str_item_intro_3220119 = [[
When Revy touches this gem, you can hear the droning sound of her giant blade grinding against chains, and can feel bursts of surging electricity.
Essential Breakthrough object for Revy.]],
  str_item_intro_3220120 = [[
Under the light of the sun, this gem radiates a luster akin to glorious white armor.
Essential Breakthrough object for Hedy.]],
  str_item_intro_3220121 = [[
This gem occasionally shows the figure of a short-haired young woman Paloma no longer recognizes...
Essential Breakthrough object for Paloma.]],
  str_item_intro_3220122 = [[
When Allura places this gem by her ear, she can hear the ticking of a clock, allowing her to exert her mastery over time more accurately.
Essential Breakthrough object for Allura.]],
  str_item_intro_3220123 = [[
With this gem, Cordy can handle any emergency with ease.
Essential Breakthrough object for Cordy.]],
  str_item_intro_3220126 = [[
This crystal can be affixed to the gem in front of Bethel's chest and enhances its brilliant luster.
Essential Breakthrough object for Bethel.]],
  str_item_intro_3220127 = [[
Essential Breakthrough object for Pasolo.
In Pasolo's hands, this crystal becomes extremely thin and light, and can dance in the air like a piece of paper in the wind.]],
  str_item_intro_3220129 = [[
This crystal is so light that Luke can even make it float in the air and dance like a butterfly.
Essential Breakthrough object for Luke.]],
  str_item_intro_3220131 = [[
The surface of the gem is carved with archaic words, and only Novio seems to understand its meaning.
Essential Breakthrough object for Novio.]],
  str_item_intro_3220132 = [[
A gem soaked in honey, with a lustrous, glowing sheen and a sweet scent.
Essential Breakthrough object for Lola.]],
  str_item_intro_3220133 = "A gem that bursts into a fiery glow whenever someone gets near, except for Kobayashi, for whom it turns to a gentle pink. Essential Breakthrough object for Tohru.",
  str_item_intro_3220134 = [[
A gem flashing occasional lightning, unexpectedly soft when held in hand.
Essential Breakthrough object for Kanna.]],
  str_item_intro_3220135 = [[
A warm current flows through this gem constantly. The calmer minds can hear the sound of a bubbling brook.
Essential Breakthrough object for Elma.]],
  str_item_intro_3220136 = [[
Stare at it long enough and you'll see things like the sky, ocean, mountains, rivers, towns, and finally a strange pair of eyes looking back at you.
Essential Breakthrough object for Lucoa.]],
  str_item_intro_3220137 = [[
You can hear inauspicious roars in this gem, with Fafnir's inaudible incantations among them.
Essential Breakthrough object for Fafnir.]],
  str_item_intro_3220138 = [[
It feels like you can see green threads when Siobhan is holding it...
Essential Breakthrough object for Siobhan.]],
  str_item_intro_3220139 = [[
Put this gem against your ear and listen carefully, you might be able to hear the sounds of an unknown entity being summoned.
Essential Breakthrough object for Erica.]],
  str_item_intro_3220140 = [[
A carefully scrubbed gem with a mixed fragrance of parchment and ink. You could almost hear the hum of reading and prayers.
Essential Breakthrough object for Florine.]],
  str_item_intro_3220141 = [[
A very hard gem that would give off a clear sound when hit by a bat. Excellent for Ruby's swing practice.
Essential for Ruby's Breakthrough.]],
  str_item_intro_3220142 = [[
An ordinary looking gem that could produce an illusion of raging flames under Rouge's gentle touch.
Essential Breakthrough object for Rouge.]],
  str_item_intro_3220143 = [[
A gem that occasionally glows pale pink and makes a refreshing and delightful sound when shaken gently.
Essential Breakthrough object for Rinne.]],
  str_item_intro_3220144 = [[
A plain-looking gem that's cool to the touch and emits a pale light in the dark.
Essential Breakthrough object for Kayano.]],
  str_item_intro_3220145 = [[
In Amemori's hands, this gem becomes lighter, occasionally emitting the word "patience."
Essential Breakthrough object for Amemori.]],
  str_item_intro_3220146 = [[
This gem smells faintly of freshly cooked food, and up close, it even seems to shine in a peculiar, fiery red.
Essential Breakthrough object for Yao.]],
  str_item_intro_3220147 = [[
A colorful gem that looks like it would taste really nice if only it was edible. Upon careful inspection, two similar but not identical lights can be seen in it.
Essential Breakthrough object for Momo&Anzu.]],
  str_item_intro_3220148 = [[
The stone is cold to the touch and emits a faint blue glow when illuminated by sunlight.
Essential Breakthrough object for Azure.]],
  str_item_intro_3220149 = [[
A mildly textured and seemingly innocuous stone. Occasionally, a silver-haired figure appears on its surface, and before you can see who it is, Roy hides the stone. Well, anyway, he's too tall for anyone to take it from him.
Essential Breakthrough object for Roy.]],
  str_item_intro_3220150 = [[
For some reason, this gem creaks all the time like a puppet being wound up.
Essential Breakthrough object for Lenore.]],
  str_item_intro_3220151 = [[
This gem is tough and scorching hot. Giles's touch can magically turn it into a ram's horn.
An essential item for Giles's Breakthrough.]],
  str_item_intro_3220152 = [[
May's grip can generate an image of a cat on the surface of this gem. At times, the silhouette of an Aurorian flashes by, but no one can tell who it is.
An essential item for May's Breakthrough.]],
  str_item_intro_3220153 = [[
Hand-polished by one of Illumina's most respected gemsmiths, only those who stand at the helm of the Illumina Federation can wield it.
Essential Breakthrough object for Reinhardt.]],
  str_item_intro_3220154 = [[
Whenever Vice is near, the gem starts to vibrate slightly, alternately emitting a red and green glow.
Essential Breakthrough object for Vice: Keen Sight.]],
  str_item_intro_3220187 = [[
A slightly sticky gemstone emits a sweet and delicate scent that can be detected as one approaches it. Li Tianxian always bears a satisfied smile every time he uses it. Maybe it's actually a candy bar?
Essential Breakthrough object for Li Tianxian.]],
  str_item_intro_3220188 = [[
This gem features a silky texture and a delicate floral fragrance. Upon closer inspection, you'll find its intricate patterns that shape a begonia flower.
Essential Breakthrough object for Dantang.]],
  str_item_intro_3221000 = "Can be redeemed for exclusive Aurorian Solamber.",
  str_item_intro_3221001 = "Can be redeemed for non-exclusive 5-Star Forest Aurorian Solamber.",
  str_item_intro_3221002 = "Can be redeemed for non-exclusive 5-Star Thunder Aurorian Solamber.",
  str_item_intro_3221003 = "Can be redeemed for non-exclusive 5-Star Fire Aurorian Solamber.",
  str_item_intro_3221004 = "Can be redeemed for non-exclusive 5-Star Water Aurorian Solamber.",
  str_item_intro_3221005 = "Can be redeemed for non-exclusive 6-Star Forest Aurorian Solamber.",
  str_item_intro_3221006 = "Can be redeemed for non-exclusive 6-Star Thunder Aurorian Solamber.",
  str_item_intro_3221007 = "Can be redeemed for non-exclusive 6-Star Fire Aurorian Solamber.",
  str_item_intro_3221008 = "Can be redeemed for non-exclusive 6-Star Water Aurorian Solamber.",
  str_item_intro_5840001 = "The most common Unique Tree seedpack for growing the most common Unique Trees.",
  str_item_intro_5840002 = "A Unique Tree Seedpack II for growing Unique Trees II with minor mutations.",
  str_item_intro_5840003 = "A Unique Tree Seedpack III for growing Unique Trees III with frequent mutations.",
  str_item_intro_5840004 = "A Unique Tree Seedpack IV for growing Unique Trees IV with complex mutations.",
  str_item_intro_3220155 = [[
A hard and heavy gem. Every so often, a huge black shadow can be seen flashing through it, accompanied by what appears to be the growl of a fierce beast.
Essential Breakthrough object for Barton: Deft Blades.]],
  str_item_intro_3220156 = [[
A rare gem. Take a close look and you'll notice its constantly fluctuating luster, like a token of an unyielding will.
Essential for Nina's Breakthrough.]],
  str_item_intro_3220157 = [[
A gem composed of such tough material that it doesn't crumble no matter how hard you drop it. How do we know? Well, you'll have to ask Sanae.
Essential for Sanae's Breakthrough.]],
  str_item_intro_3220158 = [[
Essential Breakthrough object for Joker.
A gem with a bright luster.
It bears a strong sense of rebellion.]],
  str_item_intro_3220159 = [[
Essential Breakthrough object for Queen.
A gem that is completely translucent.
It bears a strong sense of rebellion.]],
  str_item_intro_3220160 = [[
Essential Breakthrough object for Fox.
A gem that is warm to the touch.
It bears a strong sense of rebellion.]],
  str_item_intro_3220161 = [[
Essential Breakthrough object for Violet.
A flower-shaped gem.
It bears a strong sense of rebellion.]],
  str_item_intro_3220162 = [[
Essential Breakthrough object for Mona.
A gem bearing scratches seemingly made by sharp claws.
It bears a strong sense of rebellion.]],
  str_item_intro_3220164 = [[
At first glance, this gem seems to be filled with steam that turns into flames instantly, but regardless of what changes occur inside this gemstone, its sturdiness remains steadfast.
Essential Breakthrough object for Carleen: Smoldering Soul.]],
  str_item_intro_3220165 = [[
When Ciel looks closely at this crystal, she feels like she can see some mysterious formulas that bring her a steady stream of inspiration.
Essential Breakthrough object for Ciel.]],
  str_item_intro_3220166 = [[
This gem vibrates violently when there are wondrous beasts nearby.
Essential Breakthrough object for Fia.]],
  str_item_intro_3220167 = [[
This magical gem creates illusions of itself... Be careful and don't let it fool you.
Essential Breakthrough object for Jeno.]],
  str_item_intro_3220168 = [[
This gem is cool to the touch. The sound of waves can be heard inside it sometimes.
Essential Breakthrough object for Rainbow.]],
  str_item_intro_3220169 = [[
Whenever she holds this gemstone, Sadie feels an enormous sense of courage flowing from her palm into the rest of her body. Even her heartbeat changes accordingly!
Essential Breakthrough object for Sadie.]],
  str_item_intro_3220170 = [[
A gem with a strong smoky scent. What's more amazing is the occasional flickering image of a blade on its surface.
Essential Breakthrough object for Pollux.]],
  str_item_intro_3220171 = [[
When you listen to this marvelous gem up close, you can hear the caws of a raven coming from within.
Essential Breakthrough object for Casta.]],
  str_item_intro_3220172 = [[
If you look carefully, this gemstone flickers and flashes like the greatest moments in cinematic history. With it, Lilica's skills can reach even newer heights!
Essential Breakthrough object for Lilica.]],
  str_item_intro_3220173 = [[
When Minos fires his gun, the image of a raging minotaur seems to appear beneath the surface of this gemstone.
Essential Breakthrough object for Minos.]],
  str_item_intro_3220175 = [[
A gem that is covered in scars. You can feel its sharp edges and corners when it's within your grasp, but if you keep on holding it and never let go, your hands are heated by an inexplicable warmth.
Essential Breakthrough object for Axelia.]],
  str_item_intro_3220176 = [[
A gem that shines vibrantly with a myriad of colors. It glows brilliantly even without being polished, and the silhouette of a flying bird can be seen inside the gem from time to time.
Essential Breakthrough object for Beretta.]],
  str_item_intro_3220177 = [[
This colorful gem feels incredibly warm. If you carry it with you for long enough, you may even share Goldie's good luck.
Essential Breakthrough object for Goldie.]],
  str_item_intro_3220178 = [[
This gem is so hard, even if you were to hit it as hard as you could with a giant hammer, you wouldn't leave a scratch.
Essential Breakthrough object for Vic.]],
  str_item_intro_3220180 = [[
It feels solid, but bounces back if you press down on it. Brandy apparently uses this to train the speed of her shutter finger.
Essential Breakthrough object for Brandy.]],
  str_item_intro_3220181 = [[
The warmth of this stone in your hand is proof of Zhong Xu's passionate heart.
Essential Breakthrough object for Zhong Xu.]],
  str_item_intro_3220182 = [[
The color of this thin and tough gemstone changes according to the angle of light shining on it.
Essential Breakthrough object for Mu Yuebai.]],
  str_item_intro_3220183 = [[
This gemstone exudes a faint herbal fragrance with a slightly bitter taste and smells like Liqing's apothecary.
Essential Breakthrough object for Liqing.]],
  str_item_intro_3220184 = [[
It has a worn and weathered feel about it, but at the same time, it is very bright and beautiful.
Essential Breakthrough object for Jeriah.]],
  str_item_intro_3220185 = [[
Smooth to the touch, it appears as though Kya caresses it often. Upon closer inspection, there seems to be a moving dial within... is this a watch?
Essential Breakthrough object for Kya.]],
  str_item_intro_3220186 = [[
The pure, holy light enveloping this jewel gives people the feeling they'll tarnish its brilliance by touching it.
Essential Breakthrough object for Tina.]],
  str_item_intro_3220189 = [[
Hard to the touch, this stone reflects a dazzling light under the sun. If you smell it carefully, you can detect a hint of floral fragrance on it.
Essential Breakthrough object for Leyn.]],
  str_item_intro_3220190 = [[
An exquisitely polished gemstone cut with superb craftsmanship. Either way, it looks really expensive, so let's put it down carefully.
Essential Breakthrough object for Matthieu.]],
  str_item_intro_3220191 = [[
Though it looks very hard, it is unexpectedly soft and springy to the touch, like a dog's paw. You just can't stop yourself from squeezing over and over again.
Essential Breakthrough object for Hati.]],
  str_item_intro_3220192 = [[
This dull gemstone feels rough to the touch. Leo says this is proof that it has been polished by the wind and sand at the border.
Essential Breakthrough object for Leo.]],
  str_item_intro_3220193 = [[
Move close to it and you'll hear the distinct sound of rushing water. Perhaps this kind of surging undercurrent flows in Kristen's heart...
Essential Breakthrough object for Kristen.]],
  str_item_intro_3220199 = [[
Melodious bird-like sounds can be heard from inside this crystal-clear gemstone.
Essential Breakthrough object for Yingel.]],
  str_item_intro_3220200 = [[
A gemstone that Anatoli collected was produced in veins inside Eternal Night and transported thousands of miles back to Illumina. It is warm to the touch, and the reflection of someone can be seen vaguely on its surface.
Essential Breakthrough object for Anatoli.]],
  str_item_intro_3220201 = "At first glance, it appears to be your average garden-variety stone, but put it to your ear and listen carefully—you'll hear the clashing of two bellowing roars entwined, somehow making it seem even more dazzling.\nEssential Breakthrough object for Mia: Lustrous Soul.",
  str_item_intro_3220202 = [[
Gaze into this gemstone and you'll see what seems to be a sunny day after a thunderstorm. This is the future that awaits Lumopolis under his rule.
Essential Breakthrough object for Schwartz: Almighty Clamor.]],
  str_item_intro_3220203 = [[
A beautiful gemstone that radiates a colorful shimmer when exposed to sunlight, projecting the image of a divination book.
Essential Breakthrough object for Jakine.]],
  str_item_intro_3220204 = [[
A gemstone enshrouded by a warm light like candles in winter or street lamps in the dark that guide the way for those who are lost.
Essential Breakthrough object for Joshua.]],
  str_item_intro_3220205 = [[
An exquisite gemstone that Blanc often plays with. She says that the bottom of this gemstone reflects a red halo, but no one else can see it.
Essential Breakthrough object for Blanc: Pura Cordis.]],
  str_item_intro_3220206 = [[
Lorelei playfully claims this gemstone reeks of money, yet she absolutely adores it.
Essential Breakthrough object for Lorelei]],
  str_item_intro_3220207 = [[
Smooth on the surface yet sharp to the touch, does this crystal imply that beneath its glossy exterior also lie hidden scars of the past?
Essential Breakthrough object for Cena.]],
  str_item_intro_3220208 = [[
A blazing and dazzling crystal, spinning slowly...
Essential Breakthrough object for Bopper.]],
  str_item_intro_3220209 = [[
Essential Breakthrough object for Wrath: Proud Fervor.
It pricks anyone daring to touch, caused by the restless crimson lightning swirling within the crystal, awaiting her to conquer her chosen battlefield.]],
  str_item_intro_3220210 = "Essential Breakthrough object for Joselyne.\nUpon close observation, a gentle radiance pulsates at the very core of the gem—reminiscent of the chants of devoted worshippers and the holy light shattering the night.",
  str_item_intro_3220211 = [[
This gem was buried underground for eons until Antony excavated it, wiped away the dirt, and unearthed the root of its mystery.
Essential Breakthrough object for Antony.]],
  str_item_intro_3220212 = [[
It looks more like a naturally-formed ice crystal than a gemstone. Perhaps Zarya made it herself?
Essential Breakthrough object for Zarya.]],
  str_item_intro_3220213 = [[
No. 33 found this gemstone near the ruins she once guarded. Whenever her loneliness becomes too much to take, No. 33 regards it as her companion and tries to communicate with it.
Essential Breakthrough object for No. 33.]],
  str_item_intro_3220214 = "Essential Breakthrough object for Rebecca. This gemstone was given to Rebecca by her parents. Whenever she holds it tightly, she can feel the everlasting warmth of her family.",
  str_item_intro_3220215 = [[
A gemstone formed from Rebecca's venom. Isa feels like her body is filled with energy whenever she has this with her.
Essential Breakthrough object for Isa.]],
  str_item_intro_3220216 = [[
This ordinary-looking stone contains an unknown power. No one knows what trap or clockwork creation Xuan Ji will embed this stone into.
Essential Breakthrough object for Xuan Ji.]],
  str_item_intro_3220218 = [[
This mysterious gem is exactly the same weight as a Nightium. If you listen carefully, you can even hear the sound of Nightium rattling inside the gem.
Essential Breakthrough object for Sheol.]],
  str_item_intro_3220219 = [[
This heavy brilliant gem feels like it is trembling slightly from distant emotions in your hand. It's almost as if past events that have been buried deeply are about to burst out.
Essential Breakthrough object for Istvan: Scarred Pith]],
  str_item_intro_3220220 = "Vergil appraised this gem as having high artistic value. It's reported that he likes to carry this gem with him like a good luck charm. Essential Breakthrough object for Vergil.",
  str_item_intro_3220221 = [[
An extremely profound and breathtaking gemstone of unknown origin. It seems to foretell the mysterious and unpredictable future of the Aurorians...
Essential Breakthrough object for Algol.]],
  str_item_intro_3220223 = [[
A stone formed from scales in an ancient era, perhaps holding the distant musings of the Chen'ni's clan.
Essential Breakthrough object for Chen'ni.]],
  str_item_intro_3220224 = [[
A stone possibly harboring mysterious powers. Luo Song might use it to knock some sense into mischievous fiendlings.
Essential Breakthrough object for Luo Song.]],
  str_item_intro_3220225 = [[
A gemstone with a protective hue that blends seamlessly with the ice once it falls into the snow, making retrieval nearly impossible. So, it's best to handle it with care.
Essential Breakthrough object for Tiare.]],
  str_item_intro_3220227 = [[
A chunk of Lumamber with abnormally sharp edges and corners. Although great care must be used when handling this Lumamber, a faint and gentle warmth can be felt coming from it.
Essential Breakthrough object for Rachel.]],
  str_item_intro_3220228 = [[
A beautiful gemstone that exudes both a brilliantly colorful luster and the faintest hint of candy.
Essential Breakthrough object for Zeta.]],
  str_item_intro_3220229 = [[
An ordinary stone that Batia says can be obtained by using a pickaxe and a furnace as well as other methods.
Essential Breakthrough object for Batia.]],
  str_item_intro_3220230 = [[
The instant you touch this gemstone, you can hear ancient whispers, not from afar or near your ear, but deep in your mind, like an ancient being pulsing and struggling to break free.
Essential Breakthrough object for Victoria: Elegy.]],
  str_item_intro_3220231 = [[
A gemstone with an eerie, vivid color. The moment you touch it, blood begins to drip down the walls. Only when you pull back your hand in fear do you see it's all a hallucination.
Essential Breakthrough object for Wilhelm.]],
  str_item_intro_3220232 = [[
As soon as you grasp this gemstone, you see thousands of blades falling from the sky, cutting into your flesh. You scream in pain, but when you look at yourself, you find no harm.
Essential Breakthrough object for Nails: Sacred Rite.]],
  str_item_intro_3220233 = [[
A gem excavated from the ruins. Perhaps you can feel the passion of adventure from it.
Essential Breakthrough object for Ryza.]],
  str_item_intro_3220234 = [[
A gem excavated from the ruins. Perhaps you can feel the beauty of music from it.
Essential Breakthrough object for Klaudia.]],
  str_item_intro_3220235 = [[
A gem excavated from the ruins. Perhaps you can feel a noble temperament from it.
Essential Breakthrough object for Patricia.]],
  str_item_intro_3220237 = [[
A crystal-clear gem with the touch of a cool breeze above the clouds and the moist softness of the deep sea.
Hold it in your hand, and you will hear a quiet whisper, "Don't be afraid. The world is sleeping in your dream."
Essential Breakthrough object for Maya.]],
  str_item_intro_3220238 = [[
It looks plain at first, but when you touch the edge, you'll see how sharp it really is. There's a pulsing energy within, like unspoken rage.
Essential Breakthrough object for Mithra.]],
  str_item_intro_3231101 = [[
Common Gift. Best effect when given to Lumopolis Aurorians.
Thin, delicate sheet of silver as light as feather. A favorite in Lumopolis.]],
  str_item_intro_3232101 = [[
Valuable Gift. Best effect when given to Lumopolis Aurorians.
Lumamber packaged in gold. The primary gem of high-society Lumopolis.]],
  str_item_intro_3233101 = [[
Best effect when given to Lumopolis Aurorians.
Very precious handicraft made with Lumina gem mounted on valuable white crystal.]],
  str_item_intro_3231102 = [[
Common Gift. Best effect when given to Umbraton Aurorians.
Replica of different famous paintings. Popular in Umbraton.]],
  str_item_intro_3232102 = [[
Valuable Gift. Best effect when given to Umbraton Aurorians.
Only certain tycoons in Umbraton get an occasional sip of this precious libation.]],
  str_item_intro_3233102 = [[
Best effect when given to Umbraton Aurorians.
Alluring gem with a unique green shine, very sought after in Umbraton.]],
  str_item_intro_3231103 = [[
Common Gift. Best effect when given to Rediesel Wrench Aurorians.
A substance leftover from the old times. Rediesel Wrench folks use it for decoration or buttering up their Colossus.]],
  str_item_intro_3232103 = [[
Valuable Gift. Best effect when given to Rediesel Wrench Aurorians.
Key to dynamites, ammo, and explosives. Internal hard currency of the Rediesel Wrench.]],
  str_item_intro_3233103 = [[
Best effect when given to Rediesel Wrench Aurorians.
Rare strong liquor that stokes any drinker after just one shot. Loved by all Rediesel Wrench folks.]],
  str_item_intro_3231104 = [[
Common Gift. Best effect when given to Illumina Aurorians.
Intro-level book in Illumina Federation, with extensive pictorials for easy learning.]],
  str_item_intro_3232104 = [[
Valuable Gift. Best effect when given to Illumina Federation Aurorians.
Illumina Federation guidebook that teaches the reader how to apply science to deal with various problems.]],
  str_item_intro_3233104 = [[
Best effect when given to Illumina Aurorians.
For internal use only in Illumina Federation, including all fields of knowledge known to the federation.]],
  str_item_intro_3231105 = [[
Common Gift. Best effect when given to Northland Aurorians.
Crystal of a snowflake at the moment it was formed from water. Northlanders believe it holds powerful magic and love to collect it.]],
  str_item_intro_3232105 = [[
Valuable Gift. Best effect when given to Northland Aurorians.
A very precious colorful gem discovered beneath a rainbow, believed by Northlanders to bring lasting good luck.]],
  str_item_intro_3233105 = [[
Best effect when given to Northland Aurorians.
A sheet of colorful ice taken from the ever-frozen Lake Mirror in Northland. A favorite of Northlanders.]],
  str_item_intro_3231106 = [[
Common Gift. Best effect when given to True Order Aurorians.
Ancient scarab encased in amber. The True Order believes it holds mysterious power.]],
  str_item_intro_3232106 = [[
Valuable Gift. Best effect when given to True Order Aurorians.
Scroll containing inscrutable revelations. Many secrets will be revealed should True Order members decipher it.]],
  str_item_intro_3233106 = [[
Best effect when given to True Order Aurorians.
The True Order believes it contains the ultimate revelation that will change the present civilization-as-we-know-it.]],
  str_item_intro_3231107 = [[
Common Gift. Best effect given to Independent Aurorians.
Lightweight, compact dehydrated ration popular among small settlements.]],
  str_item_intro_3232107 = [[
Valuable Gift. Best effect when given to Independent Aurorians.
Magical wonder-potion that can make a doctor out of anyone in some settlements.]],
  str_item_intro_3233107 = [[
Best effect when given to Independent Aurorians.
Pieces of a treasure map sought after by many people who felt it's worth the gamble.]],
  str_item_intro_3232108 = [[
Common Gift. Best effect when given to Longzhou Aurorians.
A foldable fan with a bamboo frame and paper surface illustrated with charming mountains and rivers. It is used in the dark rooms of the main halls in Longzhou.]],
  str_item_intro_3233108 = [[
Valuable Gift. Best effect when given to Longzhou Aurorians.
This decorative knot made of red rope symbolizes a heartfelt connection and mutual love and is one of the most important gifts in the hearts of the Longzhou people.]],
  str_item_intro_3231201 = [[
Common Gift. Best effect when given to Aurorians with childlike innocence.
Loved by anyone who's a child at heart. It comes in five flavors and you can blow whistles with it.]],
  str_item_intro_3232201 = [[
Valuable Gift. Best effect when given to Aurorians with childlike innocence.
Entertainment product for anyone who's a child at heart. Players play by verbal descriptions.]],
  str_item_intro_3233201 = [[
Best effect when given to Aurorians with childlike innocence.
Model favored by anyone who's a child at heart. Very detailed and now out of production.]],
  str_item_intro_3231202 = [[
Common Gift. Best effect when given to romantic Aurorians.
Hand-crafted doll favored by romantics. It resembles both a rabbit and a bear. Creator unknown.]],
  str_item_intro_3232202 = [[
Valuable Gift. Best effect when given to romantic Aurorians
It's very romantic to see the beautiful array of lights inside the flask in a dim setting.]],
  str_item_intro_3233202 = [[
Best effect when given to romantic Aurorians.
Bookmark made from a rare plant, featuring changing patterns and colors.]],
  str_item_intro_3231203 = [[
Common Gift. Best effect when given to Aurorians into esoterica.
Famous for its odd appearance, this insect attracts collectors of curios.]],
  str_item_intro_3232203 = [[
Valuable Gift. Best effect when given to Aurorians into esoterica.
The crystallized spiky fossil of an unknown creature for the extremely curios collectors.]],
  str_item_intro_3233203 = [[
Best effect when given to Aurorians into esoterica.
Rotten wood collected by the curious because strange whispers can sometimes be heard at its cross section.]],
  str_item_intro_3231204 = [[
Common Gift. Best effect when given to noble Aurorians.
Compact, light, exquisitely sculpted silver bell believed by sophisticated folks to be a good luck charm.]],
  str_item_intro_3232204 = [[
Valuable Gift. Best effect when given to noble Aurorians.
Rare ore that shines in different colors under different intensity of light. A present among nobles.]],
  str_item_intro_3233204 = [[
Best effect when given to noble Aurorians.
Special and scarce materials adored by nobles. Mostly from frigid regions, it's soft, light but very durable.]],
  str_item_intro_3231205 = [[
Common Gift. Best effect when given to forthright Aurorians.
A specialty from the wasteland. Straightforward people enjoy this unique taste very much.]],
  str_item_intro_3232205 = [[
Valuable Gift. Best effect when given to forthright Aurorians.
A box of tools for most crafting and repairing needs. A particular favorite of no-nonsense people.]],
  str_item_intro_3233205 = [[
Best effect when given to forthright Aurorians.
Able to measure biological and mechanical functions. Perfect product for intuitive people.]],
  str_item_intro_3239997 = "These come in all kinds of flavors! Give to Aurorians to significantly increase Affinity.",
  str_item_intro_3239998 = "Give it to Aurorians to increase Affinity significantly!",
  str_item_intro_3239999 = "Irresistible chocolate! Give it to Aurorians to increase Affinity significantly!",
  str_item_intro_3300001 = "Very hard substance but nonmetal... It seems to be a biological compound from ancient times, able to repair certain damaged areas of a Colossus and reconnect energy conduits.",
  str_item_intro_3300002 = "Obviously augmented Colossus patch, sufficient to fortify the interior of a Colossus.",
  str_item_intro_3300003 = "Not only durable but also flexible, with unknown scripts fading in and out. Necessary material for restoring certain key facilities of a Colossus.",
  str_item_intro_3300004 = "Necessary for upgrading the Bridge, a necessary Colossus installation. Very rare. Please use with care.",
  str_item_intro_3300005 = "A magical cube with an intriguing structure, possibly left behind by a brave explorer. If the information etched upon it is entered into the Colossus' database, a new room may be unlocked.",
  str_item_intro_3300006 = "This plugin has been buried in the ground for many years. It looks just like the one Soroz lost seventeen years ago! You can use it to unlock a room in the Colossus.",
  str_item_intro_3400001 = "Get 1 of every basic material for Water ascension.",
  str_item_intro_3400002 = "Get 1 of every basic material for Fire ascension.",
  str_item_intro_3400003 = "Get 1 of every basic material for Forest ascension.",
  str_item_intro_3400004 = "Get 1 of every basic material for Thunder ascension.",
  str_item_intro_3400005 = "Get 1 of every regular material for Water ascension.",
  str_item_intro_3400006 = "Get 1 of every regular material for Fire ascension.",
  str_item_intro_3400007 = "Get 1 of every regular material for Forest ascension.",
  str_item_intro_3400008 = "Get 1 of every regular material for Thunder ascension.",
  str_item_intro_3400009 = "Get 1 of every advanced material for Water ascension.",
  str_item_intro_3400010 = "Get 1 of every advanced material for Fire ascension.",
  str_item_intro_3400011 = "Get 1 of every advanced material for Forest ascension.",
  str_item_intro_3400012 = "Get 1 of every advanced material for Thunder ascension.",
  str_item_intro_3400013 = "Get 1 random basic material for Water ascension.",
  str_item_intro_3400014 = "Get 1 random basic material for Fire ascension.",
  str_item_intro_3400015 = "Get 1 random basic material for Forest ascension.",
  str_item_intro_3400016 = "Get 1 random basic material for Thunder ascension.",
  str_item_intro_3400017 = "Get 1 random regular material for Water ascension.",
  str_item_intro_3400018 = "Get 1 random regular material for Fire ascension.",
  str_item_intro_3400019 = "Get 1 random regular material for Forest ascension.",
  str_item_intro_3400020 = "Get 1 random regular material for Thunder ascension.",
  str_item_intro_3400021 = "Get 1 random advanced material for Water ascension.",
  str_item_intro_3400022 = "Get 1 random advanced material for Fire ascension.",
  str_item_intro_3400023 = "Get 1 random advanced material for Forest ascension.",
  str_item_intro_3400024 = "Get 1 random advanced material for Thunder ascension.",
  str_item_intro_3400025 = "Get 1 of every basic material for ascension.",
  str_item_intro_3400026 = "Get 1 of every regular material for ascension.",
  str_item_intro_3400027 = "Get 1 of every advanced material for ascension.",
  str_item_intro_3400028 = "Get 1 random basic material for ascension.",
  str_item_intro_3400029 = "Get 1 random regular material for ascension.",
  str_item_intro_3400030 = "Get 1 random advanced material for ascension.",
  str_item_intro_3400031 = "Common Raw Jasper. Get 1 random Jasper I (Blue, Red, Yellow, or Green).",
  str_item_intro_3400032 = "Collection of various jaspers. Get 1 Jasper I for each color (Blue, Red, Yellow, and Green).",
  str_item_intro_3400033 = "Common Raw Jasper. Get 1 random Jasper II (Blue, Red, Yellow, or Green).",
  str_item_intro_3400034 = "Collection of various jaspers. Get 1 Jasper II for each color (Blue, Red, Yellow, and Green).",
  str_item_intro_3400035 = "Raw Jasper of even more brilliant color. Get 1 random Jasper III (Blue, Red, Yellow, or Green).",
  str_item_intro_3400036 = "Collection of various jaspers. Get 1 Jasper III for each color (Blue, Red, Yellow, and Green).",
  str_item_intro_3400037 = [[
Gift from an anonymous source. Open and see what's inside.
Use to get 1 random Common Gift.]],
  str_item_intro_3400038 = [[
Exquisite gift pack from an anonymous source. There should be better presents inside, right?
Use to get 1 random Valuable Gift.]],
  str_item_intro_3400039 = [[
Presents inside the stunning package must be very valuable. Open it!
Use to get a random Aurorian gift of very high value.]],
  str_item_intro_3400040 = [[
Transparent box made from crystal and fortified with Luminatics. Light and sturdy, it contains precious Lumamber.
Use to get 50 Lumamber.]],
  str_item_intro_3400041 = [[
Strongbox for gold issued by Lumopolis. Seem everywhere now with the popularity of Nightium.
Contains 100,000 Nightium.]],
  str_item_intro_3400042 = [[
A crystal case that has a faint glow and stores enough Lumina to fully recharge prism.
Use to get 10 Prism.]],
  str_item_intro_3400043 = [[
Square crystal box with a glowing center that supplies more energy to prism.
Use to get 60 Prism.]],
  str_item_intro_3400044 = [[
A large chest that is made out of polished crystal and has elaborate decorations. It contains enough Lumina to recharge prism with more energy than they had before.
Use to get 50 Prism.]],
  str_item_intro_3400045 = [[
Large crystal case with faint glow storing enough Lumina to fully recharge several prism.
Use to get 60 Prism.]],
  str_item_intro_3400046 = "Supply Kit developed by the Aurorian Coalition. Get 1 of the following random materials: White Night Stone, Destiny Champagne I, Pine Dew, Rediesel Extract, Battle Archive I, Ancient Scroll, Tales of Survival, Bone Strengthening Pill.",
  str_item_intro_3400047 = "Supply Kit developed by the Aurorian Coalition. Get 1 of the following random materials: Morning Stone, Destiny Champagne III, Pine Frost, Rediesel Concentrate, Battle Archive II, Ancient Book, Survival 101, Marrow Cleansing Pill.",
  str_item_intro_3400048 = "Supply Kit developed by the Aurorian Coalition. Get 1 of the following random materials: Daybreak Stone, Destiny Champagne III, Tear of Pine, Rediesel Essence, Battle Archive III, Ancient Book, Survivalpedia, Reconstruction Pill.",
  str_item_intro_3400049 = "In Northland, there stands a tall tower with a beacon shining at its peak. As long as its light never dies, the Eclipsites shall never pose a threat to the continent's northernmost land.",
  str_item_intro_3400050 = [[
Unlocks the assistant: Vice Casual Wear.
Vice's casual look.]],
  str_item_intro_3400052 = [[
Unlocks the background: Snowy Forest.
This dense forest at the border of the Northland is covered with a thick layer of snow in winter. Those who enter this picturesque forest by mistake often get lost in it.]],
  str_item_intro_3400053 = [[
Unlocks the background: Far East Dojo.
It's a place in the Far East, used to practice martial arts as well as to meditate.]],
  str_item_intro_3400054 = [[
Unlocks the background: Marvelous Sky.
In the ancient lost city, this sky was once the greatest solace for its inhabitants.]],
  str_item_intro_3400055 = [[
Unlocks the background: Perfect Stage.
The place where the girls made their performance in the summer. Although a long time has passed, it feels like nothing's changed.]],
  str_item_intro_3400056 = [[
Unlocks the background: Sakura Court Hallway.
The Far East style hallway and courtyard offers a unique scenery during the cherry blossom season.]],
  str_item_intro_3400057 = [[
Unlocks the background: Legion Commander's Train.
When the four Legion Commanders of the Illumina Federation rode the special train together, something serious must have happened...]],
  str_item_intro_3400058 = [[
Unlocks the background: Oasis.
One of the Rediesel Wrench's main strongholds located in an area with complex and diverse terrain.]],
  str_item_intro_3400059 = [[
Unlocks the background: Four Angels.
The four knight commanders represent the formidable power of Lumo Nobles.]],
  str_item_intro_3400060 = [[
Unlocks the background: Summer Night Party.
At the peak of the summer night party, the girls gave themselves over to the music. Although the party is over, it's as if we can still hear their laughter and singing.]],
  str_item_intro_3400061 = [[
Unlocks the background: Blazing Tooth.
The canyon, named after its jagged features, has steep hills that are notoriously difficult to navigate.]],
  str_item_intro_3400062 = [[
Unlocks the background: Mystery Mansion.
A luxurious house of unknown origin and unclear ownership, it promises a leisurely and carefree time...]],
  str_item_intro_3400063 = [[
Unlocks the background: Circular System.
Originated from an ancient region, what secret does it hold?]],
  str_item_intro_3400064 = [[
Unlocks the background: Chord Link.
A mysterious force from a mysterious space...]],
  str_item_intro_3400065 = [[
Unlocks the background: Piano Duet.
Remember the moment when you started this with Vice?]],
  str_item_intro_3400066 = [[
Unlocks the background: Eraveil Colossus.
Colossuses have appeared in Eraveil again. Does that mean anything?]],
  str_item_intro_3400067 = [[
Unlocks the background: Letter from the Skies.
The wind brought this letter, telling the Caelestite that it was time to go home.]],
  str_item_intro_3400068 = [[
Unlocks the background: Serene Cemetery.
A secluded place in Eraveil. Even time stands still here.]],
  str_item_intro_3400069 = [[
Unlocks the background: Decorated Post.
The Eraveil Post has been newly decorated. Look forward to the holiday nights in the days to come.]],
  str_item_intro_3400070 = [[
Unlocks the background: Holiday Memories.
It was the first holiday night I spent in Eraveil...]],
  str_item_intro_3400071 = [[
Unlocks the Background: Umbraton Street at Night.
When night falls on Umbraton, the streets are quiet, yet a hint of danger lurks.]],
  str_item_intro_3400072 = [[
Unlocks the background: Gloom of the Night.
The Umbraton night swallows everything it touches. Can a ray of light pierce through?]],
  str_item_intro_3400073 = [[
Unlocks the background: Andersen Mansion.
This imposing manor reflects its owner's wealth and elegance.]],
  str_item_intro_3400074 = [[
Unlocks the background: Cloud Blossom Hotel.
Excellent food, great hot springs, and they even provide yukatas!]],
  str_item_intro_3400075 = [[
Unlocks the background image: Harbor City Pier.
The area next to the port of Harbor City is the best place to enjoy the breeze under the clear sky!]],
  str_item_intro_3400076 = [[
Unlocks the background: Summer Night.
It would be amazing if such moments lasted forever.]],
  str_item_intro_3400077 = [[
Unlocks the background: Beach Thunder Warning.
Smash it, and the game will be finished before the schedule!]],
  str_item_intro_3400078 = [[
Unlocks the background: Church Memory.
A decaying building in Euphoria. Like all other places, it's only good for shelter.]],
  str_item_intro_3400079 = [[
Unlocks the background: Mysterious Land.
A hidden, nameless land where too much of the past has been buried. Will these secrets ever see the light of day again?]],
  str_item_intro_3400080 = [[
Unlocks the background: Sacrifice?
He chose to sacrifice himself against the Eclipsites charging at him. However, nobody knew that this was just one part of his plan...]],
  str_item_intro_3400082 = [[
Unlocks the background: Pursuit of Truth.
They believe what the world considers common knowledge to all be false. The real truth lies far beyond what their eyes can perceive, just waiting for them to pursue it.]],
  str_item_intro_3400083 = [[
Unlocks the background: Colossus Stage.
A fully-equipped stage has been set up near the bar on Soroz for everyone to show off their talents.]],
  str_item_intro_3400084 = [[
Unlocks the background: Ancient Abandoned City.
Just the sight of the huge collapsed building is enough to paint a picture of how catastrophic that ancient war was.]],
  str_item_intro_3400085 = [[
Unlocks the background: Under the Winter Sky.
If you see a shining sword and a flash of blond hair whipping through the air, it's probably the Queen of the North making her rounds under the winter sky as she watches over her realm with vigilant eyes each winter.]],
  str_item_intro_3400086 = [[
Unlocks the background: Aurora Sky.
Even in Northland, this kind of aurora that covers every inch of the sky and fades into the horizon is rare. They say that whenever it appears, it may have an unknown effect on the future...]],
  str_item_intro_3400087 = [[
Unlocks the background: Road of Song.
In a Colossus that wanders through countless lands, the figure of a bright young star graces the halls. Her divine song, imbued with the power of hope, will soon spread throughout the continent.]],
  str_item_intro_3400088 = [[
Unlocks the background: Deck of The Shadowind.
Only this huge, solid deck can bear such a tall castle.]],
  str_item_intro_3400089 = [[
Unlocks the background: Eastern Docks.
The docks, houses, and boats of the continent on the other side of the sea are quite different from those in Astra, but the noisy, bustling scenes of life remain the same.]],
  str_item_intro_3400090 = [[
Unlocks the background: Comrades No Longer.
After fighting side by side with the Grand Marshal, defeating countless enemies together, the time has come to fight against her.
Fate, why do you mock me so?]],
  str_item_intro_3400091 = [[
Unlocks the background: Rediesel Courier.
The Rediesel Desert branch of the Courier Union seems to have gradually adapted to life in the Rediesel Desert.]],
  str_item_intro_3400092 = [[
Unlocks the background: Jeriah's Office.
Jeriah handles her daily matters here and has imprinted this place with her personal style.]],
  str_item_intro_3400093 = "Unlocks the background: Carefree Place.\nIn this mood, cafes, restaurants, or bars all have one common function—rest, recovery, and a place for everyone to have a leisurely time.",
  str_item_intro_3400094 = [[
Unlocks the background: Winter Wedding
Those crystal-clear decorations reflect the flawless and transparent figures of the couple and represent their pure feelings. Not even the cold can resist close contact with passionate hearts at a winter wedding.]],
  str_item_intro_3400099 = [[
Unlocks the background: The Shadow in the Flames.
As the scorching demons attacks from all sides, a figure extends a helping hand...]],
  str_item_intro_3400100 = [[
Unlocks the background: Warehouse Overview.
Storage spaces surround, for as far as the eye can see. Perhaps they hide the secrets of some unknown past.]],
  str_item_intro_3400101 = [[
Unlocks the background: Uptown Vista.
An immaculate and elegant haven, celebrated not just as the unconquerable heart of Lumopolis but as the center of the whole continent.]],
  str_item_intro_3400102 = [[
Unlocks the background: Romping Siblings.
A heartwarming scene of siblings immersed in laughter. Though countless days and nights have passed, the memory remains vivid, etched forever in their hearts.]],
  str_item_intro_3400103 = [[
Unlocks the background: Nightfall Plaza.
The resplendent Center Square in Lumopolis glows magnificently even as the night descends, rivaling its daytime brilliance.]],
  str_item_intro_3400109 = [[
Unlocks the background: Dawn Academy.
There exists a place in Lumopolis where devout believers study the teachings of the God of Light, and all who pass through its hallowed doors are filled with respect.]],
  str_item_intro_3400110 = [[
Unlocks the background: Mysterious Ruin.
In this unknown space deep beneath Northland, it seems as though some artificial device is still active.]],
  str_item_intro_3400111 = [[
Unlocks the background: Gentle Starlight.
A sleepless night alone, on the Bridge beneath the starry sky. You can still hear the music of the universe without even having to press the control panel's keys.]],
  str_item_intro_3400112 = [[
Unlocks the background: Tranquil Afternoon.
Lumopolis is home to many elaborate and warm little gardens where the nobles enjoy afternoon tea. Even the impending doom of the world feels a million miles away from here.]],
  str_item_intro_3400113 = [[
Unlocks the background: Underground Clinic.
A relatively humble clinic that is home to precious memories.]],
  str_item_intro_3400114 = [[
Unlocks the background: The Darkest Corner.
Even lost in darkness, she still yearns to embrace the light once again.]],
  str_item_intro_3400115 = [[
Unlocks the background: Hospitality.
Only those approved by Sheol are permitted to reside in this luxurious and comfortable room.]],
  str_item_intro_3400116 = [[
Unlocks the background: New Continent.
The Shadowind has successfully arrived at a new continent, but this doesn't mean its adventure has come to an end as many more unknown things are waiting for them.]],
  str_item_intro_3400117 = [[
Unlocks the background: Shadows Are Everywhere.
The Shadowlord continues to watch over Umbraton. The shadow will always watch you.]],
  str_item_intro_3400118 = [[
Unlocks the background: Dark History.
The dust-sealed history will be exposed one day. Is this person a dictator who dominated Umbraton or a hero who saved Umbraton?]],
  str_item_intro_3400119 = [[
Unlocks the background: Reception Room.
In a room with moderate lighting, various items and decorations are arranged in an orderly manner. This room is dedicated for work and the reception of guests.]],
  str_item_intro_3400120 = [[
Unlocks the background: Longzhou Charm.
The west side of Twin Pavilions Bay is under Umbraton's management, yet culturally, glimpses of Longzhou's unique charm still shine through. From lanterns hanging in every street to delicious Longzhou snacks, all showcase the vibrant features of the distant land, enabling visitors here to fully immerse themselves in the exotic culture and customs.]],
  str_item_intro_3400121 = [[
Unlocks the background: Harbor of Twin Pavilions Bay.
Cargo ships departing from the Longzhou continent ultimately dock at the harbors in Twin Pavilions Bay, where they finalize their trade and goods exchanges before heading back. These ports play a vital role in the shipping between Longzhou and Astra continents.]],
  str_item_intro_3400122 = [[
Unlocks the background: Spring Festival in Ji Kingdom
Spring Festival is the most important festival on the Longzhou Continent. The royal family would host banquets for esteemed guests while the citizens gathered for leisure and catch-up. In the Ji Kingdom, the locals organize temple fairs, pay homage to the Dragon Maiden, and drive away the Nian beast during the festival, hoping for health and good fortune in the coming year. Some merchants hire fiendlings to put on shows themed on the beast-chasing ritual, adding a touch of fun to the beginning of the new year.]],
  str_item_intro_3400126 = [[
Unlocks the background: Spring Festival Reunion Feast
In Longzhou, the night of the Spring Festival is a time of reunion. The Caelestite and all his companions in Longzhou have gathered together to have a delicious and auspicious holiday feast together and wish everyone a better time in the coming year.]],
  str_item_intro_3400123 = [[
Unlocks the Background: Manor Scenery.
Endowed with a unique geographical location and deep cultural roots, this manor on Azurite Island boasts breathtaking scenery and allure, making it a favored resort for Lumo Nobles to stroll and unwind.]],
  str_item_intro_3400129 = [[
Unlocks the background: Borderland Cavern
Deep within ice-covered caverns, ice pillars connect the dome to the earth, resembling sculptures of deities. As the aurora cascades down, those towering and rugged ice pillars and the ice flowers on the cave walls gleam in their peculiar forms, completing the solemn and chilling ambiance.]],
  str_item_intro_3400130 = "Unlocks the background: Snowbound Border\nOn bleak snowy days, the seemingly endless snowy desert has an end—Tall mountains stand like a city wall in the distance, dividing the world. Several small houses covered in ice and snow are faintly visible at the foot of the mountain. Life there must be filled with loneliness, isn't it?",
  str_item_intro_3400133 = [[
Obtain to unlock the background: Underground Volcanic Core.
After so many years, the nomadic Rediesel Wrench never realized the volcano beneath their feet was still churning with life.]],
  str_item_intro_3400134 = [[
Obtain to unlock the background: Moon Over Desert Sands.
Sitting in the desert under the night sky is an unlikely group of people. As their eyes twinkle in the starlight, their memories intertwine.]],
  str_item_intro_3400135 = [[
Unlocks the background: Spearhead
Its internal structure is more concise and smooth compared to Soroz, and each control panel exudes a dangerous aura.]],
  str_item_intro_3400136 = [[
Unlocks the background: Fiery Fun.
Rebellion and obedience are just two different types of firewood. With the right amount of heat, both will ignite and become an unstoppable fireball!]],
  str_item_intro_3400138 = [[
Unlocks the background: Advent of Truth Parade.
You are the embodiment of the collective wisdom of the True Order. All that you experience shall guide the True Order into an ever-greater future.]],
  str_item_intro_3400139 = [[
Unlocks the background: Lonely Island Beach.
In the distant seas, there lies a lonely island forgotten by the world, surrounded by endless azure and covered with lush dense vegetation. Ancient ruins rest within this pristine verdant cradle, having endured through the ages.]],
  str_item_intro_3400140 = [[
Unlocks the background: Waveswept Rendezvous.
The island lies silently at the bottom of the sea, along with the evidence of its former glory. Now, a new summer adventure is about to begin.
Companions who stand by your side are the most precious treasures.
In the limited time you have, enjoy this endless adventure with your companions!]],
  str_item_intro_3400141 = "Unlocks the background: Millennial Yearning.",
  str_item_intro_3400142 = [[
Unlocks the background: Meet Again.
When the stars reach their destination.
He steps forward, to his companions and into the sunlight.]],
