  str_item_intro_3410601 = "A Jasper order box prepared by the Umbraton Guild. Open to choose 1 Jasper I.",
  str_item_intro_3410602 = "A Jasper order box prepared by the Umbraton Guild. Open to choose 1 Jasper II.",
  str_item_intro_3410603 = "A Jasper order box prepared by the Umbraton Guild. Open to choose 1 Jasper III.",
  str_item_intro_3410604 = "A pack previously used by the Aurorian Coalition. Open it to choose 1 valuable faction gift.",
  str_item_intro_3410605 = [[
You have left a significant mark upon the Desolation Codex and received the reward you deserve.
Open to receive various random upgrade materials, plus a small chance to obtain Star Flares!]],
  str_item_intro_3410606 = "This treasure chest is proof of your deep bond with the members of the Silent Hunters. Open it to obtain incredible rewards.",
  str_item_intro_3410607 = "A chest with unique mechanic design, open to get 1 Carrier.",
  str_item_intro_3410608 = "A box acquired during a chaotic festive celebration. The content inside remains unknown. Who doesn't like surprises?",
  str_item_intro_3410609 = "A specially ordered gift pack. Open it to choose 1 valuable gift.",
  str_item_intro_3410610 = "Rainbow Order Box III. Open to choose 1 advanced ascension material.",
  str_item_intro_3410611 = "Rainbow Order Box IV. Open to choose 1 premium ascension material.",
  str_item_intro_3410612 = "Choose one from the Thunder Solamber Druse, Water Solamber Druse, Forest Solamber Druse, and Fire Solamber Druse to obtain.",
  str_item_intro_3410613 = "Rainbow Order Box I. Open to choose 1 basic ascension material.",
  str_item_intro_3410614 = "Rainbow Order Box II. Open it to choose 1 regular ascension material.",
  str_item_intro_3410615 = "Open to receive all of the upgrade materials needed to raise an Aurorian to Ascension III, including: General Jasper II ×300, Nightium ×750,000, Coalition Order Box I ×10, Coalition Order Box II ×10, Coalition Order Box III ×10, Rainbow Order Box I ×30, Rainbow Order Box II ×50, Rainbow Order Box III ×50, and Rainbow Order Box IV ×20.",
  str_item_intro_3410616 = "The effort you put into doing tough patrols and dangerous expulsions isn't for nothing. Open this up and see what rewards are inside!",
