  str_item_intro_3420113 = [[
Choose an Aurorian from the following 6-star Aurorian list to fight beside you: <color=#ffffff>Hiiro/Sinsa/Eve/Uriel/Carleen/Sharona/Sariel/Raphael/Connolly/Charon/Eicy/Victoria/Jona/Nikinis/Gabriel/Migard/Michael/Gronru/Irridon/Wrath</color>.
