  str_item_intro_3420129 = "Choose an Aurorian from the following 5-star Aurorian list to fight beside you: <color=#ffffff>Beretta/Casta/Ciel/Sanae/Roy/Kayano/Erica/Dayna/Vivian/Mia/Nemesis/Regina/Robyn/Faust/Kleken/Barton/Keating/Louise/Noah/Hydrad/Schwartz/Maggie/Istvan/Barbara/Leona/Pact/Odi/Philyshy/Corax/Benny and Curo/Cuscuta/Areia/Sikare/Beverly/Taki/Genevieve/Naroxel/Cordy</color>.",
  str_item_intro_3420132 = "Choose an Aurorian from the following 5-star Aurorian list to fight beside you: <color=#ffffff>Beretta/Casta/Ciel/Sanae/Roy/Kayano/Erica/Dayna/Vivian/Mia/Nemesis/Regina/Robyn/Faust/Kleken/Barton/Keating/Louise/Noah/Hydrad/Schwartz/Maggie/Istvan/Barbara/Leona/Pact/Odi/Philyshy/Corax/Benny and Curo/Cuscuta/Areia/Sikare/Beverly/Taki/Genevieve/Naroxel/Cordy/Kya/Kristen/Blanc: Pura Cordis/Joselyne</color>.",
  str_item_intro_3420135 = "Choose an Aurorian from the following 5-star Aurorian list to fight beside you: <color=#ffffff>Beretta/Casta/Ciel/Sanae/Roy/Kayano/Erica/Dayna/Vivian/Mia/Nemesis/Regina/Robyn/Faust/Kleken/Barton/Keating/Louise/Noah/Hydrad/Schwartz/Maggie/Istvan/Barbara/Leona/Pact/Odi/Philyshy/Corax/Benny and Curo/Cuscuta/Areia/Sikare/Beverly/Taki/Genevieve/Naroxel/Cordy/Kya/Kristen/Blanc: Pura Cordis/Joselyne/Isa/Li Tianxian</color>.",
