Choose an Aurorian from the following 6-star Aurorian list to fight beside you: <color=#ffffff>Victoria, Raphael, Connolly, Uriel, Gronru, Charon, Carleen, Sinsa, Sharona, Gabriel, Nikinis, Eve, Jona, Michael, Wrath, Irridon, Sariel, Eicy, Migard, Hiiro, Beryl, Fleur, Smokey, Revy, Gram, Paloma, Bethel, Luke, Hedy, Novio, Siobhan, Florine, Ruby, Rinne, Amemori, Yao, Azure, Lenore, Giles, Barton: Deft Blades, Nina, Carleen: Smoldering Soul, Fia, Jeno, Pollux, Lilica, Minos, Axelia, Vic.</color>.
Note: This kit will expire at 09:00, 31 August 2023 (UTC+0), 04:00, 31 August 2023 (UTC-5). Claim it on time, or it will be automatically converted into 3,000 Lumamber and sent to you via your in-game mailbox.]],
  str_item_intro_3430101 = "Open to select either Corax, Leona, Mia, or Areia. You'll also receive all of the upgrade materials you'll need to raise the Aurorian to Ascension I, Lv. 10!",
  str_item_intro_3430102 = "Open to select either Barton, Maggie, Nemesis, or Sikare. You'll also receive all of the upgrade materials you'll need to raise the Aurorian to Ascension I, Lv. 25!",
  str_item_intro_3430103 = "Open to select either Hydrad, Istvan, Vivian, or Louise. You'll also receive all of the upgrade materials you'll need to raise the Aurorian to Ascension II, Lv. 1!",
  str_item_intro_3440001 = "Use it to obtain dark chocolates, Lumamber, and random Aurorian upgrade materials.",
  str_item_intro_3440002 = "Use to obtain Sunny Sweets, Lumamber, and random Aurorian upgrade materials.",
  str_item_intro_3440003 = "Captain Mu Yuebai handed a red envelope to everyone when you celebrated the Spring Festival together on the Shadowind. What kind of surprise could be inside?",
  str_item_intro_3440005 = "Use to obtain Lumamber and random Aurorian upgrade materials.",
  str_item_intro_3500001 = "Mystery material found in ancient ruins. It contains great power and is essential for refitting equipment.",
  str_item_intro_3500003 = [[
Instantly promotes an Aurorian to Ascension II Lv.1.
A mysterious ancient relic that is containing a substance and shines brightly. It can increase the power of an Aurorian to a great level.]],
  str_item_intro_3511001 = [[
Raises Water Enlightenment level.
Embed this mysterious cube provided by Enlightener seamlessly into a tablet to activate and reveal a snippet of the enlightenment training.]],
  str_item_intro_3511002 = [[
