  str_item_intro_3621001 = "A cushioned chair with a high back. Offers great back support and looks comfortable to nap in.",
  str_item_intro_3621002 = "A small, single-person sofa. Since it has no backrest, perhaps a small table should be placed in front of it...",
  str_item_intro_3621003 = "A wide sofa that can seat two people, although it's really comfortable with just one person, too...",
  str_item_intro_3621004 = "An uncommon sofa that seats up to four people. Perfect for larger gatherings.",
  str_item_intro_3621005 = "A small, hexagon table, usually used to hold drinks, teapots, cups, and snack plates. Best if placed in small party rooms.",
  str_item_intro_3621006 = "A long tea table, generally paired with a loveseat or a 4-seater sofa. Best if placed in large party rooms.",
  str_item_intro_3621007 = "A device that automatically serves drinks, so long as it is stocked with the right ingredients. Can't make coffee out of just sugar and water, after all...",
  str_item_intro_3621008 = "A musical instrument purportedly from an unknown tribe in a distant land, popular in Umbraton originally. Generally comprised of a large drum and several smaller drums and cymbals, other percussive instruments can be added as well. Regardless of the configuration, however, the entire set is played by a single musician.",
  str_item_intro_3621009 = "A small plant in a small pot. Helps purify the air in a room and adds some green to it.",
  str_item_intro_3621010 = "Potted plant that is as tall as a person, it purifies the air around them and gives any room a more natural feeling. Also serves as a decent hiding place.",
  str_item_intro_3622001 = "An exquisite and intricate landscape painting. Allows the viewer to appreciate nature's beauty without ever leaving home.",
  str_item_intro_3623001 = "A sun-shaped lamp that can be affixed to the ceiling. Gets its name from its powerful lighting and large area of coverage.",
  str_item_intro_3623002 = "A lightweight, easy-to-install indoor ceiling light with iron support. A wide range of decorations can be affixed to it, making it very popular.",
  str_item_intro_3623003 = "Provides any room with a cool breeze. It was originally used to channel clean air into the Undercities, and soon afterward it was discovered to be able to keep rooms cool, fresh and comfortable.",
  str_item_intro_3623004 = "Lights installed on ceilings. Used by many city-states for their low energy consumption, wide lighting, and compact size.",
  str_item_intro_3623005 = "A ceiling light that hangs from the ceiling. Its hinged lock structure makes it very easy to adjust, but it will sway back and forth in an earthquake or windy weather, which can be very dangerous. For this reason, this type of light is prohibited on ships.",
  str_item_intro_3631001 = "A luxury furnishing imported from the Far East by a fleet that dominated the oceans. Elegant in color and style but delicate to the touch. Be very careful when placing it.",
  str_item_intro_3631002 = "A sun-shaped icon. Silent and solemn, it empowers the faith of any who see it.",
  str_item_intro_3631003 = "A beautiful, big cask, crafted by a legendary artisan. Only the finest wine can be stored in a vessel as precious as this.",
  str_item_intro_3631004 = "Said to originate in the Far East, this simple but useful piece of furniture can block wind, separate spaces, and provide privacy. In addition, it can be embellished so as to beautify the space around it and create for its owner an air of mystery. Quickly became popular in the cities and towns of Astra.",
  str_item_intro_3631005 = "A huge, gilded instrument adorned with various gemstones that represent different celestial bodies. Helps scholars get familiar with astrology and perform divinations quickly, but with questionable accuracy...",
  str_item_intro_3632001 = "A communication device of the Illumina Federation that originated within the Undercities. As communications between city-states increased, so too did their adoption of this particular technology.",
  str_item_intro_3632002 = "A gilded chalice often seen during Lumopolis celebrations. The creator also imbued this chalice with unknown Luminatics, granting it a pair of moving, illusory wings.",
  str_item_intro_3632003 = "This embossed board represents the ancient history of Lumopolis civilization. It is said that each pattern contains a lot of literary allusions. Just seeing it gives one a sense of timelessness...",
  str_item_intro_3632004 = "A candleholder enhanced by Luminatics, it can never be blackened by smoke, and can automatically light and extinguish its own candle.",
  str_item_intro_3632005 = "An exquisite hanging clock resulting from the harmonious fusion of Illumina machinery and Lumopolis craftsmanship. Its primary function is purely decorative; it just so happens to accurately tell time as well.",
  str_item_intro_3641101 = "A decorative suit of armor, it is a traditional furnishing among the noble clans of Lumopolis, particularly those with warrior histories. It also serves to remind their descendants of the nobility of their martial heritage and to discourage hedonistic behavior in the family.",
  str_item_intro_3641201 = "A furnishing loved by the folks of Umbraton who pose as people of culture. It is made mostly out of precious wood and has classic books and precious vessels placed on it. However, one simply must question the authenticity of these antiques...",
  str_item_intro_3641301 = "A rifle rack produced by the Illumina Federation that fills any room with the spirit of battle. Leave it to the main force in the fight against Eclipsites to come up with furniture like this. Compared to its previous designs, this rifle rack is lighter overall, yet boasts higher stability.",
  str_item_intro_3641501 = "A scaled model of an automobile comes complete with pipes, rivets, all sorts of metal plating, and even some wooden parts. This tiny, patchwork model is the spitting image of the Rediesel Wrench's pride and joy, the Powerball convertible car.",
  str_item_intro_3641102 = "A rug made out of luxurious fabric by skilled craftsmen of Lumopolis with fine craftsmanship. This isn't a rug that any ordinary person can afford... Besides being quite valuable, it is also a symbol of status.",
  str_item_intro_3641202 = "A large black rug manufactured in Umbraton. Soft and thick, it is masterfully woven and completely silences footsteps.",
  str_item_intro_3641302 = "A rather square rug with neat horizontal and vertical threadwork that is rather representative of the industrial style of Illumina Federation. One glance is all it takes to know that this is produced by the factories of Gannon City. It is very durable.",
  str_item_intro_3641402 = "A thick and heavy rug woven from a large amount of Northland cotton and animal fur. Can provide respite in even the coldest environments.",
  str_item_intro_3641502 = "The crude fellows of Rediesel Wrench must have randomly stitched together old clothes to make this... The smell of Rediesel indicates that they must have used Rediesel to dye this rug. Would anyone really spend a lot of money to buy this and keep it at home?",
  str_item_intro_3641602 = "An eye-catching red carpet with an almost unnoticeable pattern. Upon closer inspection, the pattern seems to quiver and twist slightly, bringing a sense of unease and discomfort to those who set eyes on it... Who would buy this sort of carpet?",
  str_item_intro_3642102 = [[
Furniture item. Can be placed in rooms on your Colossus.
A masterpiece produced by an unknown painter of Lumopolis. The original can be found in the collection of a high-ranking noble, and this, of course, is a replica. The outstanding painting skills put the viewer inexplicably at ease after gazing upon it, and that is why so many copies have been made. Even so, each copy is considerably expensive, and buyers scramble for a chance to have one of their very own.]],
  str_item_intro_3642201 = "The underground forces of Umbraton fight in the open and in the shadows. These two swords are used when they have a dispute that cannot be reconciled. Both parties to the dispute will appoint a swordsman to duel each other with these swords to decide the matter.",
  str_item_intro_3642301 = "Another example of strong military influence in Illumina furniture, this rifle is the first thing to come to mind when Illuminans think of wall decor—it seems they truly are ready for war at all times.",
  str_item_intro_3642401 = [[
Furniture item. Can be placed in rooms on your Colossus.
Even in the wintry Northland, it stays perennially green. Thus the locals see it as a symbol of hope and abundance, with the expression, "No mistletoe, no bliss." They'll often gather the plant and weave it into a wreath for the house to bring good luck.]],
  str_item_intro_3641103 = [[
Furniture item. Can be placed in rooms on your Colossus.
This item represents the power held by the princes and nobles of Lumopolis. Extravagantly decorated and made of precious metals, it conveys the temptation of power and symbolizes the weight it brings.]],
  str_item_intro_3641503 = "A mishmash of scrap metal, steel sheets, and rivets with a cushion from who knows where on it... Although it is a bit crude and damaged, it is soft and surprisingly sturdy.",
  str_item_intro_3651001 = "A small-scale model of the Spire. As a high-quality replica of the original, it seems to contain the sealed power of the original as well.",
  str_item_intro_3651002 = "This looks like an extremely realistic miniature version of the Spire. You can feel an ancient mysterious power in the Spire when you get close to it.",
  str_item_intro_3651003 = "Only those who explore the highest levels of the Spire can obtain this decoration. Not only is it extremely realistic, but it also has some of the Spire's power. When they see this, it feels like they are standing in front of the real Spire.",
  str_item_intro_3651004 = "This is an extremely rare souvenir that can only be obtained by those who explore the Spire. Although it is just a model, it looks exactly the same as the Spire. If you observe it carefully, you can even see many details of the real Spire. It is said that this can affect the real Spire...",
  str_item_intro_3651005 = "A mysterious memento gifted by a spire, and only obtainable by exploring the spire's depths. Some say it symbolizes the will of the spire and its recognition of those brave enough to explore it.",
  str_item_intro_3651101 = "A miniature Eclipsite figurine found in the Secret Territory, likely a souvenir left behind by another explorer. It lacks the terrible ferocity of its original, and even seems a little cute... Once you get used to it.",
  str_item_intro_3651102 = "Found in the depths of the Secret Territory, this figurine seems to be made in the likeness of a certain High-Level Eclipsite. Because of its hideous face, it can inspire fear in many people even if it doesn't move. However, if you get used to it, you can use it to scare away petty thieves who sneak into your room...",
  str_item_intro_3651201 = "An extremely rare figurine that looks exactly like Soroz. Created with the concentrated Luminatics of the friends of the Navigator, and manufactured by Soroz's mysterious crafting techniques. It represents the unshakable bond between Soroz, the Navigator, and their friends.",
  str_item_intro_3662001 = "After evading the pursuit of the Eclipsites, to commemorate the first time everyone met each other, Soroz specially asked Firefly to draw this hanging picture based on the image it recorded. Almost everyone thought this was a photo because the scene was recreated so realistically.",
  str_item_intro_3661101 = "A rock found in Red-Eye Gorge that contains a small amount of volcanic power and feels hot to the touch. Every once in a while, it makes a rumbling sound or has a small eruption, but it is pretty much harmless. Those who are brave might be able to use this to cook meals or barbecue meat.",
  str_item_intro_3661102 = "The white dawn flowers Dawn planted in Red-Eye Gorge, which only bloom once every few years. The flowers are gorgeous, and its floriographical meaning is \"the hope of dawn.\"",
  str_item_intro_3662101 = "Due to her illness, Eve could only drink cold water that was about 15 degrees cool and hot water that was about 45 degrees warm. In the Rediesel Desert, where water was scarce, Sinsa always keeps two thermos bottles with him so that his little sister will always have water to drink. He even drew a smiley face on the bottle to make his sister happy.",
  str_item_intro_3661103 = "Although the dojo no longer exists, the katana rack of Sakae Dojo is kept in good condition. Sweep off the dust and fill it with katanas to recreate the past glory of Sakae Dojo.",
  str_item_intro_3661104 = "This rare and colorful cherry tree is only found in the vicinity of Cloud Mountain. People like to hand all sorts of blessings on it to pray for their wishes to come true.",
  str_item_intro_3662102 = "An exotic painting of a ferocious dancing dragon baring its fangs and claws. However, instead of intimidating people, it gives people an inexplicable sense of security. Maybe this is related to the unique culture of the Far East.",
  str_item_intro_3661105 = "A popular daruma in the Cloud Mountain region. Keep this at home to bring good luck. It might even make some of its owner's wishes come true.",
  str_item_intro_3661106 = "A daruma that looks slightly ferocious. Keep this at home to get rid of bad luck and prevent the wicked from knocking on your door.",
  str_item_intro_3661107 = "A daruma that glows with a golden light every now and then. You can almost see fortunes coming your way when you look at it—well, let's hope they do.",
  str_item_intro_3661108 = "A daruma that represents knowledge. It is said that this daruma brings academic success, so many students pray to get one. This will probably be very popular in Gannon City.",
  str_item_intro_3661109 = "It is said that everyone will come across a daruma that suits them the best. These dolls will grant your greatest wishes and bless you throughout your life.",
  str_item_intro_3661110 = [[
Furniture item. Can be placed in rooms on your Colossus.
A model of the overstated castle by the sea, perfectly capturing its mysterious and strange aura. Indistinct voices can occasionally be heard coming from within its walls, which are not entirely unlike those of the ancient legends surrounding this structure.]],
  str_item_intro_3661111 = [[
Furniture item. It can be placed in rooms on your Colossus.
After studying Soroz's technology, Fleur created the machinery called "Rediesel Steel MkV Zero", which is a model of it. Compared to the actual machinery, this model boasts greatly improved performance and can be said to be perfect, except that it is incredibly small.]],
  str_item_intro_3661112 = "Furniture item. Can be placed in rooms on your Colossus.\nA cart made to earn some extra money during the summer. Contains special equipment for making ice cubes and crushing them into shaved ices, providing lucky customers with a cool treat on a hot summer's day. Although shaved ice season is over, the equipment on the cart is still useable, and occasionally starts by itself—a clear indication that it believes itself to be too young for retirement.",
  str_item_intro_3661113 = [[
Furniture item. Can be placed in rooms on your Colossus.
An inflatable sofa manufactured by the Tir' Hotel. It is equipped with a water gun at the back, which sprays water at regular intervals, keeping everyone feeling cool and refreshed in the scorching summer sun.]],
  str_item_intro_3661114 = [[
Furniture item. Can be placed in rooms on your Colossus.
An inflatable sofa manufactured by the Tir' Hotel. The spraying device behind its cushion can generate a fountain-like spray at regular intervals. Although it provides greater relief, its fountain is considerably powerful, occasionally scaring those who sit on it.]],
  str_item_intro_3661115 = [[
Furniture item. Can be placed in rooms on your Colossus.
An inflatable sofa manufactured by the Tir' Hotel. Must be handled carefully, as there is an automatic fireworks detonator attached to its rear. Once activated, it launches various fireworks, providing all in its vicinity with a mini fireworks show. The launch angle ensures that those sitting on it are out of harm's way, but that doesn't mean it won't give them the odd fright.]],
  str_item_intro_3661116 = [[
Furniture item. Can be placed in rooms on your Colossus.
An inflatable sofa manufactured by the Tir' Hotel. The handles on both sides are actually bubble machines. Once activated, colorful bubbles fill the air, making it very popular with children.]],
  str_item_intro_3661117 = [[
Furniture item. Can be placed in rooms on your Colossus.
A portable water sofa manufactured by the Tir' Hotel. After unfolding this sofa, you can decorate it with the coconut tree accessories. Once filled with water, it makes every day feel like a day at the seaside.]],
  str_item_intro_3661118 = [[
Furniture item. Can be placed in rooms on your Colossus.
A surfboard manufactured by the Tir' Hotel. Made of special materials, resulting in a light, durable, and strong board. With its expertly crafted aquadynamic shape, this surfboard is capable of taming any wave.]],
  str_item_intro_3662103 = [[
Furniture item. Can be placed in rooms on your Colossus.
A souvenir of your time at the Ocean Sovereign festival. When you gaze at the blue sea and sky, and the beach with its swaying green trees, it's as if you're back by the seaside, reliving that happy day.]],
  str_item_intro_3661119 = [[
Furniture item. Can be placed in rooms on your Colossus.
Undercity 24 is one of the essential bases of the Dunefire Line, and undertakes the majority of the vanguard's logistics, training, and medical operations, among other duties. This miniature model perfectly reflects its comprehensive nature.]],
  str_item_intro_3661120 = [[
Furniture item. Can be placed in rooms on your Colossus.
The sand table was for internal use in Illumina Federation Military Academy. It was mapped out individually by special surveyors and then scaled down accordingly. This table, composed of sand, wood, and figurines, accurately simulates the strategic situation of an actual battlefield and allows students to conduct war command exercises across a variety of battle conditions.]],
  str_item_intro_3661121 = [[
Furniture item. Can be placed in rooms on your Colossus.
The main body of this medal collection board is an iron plate marked with many holes. This item is said to be a tribute to the valiant efforts of The Stone Force against the Eclipsites. It is also a symbol of their enduring glory. The medals hanging from it represent that The Stone Force are never far away and will forever be standing firmly on the Defensive Line with each new generation of soldiers to hold off the Eclipsite threat.]],
  str_item_intro_3662104 = "Furniture item. Can be placed in rooms on your Colossus.\nThe Illumina Federation interior specially issued this banner to the defenders of the Dunefire Line to commend them for successfully repelling a large-scale Eclipsite invasion. Whenever defenders see this banner waving on the defensive line, the sense of honor it instills reminds them of their solemn creed—Wherever life faces peril, there you'll find us.",
  str_item_intro_3661122 = "Don't worry—there aren't any dead bodies buried here, so you can't really call this a tombstone. What? That hand? Oh, it's all just part of the show!",
  str_item_intro_3661123 = "Appears whenever you refuse to give Nightium! Well, it can't speak, in fact, it's actually not a ghost—it's just a chicken under a sheet.",
  str_item_intro_3662105 = "This lamp is actually made from wooden panels carved into a pumpkin shape. When switched on, light shines from its eyes, nose, and mouth, creating a somewhat eerie atmosphere.",
  str_item_intro_3661124 = "White from top to bottom, with a perfectly straight peak, this lofty tower serves as a symbol of Eraveil. This exquisite model perfectly restores the appearance of that proud monument.",
  str_item_intro_3661125 = "A doll of a Caelestite youngster. It looks adorable if you place it on the ground—and it appears that the Fireflies have taken a particular liking to it.",
  str_item_intro_3661126 = "A potted dandelion. Although its flower looks very flimsy, this tenacious plant can survive anywhere, as long as it has water and soil.",
  str_item_intro_3661127 = [[
Furniture item. Can be placed in rooms on your Colossus.
Is this merely a model? No, it's a miniature world! Not only does it have a moving train, but it also features a realistic natural landscape, including mountains, rivers, and trees! Just watch the model train winding around the mountain for a moment, and you'll feel like you are part of this miniature world, taking in the beautiful scenery.]],
  str_item_intro_3661128 = [[
Furniture item. Can be placed in rooms on your Colossus.
Now you too can gaze upon beautiful autumn trees on the Colossus! For some reason, this bonsai plant still retains the color of the season all year round. Its yellow leaves occasionally fall, allowing you to revel in the melancholy pathetic fallacy of autumn anytime and anywhere, even it does create more mess for the Fireflies to clean up.]],
  str_item_intro_3661129 = "Furniture item. Can be placed in rooms on your Colossus.\nThis flower always faces the sun! Look at this positive little potted plant—put it in your room and watch as it is filled with warmth and optimism.",
  str_item_intro_3661130 = [[
Furniture item. Can be placed in rooms on your Colossus.
A golden belt symbolizes your honor and proof of the blood, sweat, and tears you shed in Umbraton's Underground Arena. Though you can't bring yourself to let just anyone touch it, it's okay if they marvel at it from a distance.]],
  str_item_intro_3661131 = [[
Furniture item. Can be placed in rooms on your Colossus.
A reasonable transaction should be fair to both sides. As a symbol of weighing goods, these gold-plated scales represent the concept of fairness recognized by both parties. This is why it is often placed in the halls of Umbraton's guilds to show guests that their transactions are fair and honest.]],
  str_item_intro_3662106 = [[
Furniture item. Can be placed in rooms on your Colossus.
A fan which full of foreign culture. It was made of soft yet sturdy paper. The paintings on it express an exotic style not often seen in this part of the world.]],
  str_item_intro_3662107 = [[
Furniture item. Can be placed in rooms on your Colossus.
A stained-glass mosaic produced by a Lumopolis craftsman that transcends the beauty of nature itself. When the light shines on it, it reflects its vivid colors to a beautiful and dazzling effect.]],
  str_item_intro_3661132 = [[
Furniture item. Can be placed in rooms on your Colossus.
Allegedly an ice dragon once patrolling the Northland skies. However, it is now harmless as a mere statue. It also emits a nice trace of cold air, how convenient!]],
  str_item_intro_3661133 = [[
Furniture item. Can be placed in rooms on your Colossus.
The rack and the cloak seem ordinary, but according to some elders in Northland, there's a peculiar tale behind it...]],
  str_item_intro_3661134 = [[
Furniture item. Can be placed in rooms on your Colossus.
According to certain Northland folktales, you'll find your one true love if you wear it!]],
  str_item_intro_3661135 = [[
Furniture item. Can be placed in rooms on your Colossus.
The most common type of house in Northland. It even replicated the occasional smoke rising from the chimney on a snow-laden roof. The glows in the windows give off the impression that the miniature house is indeed occupied.]],
  str_item_intro_3662109 = [[
Furniture item. Can be placed in rooms on your Colossus.
A head of a reindeer, but not a real one. It's actually fur stuffed with chipped wood, and has a special mechanism to make the eyes move occasionally!]],
  str_item_intro_3661136 = [[
Furniture for room on the Colossus.
Nothing expresses love more than cooking and serving a part of your own body. Given the even distribution of fat, Tohru is supremely confident with how delectable her tail will taste. She is also a master of grilling, since practice makes perfect. Still, it's poisonous so be careful.]],
  str_item_intro_3661137 = [[
Furniture for room on the Colossus.
Spontaneous handicraft by Tohru. To dragons, human art is beyond comprehension, since the subject and procedures are both too simplified. Tohru imitated other's work in creating this woodcarving. She cares not what purpose it serves, as long as it's appreciated.]],
  str_item_intro_3662110 = [[
Furniture for room on the Colossus.
A groupfie is a must on any group trip! Stand closer now... It's almost impossible to get five dragons in the same shot... Say cheese!]],
  str_item_intro_3661138 = [[
Furniture item. Can be placed in rooms on your Colossus.
A piano found in the Lost City. Though similar in style to some pianos on Astra, it's particularly well-made and still produces a beautiful sound even after all these years. Even if it does sound a little off, it can still be tuned according to its unique internal structure! What a rare gem for musicians!]],
  str_item_intro_3661139 = [[
Furniture item. Can be placed in rooms on your Colossus.
An understated piece that's somehow different from Illumina's usual simple style. With its unique smooth texture and beautiful design, even those from Lumopolis would like it.]],
  str_item_intro_3661140 = [[
Furniture item. Can be placed in rooms on your Colossus.
A carpet found in the Lost City. Not only is it made from a very special material, its intersecting diamond-shaped pattern makes it even more striking.]],
  str_item_intro_3661141 = [[
Furniture item. Can be placed in rooms on your Colossus.
Easily found on the streets of the Lost City, it's almost as common as street lights, making them a tempting substitute to road signs... Its screen features a jumble of patterns that flicker on and off constantly, and it's impossible to know what's inside it. Looks like the only way to find out is by breaking it.]],
  str_item_intro_3661142 = [[
Furniture item. Can be placed in rooms on your Colossus.
A mailbox found in the Lost City. Because the engraving on it had faded, it was initially mistaken for a small storage box for emergency rations. It wasn't until they found letters inside that people realized it was a mailbox. However, it doesn't look like anyone's still using it.]],
  str_item_intro_3661143 = [[
Furniture item. Can be placed in rooms on your Colossus.
A common fixture placed on roadsides in the Lost City for passers-by to rest on. Well, if it's placed at home, it can be used to sit and lie down on.]],
  str_item_intro_3661144 = [[
Furniture item. Can be placed in rooms on your Colossus.
After all these years, it's still miraculously intact! The technology in Lost City is simply astounding. Once a piece of paper is placed in, it's immediately cut into thin strips, making any message on it unintelligible.]],
  str_item_intro_3661145 = [[
Furniture item. Can be placed in rooms on your Colossus.
It's still in remarkable condition after all these years... but it's gone out of use. A little tidying up reveals a clean and uncluttered desktop and all kinds of office supplies that simply fill the office with energy.]],
  str_item_intro_3661146 = [[
Furniture item. Can be placed in rooms on your Colossus.
Not only does it swivel around delightfully, but the seat height can also be adjusted, and the backrest can even be lowered, allowing its user to lie down comfortably for a little shut-eye. In terms of ambiance, placing it with the desk creates a wonderful sense of harmony that makes one linger on at work and forget about time.]],
  str_item_intro_3661147 = [[
Furniture item. Can be placed in rooms on your Colossus.
An ornament from the Far East made of bamboo that requires running water. Its ingenious mechanism makes a pleasant thud at regular intervals, which can also help you keep the time.]],
  str_item_intro_3661148 = [[
Furniture item. Can be placed in rooms on your Colossus.
A rapid growing bamboo plant that requires regular pruning. Though it's a little troublesome, you can get a lot of bamboo from it. The rustling sound the leaves make in the wind is also revitalizing to the listener.]],
  str_item_intro_3663001 = [[
Furniture item. Can be placed in rooms on your Colossus.
A doll hung under the eaves. It's easy to make, and really cute. When the wind blows, it'll even dance with it, as if praying for the rain to stay away. If it works, it means that the heavens saw its dance!]],
  str_item_intro_3661149 = [[
Furniture item. Can be placed in rooms on your Colossus.
A helmet worn by Far East warriors. The over-the-top ornaments are said to represent the faction or clan to which the warrior belonged. More importantly, they serve as a symbol of honor.]],
  str_item_intro_3661150 = [[
Furniture item. Can be placed in rooms on your Colossus.
Originally, it was a flag that soldiers or samurais put on their backs to guide troops in battle. When placed at home, it gives off a solemn feeling.]],
  str_item_intro_3662111 = [[
Furniture item. Can be placed in rooms on your Colossus.
A type of calligraphy popular among Far East people. The words are usually written by master calligraphers, but of course most are just copies of the original. The strokes hold a special kind of beauty that most outsiders can never fully appreciate.]],
  str_item_intro_3661151 = [[
Furniture item. Can be placed in rooms on your Colossus.
As the word "withered" indicates, this miniature landscape is completely dry. Fine sand is used to represent water and stones to represent mountains. In the Far East, it's believed that this kind of static landscape helps one meditate and calm the mind.]],
  str_item_intro_3661152 = [[
Furniture item. Can be placed in rooms on your Colossus.
A streetlamp decorated in the Far East style that is commonly found on Cloud Island. The local residents use them not only for illumination, but also as road signs.]],
  str_item_intro_3663002 = [[
Furniture item. Can be placed in rooms on your Colossus.
Koufu-jou locals hang them on their doors for lighting, and the lanterns from each house make the streets as bright as day. People also use it with a bamboo pole to light the way at night.]],
  str_item_intro_3661159 = [[
Furniture item. Can be placed in rooms on your Colossus.
A lance that was given to Carleen when she was ordained as a knight. It later became her exclusive battle weapon. Though this is only a replica, it still emits the power of Moon Cocoon when displayed at home...]],
  str_item_intro_3662116 = "Furniture item. Can be placed in rooms on your Colossus.\nFamous producer—Tourdog's favorite decoration. He says that as long as this clapperboard hangs on his wall, he can often hear the crispy sounds of its claps, which motivates him to begin a new day of work. Seeing how diligently he works, onlookers can't help but be encouraged to work hard as well.",
  str_item_intro_3661153 = [[
Furniture item. Can be placed in rooms on your Colossus.
Used often by cheerleaders at rallies to accompany their various cheering dances. However, someone modified this pair by installing a bizarre component to it, and now they cheer on their own. You might find it odd at first, but it's amusing once you get used to it.]],
  str_item_intro_3661154 = [[
Furniture item. Can be placed in rooms on your Colossus.
Junked racecar tires that have been recycled and stacked together into a chair. Somewhat rustic but very soft.]],
  str_item_intro_3662112 = [[
Furniture item. Can be placed in rooms on your Colossus.
A banner said to be used as the finish line of the Blazing Rally. Participants of the race love to bring it home for decoration or place it on their car as a memento.]],
  str_item_intro_3661155 = [[
Furniture item. Can be placed in rooms on your Colossus.
Every year, almost all of Rediesel Wrench's members participate and compete in a self-hosted rally race, drawing spectators from all walks of life. This cup is evidence of the owner's outstanding performance in the race.]],
  str_item_intro_3661156 = [[
Furniture item. Can be placed in rooms on your Colossus.
A plant that usually only grows in the desert, resistant to the extremely cold and dry climate. Among the toughest of all houseplants, it doesn't require much watering. Be careful with its spines!]],
  str_item_intro_3662113 = [[
Furniture item. Can be placed in rooms on your Colossus.
Called a "energizing tire," but actually just a regular racecar tire. However, when hung as wall decor, it fills the room with the exciting exuberance of a rally.]],
  str_item_intro_3661157 = [[
Furniture item. Can be placed in rooms on your Colossus.
According to members of the True Order, this scroll was first discovered in an ancient ruin. It bears no words, yet those of the True Order are able to gleam Revelation from within...]],
  str_item_intro_3642602 = [[
Furniture item. Can be placed in rooms on your Colossus.
Drawn by an unknown member of the True Order who self-proclaimed to have seen the Truth of the World, left this behind, and then vanished. His proclamation is doubted by most, yet it is undeniable that there is something strangely alluring about this bizarre painting...]],
  str_item_intro_3661158 = [[
Furniture item. Can be placed in rooms on your Colossus.
Inseparable, perfect, circulatory, true, unique... Members of the True Order interpret the pattern differently, but they all believe that placing a heptagram under their feet helps see the ultimate truth...]],
  str_item_intro_3662115 = [[
Furniture item. Can be placed in rooms on your Colossus.
Sandy dunes! Racecars! The Blazing Rally invites the most courageous, indomitable and resourceful racers to a party of speed! Till your heart's content! Till the end of the world!]],
  str_item_intro_3661169 = [[
Furniture item. Can be placed in rooms on your Colossus.
A small piece of machinery powered by a mysterious force that spins non-stop when slightly pushed. It is rumored that it will keep spinning until the end of the world if unstopped.]],
  str_item_intro_3661170 = [[
Furniture item. Can be placed in rooms on your Colossus.
A gate that used to be placed in Cloud Gardens. It is classy and suitable for decoration in other places.]],
  str_item_intro_3661162 = [[
Furniture item. Can be placed in rooms on your Colossus.
Anyone who is able to remove an intact set of fish bones and arrange them so neatly must have deep knowledge of fish. This fishbone ornament is not only a decorative piece but also a show of its maker's craftsmanship.]],
  str_item_intro_3662117 = [[
Furniture item. Can be placed in rooms on your Colossus.
One can imagine the skill of the fisherman by looking at the rubbing. A gigantic fish like this one must have caused huge waves when it struggled. The fisherman probably had to tangle with it for quite a bit before finally taking it down, and decided to keep this rubbing as a souvenir.]],
  str_item_intro_3661163 = [[
Furniture item. Can be placed in rooms on your Colossus.
A chair made from a round stump, its surface is rough and its growth rings are visible. It adds a unique sense of wilderness to the room, though.]],
  str_item_intro_3661164 = [[
Furniture item. Can be placed in rooms on your Colossus.
The carpet is rumored to have been used by the Caelestite. It is painted with patterns composed of various lines and shapes. Some say the patterns resemble part of the tower if you stare at them long enough while others think they resemble the sky. It is truly mysterious.]],
  str_item_intro_3661165 = "Furniture item. Can be placed in rooms on your Colossus.\nA model of a vehicle from another world.\nIt seems a very familiar object to the Phantom Thieves of Hearts.\nMona looks at it with a smug smile—or is it just your imagination?",
  str_item_intro_3661166 = [[
Furniture item. Can be placed in rooms on your Colossus.
A stuffed toy of a demon from another world.
It's shaped a bit like a snowman, which is why people like it.
Did you hear that? It sounded like someone saying "hee-ho."]],
  str_item_intro_3661167 = [[
Furniture item. Can be placed in rooms on your Colossus.
A mysterious device found in the ancient ruins. It's said to be able to fry food and even has seasoning capabilities! It's such a rare and valuable item that many participated in a Food Cart King competition for the chance to obtain it...]],
  str_item_intro_3661168 = "Furniture item. Can be placed in rooms on your Colossus.\nToss in oil, hulled grains, and seasonings—usually sugar, and the hulled grains will start to puff up after the machine is activated, making a wonderful snack. But unfortunately, this one is just a decoration that can't be used...",
  str_item_intro_3661160 = [[
Furniture item. Can be placed in rooms on your Colossus.
A must in all amusement parks! Children love it! Of course, this one's a bit small... It can only be used as decoration.]],
  str_item_intro_3661161 = [[
Furniture item. Can be placed in rooms on your Colossus.
It's a seesaw! A seesaw! But it looks like it's built for a small animal. The Fireflies aboard the Colossus love it. You can often see them springing up and down, practicing coordinating their movements.]],
  str_item_intro_3661001 = "Furniture item. Can be placed in rooms on your Colossus.\nWhen fully inflated, this swim ring looks like a... powerful Eclipsite?! Uh... Anyway, it's just a swim ring, and it's pink, too. It doesn't look all that scary—in fact, it's even kind of cute.",
  str_item_intro_3661002 = [[
Furniture item. Can be placed in rooms on your Colossus.
Originally manufactured and sold in the Illumina Federation, it was repainted in a small town to give it more of a summertime feel. After its new paintjob, it allegedly generates an even cooler breeze than before!]],
  str_item_intro_3661003 = [[
Furniture item. Can be placed in rooms on your Colossus.
This station sign from the Lumopolis Shuttle Hub seems mysteriously solid and durable, remaining free of rust after years of sun and rain. Its simple colors and stylish design make it the perfect souvenir of a long journey to Lumopolis.]],
  str_item_intro_3661004 = [[
Furniture item. Can be placed in rooms on your Colossus.
Though this crown won't grant you any real power, it is a token of a true charmer. This crown was once presented to the winner of Miss Umbraton. The magnificent jewels fit in with the stunning beauty, which made a deep impression on the crowd.]],
  str_item_intro_3661005 = [[
Furniture item. Can be placed in rooms on your Colossus.
This hat is particularly popular in desert regions. With an especially wide rim, it provides protection from the wind and sand. Those who live in and around the desert often wear this cloak and hat combo with a mask during certain festivals, singing and dancing for outsiders as a way of sharing the culture of their home.]],
  str_item_intro_3661006 = [[
Furniture item. Can be placed in rooms on your Colossus.
The "bean bag" was originally a delicacy of the desert region, made from perennial beans native to the area. This concept was eventually carried over to the realm of furniture-making. According to the locals, sticking a cute expression on your beanbag makes people want to dive into it even more.]],
  str_item_intro_3661007 = [[
Furniture item. Can be placed in rooms on your Colossus.
Relive the battles of the Underground Arena on your Colossus! The images of the challengers it projects will show you every combat detail and recreate the tournament's thrill.]],
  str_item_intro_3661008 = [[
Furniture item. Can be placed in rooms on your Colossus.
A large maple bonsai that can decorate a room all by itself. Of course, it would be better with a few extra decorations to accompany it.]],
  str_item_intro_3661009 = [[
Furniture item. Can be placed in rooms on your Colossus.
A small maple tree potted plant. Combine it with multiple potted plants to make a truly beautiful arrangement.]],
  str_item_intro_3661010 = [[
Furniture item. Can be placed in rooms on your Colossus.
Some villagers believe this mask holds power to scare off evil and brings good luck, so they often place it in a prominent position in their home, hoping it will bless their entire family.]],
  str_item_intro_3661011 = [[
Furniture item. Can be placed in rooms on your Colossus.
Originally from the Far East, this type of furniture has gradually become popular across the continent in recent years. In winter, it brings warmth and peace of mind, and as long as you sit at it, you can spend the entire day without moving. Some have even begun to refer to this phenomenon as the Spell of Warm Table.]],
  str_item_intro_3661012 = [[
Furniture item. Can be placed in rooms on your Colossus.
The spruce is the most common tree in Northland, and it is also an important material used in the construction of houses and furniture. Because of this, spruce has come to represent the concept of family in Northland, and people of Northland place spruce in their homes during the New Year holidays. They hang various decorations from the branches of the spruce and place gifts beneath them to be opened in the presence of family to celebrate their most important festival.]],
  str_item_intro_3661013 = [[
Furniture item. Can be placed in rooms on your Colossus.
People in the Far East love to celebrate holidays with this. Supposedly started as food, but once Northland people believed it could bring bliss, it was replaced with clay and clothes. However, it does resemble Tweety somehow...]],
  str_item_intro_3661014 = [[
Furniture item. Can be placed in rooms on your Colossus.
"Make a heart-shaped cake for your special someone when the time comes." The trend seemed to take off overnight, but it's quite popular among young girls. After all, not only is it pleasing to the eye, it's also delicious, and more importantly, it gives one such a delightful feeling!]],
  str_item_intro_3661015 = [[
Furniture item. Can be placed in rooms on your Colossus.
It seems to be a hanging ornament from the Far East. Light and convenient, it can be hung under eaves or at doors or windows. As long as there's wind, it'll make a clear, ringing sound that's simply refreshing and relaxing.]],
  str_item_intro_3661016 = [[
Furniture item. Can be placed in rooms on your Colossus.
This cute looking bear is perfect as a gift and is also surprisingly tasty. But, can you really bear to eat it?]],
  str_item_intro_3661017 = [[
Furniture item. Can be placed in rooms on your Colossus.
It is said to be a toy based on the ancient king's jester. It looks silly and cute and serves as a great gift, certain to bring a unique kind of joy.]],
  str_item_intro_3661018 = [[
Furniture item. Can be placed in rooms on your Colossus.
Favored by members of the Rediesel Wrench, this helmet provides protection in all kinds of accidents and shields the rider from wind and dust. Its bright colors ensure its wearer never goes unnoticed.]],
  str_item_intro_3661019 = [[
Furniture item. Can be placed in rooms on your Colossus.
This Soroz model is made from thin sheets of material that have been joined together. It appears to be the masterpiece of some kids, and while it resembles the real thing in many ways, some details reveal the joy and humor of young children.]],
  str_item_intro_3661020 = [[
Furniture item. Can be placed in rooms on your Colossus.
A custom-made gigantic cake tower made to celebrate one year of being together. It is marvelous when placed in front of your eyes. Because it is so... tall! Other than its stunning appearance, every layer of cake also spins slightly, revealing its various, colorful lace.]],
  str_item_intro_3661021 = [[
Furniture item. Can be placed in rooms on your Colossus.
Oh... it has been a year already. All those past memories can be found on it.]],
  str_item_intro_3662118 = [[
Furniture item. Can be placed in rooms on your Colossus.
An warning letter poster that the Phantom Thieves of Hearts sends to their targets in another world. The graphic design is quite artistic.
Looking at the poster, Fox seems very pleased with himself. Or is it your imagination?]],
  str_item_intro_3661022 = [[
Furniture item. Can be placed in rooms on your Colossus.
Do these colors look familiar to you? That's right! This surfboard was designed based on Brock and is just as durable, reliable, and easy to control as him!]],
  str_item_intro_3661176 = [[
Furniture item. Can be placed in rooms on your Colossus.
Someone actually planted the whole tree in a pot! Just for the view! They must be really fond of palm trees to think of this.]],
  str_item_intro_3661171 = [[
Furniture item. Can be placed in rooms on your Colossus.
A lifelike starfish sculpture, which can be mistaken for a real starfish at first glance. Though made with soft sand, it's somehow able to keep its form and is unexpectedly tough.]],
  str_item_intro_3661172 = [[
Furniture item. Can be placed in rooms on your Colossus.
Yes, it is solid but still made with sand. So, don't take the name too literally! It was given the name hoping it would last longer, and thus far, the castle has been held together quite well.]],
  str_item_intro_3661173 = [[
Furniture item. Can be placed in rooms on your Colossus.
Check it out! An event filled with many wonderful jaw-dropping performances that the audience will never forget! That's why even its poster looks alluring.]],
  str_item_intro_3661174 = [[
Furniture item. Can be placed in rooms on your Colossus.
A multicolored ball. Just giving it a few spins on a stage is enough to turn the audience's eyes, let alone all the vaudeville tricks one can perform with it. One of the key items needed in an amazing show.]],
  str_item_intro_3661175 = [[
Furniture item. Can be placed in rooms on your Colossus.
Lots of balloons! They're colorful and make you feel a little buoyant when you hold onto them! Just remember not to let children who are too young play with them, or else the balloons might really drag them into the sky!]],
  str_item_intro_3661177 = [[
Furniture item. Can be placed in rooms on your Colossus.
What kind of tree is this? Its branches are all gnarly and twisted... It looks like the kind of tree you would see in a horror movie. It would be even scarier with a few spooky lanterns hanging from it...]],
  str_item_intro_3661178 = [[
Furniture item. Can be placed in rooms on your Colossus.
Is it supposed to be... smiling? Only the person who made it would know, but there's definitely something strange about how it's smiling. Again, is that really a smile...?]],
  str_item_intro_3661179 = [[
Furniture item. Can be placed in rooms on your Colossus.
Glub, glub, glub... Who knows what kind of crazy concoction is boiling in this cauldron? Could it be a love potion, like the ones in fairy tales? Or maybe something much more sinister...]],
  str_item_intro_3661180 = [[
Furniture item. Can be placed in rooms on your Colossus.
An odd puppet made by even odder merchants in Umbraton. On the surface, it looks just like Soroz, but if you squeeze it just a little bit... It belts out a loud and creepy scream. I wonder what kind of shenanigan this is supposed to be?]],
  str_item_intro_3661023 = [[
Furniture item. Can be placed in rooms on your Colossus.
Once filled with water, it will continuously generate a water flow using its built-in mechanisms. Perfect for combating the torrid summer heat. By the way, do remember to wipe the floor after use.]],
  str_item_intro_3661024 = [[
Furniture item. Can be placed in rooms on your Colossus.
This unicycle can actually move forward even with one wheel! It's just a little slow... When watching the rider's acrobatic riding skills, one can't help but feel amazed and anxious at the same time.]],
  str_item_intro_3661025 = [[
Furniture item. Can be placed in rooms on your Colossus.
It appears to be an ancient device found in one of the many mysterious ruins of Astra. Despite being relatively old, it still works surprisingly well, and can faithfully record video footage.]],
  str_item_intro_3701001 = "This book is just one volume in a series. Put it on the bookshelf in the Cafe, so you can take a look at it whenever you want!",
