Beneath the scarlet curtain is a dark nursery rhyme...]],
  str_item_intro_3763013 = [[
Unlocks the corresponding avatar frame.
The striking crown is a token of honor and dignity.]],
  str_item_intro_3763014 = [[
Unlocks the corresponding avatar frame.
Exclusively for the Grand Marshal!]],
  str_item_intro_3763015 = [[
Unlocks the corresponding avatar frame.
"Will wearing this improve one's hospitality skills?"]],
  str_item_intro_3763016 = [[
Unlocks the corresponding avatar frame.
Wear this, great magician!]],
  str_item_intro_3763017 = [[
Unlocks the corresponding avatar frame.
The sun is really strong, so take care of yourself and don't get sunburned!]],
  str_item_intro_3763018 = [[
Unlocks the corresponding avatar frame.
It's the 1st Anniversary! Put it on and go celebrate!]],
  str_item_intro_3763019 = [[
Unlocks the corresponding avatar frame.
Just put this on and you'll look all fuzzy like a Bica!]],
  str_item_intro_3763020 = [[
Unlocks the corresponding avatar frame.
Don't worry, it isn't hot!]],
  str_item_intro_3763021 = [[
Unlocks the corresponding avatar frame.
Does it look like a bat's claw is grabbing your head? The headband is just too tight.]],
  str_item_intro_3763023 = [[
Unlocks the corresponding avatar frame.
They say wearing this cap helps you rap better. Surprisingly, it improves your baseball skills too.]],
  str_item_intro_3763024 = [[
Unlocks the corresponding avatar frame.
A must for any singer! Immerse yourself in the music!]],
  str_item_intro_3763025 = "Unlocks the corresponding avatar frame.\nIt's not for eating—it's for wearing!",
  str_item_intro_3763026 = [[
Unlocks the corresponding avatar frame.
Can wearing this really make you as strong as Jeriah? One thing is for sure, at least it'll keep you safe from the wind...]],
  str_item_intro_3763027 = [[
Unlocks the corresponding avatar.
"Actually, it's a pair of clear lens glasses."]],
  str_item_intro_3763028 = [[
Unlocks the corresponding avatar.
"Aha! He's the culprit!"]],
  str_item_intro_3763029 = [[
Unlocks the corresponding avatar frame.
"2-Year Anniversary? Put it up! Just remember to take down the one from last year, eh?"]],
  str_item_intro_3763031 = [[
Unlocks the corresponding avatar frame.
"Does that world really exist? If it doesn't, why am I here?"]],
  str_item_intro_3763032 = [[
Unlocks the corresponding avatar frame.
It looks easy to get pricked; who would be willing to wear it...]],
  str_item_intro_3763033 = [[
Unlocks the corresponding avatar frame.
That's what you mean by being a gentleman?]],
  str_item_intro_3800001 = "Contains 50 Lumamber.",
  str_item_intro_3800002 = "Contains 50 Lumamber.",
  str_item_intro_3800003 = "Contains 50 Lumamber.",
  str_item_intro_3800004 = "Contains 50 Lumamber.",
  str_item_intro_3800005 = "Contains 50 Lumamber.",
  str_item_intro_3801001 = [[
Legendary Aurorian breakthrough material.
All members of the Silent Hunters own this crest. Although a thousand years have passed, it still contains great power and can stimulate the potential of the Silent Hunters.]],
  str_item_intro_3900101 = "After each simulated command, the Command Archives will award a certain number of points according to your performance. After accumulating a certain number of Command Points, you will be promoted to the corresponding Command Level, representing your tactical proficiency.",
  str_item_intro_3900201 = "You can obtain valuable Data Fragments from the simulation room's Command Battles via the massive data collection stored on its Data Disks. With enough data fragments, you can get a complete message from them.",
  str_item_intro_3910100 = [[
Through diligent training comes victory.
Defeat all the enemies in this Data Disk challenge to clear the stage.]],
  str_item_intro_3910200 = [[
Often, the purpose of combat is not to defeat the enemy but to gather enough resources to win the war.
In this challenge from the Data Disk, you need to obtain X number of special items to clear the stage.]],
  str_item_intro_3910300 = [[
Defend your allies to the last, even if it costs you your life.
In this challenge from the Data Disk, ensure that the NPC survives for X rounds.]],
  str_item_intro_3910400 = [[
Do you know what kind of enemy lies ahead? Without exception, they are guaranteed to be very strong. Please be careful.
In this challenge from the Data Disk, defeat the elite enemy to clear the stage.]],
  str_item_intro_3910500 = [[
The mind is sharper than any sword.
In this challenge from the Data Disk, you must solve the puzzle to clear the stage.]],
  str_item_intro_3910600 = [[
Battle is a game, much like chess.
In this challenge from the Data Disk, defeat all of the enemies to clear the stage.]],
  str_item_intro_3910700 = [[
On the cruel battlefield, the only true victor is the last survivor.
In this challenge from the Data Disk, survive for X rounds to clear the stage.]],
  str_item_intro_3910800 = [[
The enemy strikes like waves, and your defense will be the levee. Just hold on.
In this challenge from the Data Disk, defeat all the enemies to clear the stage.]],
  str_item_intro_3910900 = [[
You and your enemies share the same tactics. You may be kindred spirits.
In this challenge from the Data Disk, defeat all the enemies to clear the stage.]],
  str_item_intro_3911000 = [[
Cut off the head of the snake, and the body will fall. Defeat the enemy leader, and victory will be yours.
In this challenge from the Data Disk, defeat the enemy leader to clear the stage.]],
  str_item_intro_4090014 = "Bound by fate, the twins' memories slowly piece together, as a snow-white daffodil blossoms beneath the inky snowfall by Lake Mirror, awaiting their reunion through the mirror.",
  str_item_intro_4090334 = "Provided by the Cloud Blossom Hotel, this robe exemplifies the local Cloud Mountain style. This yukata was tailor-made for Vice. It comes with a unique sash and pendant, as well as adorable bells, creating a gentle air somewhat uncharacteristic of Vice. Whenever she puts on this yukata, she recalls that unforgettable and precious memory.",
  str_item_intro_4090923 = "Stop staring at me...!\nCould anything be more embarrassing? Entwining thorns lifting Pact's feet, tearing her silk stockings and black veil to pieces. Amid the chaos, Pact tries to balance the glass of red wine in her hand—it seems that this dignified and luxurious dress is not as easy to control as it looks.",
  str_item_intro_4090383 = "This is bad! Gronru is stuck in her toy box and can't get out! To celebrate the coming of the New Year, Gronru has a surprise gift for you! Just look at how cute she is, stuffed in there with a pile of toys in that festive red and white outfit—she even tied up her mechanical arm with a pretty bow! Just try to ignore the deadly-looking bomb in her hand...",
  str_item_intro_4090333 = "Vice chose a simple and comfortable swimsuit to attend the Ocean Sovereign festival. This swimsuit adopts a specially structured design to precisely match Vice's wearing habits and allows her tail to be placed freely. In addition to its special structure, look carefully and you'll notice that the black and gold sun cover also suits her vibrant personality. As her ice crusher crunches away, this short-haired beauty sends you an invitation to join her in the water with a smile. Beach volleyball, ice-cold drinks, the shaved ice cart... during that summer, you and Vice shared some deeply personal memories.",
  str_item_intro_4090853 = "An eerily alluring outfit composed of a captivating top, elegant skirt, beautifully woven sleeves, a ceremonial veil, and stylish boots... Not only is Jane's outfit stunning, the flowers along the hem of her skirt also hold some special meaning. Why would she choose to wear this kind of attire when she prides herself on being an outsider?",
  str_item_intro_4090863 = "Part of the White Maiden series designed for the Ocean Sovereign celebration. Its impeccable pure white glow has been specially selected to reflect the innocence and piety inseparable from Uriah's identity. Flower vines appear around her, silently heeding her call. To others, her state of mind remains unchanged. Only the flowers around her know the truth—when standing in full view by the seaside, she cannot help but feel a little shy in this outfit. The sunny sky, the salty ocean breeze, the cold seawater... When she waves her ceremonial sword, the most beautiful and poetic music will play once more.",
  str_item_intro_4090573 = "As Philyshy curls up in bed wearing her fuzzy pajamas, she falls into a deep sleep and dreams a beautiful afternoon dream. In this dream, Yumi is beside her, hugging her and stroking her hair—like a little personal heater, warming her heart and taking her back to simpler times.",
  str_item_intro_4091023 = "This simple outfit embodies the essence of what it means to have a burning soul, and in the dark, oppressive confines of the underground arena, it serves as the only guiding light. Renegades take the stage, fighting with robust bodies, spirit, and perseverance, their blood burning like fire. They rage like blazing meteors, then fade away like ashes. She snaps her fingers, ready to hunt down all in her sights.",
  str_item_intro_4090453 = "As the snow begins to fall and winter arrives with it. Now, the empty streets are filled only with the flicker of warm yellow lights. If you are a lonely traveler, don't worry about losing your way. Just look around the corner—your carriage awaits. With a white tuxedo, black boots, slick, shining hair, and elegant manners, a discreet and quiet gentleman has been waiting to give you a ride.",
  str_item_intro_4090993 = "Areia curls up coyly on the sofa, her bare legs, shoes discarded to one side, and quaint dress indicating that she has just returned from a ball. Like a fairytale princess, her graceful, magical gown will disappear with the ticking of the clock, but this memory—this time spent with you—will never disappear or fade.",
  str_item_intro_4090263 = "What is the meaning of existence for an incorporeal consciousness? After putting on these strange clothes, the baffling question lingers in Uriel's mind, compelling her to ponder it without end. Can she find the answer in the world of simulated literature? Who knows. But you can walk, think, and feel along with her quest.",
  str_item_intro_4090543 = "Stern and serious is Nadine's modus operandi. Never tiring, she always performs her duties. Even with her new spring outfit and cute little lantern, her character shines through.",
  str_item_intro_4091113 = "After arriving at the beach, even the usually melancholy Beryl is more relaxed than usual. This swimsuit is quite minimalist, but it's still able to accentuate Beryl's figure every now and then. However, she's oblivious to this and completed fixated on building her sandcastle. That is perhaps Beryl's favorite thing about this beach trip.",
  str_item_intro_4090883 = "Blue sky, white clouds, smooth streets—this doesn't look like the Rediesel Desert. Maggie looks very different as well with her crisp, clean sailor's uniform, and bow tie blowing in the wind. On this bright morning, you can see her riding leisurely, nibbling her bread. Won't she be late for school?\n\nThis outfit makes Maggie stand out among the Rediesel Wrenches, and it also lets her view different scenery. Maybe this is part of its magic?",
  str_item_intro_4090963 = "Um, teacher? Is it Sariel? It seems Sariel takes her second job seriously. She even put on the uniform! This new Sariel seems much more reliable than the old one. She speaks gently and eloquently. Perhaps soon you'll be able to take a lesson from her!",
  str_item_intro_4091053 = "The clothing might be ordinary, but Eve is still Miss Popularity in Rediesel Wrench. Even she doesn't know how popular she is. And now, as a cheerleader, she's even more loved after putting on this outfit! Just don't stare, or you'll get a wrench to the face!",
  str_item_intro_4090064 = [[
This light, silky smooth garment covered in ribbons... pajamas?! Why would anyone design such a thing? How is one supposed to wear it in front of others? Troubled, Carleen was at a loss at how to proceed, so she decided to try it on first, but she wasn't expecting to feel completely different from her usual serious self.
In order to join the slumber party and have a good time with everyone, Carleen decided to take the plunge.]],
  str_item_intro_4090303 = "Jet black sleeves and a crimson cloak. Presenting, the samurai who rid the world of evildoers—Shinnosuke!\nAs leader of the Rediesel Wrench, Sinsa practices the principle of \"do as the locals do.\" Be it the clothes he wears or the blade at his waist, they're a perfect representation of Cloud Island's charm, and even his laughter seems to be entirely spontaneous. But be warned, if this ronin samurai's in the right mood, he might recite an impromptu poem and sing a song...",
  str_item_intro_4090443 = [[
The breeze blows through the pines, and the warm sunshine lightens the hall. When you get away from the hustle-bustle of the city and endless work, why not take the opportunity to rest at the peaceful Cloud Mountain Hotel? Vivian's work-life balance principle is the true way to regain strength and energy before resuming work!
Of course, this must all be planned!]],
  str_item_intro_4090643 = "Wrath's new combat outfit is woven from oriental silk threads, not only slim-fitting but also elegant and graceful. Although it looks a little thin, it's easy to move around in, and it doesn't seem to impede her fighting ability at all.\nThrowing punches and flexing her muscles, rushing in and removing all obstacles in her path—no matter what dangers come her way, the unwavering Wrath will meet them headlong!",
  str_item_intro_4090893 = [[
To make the most of this rare holiday, Irridon prepared Cloud Island style clothes. The gold fabric adorned with embroidery paired with a snow-white fur cape looks simply magnificent. She was keen to wear her outfit out on a stroll through Cloud Island's streets or take a ride on the train to enjoy the sights.
However, sudden events upended all her plans, and in order to protect her vacation, Irridon didn't hesitate to turn Cloud Island's station into the Hall of Justice.]],
  str_item_intro_4090653 = [[
"Navigator, come pway hanetsuki with me!"
Tweety was in such excitement as she approached. But who knew a fun casual game was going to turn into a relentless battle for the top?! With such magnificent serves and strong drop shots, it's impossible for an ordinary player to survive!
Whoever loses the game will be punished by getting their faces drawn on. One can only hope that Tweety shows some mercy and controls herself a little...]],
  str_item_intro_4090233 = [[
Though shy by nature, Connolly decided to help cheer on her friends participating in the races. However, compared to what she was used to wearing daily, this uniform was really "something else."
Nonetheless, Connolly accepted the bold outfit pitched to her by a salesman in the hopes of becoming more outgoing.]],
  str_item_intro_4090613 = [[
"Ooh... So this is what the continent looks like!"
Chandra, high up in the clouds, has no fear of heights at all. As she watches the rally taking place far below, the intense competition causes her to exclaim from time to time. But... what's with the hot air balloon and her strange outfit?
Turns out it's all part of her mysterious "visualization therapy," which does seem to help people release pent-up emotions.]],
  str_item_intro_4090843 = [[
"As hot as desert sand and as fresh as spring water, a juxtaposition of the modern and the traditional."
"Shocking and outrageous..."
Though reviews varied wildly, the minute Istvan donned his costume, all criticisms fell away. Though better suited for a grand hall, even here he exudes the charisma of a superstar. Perhaps it's the aura of the "Shadowlord" himself that lends an extra charm factor.]],
  str_item_intro_4090603 = [[
A race judge's outfit always stands out. After all, in order for racers to spot the judges at high speeds, they'll need to stand out.
Jona, who only applied for the job because she needed money to cover her bar tab, soon discovered the race's dark secrets. Though she had intended to mind her own business, she ended up heading to the track for the sake of a little girl, determined to bring justice down on the crooks heading the fixed races.]],
  str_item_intro_4090713 = [[
The scorching sun causes racecars to emit columns of smoke, and sweat evaporates with a hiss as soon as it hits the ground.
Even so, Taki enters the races "fully prepared", determined to best his opponents. But is he really only in it for the money?]],
  str_item_intro_4091263 = "The best-selling author, who is caught in a creative bottleneck, dresses up nicely, planning to wander the streets for ideas. What's the point of dressing up? Perhaps, it's because she does not want people to know that the majestic guild manager has such a \"girlish\" hobby in private.\nBut be careful not to underestimate Bethel's dedication to her hobby—she is willing to risk it all just for a flash of inspiration...",
  str_item_intro_4090673 = "The breeze blows, and the fluffy white dress sways gently, revealing the embroidered red flowers. Alice's outfit somehow reminds people of... a type of cake. Yes. The strawberry cake one can only taste at birthday parties. But at Dream Dessert House, you can try any dessert you want for free as long as you answer the questions of Alice, the owner, honestly. This is Alice's special punishment for you. Oops, I mean... special \"reward.\"",
  str_item_intro_4090103 = [[
"A clean and tidy outfit is the pride of a maid"!
Put on the maid suit Lita sewed by hand and the lace-trimmed headband. Oh, don't forget to put on the apron with the golden bow knot.
Today Louise has to help the master get dressed and organize an afternoon tea. Don't worry, the bees, fawns, and even the clouds will help.
Look! The maid has started working already.]],
  str_item_intro_4090283 = [[
Ahem, let's give a warm welcome to the Head Maid of Upton Manor! What, she looks familiar? Yes, you are right. This is our lovely Raphael!
Recently, she received a special assignment to train the maids of Lumopolis in battle skills. Now the semester is drawing to its end, the maids, under the careful guidance of Raphael, have all achieved excellent results. It's just... Rafael's career as a maid doesn't seem to be going so well.]],
  str_item_intro_4091163 = [[
Fleur spent a lot of time and effort trying to make the bread in his memory, but he never succeeded.
This time, Fleur was better prepared. He changed into a neatly sewn shirt, a properly ironed apron, and put on polished shoes. The outfit is said to be the guarantee for making great bread. As cheesy as that sounds, Fleur still chose to believe it for the sake of his heart's content.]],
  str_item_intro_4090703 = "Under Leona's sharp scrutiny, you feel the air around you heat up and your breath shortens. Is it because of nerves? Indeed, who wouldn't be nervous in front of the powerful and beautiful Leona? With strappy sandals wrapped around her legs and her body adorned with accessories, she looks very different from her usual self. Still, she effortlessly exudes the feeling that everything in the world is her oyster.",
  str_item_intro_4090813 = "This is the costume that Brock specially prepared for himself in search of a certain \"something.\" Swimming trunks that help him get around easily, a surfboard in his special style, and a transparent coat that's reminiscient of a raincoat. Transparent coat? Let's be frank, the real reason Brock designed a transparent coat was probably to fish for compliments from us—Behold, that body of his built from protein powder and hard exercise, of sunshine and sweat, is longing for your praise.",
  str_item_intro_4091123 = "A popular urban legend in Umbraton recently. Calling cards, thieves wrecking chaos all over, a stolen gem... Is our key suspect the careless Smokey after all? If you want to know the truth, I'm afraid you will have to unlock her handcuffs first. Of course, her new title is as intriguing as her new clothes—\"Black Cat,\" who will come and pick up the gems in three days, just as promised.",
  str_item_intro_4090384 = "Did this outfit come first, or did the game that this outfit accompanied come first? It doesn't matter anymore. The important thing is that Gronru prepared this especially for her vacation and entered holiday mode right away after wearing it. Even if she is just going to the aquarium for a day and not the beach.",
  str_item_intro_4090413 = "How many identities does she have? She's the Guide of Lumopolis, but she has many other responsibilities as well. One of them is to serve as the public ambassador for the Tir' Hotel. This swimsuit she's wearing is for a flyer's photoshoot. Delicate and precise, it's made of the most exquisite material. Looking at her, one can't help but wonder about this hotel she's promoting.",
  str_item_intro_4090873 = "Beverly wears this swimsuit of armor to fit in better with the local environment when she visits her family's island territory. Although it is much more minimalistic than her usual attire, her aristocratic aura is too strong to hide, not only because of her warrior familial roots, but also because of her pursuit of a noble's honor.",
  str_item_intro_4091293 = "Although he is dressed in cool summer clothes, his serious gaze informs everyone that he is not here to relax but to complete a compulsory mission. This outfit allows Luke to maintain his stamina in the hot and humid forest, and it is also a formal outfit specially prepared to be worn in the fight to protect precious butterflies from shameless poachers.",
  str_item_intro_4091483 = "The water party in the desert is about to begin, but what makes a lot of people particularly excited is the opportunity to witness Azure's amazing figure! She's especially alluring under the sheer clothing... Ahem, please control yourself and don't stare for too long! Enjoying a warm, humid evening breeze, listening to loud music, and dancing with a crowd from time to time is a blast!",
  str_item_intro_4090254 = "A magnificent stage outfit that gives off an elegant air of ancient nobility. It looks quite out of place with today's fashion, but that is because Charon designed his new costume to be this way. Extravagant as it may be, it quickly grabs the audience's attention whenever Charon stands before the camera, granting him the opportunity to showcase his unforgettably impressive acting skills at their full potential. In those moments, it can be said that both Charon and his costume were made for acting.",
  str_item_intro_4090683 = "Extra, extra! A recent collaboration between the Courier Union and the Umbraton newspapers gives couriers an added job: newspaper subscription sales. And thus, Wendy dons her brand-new papergirl uniform and sets off on her newspaper selling endeavors with her characteristic excitement and diligence! Wendy's speedy and spirited nature never lets her fall behind her peers, even when she's taking on an unfamiliar task!",
  str_item_intro_4091003 = "Sikare, usually bound to the past, has switched up her regular looks for a new one to deal with an unexpected situation. While she looks like a regular doctor, the contents of her briefcase is filled with medical instruments that are anything but ordinary. This is because she must not only attend to the maladies of the living, but to the wishes of the dearly departed as well...",
  str_item_intro_4091203 = "Thanks to popular demand, Hedy ends up participating in an exchange event meant to foster unity and cooperation between the Illumina Federation and Lumopolis. At her superiors' behest, she travels to Gannon City to act as a sheriff for a day, promoting traffic safety and crime prevention on the streets. Despite being a proud knight of Lumopolis, Hedy obeys and dons her Federation uniform. Though she finds it somewhat uncomfortable, it does not obscure her natural charm and confidence.",
  str_item_intro_4091193 = "Revy intentionally lands herself in jail in her endeavor to obtain a legendary hot sauce of her memories, heading into danger alone. Behind those massive stone walls, she finds herself surrounded by hardened criminals from criminally-rampant areas. A perilous situation, indeed... Can Revy, who hails from the Illumina Federation and has never before experienced the chaotic dangers of such a place, succeed in her special undercover mission?",
  str_item_intro_4091213 = "A beautiful, crimson flower adorned with countless, vicious thorns: everything about Paloma's appearance screams, \"approach at your own peril.\" Coupled with a faint smile, an air of cold elegance surrounds her. Those who lay eyes on this deadly damsel know in their hearts that provoking her would be the last thing they ever do. Incurring the wrath of the most sinister Umbraton crime lord would be a wiser decision by comparison. Or has she already become a crime lord...",
  str_item_intro_4090123 = "One day, a legend suddenly emerged in Gannon—that of the \"Enforcer of Justice\" aka \"The Punisher.\" A sudden flash of lightning splits open the sky whenever someone breaks the rules, and Nemesis appears beside them to hand down thunderous punishment. After doing so, she delivers a one-liner that cuts them to the bone and forces them to repent. After executing her justice, she disappears in a flash of light to punish another evildoer.",
  str_item_intro_4090773 = "On a rare day off, Bethlehem stumbles upon the biography of a talented songstress. She soon gets lost in the pages of this book, becoming one with the singer, experiencing her rise to fame, her triumphs, and then the loss of her voice. \"What if I were just like her?\" It's a question for which Bethlehem has no answer. All she can do is imagine herself in the songstress's shoes, picking up a musical instrument and performing. She imagines having a passion for creation, she imagines inevitably losing her voice on the stage, she imagines life as the songstress, all while coming to terms with her own future.",
  str_item_intro_4090833 = "In order to awaken Lilin, who they defend so ardently, they must... become idols? Even so, they seem to rigidly abide by their programming as maids. Can they really make it to the top of a profession where vitality and creativity are crucial? Well, if there is a blueprint they can follow, and their number advantage can be utilized somehow, it might be possible...",
  str_item_intro_4091313 = "Although he maintains his unique perspective of the world, Novio becomes a master pianist the instant he dons this new look. He brings warmth and goodwill to the strong-hearted survivors of Northland, and encourages a certain special audience member to persevere and move forward resolutely, forever striving for self-improvement.",
  str_item_intro_4091383 = "Although her superior forces her to take part in the idol competition, Siobhan still does her utmost to prepare well. While working on her talents, she also devotes considerable effort to researching and designing the perfect outfit. This unyielding spirit of scientific research brings about an amazing transformation in Siobhan—her shining light that cannot be extinguished, the unignorable road to future stardom.",
  str_item_intro_4090273 = "She is a horror among the lovers of Lumopolis—Each Mooncrown Day, there will be a knight in white patrolling all corners of the city, looking for those in love. As soon as she finds one, she will immediately issue a \"Ban on Falling in Love.\" Therefore, she is known as the \"lightning strike that breaks love,\" which terrifies lovers.",
  str_item_intro_4090553 = "Unlike his usual professional look, Pittman seems to have been influenced by the festivity of Mooncrown Day when he chose his outfit. It carries a gentleness not often seen in him without losing his usual firmness and elegance. Of course, this is not because he is spoken for, but simply to be a qualified messenger and fulfill a long-cherished wish of someone else.",
  str_item_intro_4090913 = "In Chloe's world, love always comes with separation, so it would be a little too much to ask her to play the music that celebrates sweet love. In that case, we might praise the eternal love in the name of God—people's affections may fade after a few years, but worry not, the light will bless and love everyone equally.",
  str_item_intro_4091673 = "There is no shortage of all sorts of magic tricks in a social place like this, but a sense of mystery is the key to all of them. A card, a word, or even just a glance. One could complete the grand and exquisite performance in a moment of inattention with none the wiser. Although there is no applause like usual, it's a good deal for Jeno when he wants to do favors for his friends once in a while.",
  str_item_intro_4090043 = "A cold corpse, marked clues, cordon after cordon... Such a classic and suspenseful scene can always make everyone's imagination go wild. For instance, the detective could be the murderer or colluding with the murderer, the murderer could be hiding among us, or all the witnesses could be murderers... Who would have thought the deceased and the detective were working together?",
  str_item_intro_4090483 = "An ominous atmosphere crept into the peaceful streets of Umbraton. Although passers-by on the street seemed to enjoy the quiet night, the vigilant eyes of one particular patrol officer watch closely to capture all traces of sin. As long as they are hiding in this city, she, the guardian of peace, will not stop patrolling the streets. Everything is for... her one and only sister!",
  str_item_intro_4091484 = "An office with bright and clean windows, a soft sofa, intoxicating wine, and the interim director half lying down on the sofa. Don't let her lazed demeanor deceive you—this beautiful woman is dangerous, especially to the one who would soon become her prey, in a literal way.",
  str_item_intro_4091663 = "\"Well... where are those cute little ones?\" To find those wondrous beasts and expose the truth, Fia becomes a detective and starts to investigate this mysterious case carefully by examining all kinds of evidence and considering the key points of suspicion. Looking at how earnest and hardworking she looks, maybe she really will discover something.",
  str_item_intro_4090983 = "Under the order of the Shadowlord, the reclusive Cuscuta is tasked to be a detective and catch rampant criminals. Though she struggles with street visits and witness interviews, her keen intuition allows her to deduce the criminal's identity from the clues at hand. From the comfort of her chair, she observes the chess game and loses herself in contemplation until she finds the answer through deduction.",
  str_item_intro_4091034 = "People should not commit crimes, or they will face condemnation from the heavens, which is known in the mortal world as trial, judgment, and punishment. Of course, the process is not as terrifying as it sounds, especially when Eicy becomes your interrogation officer. The gentle girl never relies on violence to break down a person's defenses... Or rather, those defenses are useless in the first place. So if you ever meet her, don't put up a pointless fight. Just leave everything to Eicy.",
  str_item_intro_4090293 = "In order to honor the master's final wish, Gabriel donned a magnificent gown and ventured to the orphanage in Umbraton. The gloomy and rundown surroundings contrasted with the exquisite attire, and Gabriel's somewhat clumsy actions led the orphans to mistake her for a witch. But in the end, the orphans sensed Gabriel's heartfelt dedication to safeguarding their home, and the dress itself seemed to radiate a comforting light.",
  str_item_intro_4090463 = "To adults, it may be a frightful grimoire of black magic, but to them, it is a gateway into a wondrous realm of fantasy, enchantment, and extraordinary wonders crafted exclusively for their inquisitive and spirited souls. To concoct the forbidden potion, they tirelessly search for peculiar ingredients, donning unique attire that only further accentuates their individuality.",
  str_item_intro_4090623 = "To ensure the study session organized by Leah goes smoothly, Sylva made a special effort to don this formal attire, resembling a young scholar ready to meet his esteemed teacher—intelligent, wise, and well-mannered. His demeanor effortlessly infused the study session with a positive atmosphere, earning him the title of a 'model student'...",
  str_item_intro_4091433 = [[
While traveling the forest at night, ominous beings are said to linger in the world following a thunderstorm. For this reason, Rinne dons her ceremonial garments and holds the Kagura Bell high, ready to purge vile presences from this world in defense of the living.
"An ode to the dead and the living. May this song accompany you to the other side of the River Lethe."
"The River Lethe flows. Resentment and bitterness grow."
"The datura sings in harmony."
"Listen peacefully. Let your soul follow me."]],
  str_item_intro_5000001 = "It is said to contain some mysterious substances with ancient information, which can speed up building construction and furniture making.",
  str_item_intro_5000002 = "Cloud Gardens - Treasure Refreshes",
  str_item_intro_5002101 = "Tough wood, suitable for building construction, furniture making, etc.",
  str_item_intro_5002201 = "The newly excavated ore needs to be further processed. Having said that, it already has some value on the market.",
  str_item_intro_5003001 = "Stone pieces found in various parts of Cloud Gardens that are supposed to be relics, but their exact function is unknown. The Chubbs do like these pieces and will exchange certain things for them.",
  str_item_intro_5003101 = "A common glue for building construction and furniture making, which can bind materials together well and make the components strong.",
  str_item_intro_5003102 = "The best glue for building construction and furniture making. Just a little bit of it is enough to bind the materials tightly and make the components very strong.",
  str_item_intro_5011001 = "Light Axe Lv. 1. Its handle is hollow, allowing it to cut through thick tree trunks quickly.",
  str_item_intro_5011002 = "Light Axe Lv. 2. Its handle is hollow, allowing it to cut through thick tree trunks quickly.",
  str_item_intro_5011003 = "Light Axe Lv. 3. Its handle is hollow, allowing it to cut through thick tree trunks quickly.",
  str_item_intro_5011004 = "Light Axe Lv. 4. Its handle is hollow, allowing it to cut through thick tree trunks quickly.",
  str_item_intro_5011005 = "Light Axe Lv. 5. Its handle is hollow, allowing it to cut through thick tree trunks quickly.",
  str_item_intro_5012001 = "Champion's Rod Lv. 1. It's well-balanced, tough, and has a strong fishing line, making it a great tool for catching big fishes.",
  str_item_intro_5012002 = "Champion's Rod Lv. 2. It's well-balanced, tough, and has a strong fishing line, making it a great tool for catching big fishes.",
  str_item_intro_5012003 = "Champion's Rod Lv. 3. It's well-balanced, tough, and has a strong fishing line, making it a great tool for catching big fishes.",
  str_item_intro_5012004 = "Champion's Rod Lv. 4. It's well-balanced, tough, and has a strong fishing line, making it a great tool for catching big fishes.",
  str_item_intro_5012005 = "Champion's Rod Lv. 5. It's well-balanced, tough, and has a strong fishing line, making it a great tool for catching big fishes.",
  str_item_intro_5013001 = "Weighted Pickaxe Lv. 1. With a weighted head, its swinging force is strong enough to break any rocks.",
  str_item_intro_5013002 = "Weighted Pickaxe Lv. 2. With a weighted head, its swinging force is strong enough to break any rocks.",
  str_item_intro_5013003 = "Weighted Pickaxe Lv. 3. With a weighted head, its swinging force is strong enough to break any rocks.",
  str_item_intro_5013004 = "Weighted Pickaxe Lv. 4. With a weighted head, its swinging force is strong enough to break any rocks.",
  str_item_intro_5013005 = "Weighted Pickaxe Lv. 5. With a weighted head, its swinging force is strong enough to break any rocks.",
  str_item_intro_5014001 = "The shovel head is thickened, so even if it hits hard rocks, it will never chip. It will make digging like a breeze.",
  str_item_intro_5011012 = [[
A rough, hard stone that can sharpen a dull edge.
The Light Axe can be upgraded in the backpack.]],
  str_item_intro_5012012 = "The high-quality wood found in Cloud Gardens is cut into thin slices to increase the hardness of the rod body and maintain its tenacity. With the special fishing line, the Champion's Rod can easily cope with all kinds of situations. The Champion's Rod can be upgraded in the backpack.",
  str_item_intro_5013012 = [[
By turning the wheel quickly by hand, you can sharpen the blunt tip of the pick.
The Weighted Pickaxe can be upgraded in the backpack.]],
