  str_item_intro_5176207 = "This is the Nostalgia Chair blueprint. Use it to unlock the item's production method in the Hyacinth Tower.",
  str_item_intro_5176208 = "This is the Nostalgia Banner blueprint. Use it to unlock the item's production method in the Hyacinth Tower.",
  str_item_intro_5176209 = "This is the Nostalgia Lamp blueprint. Use it to unlock the item's production method in the Hyacinth Tower.",
  str_item_intro_5176210 = "This is the Nostalgia Fence blueprint. Use it to unlock the item's production method in the Hyacinth Tower.",
  str_item_intro_5176211 = "This is the Nostalgia Plant blueprint. Use it to unlock the item's production method in the Hyacinth Tower.",
  str_item_intro_5176212 = "This is the Nostalgia Vine Canopy blueprint. Use it to unlock the item's production method in the Hyacinth Tower.",
  str_item_intro_5134049 = "This is the Record Obelisk blueprint. Use it to unlock the item's production method in the Hyacinth Tower.",
  str_item_intro_5211001 = "A pavilion with crooked pillars and a moss-covered stone roof. Although it does not seem to be in line with architectural common sense, the pavilion is nevertheless really sturdy.",
  str_item_intro_5211002 = "The archway is said to be carved from a single block of stone, and even if it is covered with a layer of grass, there is no need to worry about its durability.",
  str_item_intro_5211003 = "A stop for people to take a break when transporting supplies in the valley. It is fast to build and easy to disassemble, so many can be built en route.",
  str_item_intro_5211004 = "A bottomless well built at the collection of groundwater sources. A stone fence was installed around it to avoid falling into the water. As the well is very deep, the water is pure and cool.",
  str_item_intro_5211005 = "A uniquely shaped windmill. Though it appears to be on the lower end, it makes sufficient use of the wind! And with some wonderful technology, the sails will slowly rotate even when there is no wind.",
  str_item_intro_5221001 = "Wooden fences. When connected, they can enclose a piece of land in Cloud Gardens.",
  str_item_intro_5221002 = "Shorter railings. The randomly spliced wooden strips give off a rustic vibe.",
  str_item_intro_5221003 = "Wooden hedges that are easy to make. Ideal for barricading and dividing areas.",
  str_item_intro_5221004 = "Stone fences that are heavy but strong. They are more durable than wooden fences.",
  str_item_intro_5221005 = "Stone hedges. Once planted in the ground, they can be used for many years, even when they are exposed to different weathers.",
  str_item_intro_5221006 = "The sturdy stone railings not only look stable, but also give people a sense of security.",
  str_item_intro_5223001 = "Square floor tiles that can be laid neatly. Suitable for main roads and important buildings.",
  str_item_intro_5223005 = "Floor tiles made of irregular stones. Suitable for paving paths and decorating courtyards.",
  str_item_intro_5231001 = "A table supported by two trapezoidal stone slabs. Heavy but sturdy.",
  str_item_intro_5231002 = "A smaller round stone table. When paired with the corresponding chairs, are suitable for casual conversations between two friends.",
  str_item_intro_5231003 = "A wooden table with supports on all four sides. Wide and flat, it is suitable for multiple people to sit together in leisure.",
  str_item_intro_5232001 = "A round stone bench with a stone pillar inside the hollow body for support. It is not only sturdy, but its rounded edges also reduce safety hazards.",
  str_item_intro_5232002 = "A square stone bench, which is wide at the bottom and narrow at the top, has a layer of wood on it to isolate the cold air of the stone. It is generous in shape and simple in production. The only fly in the ointment is that it is easy to hit the edge of the stone bench.",
  str_item_intro_5232003 = "A simple and lightweight wooden chair that is supported on both sides. The chair will wobble slightly when you sit on it.",
  str_item_intro_5232005 = "Suspended by a rope from an oddly shaped stone pillar, the bed is designed in the shape of a round leaf, which cleverly maintains its balance and allows people to lie comfortably in it without falling over.",
  str_item_intro_5232006 = "A bench composed of a stone platform. You can not only sit but also lie down on it. As it is made of stone, it is also cool to the touch.",
  str_item_intro_5233001 = "Two rocks, one large and one small, are placed in a staggered manner. If placed in the right position, they can bring unique scenery to the surrounding residences.",
  str_item_intro_5233002 = "It looks like a stalagmite that has been magnified several times. If properly decorated, it will let off a different vibe.",
  str_item_intro_5233003 = "A cluster of several pieces of variously shaped pebbles, usually placed as a decoration on the roadside and in the courtyard.",
  str_item_intro_5233004 = "The roof of the pavilion is umbrella-shaped. Supported by a column, it is intentionally designed to be lopsided, supposedly to create more shade. Its ceiling is covered with vines. When the wind blows through the hanging branches and leaves, it is a special scene.",
  str_item_intro_5233005 = "The combination of overlapping rocks, small waterfalls formed by gurgling water, and a small pool surrounded by thick stone flakes can bring continuous and pleasant water sounds to the courtyard.",
  str_item_intro_5233006 = "An upright rock pillar that can be used as the main body of a rock group.",
  str_item_intro_5233007 = "It is made up of many slanting rock pillars and looks like a small mountain.",
  str_item_intro_5233008 = "The slightly inclined rock pillars are well-suited to be the transition between rocks that are vastly different in shape.",
  str_item_intro_5233009 = "With its sharp peak and slender overall shape, this rock pillar delivers a sense of coldness. It is best to find suitable rocks to match it.",
  str_item_intro_5233010 = "It looks like a sloping hill and can also be considered as the main body of a rock group.",
  str_item_intro_5234001 = "A street lamp that offers long-lasting brightness using some fantastic technology. This low lamp can only illuminate a small area.",
  str_item_intro_5234002 = "A street lamp supported by a pole. The height of this light source allows it to illuminate distant areas.",
  str_item_intro_5234007 = "A tall flower stand that allows people to enjoy blooming flowers from a distance.",
  str_item_intro_5234009 = "With various road signs nailed to its top, this wooden plate can keep people from getting lost in Cloud Gardens. Just be sure to put it in the correct position!",
  str_item_intro_5234011 = "An umbrella that can bring enough shade. Its downside is that it is a little heavy and difficult to carry.",
  str_item_intro_5234012 = "A flower named after the sun. Its tall stem and large flower give it an arrogant temperament. Some people believe this flower represents \"a light-seeking heart.\"",
  str_item_intro_5234013 = "An area that was piled up with stones. The ground has been leveled, and this area is specially used for planting various flowers.",
  str_item_intro_5234014 = "A low flower stand. Suitable for roadside and door-front decorations.",
  str_item_intro_5234018 = "A single-person tent used in the wild. The cone shape ensures that the tent is sufficiently tall. It is easy to set up but so small that it can only accommodate one person.",
  str_item_intro_5234019 = "A tablecloth with all kinds of food. It seems you'll be able to enjoy a delicious meal in the wild!",
  str_item_intro_5234020 = "A sturdy and heat-resistant stove. The gap in the base ensures good air intake for huge flames that emit intense heat.",
  str_item_intro_5234023 = "Even weeds shouldn't be wasted. Collect them now because you never know what you can use them for later.",
  str_item_intro_5234024 = "A large crate made out of wooden boards that is easy to process. It is very suitable for storing materials.",
  str_item_intro_5234025 = "A stack of several wooden crates. You know it's a warehouse when you see them.",
  str_item_intro_5234037 = "A campfire stove built with stones. Suitable for starting a controlled fire in the wild.",
  str_item_intro_5234038 = "An anchor salvaged from the bottom of the sea. It is extremely strong and sturdy and looks like it can hold a large ship in place even when the ocean is turbulent. It's a pity that its charge has long disappeared, leaving it waiting perpetually for a new owner.",
  str_item_intro_5234039 = "Powered by undulating waves, this surfboard enables its user to come and go as they please on the water and execute various moves. It seems like a pity to place this in Cloud Gardens...",
  str_item_intro_5241002 = "A swing that wobbles slightly when you sit on it. Be careful not to swing too high! Some people would like to sit on it and sleep. The rolling feelings can really make a person fall asleep quickly.",
  str_item_intro_5241003 = "A toy that offers an experience that slightly resembles real riding. It is said that people can use it to work on their balance.",
  str_item_intro_5241004 = "Kite flying is a good activity for sunny and breezy days. After flying the kite to the sky, as long as the string of the kite is tied on the shelf, it will not be blown away.",
  str_item_intro_5241005 = "A lightweight easel designed for outdoor sketching. It is just the right angle and size to keep you focused while drawing.",
  str_item_intro_5241006 = "The stage and loudspeakers are carefully positioned so that the audience can enjoy the performance from all angles. It is said that this theater also has wonderful technology, sometimes showing different special effects for various programs.",
  str_item_intro_5241007 = "It's said that this statue was built to commemorate a Caelestite woman who visited all the famous mountains and rivers on the continent. But no one remembers her name anymore, and this statue is all that's left for future generations to remember.",
  str_item_intro_5241008 = "Every time you see it, you will always want to give it a few punches... but you can never knock it down, which is a bit disappointed. Nevertheless, it's great for venting.",
  str_item_intro_5241016 = "A huge corridor. The columns look like the bones of some ancient creature... Some people say that the corridor is actually an important component of the Colossus.",
  str_item_intro_5242101 = "Despite its strange look on the outside, the unique structure allows for plenty of light and air in the room, making it very habitable.",
  str_item_intro_5243001 = "Fertile land that can provide sufficient nutrients for any kind of plant.",
  str_item_intro_5234008 = "The head of this scarecrow is made of linen. If you look at it from up close, it looks like a person with lots of pockmarks on his face and is quite the effective tool for scaring people with.",
  str_item_intro_5234015 = "A picture is worth a thousand words. This wooden sign can be understood with just a glance: \"Please don't hurt the pangalos!\"",
  str_item_intro_5234016 = "A device that can be used to tell the time by the projection of sunlight, the primitive form of a clock. The downside is that the sundial doesn't work on cloudy and rainy days or during nighttime.",
  str_item_intro_5234017 = "An instrument used to determine wind direction. It's sensitive enough that even a gentle breeze can be accurately measured. If the wind is too strong and changes directions from time to time, remember to take it down! Lest it spins too fast and breaks.",
  str_item_intro_5234026 = "A stone mill that seemingly requires a lot of effort to maneuver. Said to have been used to grind flour in ancient times. Although it has lost its efficiency in the modern era, it's still good for occasional strength-training.",
  str_item_intro_5234027 = "A lightweight but sturdy wooden barrel. The handle has a non-slip design so that it doesn't spill and no one's efforts are wasted.",
  str_item_intro_5234028 = "Although it is made of ceramic, its edges have been reinforced, making it resistant to falling and shattering, and there are handles to facilitate moving.",
  str_item_intro_5234029 = "A machine that only requires a single operator to spin fabric. The only downside of it is the complicated maintenance...",
  str_item_intro_5234030 = "A pot filled with lush green grass. It is very heavy and requires a certain degree of physical strength to move.",
  str_item_intro_5234033 = "A shelf covered in vines. It can provide shade in summer and remain green even in late autumn.",
  str_item_intro_5234036 = "A flower bed composed of three tiers of stones ensures that flowers can be planted in the uppermost tier to attract the most attention, while the lower two tiers can hold green fauna for added contrast.",
  str_item_intro_5241015 = "A fascinating device that you can place records on to play music. Loudspeakers have made it possible to transmit music so that it reverberates far off into the distance.",
  str_item_intro_5241017 = "Aquarium",
  str_item_intro_5251001 = "Hyacinth Tower",
  str_item_intro_5252001 = "Museum",
  str_item_intro_5253001 = "Store",
  str_item_intro_5254001 = "Fountain of Hope",
  str_item_intro_5255001 = "A large, sturdy, waterproof, and dustproof box that is capable of storing many items.",
  str_item_intro_5256001 = "Adventures with our friends are full of challenges, thrills, and lots of joy and laughter. To commemorate these unforgettable moments during our travels, our friends made these medallions and placed them here to remember bygone moments and victories.",
  str_item_intro_5270001 = "Breeding Plot",
  str_item_intro_5275001 = "For love and hope, let's spread our songs to the entire continent!\nThis stage was specially built for touring—it features various functions, can be erected in no time at all, and is also very sturdy, able to bear all manner of singing and dancing mayhem upon its solid surface.",
  str_item_intro_5275002 = "A few beats are all it takes to add that extra special atmosphere to a performance! If you believe a band has a natural leader, it's got to be the drummer. That's why this is essential for any touring stage.",
  str_item_intro_5275003 = "Even dance music requires some knowledge of musical composition, and with this easy-to-use keyboard, with a wide range of sounds and effects, any decent keyboard player can become a solo music-making machine.",
  str_item_intro_5275004 = "Wish upon a star! No one knows when this rumor started spreading among idol fans, but apparently, when you wish upon a star decoration like this, your heartfelt encouragement will be conveyed directly to your favorite idol!",
  str_item_intro_5275005 = "If you want to cheer on your favorite idol, you're going to need some official merchandise to wave in the air, so placing such a table like this near the stage only makes sense—that way, fans can get their hands on all kinds of supporter gear when they need it most.",
  str_item_intro_5275006 = "Most tours require a range of guitars to be prepared beforehand. This guitar stand not only allows guitarists to choose any guitar that suits their style, it also allows multiple guitarists to plug in and play together, lending an added level of excitement to any performance.",
  str_item_intro_5275007 = "This kind of amplification device is indispensable for touring artists—no matter how big the venue is, and no matter how large the audience, this will make sure an idol's voice can be heard by everyone... and it's also very cute!",
  str_item_intro_5275008 = "These decorations are usually placed near tour venues. When you see them floating in the sky and flying in the wind, you can't help but feel that they're really dancing with their esteemed idol.",
  str_item_intro_5275009 = "These decorative lights are often found near touring stages and seem to be used by fans to cheer on their idols. Although they're not official merchandise, they're surprisingly well-made.",
  str_item_intro_5275010 = "How could any tour be complete without idol standees? Even if you can't take pictures with your idol, or even see your idol up close, as long as you have this, you're guaranteed some decent selfies.",
  str_item_intro_5275011 = "Flowers represent wishes of happiness, so naturally, many flowers represent many wishes of happiness. If you're not careful, the whole tour venue could end up being flooded with flower baskets sent by ardent fans wishing happiness to their favorite idol.",
  str_item_intro_5275012 = "Apparently, the star decorations on this wall were glued on by fans one by one. This is not just a decoration—this is proof of a fanbase's devotion, a symbol of their sincerest hopes that their idol will have a successful tour.",
  str_item_intro_5275013 = "These seats are specially arranged for tours, though many fans prefer to stand on them to cheer for their idols rather than sit on them. There is another reason fans stand on these chairs, of course—so that their idol can see them among the crowd.",
  str_item_intro_5234043 = [[
Since snow is so soft, why not make a sofa out of it?
Perhaps many people have had this idea before. Of course, this sofa is made of ordinary materials, it's just that the back looks like a snowy mountain, and with its soft cushions, it really does make you feel like you're lying on the snow.]],
  str_item_intro_5234044 = "Legend has it that this extraordinary creature never grows old, and this wonderful display reflects the essence of that legend. If you stare at it for a while, you may find yourself becoming addicted to it.",
  str_item_intro_5234045 = "The Courier Union carries the thoughts and wishes of the world, even to the ends of Astra! This mailbox is said to have been specially set up for this purpose, reducing the distance between loved ones.",
  str_item_intro_5234046 = "If there's ever anything you dare not say to someone's face, write it in a letter and put it here. That certain someone might just see it and learn how you feel.",
  str_item_intro_5276001 = "This ceremonial venue usually set up for Mooncrown Day is very suitable for holding various events, especially weddings.",
  str_item_intro_5276002 = "Whether for festival parades or weddings, this would be the best choice for style, decoration, and comfort.",
  str_item_intro_5276003 = "A fun new invention. If couples still take care of each other after going for a spin in these, that just shows how much they love each other.",
  str_item_intro_5276004 = "The roses on this pavilion were cultivated specially for the festival, and only bloom on Mooncrown Day to bless the newlyweds who come here.",
  str_item_intro_5276005 = "Chocolate is bitter at its base, and only becomes sweet with the addition of sugar. Perhaps... this symbolizes what some love is like? In any case, it has become one of the symbolic gifts of Mooncrown Day, probably because most people only remember the sweetness and ignore the bitterness.",
  str_item_intro_5276006 = "These arches, with their unique shape, are decorated with flowers of various colors, making them very suitable for new couples to take photos or make wishes under.",
  str_item_intro_5276007 = "A decoration often used on Mooncrown Day. Consisting of several tall glasses filled with drinks, it is specially used for entertaining guests.",
  str_item_intro_5276008 = "This candlestick holder's tall shape is pleasing to the eye and capable of dispersing the light emitted by the candles evenly, adding a touch of romance to tender wedding proceedings.",
  str_item_intro_5276009 = "Beloved by all wedding officiants. This device allows all guests present to hear the vows of the two newlyweds clearly, and can also play music to fill the venue with the perfect atmosphere.",
  str_item_intro_5276010 = "Perfect for seating couples, even when it is not Mooncrown Day. It's almost certainly guaranteed to be occupied on Mooncrown Day.",
  str_item_intro_5276011 = "Huh? They're a couple? Ah, it's just a special outfit made for the festival. Quite fitting for the occasion, really.",
  str_item_intro_5276012 = "Suitable for Mooncrown Day as both decor and gifting to others. It gives celebrations a colorful flair and fills the air with a gentle fragrance.",
  str_item_intro_5276013 = "A carpet made of rose petals! Truly indicative of how seriously the host takes the ceremony. When newlyweds step onto it, the eyes of all guests present look their way.",
  str_item_intro_5276101 = "A table with matching chairs boasting a quaint vintage design that is fortunately also very comfortable to sit on, and seems suitable for certain meetings, especially when discussing complicated cases. Perhaps this trend is all the influence of a certain famous detective.",
  str_item_intro_5276102 = "They say that the famous detective often gathered intelligence, organized clues, and conducted various analyses on this type of board, even relying solely on this method to find the culprit.",
  str_item_intro_5276103 = "Since that famous detective's rise to fame, his vehicle of choice has also grown in popularity. After all, who wouldn't enjoy such a sturdy, fast, and easy-to-operate vehicle?",
  str_item_intro_5276104 = "If your mind is feeling blocked, just have a cup of coffee. And if you still can't figure it out, have another cup. As the best companion for contemplation, the famous detective has never been stingy when it comes to picking out coffee sets.",
  str_item_intro_5276105 = "Crimes often seem to occur on cold nights, so great detectives need to equip themselves with windproof coats and hats. This naturally makes this coat rack essential in any detective's domicile.",
  str_item_intro_5276106 = "A small, lightweight trolley upon which coffee, refreshments, and other items for afternoon tea are mostly placed. When entertaining guests, it is particularly convenient for servants to arrange various food items on it in a timely fashion.",
  str_item_intro_5276107 = "When his deductive inspiration dries up, or he is trapped in a maze of thought, the famous detective likes to use this instrument to relax, filling the entire street with the sound of his sub-par ditties. Fortunately, what people care about is not the level of his musical proficiency but their passion for the great detective's legend. This is why so many people flock in droves to purchase this instrument.",
  str_item_intro_5276108 = "The tall backrest and soft cushions provide maximum comfort while helping to maintain a good sitting posture. Entirely suitable for detectives who like to relax and ponder.",
  str_item_intro_5276109 = "This uniquely designed rack can hold many pipes and bring a true detective feel to your home. Of course, this is all due to the popularity of the famous detective among crime fiction fans, so even those who don't smoke may also purchase one for decoration.",
  str_item_intro_5276110 = "\"Don't let a single clue get away from you!\" Time and again, the tiniest details reveal the truth. This kind of magnifying glass is indispensable as a standard accessory for the famous detective.",
  str_item_intro_5276111 = "A wind-resistant and light-weight lamp with superior brightness and life that can be carried easily with one hand. Naturally, it can be put on the ground too.",
  str_item_intro_5276112 = "This small blackboard is relatively low in height. Even when the famous detective sits in his armchair, he can use it to organize his current case, making it a handy aid for rapid analysis.",
  str_item_intro_5276113 = "The shape of this two-legged book brace is quite special, but it is very popular with a certain famous detective. Being different from most other people, the aesthetics of his bookends are also different from those of other common kinds. Of course, as a detective enthusiast, you should definitely have a pair at home.",
  str_item_intro_5276114 = "Whether it's raining or sunny, umbrellas always make for good shields and can be used as weapons in emergencies. Therefore, placing an umbrella basket like this at the door seems necessary for storing a whole range of umbrellas.",
  str_item_intro_5234047 = "\"When a writer is trapped by a blizzard in a mountain manor, their writing efficiency increases tenfold.\" This seems to a shared belief among many Umbraton editors, and has led to the popularity of this brand of typewriter, which for a time became the typewriter of choice for the town's writers.",
  str_item_intro_5234048 = "This sofa is essential if you want to open a great firm in Umbraton. The directors would sit on this sofa to attend to their business.",
  str_item_intro_5223003 = "A round small floor tile suitable for lawns and roadside decorations.",
  str_item_intro_5223004 = "A relatively large round floor tile that can not only be used for pathways but can also be used as the main component in road paving.",
  str_item_intro_5351001 = "It's the most eye-catching building and the landmark in Cloud Gardens. It holds a lot of information used for the reconstruction of Cloud Gardens.",
  str_item_intro_5351002 = "It's the most eye-catching building and the landmark in Cloud Gardens. It holds a lot of information used for the reconstruction of Cloud Gardens.",
  str_item_intro_5351003 = "It's the most eye-catching building and the landmark in Cloud Gardens. It holds a lot of information used for the reconstruction of Cloud Gardens.",
  str_item_intro_5352001 = "A place for displaying various objects as well as recording and disseminating knowledge.",
  str_item_intro_5352002 = "It not only has a larger space than it used to be, but is also slightly decorated so that the exhibits can be viewed easily.",
  str_item_intro_5352003 = "An upgraded museum with a lot more rooms. It not only has a lot of space, but also facilitates the sorting of its exhibits.",
  str_item_intro_5353001 = "The trading place in Cloud Gardens. It not only carries out general trading, but also handles mysterious orders!",
  str_item_intro_5353002 = "Added some streamlined exterior decorations, looks much more stylish now.",
  str_item_intro_5353003 = "A store with many rooms. It's a mansion dedicated to trading now.",
  str_item_intro_5354001 = "Take a look at the clear spring water, not only can you appreciate the beautiful fish, but you can also throw in a coin to make a wish.",
  str_item_intro_5354002 = "A large pond. You can enjoy the fish swimming under the glistening light, and there also seems to be a better chance for your wishes to come true.",
  str_item_intro_5354003 = "The fountain not only brings flowing water to the fish, but it is also said to make wishes come true~",
  str_item_intro_5355001 = "A large, sturdy, waterproof, and dustproof box that is capable of storing many items.",
  str_item_intro_5276201 = "A courtly seat usually graced by the rear ends of Lumopolis's most noble nobility. Its lavish design effectively radiates the quintessence of the upper class's noble demeanor, aweing the slack-jawed populace, while forcing its occupant to subconsciously constrain their own behavior. Of course, this occupant does need to have the right temperament for it, to begin with.",
  str_item_intro_5276202 = "\"A world within a world.\" People say this crystal ball contains the ghost of a certain town, but for some, it's considered a very precious memory.",
  str_item_intro_5276203 = "\"Be kind to the weak and brave in the face of aggression.\" Knights form the cornerstone of Lumopolis, and are also the banners of the city-state, flying high in the winds of the world. Although the name of this statue is unknown, even common people are swept up in the spirit of chivalry when they see its towering figure.",
  str_item_intro_5276204 = "This display cabinet is not only luxurious in design, but also sturdy in structure, making it both practical and beautiful enough to hold any collectible.",
  str_item_intro_5234049 = "\"Engraved on a stone tablet, words can last for millennia.\" Long after its carver departed this mortal coil, the city lay abandoned, civilization reduced to dust, yet this monument still stood tall, allowing future generations to glimpse the world of the past. Perhaps this is the purpose of its existence.",
  str_item_intro_5276206 = "A common fixture in the noble residences of Lumopolis, where it is often used as a long table. Spacious, firm, and elegant, it is suitable for entertaining guests, friends, family gatherings, and even discussing important matters.",
  str_item_intro_5276207 = "These high-backed chairs commonly found in the noble mansions of Lumopolis. Ensure one's comfort while helping to maintain better posture, avoiding potential faux pas at all times.",
  str_item_intro_5276208 = "A white flag for a white city. The symbol of Lumopolis, casting one's gaze upon it brings to mind all that makes the city what it is—the knights, the nobles, the clear blue sky, and the glory of its civilization.",
  str_item_intro_5276209 = "In the collective consciousness of the masses, this is a light that never goes out, and thanks to the powerful Luminatics of Lumopolis, it really never does.",
  str_item_intro_5276210 = "This elegant low fence is not designed to prevent outsiders from entering but rather to define noble mansions and estates' boundaries.",
  str_item_intro_5276211 = "Even when it comes to potted plants like this, Lumopolis stands apart from the crowd. Not only is the pot tall and exquisite, but the green plant within it is also lush and majestic. It seems that being located so high in the sky, it must have absorbed a great deal of sunlight.",
  str_item_intro_5276212 = "A mass of overgrown vines sprawling overhead. Although they creep in scattered directions, there is a uniformity to their arrangement, with gaps between them that are neither large nor small, clusters that are neither sparse nor dense, allowing sunlight to trickle in leisurely without causing sudden distress. When a gentle breeze passes, it makes for the ideal place to relax and enjoy afternoon tea.",
  str_item_intro_5234050 = "It might not match an actual Ferris wheel's grandeur, but it still stands pretty big. We can't hop on, we just gaze from afar and relive the feelings of a Ferris wheel ride in our minds.",
  str_item_intro_5234052 = "In the desert, its blue casing and massive water tank transform from symbols of conflict into a divine presence. They shower rain and dew, bringing a refreshing relief to those parched by drought.",
  str_item_intro_5234053 = "The realistic sculpture, resembling a delicate bird shrouded in sand, can easily fool the eye. Be cautious not to get it wet; otherwise, it will \"vanish\" into a sandy puddle.",
  str_item_intro_5234054 = "Can anyone truly sit on this chair? While the flowers lend a touch of beauty, the thorns studding the seat serve as a constant reminder to \"Sit upright, or risk a prickly encounter.\"",
  str_item_intro_5400001 = "A mysterious liquid, which can greatly shorten the breeding time of the Unique Tree. It is very volatile, so it must be bottled.",
  str_item_intro_5400002 = [[
Sticky liquid likely made from a mixture of premier Unique Tree sap. Boiled and supplemented with a secret formulation. Capable of changing the genus of Unique Trees.
Appearance: Thick, green liquid with yellow sludge remnants.]],
  str_item_intro_5401001 = "Tree Upgrade C - B Guaranteed Breakthrough Item",
  str_item_intro_5401002 = "Tree Upgrade B - A Guaranteed Breakthrough Item",
  str_item_intro_5401003 = "Tree Upgrade A - S Guaranteed Breakthrough Item",
  str_item_intro_5402001 = "Tree Upgrade C - B Targeted Breakthrough Item",
  str_item_intro_5402002 = "Tree Upgrade B - A Targeted Breakthrough Item",
  str_item_intro_5402003 = "Tree Upgrade A - S Targeted Breakthrough Item",
