  str_item_intro_5421111 = "The red basic Quinlan Tree bred with Rose Crystalloids looks very vibrant.",
  str_item_intro_5421112 = "The Quinlan Tree I that you have recently grown doesn't look out of the ordinary, but it makes a wonderful sound in the breeze.",
  str_item_intro_5421113 = "The yellow basic Quinlan Tree bred with Rose Crystalloids gives a slight sense of desolation.",
  str_item_intro_5421211 = "A genus of the Dwarf Leaf Quinlan Tree, which has undergone some minor mutations, is bred with Rose Crystalloids and has a color similar to that of red agates.",
  str_item_intro_5421212 = "A Quinlan Tree II that has undergone some minor mutations. Its leaves are small and dense, hence the name.",
  str_item_intro_5421213 = "A genus of the Dwarf Leaf Quinlan Tree, which has undergone some minor mutations, is bred with Rose Crystalloids. The yellow leaves wave marvelously in the breeze.",
  str_item_intro_5421221 = "A genus of the Giant Leaf Quinlan Tree, which has undergone some minor mutations, is bred with Rose Crystalloids, and each leaf looks like a thin piece of red crystal.",
  str_item_intro_5421222 = "A Quinlan Tree II that has undergone some minor mutations. The leaves are so broad and strong that you can almost make clothes out of them directly.",
  str_item_intro_5421223 = "A genus of the Giant Leaf Quinlan Tree that has undergone some minor mutations. It is bred with Rose Crystalloids and has an autumn feel.",
  str_item_intro_5421311 = "A Quinlan Tree III that has undergone frequent mutations. It has a clustered crown and its leaves are smooth, dense, and very distinctive.",
  str_item_intro_5421312 = "A precious genus of the Good-Natured Quinlan Tree that has undergone frequent mutations. It is bred with Rose Crystalloids. Its blue crown gives out a pleasant feeling.",
  str_item_intro_5421313 = "A precious genus of the Good-Natured Quinlan Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. Its yellow leaves are layered on top of each other, and even if the strong wind blows, they will not disperse.",
  str_item_intro_5421321 = "A precious genus of the Sunburst Quinlan Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. Its red crown looks even more intense now.",
  str_item_intro_5421322 = "A Quinlan Tree III that has undergone frequent mutations. It has a dense crown, thick branches, and strong vitality.",
  str_item_intro_5421323 = "A precious genus of the Sunburst Quinlan Tree that has undergone frequent mutations. It is bred with Rose Crystalloids. From a distance, its blue crown looks like a calming body of water.",
  str_item_intro_5421331 = "A precious genus of the Icy Blue Quinlan Tree that has undergone frequent mutations. It is bred with Rose Crystalloids. The Pink leaves of the tree match its crown and body, adding a sense of spring to it.",
  str_item_intro_5421332 = "A precious genus of the Icy Blue Quinlan Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. The red crown of the tree forms a strong contrast with its original cold and beautiful image.",
  str_item_intro_5421333 = "A Quinlan Tree III that has undergone frequent mutations. Its leaves are uneven, with a cool and gorgeous vibe.",
  str_item_intro_5421341 = "A precious genus of the Mistral Quinlan Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. The blue canopy adds a touch of coldness to its original cold image.",
  str_item_intro_5421342 = "A Quinlan Tree III that has undergone frequent mutations. Its leaves have sharp edges, showing irregular projections. When the breeze blows through the canopy, it seems to dance like a sharp blade, bringing a sense of harshness.",
  str_item_intro_5421343 = "A precious genus of the Mistral Quinlan Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. The light yellow leaves soften the original aura of coldness and bring a touch of warmth.",
  str_item_intro_5421411 = "A rare genus of the Sungazing Quinlan Tree, which has undergone complex mutations, is bred with Rose Crystalloids. The blue crown of the tree is like those who have a pure heart, looking up at the blue sky and praying. Thus, it is also called the \"Praying Quinlan Tree.\"",
  str_item_intro_5421412 = "A Quinlan Tree IV that has undergone complex mutations. It is shaped like a trumpet stretched up to the sky. It is hard to imagine how the thin branches alone can support the huge crown of the tree. That must be the work of some unknown forces.",
  str_item_intro_5421413 = "A rare genus of the Sungazing Quinlan Tree, which has undergone complex mutations, is bred with Rose Crystalloids. The yellow trumpet-shaped crown looks like a brass horn. It is said that in ancient times, the giants even used it to play music! Because of that, the tree is also named the \"Horn Quinlan Tree.\"",
  str_item_intro_5421421 = "A rare genus of the Monolith Quinlan Tree, which has undergone complex mutations, is bred with Rose Crystalloids. When standing on the green crown of the tree, you will have the illusion that you are on the hills, so it is also called the \"Hillock Quinlan Tree.\"",
  str_item_intro_5421422 = "A rare genus of the Monolith Quinlan Tree, which has undergone complex mutations, is bred with Rose Crystalloids. The white crown looks very smooth, and you can even have a good sleep on it.",
  str_item_intro_5421423 = "A Quinlan Tree IV that has undergone complex mutations. The tree canopy has hardened to become a small stone platform! It is said that there is a stone pole in the trunk that supports it, with its outer side wrapped in the heavy bark... Whether this Unique Tree can still be called a plant is really to be discussed.",
  str_item_intro_5421431 = "A Quinlan Tree IV that has undergone complex mutations. Its leaves are filamentous, gentle, fine, and tangled. It looks like a fluttering soul recorded in legend. Some people say that this genus has its consciousness and even soul...",
  str_item_intro_5421432 = "A rare genus of the Psyche Quinlan Tree, which has undergone complex mutations, is bred with Rose Crystalloids. The red crown looks ominous, but it has a fatal attraction. When those gentle leaves dance with the wind, it is easy to be fascinated and watch them for days and nights.",
  str_item_intro_5421433 = "A rare genus of the Psyche Quinlan Tree, which has undergone complex mutations, is bred with Rose Crystalloids. The yellow leaves form various small streamers that sway on the crown of the tree as if to welcome someone, hence its nickname, the \"Welcoming Quinlan Tree.\"",
  str_item_intro_5421441 = "A Quinlan Tree IV that has undergone complex mutations. The converging leaves have come together to form a huge and dense canopy. From time to time, leaves fly out of it, looking like it is raining falling leaves.",
  str_item_intro_5421442 = "A rare genus of the Blooming Quinlan Tree, which has undergone complex mutations, is bred with Rose Crystalloids. The green crown looks full of vitality. If you approach the hanging branches, they will tremble slightly, and the whole tree will rustle like it is responding to someone...",
  str_item_intro_5421443 = "A rare genus of the Blooming Quinlan Tree, which has undergone complex mutations, is bred with Rose Crystalloids. When blue leaves fall on one another, it gives people the illusion that they are in a river or the sea, hence it is also called the \"Ocean-on-land Quinlan Tree.\"",
  str_item_intro_5421451 = "A Quinlan Tree IV that has undergone complex mutations. It is exceptionally rare and vigorous. As its name suggests, rumor has it that the tree keeps growing after being chopped down.",
  str_item_intro_5421452 = "A rare genus of the Unyielding Quinlan Tree that is bred with Rose Crystalloids. Its brown leaves give a sense of aging, but it is even more lively indeed. It is said to be able to survive without water.",
  str_item_intro_5421453 = "A rare genus of the Unyielding Quinlan Tree that is bred with Rose Crystalloids. It grows so fast that a blue crown is almost formed overnight, thus its nickname, Endless Ocean of Leaves.",
  str_item_intro_5421461 = "A Quinlan Tree IV that has undergone complex mutations. It is exceptionally rare. It branches out from its roots towards both sides and loops upwards in a circle, looking just like a door frame made with trees, hence its informal name, The Quinlan Doorway.",
  str_item_intro_5421462 = "A rare genus of the Archway Quinlan Tree that is bred with Rose Crystalloids. The tree's blue arch is sometimes misty and covered with frost in the winter. From a distance, it looks like a tree formed from snow and ice.",
  str_item_intro_5421463 = "A rare genus of the Archway Quinlan Tree that is bred with Rose Crystalloids. Instead of intimidating those who gaze upon it, this red doorway generates feelings of warmth and comfort. Some say that it brings good luck to its planter.",
  str_item_intro_5421471 = "A Quinlan Tree IV that has undergone complex mutations. This extremely rare tree has a remarkably relaxing effect on all who behold it, due to the way its forked trunk and crown sway in the breeze, and how it glistens with trickles of dew. This is why it is known as the \"Carefree Quinlan.\"",
  str_item_intro_5421472 = "A rare genus of the Winsome Quinlan Tree which has undergone complex mutations after being bred with Rose Crystalloids. Due to the blue dew that accumulates on its leaves, this Quinlan looks as though it is submerged in a shallow sea when viewed from afar, hence its nickname—the Winsome Lighthouse.",
  str_item_intro_5421473 = "A rare genus of the Winsome Quinlan Tree which has undergone complex mutations after being bred with Rose Crystalloids. Purple dew lends the entirety of this unique tree a hint of charm. As it sways in the breeze, it looks carefree and content while radiating an enchanting allure.",
  str_item_intro_5421481 = "A Quinlan Tree IV that has undergone complex mutations. This extremely rare tree's upright trunk and flame-shaped crown make it stand tall like a burning beacon. It is possible that those who gaze upon its form may mistake it for an actual source of illumination!",
  str_item_intro_5421482 = "A rare genus of the Blazing Quinlan Tree which has undergone complex mutations after being bred with Rose Crystalloids. The huge pink crown of this tree is like a cloud of mysterious fog floating on a trunk and branches. When the wind blows, the crown of the \"Rosewater Mist\" becomes irregular, infecting onlookers with a peculiar sensation.",
  str_item_intro_5421483 = "A rare genus of the Blazing Quinlan Tree which has undergone complex mutations after being bred with Rose Crystalloids. Its red crown makes it a veritable torch, especially when it dances in the wind, creating the illusion of a raging prairie fire.",
  str_item_intro_5422111 = "The Mint Green Arthur Tree bred with Rose Crystalloids is tall and has a sense of spring to it.",
  str_item_intro_5422112 = "The Dark Green Arthur Tree bred with Rose Crystalloids is sturdy and calming.",
  str_item_intro_5422113 = "The Arthur Tree I that you have recently grown doesn't look out of the ordinary. Its tall and straight trunk, compact branches, and upward-growing needles are what make it special.",
  str_item_intro_5422211 = "A genus of the Short Leaf Arthur Tree, which has undergone some minor mutations, is bred with Rose Crystalloids. The red needles are very short, and when they fall, they form a red carpet under the tree, which is pleasing to the eye.",
  str_item_intro_5422212 = "A genus of the Short Leaf Arthur Tree, which has undergone some minor mutations, is bred with Rose Crystalloids. The short needles have a green texture like mottled emeralds.",
  str_item_intro_5422213 = "An Arthur Tree II that has undergone some minor mutations is very different from the original one. While the branches extend outward, the crown is sparse and the leaves become short and thick. It's hard to identify it as an Arthur Tree if not for the thoughtful note.",
  str_item_intro_5422221 = "A genus of the Long Leaf Arthur Tree, which has undergone some minor mutations, is bred with Rose Crystalloids. The leaves dry quickly after falling, and there will be pleasant \"click\" sounds when stepping on them.",
  str_item_intro_5422222 = "A genus of the Long Leaf Arthur Tree, which has undergone some minor mutations, is bred with Rose Crystalloids. The slender leaves are soft but tough, and many people like to use them to make pen barrels.",
  str_item_intro_5422223 = "An Arthur Tree II that has undergone some minor mutations. Its appearance has changed dramatically. The branches grow arbitrarily and the leaves become elongated. It is hard to imagine that it originated from those tall Arthur Trees.",
  str_item_intro_5422311 = "An Arthur Tree III that has undergone frequent mutations. The crown and branches of the tree merge into one, looking like a mountain rock. Hardened on the surface and hollow inside, it will make a wonderful echo when knocked.",
  str_item_intro_5422312 = "A precious genus of the Ridge Arthur Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. The green texture on one side of the branch would easily be mistaken for the moss attached to it.",
  str_item_intro_5422313 = "A precious genus of the Ridge Arthur Tree that has undergone frequent mutations, is bred with Rose Crystalloids. Part of its bark shows a light red color, which gives birth to some horror stories, but those are all nonsense.",
  str_item_intro_5422321 = "An Arthur Tree III that has undergone frequent mutations. It has a low canopy and long soft branches hanging down. It looks like a small forest from a distance, so it also has the reputation of a \"One Tree Forest.\"",
  str_item_intro_5422322 = "A precious genus of the Banyan Arthur Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. Its huge red crown is like an umbrella, which is enough to block the scorching sun and bring people a cool shade.",
  str_item_intro_5422323 = "A precious genus of the Banyan Arthur Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. It possesses a huge green crown and strong branches hanging down. Anyone walking near it would probably think that they have strayed into a small forest.",
  str_item_intro_5422331 = "A precious genus of the Heath Arthur Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. Its slightly pale canopy is matched with the cracked trunk, making many people think that it has withered. However, once they notice that the tree has been standing there for a really long time, they will change their mind.",
  str_item_intro_5422332 = "An Arthur Tree III that has undergone frequent mutations. It resembles the decayed trees commonly seen in the wilderness, hence the name. However, the small crown growing on its twisted trunk shows its tenacious vitality as if to tell everyone: \"I'm still alive.\"",
  str_item_intro_5422333 = "A precious genus of the Heath Arthur Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. Its green crown and withered branches form a strong contrast. Some would even suspect whether the two are from one plant, but the fact is that they do belong to the same Heath Arthur Tree. Perhaps that is the charm of the Unique Tree.",
  str_item_intro_5422341 = "A precious genus of the Lake Arthur Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. Its juice is light yellow and tastes a little bitter at first, but the aftertaste gets a little sweet. It is said that the juice is good for restoring physical strength, and some people say that drinking it too much will make you dizzy.",
  str_item_intro_5422342 = "An Arthur Tree III that has undergone frequent mutations. It is named after the natural pool formed at the root of the tree, and the tip of the canopy dripping water at all times. No one can fathom the principle and meaning of this mysterious cycle. People can only drink the water from the root pool and marvel at the power of mutations.",
  str_item_intro_5422343 = "A precious genus of the Lake Arthur Tree that has undergone frequent mutations, is bred with Rose Crystalloids. The water in the pool is green. At first glance, it looks poisonous, but in fact, it is very chilled and has a refreshing fragrance, which is very surprising.",
  str_item_intro_5422411 = "A precious genus of the Inkstone Arthur Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. Part of its trunk and crown will shine with green light as if there is a trickling stream flowing in it, which is fantastic.",
  str_item_intro_5422412 = "An Arthur Tree IV that has undergone complex mutations. It has exposed roots, swollen and hardened trunks, and a crown that turns into a mass of glowing leaves! From a distance, it looks like a small lighthouse, hence it's also named the \"Lighthouse Arthur Tree.\"",
  str_item_intro_5422413 = "A rare genus of the Inkstone Arthur Tree, which has undergone frequent mutations, is bred with Rose Crystalloids. The stone-shaped trunk and crown shine like gold. Those who do not know it might even think that they have come to a resplendent palace, so the tree is also known as the \"Palace Arthur Tree.\"",
  str_item_intro_5422421 = "An Arthur Tree IV that has undergone complex mutations. Part of its trunk is combined with its hardened crown to form hollow stone plates! The outer wall of these stone plates is hard but very thin. When knocked on, it will make a variety of sounds, and some people even say that the tree would speak through its crown...",
  str_item_intro_5422422 = "A rare genus of the Boulder Arthur Tree, which has undergone complex mutations, is bred with Rose Crystalloids. Its huge green crown is like a green gem. Just tap it gently, and it can make all kinds of clear and melodious sounds, hence its nickname, the \"Arthur Tree Musician.\"",
  str_item_intro_5422423 = "A rare genus of the Boulder Arthur Tree, which has undergone complex mutations, is bred with Rose Crystalloids. The blue stone plate makes a melodious sound and trembles slightly, forming a dreamy flashing blue afterimage.",
  str_item_intro_5422431 = "A rare genus of the Shutter Arthur Tree, which has undergone complex mutations, is bred with Rose Crystalloids. When the yellow heart of the tree radiates, the texture of its trunk will produce an illusion of light yellow leaves, giving people a feeling that this Unique Tree is full of life again! Hence its nickname, the \"Resurrected Arthur Tree.\"",
  str_item_intro_5422432 = "An Arthur Tree IV that has undergone complex mutations. It has a hollow trunk, in which the heart of the tree forms a peculiar mushroom shape and emits wonderful light. It is said that once the danger is detected, the outer bark of the tree will close and block the light in it, hence it's also named the \"Lightblocker Arthur Tree.\"",
  str_item_intro_5422433 = "A rare genus of the Shutter Arthur Tree, which has undergone complex mutations, is bred with Rose Crystalloids. It emanates a blue glow from the heart of the tree. After the light is deflected in the hollow trunk, it will create an illusion for people that the tree is surrounded by a stream, and they would even mistakenly believe they are underwater...",
  str_item_intro_5422441 = "An Arthur Tree IV that has undergone complex mutations. Some branches and leaves of this tree have combined and mutated into a \"lantern.\" The branches that act as the \"wick\" can even emit a warm light! There is no question that this is a beacon for travelers walking in the dark wilderness.",
  str_item_intro_5422442 = "A rare genus of the Brightness Arthur Tree, which has undergone complex mutations, is bred with Rose Crystalloids. It is said that its \"lantern\" emits a gentle blue light because its trunk contains Lumina.",
  str_item_intro_5422443 = "A rare genus of the Brightness Arthur Tree, which has undergone complex mutations, is bred with Rose Crystalloids. Its leaves are red, but its \"lantern\" emits a faint red glow that reflects on the white trunk, giving it a unique charm.",
  str_item_intro_5422451 = "An Arthur Tree IV that has undergone complex mutations. The tree's canopy has disappeared, and its trunk is covered in vines composed entirely of bright flower petals. With some vines tightly intertwined and others hanging loose, this tree resembles a floral gate from a distance.",
  str_item_intro_5422452 = "A rare genus of the Arthur Tree that is bred with Rose Crystalloids. Its white petals are very cold to the touch but feel faintly warm after being plucked from the tree.",
  str_item_intro_5422453 = "A rare genus of Arthur Tree that is bred with Rose Crystalloids. Its vivid, green flower petals look distinctly like leaves; the difference is only noticeable when viewed up close.",
  str_item_intro_5422461 = "An Arthur Tree IV that has undergone complex mutations. In place of a canopy is a colossal ball of energy growing out of the tips of its branches! This orb, known as a \"fluorophore,\" seems to be composed of Lumina; when a gentle breeze blows, its light cascades down through the falling leaves and brings soft light to its surroundings.",
  str_item_intro_5422462 = "A rare genus of Arthur Tree that is bred with Rose Crystalloids. Its glowing fluorophore is as blue as the sea, and when it drifts in the wind, it gives people a feeling that water spheres are swirling around on top of a tree. In some places, it is known as the Water Dancer of the Unique Trees.",
  str_item_intro_5422463 = "A rare genus of Arthur Tree that is bred with Rose Crystalloids. Its yellow fluorophore is teeming with palpable vitality and can even make nearby flora thrive with its energy.",
  str_item_intro_5422471 = "An Arthur Tree IV that has undergone complex mutations. Its crown has completely mutated, to the point where it is now essentially a solid mass that droops down on all sides, forming a strange bowl shape. Its wonderful branches protrude from the center of this \"bowl,\" flashing like a torch to attract the attention of all who cast their eyes upon it.",
  str_item_intro_5422472 = "A rare genus of the Burgeoning Arthur Tree that is undergone complex mutations after being bred with Rose Crystalloids. Its bowl-shaped crown is a soothing blue color, and the light reflected from this central section generates a sensation similar to being in deep water, hence its other name, the \"Illusion of the Abyss.\"",
  str_item_intro_5422473 = "A rare genus of the Burgeoning Arthur Tree that is undergone complex mutations after being bred with Rose Crystalloids. Standing beneath it, you can see that the red crown is just like a blood-red sunset blocking out the sky, creating the illusion of being wrapped in the twilight.",
  str_item_intro_5422481 = "An Arthur Tree IV that has undergone complex mutations. The whole tree has hardened and mutated into a stone platform. The gurgling water falling from the top just happens to flow into the tree hole, creating a rather wonderful scene.",
  str_item_intro_5422482 = "A rare genus of the Radiant Arthur Tree that is bred with Rose Crystalloids. The trunk is white. Together with the light blue waterfall, it forms a rather refreshing landscape. Simply standing under the tree and listening to the sound of running water is a pleasure, hence the alias \"Drops of Pleasure.\"",
  str_item_intro_5422483 = "A rare genus of the Radiant Arthur Tree that is bred with Rose Crystalloids. The trunk and the top \"branches\" are in an intriguing blue color. Seen through the yellow stream, the whole tree gives off a strange vibe, hence the name \"hazy purple-blue.\"",
  str_item_intro_5423111 = "A recently matured basic Blooming Tree. Its distinctive blooming flowers have already emerged.",
  str_item_intro_5423112 = "A Purple Blooming Tree that is bred with Rose Crystalloids. Emits a faint, enchanting glow.",
  str_item_intro_5423113 = "A Yellow Arthur Tree that is bred with Rose Crystalloids. Basking in its soft glow brings to mind the warmth of the setting sun.",
  str_item_intro_5423211 = "A Blooming Tree II that has undergone minor mutations. Already resembling a completely different variety, it has multiple trunks sticking out of a single, underground root; this gives the impression that it is actually a cluster of several plants. Though it is very different in appearance from a basic Blooming Tree, its flowers are enough to show that it is a closely-related but mutated derivative.",
  str_item_intro_5423212 = "A genus of the Festive Blooming Tree that is bred with Rose Crystalloids. The light-yellow hue of its flowers resembles several tiny suns, offering a breathtaking sight for all to behold.",
  str_item_intro_5423213 = "A genus of the Festive Blooming Tree that is bred with Rose Crystalloids. Its pale-blue flowers sway softly in the breeze like clouds drifting across the sky.",
  str_item_intro_5423221 = "A Blooming Tree II that has undergone minor mutations. Though its trunk is markedly thicker than that of a regular Blooming Tree, its most notable difference lies in its flowers. Elongated and shaped like countless trumpets, they are also the reason for which this tree was given its name.",
  str_item_intro_5423222 = "A genus of the Sonorous Blooming Tree that is bred with Rose Crystalloids. Its blue flowers contain high water content and can be used to quench one's thirst or even brew special drinks!",
  str_item_intro_5423223 = "A genus of the Sonorous Blooming Tree that is bred with Rose Crystalloids. Its flowers are fiery red, and will soften and dry out quickly once removed from the tree. This makes them a very suitable kindling material.",
  str_item_intro_5423311 = "A Blooming Tree III that has undergone frequent mutations. Its flowers only grow on its trunk, while multiple branches rise out of its roots and surround them. Its mysterious appearance has been likened to a group of imperial guards protecting their queen.",
  str_item_intro_5423312 = "A rare genus of the Sheltered Blooming Tree that is bred with Rose Crystalloids. Its flowers have turned nearly golden in color, and even appear to reflect sunlight when seen swaying in the distance.",
  str_item_intro_5423313 = "A Sheltered Blooming Tree that has undergone frequent mutations. Its light blue flowers offer a sharp contrast with its leaves and trunk, much to the aesthetic pleasure of its admirers.",
  str_item_intro_5423321 = "A Wistful Blooming Tree that has undergone frequent mutations. Its trunk is warped into a nearly-perfect circle, and its canopy is formed by its dense, hanging flowers. Its unique, almost illogical structure is as breathtaking as it is mind-boggling.",
  str_item_intro_5423322 = "A rare genus of the Wistful Blooming Tree that is bred with Rose Crystalloids. Its low-hanging blue flowers and circular shape form a natural entryway. Even when placed at the entrance of a man-made garden, it fits perfectly into its surroundings while still offering an amazing view.",
  str_item_intro_5423323 = "A Wistful Blooming Tree that has undergone frequent mutations. Its flowers have turned a pale and tender shade of white, and a fresh, floral fragrance can be noted while standing beneath its canopy. As such, its flowers have become a crucial raw material for many perfumes.",
  str_item_intro_5423331 = "A Blooming Tree III that has undergone frequent mutations. Its trunk has twisted and contorted itself into the shape of a giant flower, which can be seen from quite a distance away. Its actual flowers, however, lie within its gnarled trunk and branches, leading researchers to theorize that its unique shape is meant to protect them from would-be predators.",
  str_item_intro_5423332 = "A rare genus of the Iris Blooming Tree that is bred with Rose Crystalloids. The tips of its branches are tinged light blue, and drip with a darker secretion. According to some people, this secretion can be used as a type of ink, or even as a dye for fabrics.",
  str_item_intro_5423333 = "An Iris Blooming Tree that has undergone frequent mutations. The tips of its branches are tinged light green, while the pool of water at its base emits a deep blue glow, giving it a powerful aura of natural energy.",
  str_item_intro_5423341 = "A Blooming Tree III that has undergone frequent mutations. Said to resemble a tree from a faraway land, its blooming flowers are both beautiful and filled with a light fragrance. By staring at this tree for an extended period of time, a rainbow is said to eventually appear before your eyes. While this is only legend, it is nonetheless the reason for which this tree was given its name.",
  str_item_intro_5423342 = "A rare genus of the Iridescent Blooming Tree that is bred with Rose Crystalloids. Its purple flowers are especially enchanting. In fact, their color is so vivid that they must be used in moderation when used as decorations or accents, lest they overpower the senses.",
  str_item_intro_5423343 = "An Iridescent Blooming Tree that has undergone frequent mutations. Its yellow flowers are teeming with life, and seem to remain in bloom day and night. There are even rumors that its flowers can be used to concoct potions of vitality; as a result, it is known by some as the \"Rainbow Tree of Life.\"",
  str_item_intro_5423411 = "A Blooming Tree IV that has undergone complex mutations. Though its canopy only bears a single flower, that flower is colossal in size, resplendent in color, and dangerously sweet in aroma; some even say that the stamens of its flower can be made into an excellent seasoning for food. Often the object of fixation for many people, this tree's flower can seemingly captivate any living being with eyes to see it.",
  str_item_intro_5423412 = "A rare genus of the Bewitching Blooming Tree that is bred with Rose Crystalloids. Its light blue flower wafts in the breeze like waves in the ocean, and even emits a slightly astringent, fishy smell. As such, those living far from the sea claim that they can still experience the joy of a summer day on the beach just by admiring this tree's flower.",
  str_item_intro_5423413 = "A rare genus of the Bewitching Blooming Tree that is bred with Rose Crystalloids. Its flower has turned a dangerously captivating shade of pink. Simply looking at it can make a person forget all of their woes, making it especially difficult to tear one's eyes from it. In fact, some will even set alarm clocks to remind them about the perils of overindulging in such a beautiful sight.",
  str_item_intro_5423421 = "A Blooming Tree IV that has undergone complex mutations. Its flowers bear innumerable petals, each of which is as soft and slender as a strand of silk. They say some have even tried to use them to weave fabric, but these delicate flowers quickly become brittle after being removed from the tree, leading to a shameful waste of its natural beauty.",
  str_item_intro_5423422 = "A rare genus of the Silken Blooming Tree that is bred with Rose Crystalloids. Its azure canopy often calls to mind images of the \"Daughter of the Sea,\" a legendary figure said to have hair as blue as the ocean itself. Some even say that this tree's flowers give off the faint aroma of sea spray...",
  str_item_intro_5423423 = "A rare genus of the Silken Blooming Tree that is bred with Rose Crystalloids. Its verdant flowers are said to house the souls of all flowers, and that seeing it with one's own eyes will guarantee true love at first sight...",
  str_item_intro_5423431 = "A Blooming Tree IV that has undergone complex mutations. The corollas of its enormous flowers are distinctly disk-shaped, and appear to be facing toward something high above. Upon being noticed by people, its flowers seemingly turn away from their gaze; as a result, it is known as the \"Bashful Bloom\" in certain circles.",
  str_item_intro_5423432 = "A rare genus of the Skygazer Blooming Tree that is bred with Rose Crystalloids. Its flowers are bright and red like unbridled flames. Legends say that this robust flower looks up at the sky in order to share its wealth of vitality with the world.",
  str_item_intro_5423433 = "A rare genus of the Skygazer Blooming Tree that is bred with Rose Crystalloids. Its flower petals are white as snow and emit a strange glow. Some say that it produces a variety of illusions depending on the direction in which it faces, giving it the nickname \"the Dream-weaver.\"",
  str_item_intro_5423441 = "A Blooming Tree IV that has undergone complex mutations. Its petals are neat and beautiful, layered on top of one another. Just a glance fills one's heart with giddiness, which is why it is favored by many girls.",
  str_item_intro_5423442 = "A rare genus of the Virtuous Blooming Tree that is bred with Rose Crystalloids. Its blue canopy is intoxicating, and many viewers feel refreshed around it, like the clear skies after rain, hence it is also called \"Clear Skies.\"",
  str_item_intro_5423443 = "A rare genus of the Virtuous Blooming Tree that is bred with Rose Crystalloids. Its purple flowers look dangerous, and it is said that its flowers sway slightly coquettishly when someone is looking at it, pulling them into a trance. Anyway, please be careful around it.",
  str_item_intro_5423451 = "A Blooming Tree IV that has undergone complex mutations. The huge canopy forms a natural funnel, and the inner walls formed by its petals are so smooth that it collects morning dew in its trunk to nourish itself.",
  str_item_intro_5423452 = "A rare genus of the Dawn Blooming Tree that is bred with Rose Crystalloids. Its purple canopy dyes the dew it collects into the same color. Some scholars believe this dew has mystic powers and use it to write certain books.",
  str_item_intro_5423453 = "A rare genus of the Dawn Blooming Tree that is bred with Rose Crystalloids. The dew collected from its canopy appears blueish and can refresh those who look at it. This dew also seems to be able to cleanse impurities from the body, so it is also called the \"Dawn's Detox.\"",
  str_item_intro_5423461 = "A Blooming Tree IV that has undergone complex mutations. Its crown is divided into several long and delicate segments, which are staggered around its center. They say that after seeing it, a designer was once inspired to design a series of skirts based on the shape of its petals, leading to the nickname \"Skirted Beauty.\"",
  str_item_intro_5423462 = "A rare genus of the Aureate Blooming Tree that is bred with Rose Crystalloids. Its orange petals seem to possess the touch of temptation, and with its unique fragrance, it is a powerful reminder of all that is alluring yet dangerous in the world.",
  str_item_intro_5423463 = "A rare genus of the Aureate Blooming Tree that is bred with Rose Crystalloids. Its petals have become the color of the sky, embellished with white leaves that diffuse a fresh and clean sensation, making it popular with children.",
  str_item_intro_5423471 = "A Blooming Tree IV that has undergone complex mutations. Its crown and stamen form a butterfly shape which not only mystifies those who behold it, but also attracts actual butterflies, who dance around it as if it is their god.",
  str_item_intro_5423472 = "A rare genus of the Fluttering Blooming Tree that is bred with Rose Crystalloids. When viewed from a distance, its huge yellow stamen looks like a butterfly perched upon it. Whenever a breeze happens to blow by, it becomes even harder to distinguish...",
  str_item_intro_5423473 = "A rare genus of the Fluttering Blooming Tree that is bred with Rose Crystalloids. Its blue stamen and innate butterfly shape leave people with a strange first impression. Upon finally discovering its true form, one can only sigh at the wonder of this tree, thus it is also known as the \"Beautiful Butterfly of Mystery.\"",
  str_item_intro_5424111 = "Looking at the round roots, one can see the difference between the basic Strangefruit Tree and other varieties, and cannot help but marvel at its uniqueness.",
  str_item_intro_5424112 = "A Yellow Strangefruit Tree that is bred with Rose Crystalloids. It bears yellow fruit and leaves that seem to symbolize autumn's embrace.",
  str_item_intro_5424113 = "A Purple Strangefruit Tree that is bred with Rose Crystalloids. You may find its smell strange at first, yet its sap is completely tasteless, to the point of being similar to pure water.",
  str_item_intro_5424211 = "A Strangefruit Tree II that has undergone some minor mutations. Its roots are robust, and its fruit bears sharp spines on its exterior, which serves as a formidable defense. The vines around it also seem to be warning strangers to keep their distance.",
  str_item_intro_5424212 = "A genus of the Blooming Strangefruit Tree that is bred with Rose Crystalloids. The blue vines, stems, and leaves show that it is different from the original variety, but it seems that their fruit is still the same.",
  str_item_intro_5424213 = "A genus of the Blooming Strangefruit Tree that is bred with Rose Crystalloids. Its vines and stems give off a withering feeling, but the fruit inside is rich and lush, making its appearance seem like a disguise.",
  str_item_intro_5424221 = "A Strangefruit Tree II that has undergone some minor mutations. The fruit at the root has been warped into a completely different shape. It is believed that the separated fruit and leaf petals can absorb nutrients respectively so that even if part of the tree is damaged, other parts can keep growing to ensure its survival.",
  str_item_intro_5424222 = "A genus of the Flourishing Strangefruit Tree that is bred with Rose Crystalloids. Its red appearance is said to be due to its sap, which contains rare chemicals.",
  str_item_intro_5424223 = "A genus of the Flourishing Strangefruit Tree that is bred with Rose Crystalloids. The fruit possesses a special yellow color, which seems to result from water loss from its skin. Once the skin is peeled off, it soon becomes brittle, and then breaks into a pile of tinder.",
  str_item_intro_5424311 = "A Strangefruit Tree III that has undergone frequent mutations. The outside of the fruit hardens, becoming a stonelike ball that is very difficult to eat.",
  str_item_intro_5424312 = "A rare genus of the Thriving Strangefruit Tree that is bred with Rose Crystalloids. Although it is not clear whether its fruit has also mutated, you can vaguely sense it from the leaves. Maybe it is not a good idea to taste its fruit.",
  str_item_intro_5424313 = "A Thriving Strangefruit Tree that has undergone frequent mutations. The crown and leaves of the tree display bright colors, which are in sharp contrast to its stonelike fruit. Some people call its fruit the \"flowered stone.\"",
  str_item_intro_5424321 = "An Arcadian Strangefruit Tree that has undergone frequent mutations. It has a bent trunk, and its fruit is split into two segments, forming a natural vessel. As long as you have it, you won't have to worry about going thirsty.",
  str_item_intro_5424322 = "A genus of the Arcadian Strangefruit Tree that is bred with Rose Crystalloids. Its sap in its \"fruit pool\" has an indescribable taste, which is said to be caused by a mysterious undiscovered element.",
  str_item_intro_5424323 = "An Arcadian Strangefruit Tree that has undergone frequent mutations. It boasts even clearer juice in its center that can remain cool for a long time, making it perfect for hot summers' days.",
  str_item_intro_5424331 = "A Strangefruit Tree III that has undergone frequent mutations. The trunk is twisted, but this is actually caused by the fruit inside it. According to some studies, it is because the fruit has been bent, and the so-called \"trunk\" actually protects the skin of the fruit.",
  str_item_intro_5424332 = "A rare genus of the Mellifluous Strangefruit Tree that is bred with Rose Crystalloids. Its white canopy looks like a huge cloud in the sky.",
  str_item_intro_5424333 = "A Mellifluous Strangefruit Tree that has undergone frequent mutations. The color variance of the tree trunk is very obvious, which also indicates that the taste of the fruit has changed greatly. According to adventurers, it has a somewhat spicy and sour taste.",
  str_item_intro_5424341 = "A Strangefruit Tree III that has undergone frequent mutations. Its shape best reflects this Unique Tree's essence. The huge heaped fruit, the branches that protrude from it... This is why it is known as the \"Fruit Giant.\"",
  str_item_intro_5424342 = "A rare genus of the Hearty Strangefruit Tree that is bred with Rose Crystalloids. Its huge blue fruit looks extremely plump, proving that it truly deserves its name. The juice contained within it is said to be enough to provide water for an entire village. This is why some people call it the \"Water Tank Tree.\"",
  str_item_intro_5424343 = "A rare genus of the Hearty Strangefruit Tree that is bred with Rose Crystalloids. The huge red fruit is very bright, so no one can ignore its existence. This is why some legends claim that its juice can rejuvenate, but they may just be legends.",
  str_item_intro_5424411 = "A rare genus of the Strangefruit Tree IV that has undergone complex mutations. The fruit is huge and boasts wonderful colors. In addition, the branches with their complex structures can easily imbue one with a desire for domination after looking at it for a long time, leading even to disputes with relatives and friends. This is why it is also known as the \"Contrary Tree.\"",
  str_item_intro_5424412 = "A rare genus of the Enduring Strangefruit Tree that is bred with Rose Crystalloids. Its green fruit has a strong natural flavor. If you stare at it for too long, you may find yourself immersed in it, as if you are in the forest. You can even hear the chirping of insects and birds, and feel the leaves blowing in the wind...",
  str_item_intro_5424413 = "A rare genus of the Enduring Strangefruit Tree that is bred with Rose Crystalloids. The fruit has become a bright and charming pink. If you stare at it for a long time, you may even suddenly see a jumping rhythm emerging from inside it, which is a very strange sight to behold.",
  str_item_intro_5424421 = "A rare genus of the Strangefruit Tree IV that has undergone complex mutations. Its fruits are numerous, of different sizes, and stacked in a crisscross formation. It is said that this is one of the most ancient of Unique Trees, and there are even records of it existing in the wild! This is why it is also known as the \"Primordial Tree.\"",
  str_item_intro_5424422 = "A rare genus of the Stately Strangefruit Tree that is bred with Rose Crystalloids. Its pink fruit makes people want to drink the juice it produces. It is said that it can be used to brew a delicious drink that is highly praised by royalty, therefore, it is also known as the \"Regal Tree.\"",
  str_item_intro_5424423 = "A rare genus of the Stately Strangefruit Tree that is bred with Rose Crystalloids. From a distance, its fruit looks like liquid balls condensed from blue sea water, and you may even see ripples spreading across them. However, it is unknown whether this is merely an illusion.",
  str_item_intro_5424431 = "A rare genus of the Strangefruit Tree IV that has undergone complex mutations. Its huge fruit emits a wonderful smell at all times. Some people say that it can bring inexplicable courage to those who smell it, making them wish to conquer all they see.",
  str_item_intro_5424432 = "A rare genus of the Tranquil Strangefruit Tree that is bred with Rose Crystalloids. Its green fruit can calm the most ferocious soldiers, making it suitable for meditation and deep thinking. It is said that many wise people have attained enlightenment under its influence, leading to its nickname—\"the Revelation Tree.\"",
  str_item_intro_5424433 = "A rare genus of the Tranquil Strangefruit Tree that is bred with Rose Crystalloids. Its huge pink fruit can not only imbue people with courage, but it can also grant them strong ambition and a sense of willfulness so that they can embark on a path of no return to fight for supremacy. This is why it is also known as the \"Kingmaker.\"",
  str_item_intro_5424441 = "A rare genus of the Strangefruit Tree IV that has undergone complex mutations. Its fruit is hidden inside the trunk, but according to some scholars, the trunk is the hardened outer skin of the fruit and not an external layer wrapped around the fruit! It seems that this Unique Tree is trying really hard to protect its fruit.",
  str_item_intro_5424442 = "A rare genus of the Wonder Strangefruit Tree that is bred with Rose Crystalloids. It is said that this green fruit contains the essence of life, which, when properly extracted, can make plants grow faster, increase the yield of crops, and even improve barren soil and hard alkali soil! For this reason, many people call it the fruit of life.",
  str_item_intro_5424443 = "A rare genus of the Wonder Strangefruit Tree that is bred with Rose Crystalloids. Its huge blue fruit contains a sweet water, and its external \"bark\" layer also has a powerful moisturizing effect that protects the water inside the fruit from being lost, essentially making it a reservoir...",
  str_item_intro_5424451 = "A rare genus of the Strangefruit Tree IV that has undergone complex mutations. Although its huge fruit looks ordinary, for a certain period of time, it releases a very enchanting aroma that is said to be unforgettable! Maybe this is why so many butterflies flutter around it even though it usually doesn't have a special smell.",
  str_item_intro_5424452 = "A rare genus of the Distinguished Strangefruit Tree that is bred with Rose Crystalloids. According to some legends, this purple fruit releases a fragrance that permeates the entire land once every few hundred years! There is also a legend of a \"king\" who will emerge in this world when its fragrance spreads...",
  str_item_intro_5424453 = "A rare genus of the Distinguished Strangefruit Tree that is bred with Rose Crystalloids. Unlike the fruit of other Distinguished Strangefruit Trees, this blue fruit has a hint of freshness and neutralizes other odors! It is very popular among gardeners for this reason, but its inability to be transplanted makes ordinary gardeners sigh.",
  str_item_intro_5424461 = "A rare genus of the Strangefruit Tree that has undergone complex mutations. Its external shell has transformed into a cage that houses a delicious fruit. This fruit is known to emit a beguiling mist from time to time, which is said to ward against any would-be foragers.",
  str_item_intro_5424462 = "A rare genus of the Misty Strangefruit Tree that is bred with Rose Crystalloids. Its vividly-green fruit boasts a sour taste and an extremely pungent aroma, leading many to believe that it is poisonous. In fact, the fruit is perfectly safe to eat.",
  str_item_intro_5424463 = "A rare genus of the Misty Strangefruit Tree that is bred with Rose Crystalloids. The fleshy part of its blue fruit has undergone a mysterious transformation, which has made it extremely resilient and elastic. Even after being run over by a heavy vehicle, this fruit will quickly return to its original shape...",
  str_item_intro_5424471 = "A rare genus of the Strangefruit Tree that has undergone complex mutations. The fruit is divided into two parts—the main part of the fruit is actually enclosed by its thick shell, while the shining fruit hanging from the end of its branch is said to be the result of its canopy's mutation! However, the shape, smell, and taste of the fruit do little to corroborate this theory...",
  str_item_intro_5424472 = "A rare genus of the Sparkling Strangefruit Tree that is bred with Rose Crystalloids. Its blue light is said to smell like the ocean, earning it the nickname the \"envoy of the sea breeze.\" Others, however, claim that this is merely a hallucinogenic effect caused by the fruit's aroma.",
  str_item_intro_5424473 = "A rare genus of the Sparkling Strangefruit Tree that is bred with Rose Crystalloids. The soft, green light emitted by its fruit has a calming effect, one that supposedly makes even the most ferocious of animals docile upon approach. Whether or not this is true has yet to be confirmed.",
  str_item_intro_5425111 = "This Unique Tree has always been different from other trees. In fact, one must wonder whether it can even count as a tree... According to the research of many scholars, it is indeed a tree, so it can only be said that this is truly a Unique Tree that looks and feels wonderful.",
  str_item_intro_5425112 = "A Red Mushroom Tree that is bred with Rose Crystalloids. Its red canopy makes people feel restless and impatient, so it's probably not the best tree to sit under for shade.",
  str_item_intro_5425113 = "A Blue Mushroom Tree that is bred with Rose Crystalloids. Its blue canopy creates the illusion of a vast sky; some even say they can smell the fragrance of clouds under it.",
  str_item_intro_5425211 = "A Mushroom Tree II that has undergone some minor mutations. Its canopy has undergone many changes, becoming soft and tough at the same time, and its branches hang low due to their weight, creating the illusion of an arch. If you add some wooden beams for support and erect walls, you might be able to convert this into a small house.",
  str_item_intro_5425212 = "A genus of the Fuzzy Mushroom Tree, which has undergone some minor mutations, is bred with Rose Crystalloids. The inside of the canopy is sky blue, which creates the illusion of being in the sea.",
  str_item_intro_5425213 = "A genus of the Fuzzy Mushroom Tree, which has undergone some minor mutations, is bred with Rose Crystalloids. The red insides of the canopy is terrifying to some. There are also rumors of this tree being poisonous. However, these are the words of the prejudiced.",
  str_item_intro_5425221 = "A Mushroom Tree II that has undergone some minor mutations. With a thick trunk and a shrunken canopy, this tree feels like a bucket of water, and its thick trunk indeed can absorb water and store it, which is why it is also called the water mushroom.",
  str_item_intro_5425222 = "A genus of the Stoic Mushroom Tree, which has undergone some minor mutations, is bred with Rose Crystalloids. Although it is red, the water stored inside it has not been affected. You can even hear the sound of water flowing inside if you get close enough.",
  str_item_intro_5425223 = "A genus of the Stoic Mushroom Tree, which has undergone some minor mutations, is bred with Rose Crystalloids. Some people call its blue canopy the \"ocean canopy\" due to how it has been affected by the water stored inside. Some say you can hear the sound of rushing waves from the thick trunk if you stand on the canopy and put your ears against it.",
  str_item_intro_5425311 = "A Mushroom Tree II that has undergone frequent mutations. The canopy has retained its original size and has even become thicker than ever. It also smells amazing...",
  str_item_intro_5425312 = "A rare genus of the Enticing Mushroom Tree that is bred with Rose Crystalloids. As the canopy is completely blue, you'll feel like you're at the bottom of a shallow sea even if you just stare at it from a distance.",
  str_item_intro_5425313 = "A rare genus of the Enticing Mushroom Tree that is bred with Rose Crystalloids. The bright red canopy is extremely attractive to some and has a magical power that lures viewers closer and closer to it. However, there is no malicious reason for this, and no one knows why it has this effect.",
  str_item_intro_5425321 = "A Mushroom Tree II that has undergone frequent mutations. Not only has it become smaller, but it has started to grow in clusters too. Fortunately, it's mostly the same shape. Its greatest feature is its canopy that shines brilliantly with all sorts of lights, creating a dreamy scene when the light bounces off the powder it releases in the air.",
  str_item_intro_5425322 = "A rare genus of the Lambent Mushroom Tree that is bred with Rose Crystalloids. The blazing red of this tree makes its canopy look like a sea of flames, while its bright spots are mistaken for sparks. For this reason, this tree is also known as the flaming mushroom.",
  str_item_intro_5425323 = "A rare genus of the Lambent Mushroom Tree that is bred with Rose Crystalloids. The purple canopy looks amorous and also releases fluorescent dust that is said to be very enchanting. Some scholars also claim that this tree is a variant or a distant relative of the Enticing Mushroom Tree, but this is just speculation.",
  str_item_intro_5425331 = "A Mushroom Tree II that has undergone frequent mutations. This tree's trunk has grown crookedly and has two canopies. Some scholars speculate that this tree sucks up an exceeding amount of water from the ground to keep both canopies alive, which causes water to be excreted from the canopies and fall like raindrops.",
  str_item_intro_5425332 = "A rare genus of the Moist Mushroom Tree that is bred with Rose Crystalloids. Completely yellow, the raindrops that fall from this tree also create the atmosphere of a sunset. When raindrops fall quickly, it even seems like the tree is wrapped up in a curtain of sunset rain.",
  str_item_intro_5425333 = "A rare genus of the Moist Mushroom Tree that is bred with Rose Crystalloids. This tree resembles a sea creature due to its blue color, and the raindrops that fall from this tree are like splashing blue waves, so it is also called the controller of seawater.",
  str_item_intro_5425341 = "A Mushroom Tree II that has undergone frequent mutations. Characterized by many soft, drooping branches, at first glance, this tree looks like the beard of a wise elder, so it is also called the wise mushroom.",
  str_item_intro_5425342 = "A rare genus of the Lush Mushroom Tree that is bred with Rose Crystalloids. The yellow beard makes this tree look even wiser, and some even claim that this tree has the protection of the light. When the wind rustles through its flexible stems, it seems rays of sunlight shine through the gaps.",
  str_item_intro_5425343 = "A rare genus of the Lush Mushroom Tree that is bred with Rose Crystalloids. Its flexible green stems look just like vines. Those who enjoy the shade and the view under the canopy will feel like they are in a primary forest.",
  str_item_intro_5425411 = "A Mushroom Tree IV that has undergone complex mutations. Having grown very large and very thin, the canopy is even said to be almost transparent when viewed from certain angles! Naturally, many say that this feeling of transparency does not come from the thin canopy but comes from the cold air that is radiated by the tree at all times and reminds them of transparent ice.",
  str_item_intro_5425412 = "A rare genus of the Diluted Mushroom Tree that is bred with Rose Crystalloids. The yellow canopy and occasional cold breeze create the illusion of feeling cold even under the scorching sun, so some people call this the \"wonder tree of the land of the frozen sun.\"",
  str_item_intro_5425413 = "A rare genus of the Diluted Mushroom Tree that is bred with Rose Crystalloids. The dazzling red canopy and its natural feeling of transparency make people wonder whether this is a work of art created by people instead of a creation of nature.",
  str_item_intro_5425421 = "A Mushroom Tree IV that has undergone complex mutations. Although the canopy of this tree seems quite ordinary, it occasionally releases bursts of air that create the illusion that it is breathing. This tree also mostly lives in groups and creates a faint mist when they all release bursts of air one after another, hence its name.",
  str_item_intro_5425422 = "A rare genus of the Misty Mushroom Tree that is bred with Rose Crystalloids. When the red canopy of this tree breathes, the tiny holes that open and close every now and then make people think of wounds. In addition, the released bursts of air give an impression of blood mist at certain moments, giving it the name tragic returner of the battlefield.",
  str_item_intro_5425423 = "A rare genus of the Misty Mushroom Tree that is bred with Rose Crystalloids. The mist emitted by the blue canopy reminds onlookers of winter, making many mistakenly believe that the tree came from Northland. They are all wrong though, as the bursts of air released from this tree are slightly warm and not cold at all.",
  str_item_intro_5425431 = "A Mushroom Tree IV that has undergone complex mutations. The canopy has grown so enormously that one wonders if its trunk can bear its weight. As the canopy is too huge, it blocks the view of the sky entirely for those who are under it. For this reason, some call it the tree that covers the sky.",
  str_item_intro_5425432 = "A rare genus of the Dome Mushroom Tree that is bred with Rose Crystalloids. From time to time, the green canopy exudes the fragrance of aquatic plants, giving onlookers the strange illusion that they are next to a body of water. It is said that this tree provides nutrients for nearby aquatic plants to flourish, but no one has confirmed this.",
  str_item_intro_5425433 = "A rare genus of the Dome Mushroom Tree that is bred with Rose Crystalloids. The bright red canopy creates the illusion of a good harvest, and some have even said they can smell the sweet fragrance of fruit around it. However, this Unique Tree is completely inedible, especially the canopy, which is tough to cook and has no nutritional value.",
  str_item_intro_5510001 = "Its chubby body is not a hindrance to survival because it has a large belly full of deadly toxins. However, its extremely delicious meat still attracts many diners who are not afraid of death.",
  str_item_intro_5510002 = "Known for its bright colors, large numbers, and tender meat, it has been dominating the dining tables.",
  str_item_intro_5510003 = "Got its name from its slender and knife-shaped body, and it always moves in groups.",
  str_item_intro_5510004 = "What looks like a snake at first glance is actually a slender fish with very small fins. It likes to hide among underwater rocks and dart out to frighten people.",
  str_item_intro_5510005 = "A fish that likes to live in clear water. Abundant in number and widely distributed, it can be found in many places.",
  str_item_intro_5510006 = "This fish is said to be a dominant predator in the water, but because of its delicious meat, it has been targeted by diners and has now become a \"regular\" at high-end banquets.",
  str_item_intro_5510007 = "A slender fish that gathers along river banks, either resting or cruising, and it feeds on various tiny organisms in the water. Not only is the meat edible, but its fish oil can also be used to make various pigments.",
  str_item_intro_5510008 = "It likes to move in groups and is large in number. It has a violent personality and likes to ram its head against the enemy in a fierce fight, just like a javelin. The flesh of Makaira is firm, and its small scales are dried and used for snacks",
  str_item_intro_5520001 = "A turtle that cruises slowly through the water can barely move onshore. Probably because it moves so slowly, it has a hard shell on its back, which it relies on to keep out its enemies.",
  str_item_intro_5520002 = "This rare aquatic organism thrives in frigid waters, and can usually be found living deep beneath frozen seas. Its body is transparent, and it boasts a variety of pretty colors and winglike appendages, hence its name. A very rare sight in warm waters, most likely they've lost their way...",
  str_item_intro_5520004 = "These aquatic creatures have flat bodies and swim very slowly. They also like to explore and rest at the bottom of rivers and streams. Because of the many beautiful dots on their backs, fishermen often mistake them for large groups of scattered pearls when looking down into rivers and streams, hence their name.",
  str_item_intro_5520005 = "A creature that likes to crawl beneath the waves and is known for its unique shape. It is said that when it was first discovered, people thought it to be a strange kind of algae or coral. They didn't realize it was alive until it started moving ever so slowly...",
  str_item_intro_5520006 = "A marvelous fish that likes to live among algae, corals, and even anemones. It has a bright appearance and a comical face that makes those who see it laugh. Some have commented that water plants dance whenever this fish is around them, hence its name.",
  str_item_intro_5520007 = "This seems to be a recently discovered aquatic organism. With smooth skin and soft muscles, it swims through the ocean depths with an elegant languor which has caused it to quickly gain popularity among animal aficionados. Some of its admirers are even said to feel physical and mental pleasure whenever they see it cruising aimlessly in the water, sweeping away their worries and their strife with a wave of its tentacles.",
  str_item_intro_5520016 = "This fish likes to live in vast waters, and somehow has appeared here... People once feared it due to its black body and strange shape, but it's actually very gentle and loves swimming leisurely in the water. It even goes out of its way to avoid other small aquatic animals it encounters.",
  str_item_intro_5520101 = "Because of its vibrant colors, the Red and White Marbled Eel has become one of the most valuable ornamental fish. It not only has the nickname \"living gem in the water,\" but also is said to bring good luck to its breeders.",
  str_item_intro_5520102 = "Tricolor Marbled Eel is loved by millions because of its variable patterns, and is called the \"elegant fish.\" Whenever you see it, you will feel relaxed. Many people think that it can bring harmony to the family.",
  str_item_intro_5520103 = "A high-end ornamental fish. Known as \"swimming works of art\" because of its graceful swimming strokes, it is said to be able to eliminate future disasters for breeders.",
  str_item_intro_5520104 = "Black and White Marbled Eel has a gentle temperament and natural patterns. It is friendly to people, especially children, so some people believe that it can bless the smooth growth of children.",
  str_item_intro_5520105 = "Its scales will shine in a gorgeous golden color in the sun, so the Golden Marbled Eel is believed to bring fortune, and many businessmen would like to keep a few of these eels.",
  str_item_intro_5520201 = "This ornamental fish shimmers in red in the water. Its scales are so pronounced that they will almost make a body of water look pink, creating a magnificent sight.",
  str_item_intro_5520202 = "Although it looks a bit \"evil,\" its blood-red scales will show a vermilion color under the sunlight, making people feel as if the fish is wearing an armor made of rubies.",
  str_item_intro_5520203 = "Glittering with blue scales, it brings an inexplicable sense of coolness when swimming slowly in the water, especially in the middle of summer.",
  str_item_intro_5520204 = "The neat golden scales make it seem like a legendary general, and its swimming posture is also so overwhelming that the surrounding small fish have to retreat in its presence.",
  str_item_intro_5520205 = "Compared with others of its class, it looks elegant and calm, and its silvery-white scales and streamlined shape give it an aristocratic vibe.",
  str_item_intro_5520301 = "With a flat body and dazzling colors, this fish is like a butterfly falling into the water, swimming gracefully.",
  str_item_intro_5520302 = "An ornamental fish with a whitish head and a mostly black body. It has a mild temperament. If you observe carefully, the spots at the junction of black and white are slightly different. It can be said that each Black Butterflyfish is unique.",
  str_item_intro_5520303 = "It has a yellow and white body, which is divided into three large sections, hence the name. It is noisy and likes to tease other fish. Therefore, the waters will become lively with its presence.",
  str_item_intro_5520304 = "With a beautiful royal blue appearance, the luster of this ornamental fish varies greatly. It is shy and does not like to show itself. It often hides among rocks and water plants, so it is nicknamed \"shy girl.\"",
  str_item_intro_5520401 = "With its bright colors and large, soulful eyes, it likes to get close to other fish and is rarely rejected, making it the \"social butterfly\" of ornamental fish.",
  str_item_intro_5520402 = "The mottled spots on its back give it its name, and if paired with water plants of similar color to it... that would be a natural protective color. Therefore, when decorating, we must pay attention to its color collocation with the environment, so as to highlight its presence.",
  str_item_intro_5520403 = "Its body is mostly black, and the yellow and white fins on the back are its features. It has a quiet temperament, but once enraged, it will fight the opponent to the end, just like a stinging thorn—so don't touch it.",
  str_item_intro_5520501 = "Few people have this ornamental fish because it's really... ugly. Only the glowing beard makes it look different.",
  str_item_intro_5520502 = "The white Anglerfish seems to be much more approachable, but its glow also appears dimmer. Perhaps it's the contrast that does the magic.",
  str_item_intro_5520601 = [[
It is said that this seahorse lives very deep in the sea, and no one knows why it has come here. As it is used to living in the deep sea, it usually lurks at the bottom of the sea and is difficult to find.
Usually hiding from sight, it only appears when Lumina is around it and will be scared away if the Lumina is too strong.]],
  str_item_intro_5520602 = [[
This seahorse likes to live in the gaps between stones in streams. It has been given this name because it moves really quickly, making people think the stones have been dyed yellow.
Usually hiding from sight, it only appears when Lumina is around it and will be scared away if the Lumina is too strong.]],
  str_item_intro_5520603 = [[
White River Seahorses usually live in rivers and streams. Their body color is a natural protection, and their vertical swimming style allows them to hide in water bubbles of streams and not be discovered by their natural enemies.
Less sensitive to Lumina, it usually hides from sight and only appears when attracted by stronger Lumina, but it will be scared away if the Lumina around is too strong.]],
  str_item_intro_5520701 = "An underwater creature that likes to live in the river bend. It looks extremely ferocious with its many appendages. However, this is just a disguise, as it is very docile and lives in seclusion among the algae, making it difficult to spot.",
  str_item_intro_5520702 = "It likes to dwell in clear river bends and conceals most of its body in the yellow sand of the riverbed. As its skin is almost the same color as the sand, almost no other creatures ever notice it, making it extremely easy for it to ambush others.",
  str_item_intro_5520801 = "Don't be fooled by its incredibly small size. It weighs 1 kilo and is the smallest type of Bighead Carp in the world. Small and ordinary as it may appear, this little fish has enormous potential for growth...",
  str_item_intro_5520802 = "A slightly larger Bighead Carp. Weighing in at 5 kilos, it is much harder to catch despite its more vibrant colors. It seems that with greater weight comes greater alertness.",
  str_item_intro_5520803 = "A whopping 10 kilos Bighead Carp. With a rounder, fuller body, its bulging eyes seem to be saying, \"I can get even bigger, you know!\"",
  str_item_intro_5520804 = "The strongest of all Bighead Carp, coming in at 20 kilos. It drifts slowly and peacefully through the water, filling onlookers with a mysteriously profound sense of tranquility.",
  str_item_intro_5520805 = "A monstrosity of a Bighead Carp that weighs in at a crushing 50 kilos! A king among carp. Its belly seems to be the source of its impressive girth. Naturally, a fish of this size is quite aggressive. Other underwater creatures tend to avoid it.",
  str_item_intro_5520806 = "This Bighead Carp is of decent size, but its wild popularity stems from its brilliantly-gilded body, which is covered in dazzling, star-shaped scales. The existence of such an awe-inspiring fish must truly be a gift from the divine.",
  str_item_intro_5520811 = "Although it may look like an extremely ferocious and vicious aquatic creature, its pincers are simply used for moving aside obstacles, such as stones and water plants that prevent it from going about its business. In fact, the use of these claws in combat is merely a secondary function, as this creature is very gentle, and only puts on its fearlessly aggressive face when defending itself.",
  str_item_intro_5520812 = "This creature is known for hiding among underwater rocks, as it likes to carry stones to build its own \"castle,\" and ambush unlucky or simply curious creatures to secure itself a hearty meal.",
  str_item_intro_5520014 = "Famous for the blue rings on its body, this octopus is rarely seen in rivers. But when it appears, many aquatic creatures shy away from it, mainly due to the potent poison in its body that is said to be able to kill with one drop. Its poison is why it is so unapologetically eye-catching and unafraid of attracting the attention of other creatures.",
  str_item_intro_5520901 = "An extremely rare fish that is distinguished by its splendidly colorful body, as well as its small, yet agile frame. Incredibly alert, it is capable of hiding its colors at the first sign of motion in its vicinity; as such, capturing such an elusive fish requires no small amount of patience and determination. Nevertheless, one's hard work pays off immediately upon seeing its colorful \"ribbons\" float gracefully through the water.",
  str_item_intro_5530001 = "Windfall! This oyster happens to have pearls in it. It looks good in color and shape and can be sold for a good price.",
  str_item_intro_5530101 = "An old tin can. Not sure who threw it into the water, but this person surely pays no attention to protecting the environment...",
  str_item_intro_5530201 = "This shoe must have been \"living\" in the water for years, and even the seaweeds make it their home.",
  str_item_intro_5601101 = "One day, I will be able to protect my homeland under the great sky.",
  str_item_intro_5601201 = "I wish I can understand the amazing power that channels through the Colossus...",
  str_item_intro_5602101 = "A memory lasts a lifetime, but a record lasts a thousand years, so I will remember it, write it down, and keep it until someone finds it.",
  str_item_intro_5602201 = "I swear I will find those blueprints even if I need to travel to the ends of the earth.",
  str_item_intro_5602202 = "An outsider once said that everything has a cost. Well, what is the cost of knowledge?",
  str_item_intro_5602203 = "The brain is maintained by learning, and life is maintained by emotions.",
  str_item_intro_5603101 = "Don't give up easily. Even if an experiment has failed 99 times, it might succeed the next time.",
  str_item_intro_5603201 = "What is the ultimate principle that turns one item into another? It would be good if we could find our way to the origin of knowledge.",
  str_item_intro_5603202 = "Inspiration is like a spark that flashes by. I would spend my life searching for a way to make it last forever.",
  str_item_intro_5603301 = "The sharpest blade isn't always the best choice. Sometimes, a blunt one can work wonders. It may also be the case when interacting with her...",
  str_item_intro_5604101 = "Every tree has a destiny of its own. Do I have one too? I hope I'll find the answer soon...",
  str_item_intro_5604201 = "Do leaves come in silver? She told me no, but I didn't believe her, so here I am.",
  str_item_intro_5604202 = "The annual rings are the marks of the years engraved in the trees, their history, and their memory. Talk to them and maybe you can learn about the past that we don't know—they are also our annual rings.",
  str_item_intro_5604203 = "Between the interweaving shadows of leaves and trees, his profile appears. Is this fate's design?",
  str_item_intro_5604301 = "They grow and wither quietly. This aloof way of living is worth learning from.",
  str_item_intro_5604302 = "Where are our roots? I hope I'll find out in this lifetime...",
  str_item_intro_5605201 = "The ripple reminds me of my father who taught me to fish.",
  str_item_intro_5605301 = "That white fishing rod is a relic left by my mother, and I will pass it on to my children.",
  str_item_intro_5605302 = "The only thing that connects us is this thin thread. I hope it will never break.",
  str_item_intro_5605303 = "Even if her gift is bait, I'd be willing to take it.",
  str_item_intro_5605304 = "Sometimes fishing is not about the catch—it's about seeing the light glimmer on the waves.",
  str_item_intro_5605305 = "I can tell which way the water is flowing, but when will I be able to know what she's thinking?",
  str_item_intro_5605306 = "A subtle movement of the hook indicates a fish has taken the bait. If only life had similar signs to show us when opportunities arise.",
  str_item_intro_5606201 = "I hope I won't end up like my father, who got nothing achieved. Good luck to me!",
  str_item_intro_5606301 = "Diligence will eventually cover up my foolishness and let everyone call me a mining genius from the bottom of their hearts.",
  str_item_intro_5606302 = "Don't underestimate pebbles. Some of them may hide hidden treasures within.",
  str_item_intro_5606303 = "Always remember to sharpen the tip of your pickaxe!",
  str_item_intro_5606304 = "Just like love, mining requires not only strength, but also skill!",
  str_item_intro_5606305 = "Mineral veins have a certain smell! My nose is very sensitive, but it would be better if I can find out where he is...",
  str_item_intro_5606306 = "If we persevere, we'll definitely find that vein whether it's in this valley or not.",
  str_item_intro_5607201 = "He is the basket in which my heart is contained.",
  str_item_intro_5607301 = "It would be nice if she could read my good will.",
  str_item_intro_5607302 = "A fruit fell onto my head when I was little, and I've been blessed with good luck since. I hope my luck will persist far into the future.",
  str_item_intro_5607303 = "Most of the time, you only need to follow the bees to find good nectar. If only I could understand them...",
  str_item_intro_5607304 = "If our hearts could wear gloves, perhaps it wouldn't be so easily hurt by thorns...",
  str_item_intro_5607305 = "You need good eyes to find all the fruit at once. Yes, I want to maintain this level throughout my life.",
  str_item_intro_5608101 = "I hope he can accept me as crops embrace the sunlight.",
  str_item_intro_5608201 = "We're not sowing seeds just for harvest, it's more about planting hope.",
  str_item_intro_5608301 = "I love watching the windmill spin slowly because you don't have to think about anything. You can just watch it all day long...",
  str_item_intro_5608302 = "Seeds are incredible. Just a little of them can grow so many crops! So... As long as there are seeds, there will be hope!",
  str_item_intro_5608303 = "I need her, just like how plants need the sun.",
  str_item_intro_5608304 = "When the sun is too strong, it will burn all the crops. The same applies to caring for other people.",
  str_item_intro_5608305 = "Crops shouldn't be planted too closely together—they must be separated by furrows, in the same way I should maintain a certain distance from her.",
  str_item_intro_5609201 = "If it's possible to grow grass that doesn't need to be cut, it can be used as a large comfortable rug to sleep on!",
  str_item_intro_5609301 = "The water drop is soft and hard at the same time. Can I become someone like that?",
  str_item_intro_5609302 = "We need good soil to grow strong and healthy plants, and the same could be said about us, right? Thank the elders for giving us different soil, so that we can become different ones we want to be.",
  str_item_intro_5609303 = "I want the sweetest nectar for my future children.",
  str_item_intro_5609304 = "Ah... When will we be free to dance like the breezy bee?",
  str_item_intro_5609305 = "You can't merely cast your eyes on those beautiful flowers—the green leaves also deserve some attention, don't they?",
  str_item_intro_5610101 = "I can drive huge herds around, but I can't understand the hearts of my family. I hope my future children won't be like that.",
  str_item_intro_5610201 = "It's said that if you see a smiley face pattern on the surface when you pour a cup of milk, you'll be blessed for the rest of the year!",
  str_item_intro_5610202 = "I heard that the other villages use patrol dogs to help them herd animals, but he's the only thing I've got.",
  str_item_intro_5610203 = "There is said to be a creature called a \"camel\" that dwells in far off deserts, and its milk is supposedly quite tasty!",
  str_item_intro_5610204 = "One day, I will see the grass sprout once more, and the fields will be born anew.",
  str_item_intro_5610301 = "I heard that there is a wider grassland outside the valley, but I like the green grass here.",
  str_item_intro_5610302 = "Cheese is the best food in the world, and if you can eat it every day for a lifetime, you're in a place that is otherwise known in the legends as paradise.",
  str_item_intro_5610303 = "They say that the people of the desert settle their townships based on where water sources are located. Seeing as how I can't bear to be even a yard away from her, perhaps she is my water source...?",
  str_item_intro_5611101 = "According to the people by the sea, there's a big ship that looks almost like an island. I really want to see it!",
  str_item_intro_5611201 = "I could stay on guard duty all day long if I didn't have to sleep.",
  str_item_intro_5611202 = "I will never let evil get anywhere near here. Especially not anything that could harm the children...",
  str_item_intro_5611203 = "After becoming the guardian of this place, I cannot rest even at night.",
  str_item_intro_5611204 = "No detail can be ignored, otherwise a disaster is likely to unfold.",
  str_item_intro_5611301 = "I can walk for three days and three nights without feeling tired. I will use this talent to patrol this valley and watch out for outsiders.",
  str_item_intro_5611302 = "I will be the shield of my people! Haha, I learned it from the Knight's Oath of Lumopolis, and it's cool! I will do what I say!",
  str_item_intro_5611303 = "If we actually light up those big trees that look like torches, can we use them as sentry beacons?",
