  str_item_intro_6500001 = "Initial name card background. Can be selected via Name Card - Backgrounds!",
  str_item_intro_6500002 = "Initial name card background. Can be selected via Name Card - Backgrounds!",
  str_item_intro_6500003 = "Initial name card background. Can be selected via Name Card - Backgrounds!",
  str_item_intro_6500004 = "Initial name card background. Can be selected via Name Card - Backgrounds!",
  str_item_intro_6500005 = "Initial name card background. Can be selected via Name Card - Backgrounds!",
  str_item_intro_6500008 = "Rolling hills, covered in a blanket of white. Though bleak and still, they seem to radiate a certain vitality.",
  str_item_intro_6500011 = "Shady deals made on dark alleys under the fog's cover in the heart of Umbraton are a common sight for its residents.",
  str_item_intro_6500014 = "A repair plant in an Illumina Undercity. It's capable of repairing damaged devices very quickly; even large machinery.",
  str_item_intro_6500015 = "The celebration in Lumopolis is as grand as ever.",
  str_item_intro_6500016 = "Abundant water sources, intersections, and convenient geographical and topographical features all contribute to the prosperity of Umbraton.",
  str_item_intro_6500017 = "When the sun is engulfed by inexplicable darkness, what cataclysmic change awaits the world?",
  str_item_intro_6500018 = "Northland, the realm of perpetual frost. This land is ruled over by Bethlehem, and it is also the place she wishes to protect.",
  str_item_intro_6500020 = "No matter what, I won't let those villains ruin the concert! This is justice!",
  str_item_intro_6500021 = "Northland, the realm of perpetual frost. This land is ruled over by Bethlehem, and it is also the place she wishes to protect.",
  str_item_intro_6500024 = "At that moment, her wariness seemed to melt away, and her happy smile beamed with childish mischief, concealing a secret only for two.",
  str_item_intro_6500026 = "The quintessential Rediesel Wrench banquet beckons—a spirited celebratory feast which has become a famed mélange of desert delicacies.",
  str_item_intro_6500033 = "When weary from your journey, you can always take some time to sit with these companions of yours as you relax, talk, and listen to each other's stories.",
  str_item_intro_6500035 = "The sunshine in the castle on high remains unchanged for years. Standing in front of a large oil painting, she wears an old dress and spends a long time there, lost in deep thought, perhaps reminiscing.",
  str_item_intro_6500036 = "With Florine by your side, even the most dangerous waters will become safe.",
  str_item_intro_6500037 = "Someone has remained here for over a hundred years, just to fulfill a long-forgotten mission.",
  str_item_intro_6500038 = "As the gentle breeze disperses the gloom of the past, the bright rays of dawn will singe all sorrows to herald a new future to you.",
  str_item_intro_6500039 = "Like a lighthouse, she will illuminate the vast, dark ocean, guiding adventurers toward home.",
  str_item_intro_6500041 = "Even if it's freezing cold and the earth is covered with ice and snow, you'll always have a warm heart if you're with your companions. Happy holidays, Navigator!",
  str_item_intro_6500042 = "Sheol jumped high up into the air to repel the invading enemies. At this moment, she revealed a side of herself that no one else knew about.",
  str_item_intro_6500043 = "Many observation stations were established along the border of the desert. This is where they repel enemies and defend their distant homeland.",
  str_item_intro_6500044 = "Shops abound, bustling with voices, and the Twin Pavilions Bay's lively downtown is crowded with residents and tourists, choosing goods with keen interest amid the hustle.",
  str_item_intro_6500045 = "\"Thank you for your recognition. White Night up high!\"",
  str_item_intro_6500046 = "\"I enjoy spacing out alone, but now... with you here, it's a different kind of joy.\"",
  str_item_intro_6500047 = "\"This world is still rife with war. Will you join me in resolving these conflicts in the days to come?\"",
  str_item_intro_6500049 = "\"Ribbit! Ribbit!\"",
  str_item_intro_6500051 = [[
As a flock of drones encircles her, the girl turns back and looks at you.
"Everything is okay now."]],
  str_item_intro_6500053 = [[
Dazzling and bright, she smiles and leaps into the abyss.
"Don't let anyone take away your power or your joy."]],
  str_item_intro_6500054 = "Which path should you choose when you're at the crossroads of destiny?",
  str_item_intro_6500056 = "All that you experience shall guide the True Order into an ever-greater future. ",
  str_item_intro_6500057 = "The sea breeze, shaved ice, tricycles. The memories of that first summer spent with the maiden still remain as vivid as ever.",
  str_item_intro_6500058 = "The vow of reunion, where souls meet.",
  str_item_intro_9993001 = "A random surviving Aurorian in the team regenerates 20% HP after winning a battle.",
  str_item_intro_9993002 = "Supporter Aurorians +25% regeneration effects from Chain Combos and Active Skills in battle.",
  str_item_intro_9993003 = "+80% HP recovery when using bandages picked up in battle.",
  str_item_intro_9993004 = "Sniper Aurorians +10% element counter effect.",
  str_item_intro_9993005 = "Detonator Aurorians +30% Chain Combo damage when connecting 15+ tiles.",
  str_item_intro_9993006 = "+50% Poison, Burn, and Bleeding damage taken by Eclipsites.",
  str_item_intro_9993007 = "Sniper Aurorians +15% Chain Combo damage.",
  str_item_intro_9993008 = "Detonator Aurorians +30% chance for normal attacks to deal 150% damage.",
