  str_item_intro_9993033 = "+5% ATK for Thunder Aurorians.",
  str_item_intro_9993034 = "Increases HP by 3% for Converter and Supporter Aurorians after every victory, up to 30%.",
  str_item_intro_9993035 = "Increases ATK by 1.5% for Aurorian Snipers and Detonators after every victory, up to 15%.",
  str_item_intro_9993036 = "A random surviving Aurorian in the team gets a 1.5% stackable damage reduction after winning a battle, until the end of this Secret Territory Exploration.",
  str_item_intro_9994001 = "A random surviving Aurorian in the team regenerates 10% HP every time an Eclipsite is killed.",
  str_item_intro_9994002 = "Supporter Aurorians regenerate 100% of poison damage in HP every time Poison is triggered on a Poisoned Eclipsite.",
  str_item_intro_9994003 = "Detonator Aurorians +30% damage to Eclipsites with debuffs.",
  str_item_intro_9994004 = "Inflicts 3 stacks of Poison to all enemies when a Poisoned, Burning, or Bleeding Eclipsite dies.",
  str_item_intro_9994005 = "Every Eclipsite round, Poisoned, Burning, or Bleeding Eclipsites inflict Poison on Eclipsites in 2 surrounding clusters.",
  str_item_intro_9994006 = "Sniper Aurorians +30% damage when team is affected by debuff.",
  str_item_intro_9994007 = "Detonator Aurorians +5% damage bonus every time damage is taken (reset at end of battle).",
  str_item_intro_9994008 = "Reload a bandage on the field when a battle begins.",
  str_item_intro_9994009 = "+20% damage for all Sniper Aurorians with more than 70% HP.",
  str_item_intro_9994010 = "Detonator Aurorians gain damage bonus equal to 10% of HP loss when attacking.",
  str_item_intro_9994011 = "Lumina Spring regenerates additional 5 MS.",
  str_item_intro_9994012 = "+1 character recovered by Lumina Spring.",
  str_item_intro_9994013 = "Detonator Aurorians +10% ATK in Dangerous Area.",
  str_item_intro_9994014 = "Detonator Aurorians in Lethal Area gain +10% ATK.",
  str_item_intro_9994015 = "Delays escape rounds for Scroungers by 4 rounds.",
  str_item_intro_9994016 = "Reduces 1 cooldown round for all Aurorians after killing a large Eclipsite.",
  str_item_intro_9994017 = "Sniper Aurorians +20% ATK when killing a large Eclipsite.",
  str_item_intro_9994018 = "Aurorian with the least HP regenerates 20% HP after a large Eclipsite is killed.",
  str_item_intro_9994019 = "Inflicts Slow on all small monsters.",
  str_item_intro_9994020 = "-20% initial HP for all small monsters.",
  str_item_intro_9994021 = "-10% ATK of all small monsters.",
  str_item_intro_9994022 = "-1 cooldown for any incomplete Converter Aurorian Active Skill when a match begins.",
  str_item_intro_9994023 = "Hovers around an Aurorian and deals one Fire damage when the captain attacks.",
  str_item_intro_9994024 = "Hovers around an Aurorian and deals one Water damage when the captain attacks.",
  str_item_intro_9994025 = "Hovers around an Aurorian and deals one Forest damage when the captain attacks.",
  str_item_intro_9994026 = "Hovers around an Aurorian and deals one Thunder damage when the captain attacks.",
  str_item_intro_9995001 = "Returns an Aurorian to life at 50% HP after killed (only for the first Aurorian to receive lethal damage in a battle)",
  str_item_intro_9995002 = "Damage from a single attack dealt to a Converter Aurorian wearing the relic can never exceed 20% of Max HP.",
  str_item_intro_9995003 = "Support Aurorians' excess Healing converts to Shield for one round on one level.",
  str_item_intro_9995004 = "50% chance of unleashing a shockwave that stuns all enemies for one round in every battle.",
  str_item_intro_9995005 = "Sniper Aurorians' normal attacks and Chain Combo damage immediately remove Eclipsite shields.",
  str_item_intro_9995006 = "4 of 8 adjacent tiles randomly become chromatic tiles when a match begins.",
  str_item_intro_9995007 = "Refreshes an additional MS Luminameter when a battle starts.",
  str_item_intro_9995008 = "When a match starts, 10 random 2×2 tiles are struck by lightning that deals static damage to units within range. Aurorians are unaffected.",
  str_item_intro_9995009 = "Leaves a bomb where your movement started that detonates following your and allies' actions.",
  str_item_intro_9995010 = "Normal attack combos in multiples of 5 deal one explosion damage.",
  str_item_intro_9995011 = "Defeats Eclipsites under 7% HP.",
  str_item_intro_9995012 = "Generates an image of the Detonator Aurorian releasing skills at the starting spot, while releasing Chain Combo.",
  str_item_intro_9995013 = "Spend the Fate Dice inside to get a new random Secret Territory Relic.",
  str_item_intro_9995014 = "Grants a 40% chance for a Sniper Aurorian to release an additional Chain Combo.",
  str_item_intro_9995015 = "-1 cooldown to a random Converter Aurorian when an Aurorian uses an Active Skill.",
  str_item_intro_9995016 = "Sniper Aurorian's normal attacks inflicts Slow and -1 Movement on Eclipsites.",
  str_item_intro_9995017 = "Inflicts Wounded and deals 3% damage per tile moved to all Eclipsites when a match begins.",
  str_item_intro_9995018 = "Support Aurorian's normal attacks inflict Blindness on Eclipsites and a 30% chance of missing when attacking.",
  str_item_rpintro_9993001 = "Candle giving off warm glows that can heal wounded Aurorians.",
  str_item_rpintro_9993002 = "Old-era paint able to absorb Lumina.",
  str_item_rpintro_9993003 = "Auxiliary for recovery potion to help heal the wounded.",
  str_item_rpintro_9993004 = "Seemingly written by ancient scholars, it details the nuances in element counter effect and provides effective strategic suggestions.",
  str_item_rpintro_9993005 = "Old-era badge with wondrous setup to secure Lumina on a micro level, improving combat prowess.",
  str_item_rpintro_9993006 = "Relic from the old era, possibly strongly cursed. Wearer becomes lethal with toxins.",
  str_item_rpintro_9993007 = "Talisman for the old era, able to secure Lumina on a micro level, dealing great damage to enemies.",
  str_item_rpintro_9993008 = "Ancient short, keen blade made from old-era superalloy.",
  str_item_rpintro_9993009 = "Leather armor infused with Lumina. Light and durable, enough to improve resistance against attacks.",
  str_item_rpintro_9993010 = "Leather armor infused with Lumina. Light and durable, enough to improve resistance against attacks.",
  str_item_rpintro_9993011 = "Leather armor infused with Lumina. Light and durable, enough to improve resistance against attacks.",
  str_item_rpintro_9993012 = "Leather armor infused with Lumina. Light and durable, enough to improve resistance against attacks.",
  str_item_rpintro_9993013 = "Leather armor infused with Lumina. Light and durable, enough to improve resistance against attacks.",
  str_item_rpintro_9993014 = "Inscrutable red gem. Fire Aurorians will have a big power boost with it.",
  str_item_rpintro_9993015 = "Inscrutable red gem. Fire Aurorians will have a big power boost with it.",
