  str_item_rpintro_9993026 = "Inscrutable green gem. Forest Aurorians will have a big power boost with it.",
  str_item_rpintro_9993027 = "Inscrutable green gem. Forest Aurorians will have a big power boost with it.",
  str_item_rpintro_9993028 = "Inscrutable green gem. Forest Aurorians will have a big power boost with it.",
  str_item_rpintro_9993029 = "Inscrutable yellow gem. Thunder Aurorians will have a big power boost with it.",
  str_item_rpintro_9993030 = "Inscrutable yellow gem. Thunder Aurorians will have a big power boost with it.",
  str_item_rpintro_9993031 = "Inscrutable yellow gem. Thunder Aurorians will have a big power boost with it.",
  str_item_rpintro_9993032 = "Inscrutable yellow gem. Thunder Aurorians will have a big power boost with it.",
  str_item_rpintro_9993033 = "Inscrutable yellow gem. Thunder Aurorians will have a big power boost with it.",
  str_item_rpintro_9993034 = "A lost statuette from the old era made from high-grade materials. Durable, light, and blesses those who carry it.",
  str_item_rpintro_9993035 = "Old-era weapon made from high-grade materials and infused with Lumina to make any wielder formidable.",
  str_item_rpintro_9993036 = "Ancient shield from the old era, in perfect oval and supposedly infused with the power of the sun to deflect all lethal strikes.",
  str_item_rpintro_9994001 = "Oversized blade with palpable nastiness. Likely used for death duels in ancient times. There will be blood when used.",
  str_item_rpintro_9994002 = "Mask worn by doctors in the old eras, but a symbol of curse in the war-torn era.",
  str_item_rpintro_9994003 = "Famous old-era sword. Wielder can feel godlike power.",
  str_item_rpintro_9994004 = "Purportedly a cursed item made by a mighty warrior to ensure the doom of all enemies.",
  str_item_rpintro_9994005 = "Ancient painting by an anonymous painter that portrayed the atrocity of the plague. The artist also died in the pandemic, after which it possessed terrifying power...",
  str_item_rpintro_9994006 = "Famous old-era sword brandished by a notorious rebel, whose death cry granted it magical power.",
  str_item_rpintro_9994007 = "Ancient armor carved with the word, \"Vengeance.\" Wearer can sense the eternal rage hidden in the armor.",
  str_item_rpintro_9994008 = "Perfectly preserved statue of a goddess that provides healing power to believers of the Light.",
  str_item_rpintro_9994009 = "Carry it and you will be protected by the Goddess of Victory, winning you all of your battles.",
  str_item_rpintro_9994010 = "The dagger, rumored to originate from a very ancient civil war, gives off an ominous aura and must draw blood when drawn.",
  str_item_rpintro_9994011 = "Old-era technology. It stores much more Lumina than the small size indicates.",
  str_item_rpintro_9994012 = "Lost and forgotten sleeping bag. Helps recover strength.",
  str_item_rpintro_9994013 = "Firearm blessed by the power of the sun. Slow firing rate, but packs enough punch against formidable enemies.",
  str_item_rpintro_9994014 = "It has been owned by many in the past, though the ownerships never lasted...",
  str_item_rpintro_9994015 = "Long-range weapon firing paralysis ray. Limited range, not very powerful, and usually used to nab petty thieves.",
  str_item_rpintro_9994016 = "Radiance relic from old-era warriors etched with blessed glyphs and particularly effective against powerful enemies. (Effects double when possessing all three Radiance Relics.)",
  str_item_rpintro_9994017 = "Radiance relic from old-era warriors etched with blessed glyphs and particularly effective against powerful enemies. (Effects double when possessing all three Radiance Relics.)",
  str_item_rpintro_9994018 = "Radiance relic from old-era warriors etched with blessed glyphs and particularly effective against powerful enemies. (Effects double when possessing all three Radiance Relics.)",
  str_item_rpintro_9994019 = "Classic old-era weapon etched with blessed glyphs and particularly effective against powerful enemies. (Effects double when possessing all three Silvermoon Relics.)",
  str_item_rpintro_9994020 = "Classic old-era weapon etched with blessed glyphs and particularly effective against powerful enemies. (Effects double when possessing all three Silvermoon Relics.)",
  str_item_rpintro_9994021 = "Classic old-era weapon etched with blessed glyphs and particularly effective against powerful enemies. (Effects double when possessing all three Silvermoon Relics.)",
  str_item_rpintro_9994022 = "Mysterious ancient coin that occasionally boosts the speed of its Aurorian owner, granting more agility.",
  str_item_rpintro_9994023 = "Seemingly miniaturized Colossus from the old era that assists the owner in battle. Aurorian with a collection of floaters of four elements unleashes one powerful attack after a Chain Combo.",
  str_item_rpintro_9994024 = "Seemingly miniaturized Colossus from the old era that assists the owner in battle. Aurorian with a collection of floaters of four elements unleashes one powerful attack after a Chain Combo.",
  str_item_rpintro_9994025 = "Seemingly miniaturized Colossus from the old era that assists the owner in battle. Aurorian with a collection of floaters of four elements unleashes one powerful attack after a Chain Combo.",
  str_item_rpintro_9994026 = "Seemingly miniaturized Colossus from the old era that assists the owner in battle. Aurorian with a collection of floaters of four elements unleashes one powerful attack after a Chain Combo.",
  str_item_rpintro_9995001 = "Handicraft with a mysterious link to the land. Resurrects the wearer the moment their heart stops.",
  str_item_rpintro_9995002 = "Mighty armor blessed by the sun for the wearer to endure one grueling battle after another.",
  str_item_rpintro_9995003 = "Unknown device from the old era that can sense and convert overflowing Lumina into protective force field for the wearer.",
  str_item_rpintro_9995004 = "Coarse crystal with slightly cracked surface that indicates excess Lumina within. Just a soft touch can unleash enough Lumina to stun enemies in a battle.",
  str_item_rpintro_9995005 = "Powerful weapon from the old era. No one knows what it's made out of, only that it is too sharp for almost any armor to resist.",
  str_item_rpintro_9995006 = "A gem that shines in every color, splendid and ever-changing.",
  str_item_rpintro_9995007 = "Device for storing and replenishing Lumina.",
  str_item_rpintro_9995008 = "Famous blade from the old era, enchanted with the power of thunder. The explosive wrath is apparent upon drawing.",
  str_item_rpintro_9995009 = "Old-time item created specifically to deal with pursuers. Leaves Lumina on the trail that detonates later to kill the pursuers.",
  str_item_rpintro_9995010 = "Old-era creation that seems very pretty but carries terrifying power, dropping enemies like falling flowers with explosions.",
  str_item_rpintro_9995011 = "It can sense enemy's life force and end those who are near death's door when carried closely.",
  str_item_rpintro_9995012 = "Powerful device from the old era that can generate illusion to confuse enemies.",
  str_item_rpintro_9995013 = "Ancient relic enabling one to see the fate of all... Or, it could just be a hallucination.",
  str_item_rpintro_9995014 = "Rare red orchids specially developed in the old era. They always appear, blossom, and wither in pairs. Seems to form a bond with the wearer and assist in combat.",
  str_item_rpintro_9995015 = "Old-era item that creates mysterious bonds between two combatants.",
  str_item_rpintro_9995016 = "Product of the wartime old era. Supposedly induces aging and staggering steps.",
  str_item_rpintro_9995017 = "Allegedly a mystery item from the previous apocalyptic war. It carries a powerful curse that is strong enough to seriously wound opponents.",
  str_item_rpintro_9995018 = "The lenses glow in battle, blinding the opponent while protecting the wearer from it. Auxiliary equipment.",
  str_item_gift_open_cond_1003 = "Reach Lv. 10 to unlock the Gift Pack",
