  str_item_1602381 = "Mithra",
  str_item_intro_1600011 = "Spokeswoman for Northland. She carries a giant mirror reflecting her extraordinary appearance, and concealed many secrets...",
  str_item_intro_1600021 = "A strict, serious, determined, firm and confident commander of Illumina Federation. She's scored many victories with the longsword in hand.",
  str_item_intro_1600031 = "Served as a butler for an Uptown noble until banished to Lower Lumopolis for offending another noble. However, according to some, that's just a cover for his secret mission...",
  str_item_intro_1600041 = "An eccentric animal duo comprised of two wanderers. Now they work as freelance mercenaries known for their combat prowess and sense of humor.",
  str_item_intro_1600051 = "A girl who roams Umbraton with a somewhat crazy laugh. She loves to play lethal games with others; it's no surprise that she's given a wide berth.",
  str_item_intro_1600061 = "Second daughter of the Lumopolis Lord. Independent since young, she rose to be the Captain of the Guardians through talent and effort.",
  str_item_intro_1400071 = "Assassin girl from Rediesel Wrench. She works solo and specializes in difficult missions.",
  str_item_intro_1400081 = "A Rediesel Wrench tech, inventor of the sunbeam projector, boasting unique combat mode.",
  str_item_intro_1500091 = "Winsome young man from the True Order. He exudes an air of knowledge with his simply captivating smile and likes rattling on about his academic ideas.",
  str_item_intro_1600101 = "Bubbly girl from Northland who aspires to travel the world and sees everything through rose-colored glasses.",
  str_item_intro_1600111 = "A Legion Commander of the Illumina Federation with Dragon Power. Although she appears aloof and detached, she's definitely someone you can count on.",
  str_item_intro_1500121 = "Valiant girl from Illumina Federation who fights to uphold and enforce justice with lofty ideals.",
  str_item_intro_1500131 = "A Northland lass with powerful ice magic that can cover a region in wintry frost.",
  str_item_intro_1600141 = "Lord of Lumopolis, tirelessly maintaining law and order in the city without a moment of complacency.",
  str_item_intro_1400171 = "A short girl and captain of the Rediesel Wrench, nimble with lightning reflexes. Very few enemies can pin her down.",
  str_item_intro_1500181 = "Very popular rocker of the Rediesel Wrench. Not only can she inspire troops, she can lead them in a charge, as well.",
  str_item_intro_1600191 = "A mature woman of lethal charm, and a True Order member with certain forbidden knowledge. She loves to advocate a certain truth...",
  str_item_intro_1500201 = "Northwind",
  str_item_intro_1500211 = "The boy-next-door from Illumina Federation. Master of natural science, proficient with gardening, and fond of punishing foes with forces of nature.",
  str_item_intro_1300221 = "A wild young rebel in a rabbit headgear. Obsessed with diesel and violence, he's one of the desperados of the Rediesel Wrench.",
  str_item_intro_1600231 = "A very antisocial girl, relying on her clarinet and special ability to control water creatures to carve out a niche in the messy Umbraton.",
  str_item_intro_1500241 = "A duo from Illumina. Benny is brash and reckless, Curo is cool and calm. Despite their differences, they have great chemistry and are among the elite fighters for Illumina.",
  str_item_intro_1600251 = "Logistics officer for Illumina Federation, also the owner and a close partner in life or battle of the train, Other End.",
  str_item_intro_1600261 = "One of the Four Angels in the Lumo Knights. She's chronically pessimistic, which is in curious contrast to her fiery appearance...",
  str_item_intro_1600271 = "A Lumopolis knight and one of the famous Four Angels. She is upright and rarely smiles. She was transformed by the Illumina after she was seriously wounded, resulting in the loss of part of her emotions.",
  str_item_intro_1600281 = "One of the Four Angels in the Lumo Knights. She possesses unique healing power and gung-ho optimism.",
  str_item_intro_1600291 = "One of the Four Angels in the Lumo Knights. She's quiet, serene, and calm to the point that nothing can seem to bother her.",
  str_item_intro_1600301 = "The outspoken leader of Rediesel Wrench who is incredibly close with his members and very protective of his little sister. He is dedicated to ensuring the gang's survival.",
  str_item_intro_1500311 = "Schumann",
  str_item_intro_1400321 = "A Lumo Hall of Justice staff and a one-winged angel. She is sensitive and has a strong sense of pride. Although young, Angel is actually hardened by years of battle.",
  str_item_intro_1500331 = "Still very young but experienced for her age. Hard-working and enthusiastic, she is an upstart talent highly valued by the Illumina Federation.",
  str_item_intro_1500341 = "Sonnet",
  str_item_intro_1400351 = "Well-traveled workaholic courier who cannot fall asleep until all on hand is done.",
  str_item_intro_1500361 = "Lone wolf from Umbraton. A rebel with utter contempt for the order of Lumopolis and is inexplicably hostile to the nobles.",
  str_item_intro_1600381 = "The female pilot of giant mecha and the current Tech Officer in the Illumina Federation. She's said to be a genius retired from the military.",
  str_item_intro_1400401 = "A little girl from Rediesel Wrench, fascinated with explosions, who gets unusually excited when something detonates.",
  str_item_intro_1400411 = "A guide for newcomers to Lumopolis. She stays composed even in catastrophes, hinting at an extraordinary past.",
  str_item_intro_1400441 = "Strict and rigid, as the Chief of Staff for Illumina Federation, she's capable of planning and organizing everything to the most minute details.",
  str_item_intro_1300461 = "Four kids serving as the Lumopolis Broadcast Team... As the members of the Academy's Choir, they relish in mocking others mercilessly rather than being the little innocent children they should be...",
  str_item_intro_1300471 = "A genius researcher of the Illumina Federation. Her hunger for knowledge...and a certain Legion Commander take up all her attention.",
  str_item_intro_1400481 = "Already the leader of the Spearows at a young age, she rules Umbraton with her unsurpassed determination and diabolical, sneaky weapons.",
  str_item_intro_1300491 = "A tall, strong warrior who often strides throughout Umbraton in full armor with a great sword. He's never taken his helmet off, a man of few words who prefers letting brute force do his talking.",
  str_item_intro_1200501 = "It's still a terrifying shark even when it smiles! The protector of a small settlement. Despite the ferocious, fearsome exterior, he is actually very gentle.",
  str_item_intro_1300511 = "A taciturn crocodile grenadier and a noisy bird sniper make up this odd Rediesel Wrench duo and reliable mercenary pair.",
  str_item_intro_1300521 = "A courier providing postal services for the Illumina Federation, a total slacker without a shred of professional pride. She'll go to any length to put off or get out of work...",
  str_item_intro_1300531 = "A merchant from Rediesel Wrench. As a typical money-grabbing trader, he never passes up an opportunity to turn a profit.",
  str_item_intro_1300741 = "A junior officer of Illumina Legion. He is antisocial and doesn't get along with peers—supposedly a trait of his mysterious bloodline...",
  str_item_intro_1300581 = "Earnest, zealous New Knight of Lumopolis. Prone to overstress from the pressure of appointed heavy responsibilities at such a young age.",
  str_item_intro_1400161 = "A Rediesel Wrench sniper who wields a powerful super railgun to annihilate all opposing foes.",
  str_item_intro_1400541 = "Captain of the Lumo Nightwatch Recruits. Cool, calm, focused, and admired for treating everything seriously.",
  str_item_intro_1400611 = "Optimistic, cheerful Illumina Federation researcher, with the special ability to absorb other's negative emotions and heal their bleeding inside.",
  str_item_intro_1400731 = "New members of the Istvan Guild in Umbraton. They're always hyperactive, so please watch out!",
  str_item_intro_1500421 = "Legion commander for Illumina Federation. A warmonger who cannot stand the monotony of peacetime and will seek to win at any cost.",
  str_item_intro_1500761 = "A polite, mild-mannered and calm gentleman, but a habitual liar. He also happens to be an infamous scam artist in Umbraton.",
  str_item_intro_1500781 = "A member of the Umbraton Spearows. Reserved and socially anxious, she and Dayna rely on each other to survive in Umbraton.",
  str_item_intro_1600771 = "The ruler of Northland with years of accumulated wisdom and experience. She is able to handle anything with ease.",
  str_item_intro_1300591 = "A member of the Courier Union, who is responsible for correspondence with the True Order. Despite her shortcomings, everyone accepts her because she forthright and has nothing to hide.",
  str_item_intro_1300801 = "A researcher of the Illumina Federation. She is a genius who is fanatical about machines and models and finds it difficult to socialize. However, she can talk endlessly when talking about something she's fanatical about.",
  str_item_intro_1300821 = "An innocent and cute Fae from Northland Pine who is clueless about the ways of the world. She has a pair of precious Gemstone Horns and has been carefully protected since she was a child.",
  str_item_intro_1400451 = "A cadre member of the True Order and follower of Victoria. He is taciturn and strongly believes in the ideals of the True Order. His lifelong goal is to spread the ideals of the True Order.",
  str_item_intro_1400571 = "The Intel Chief of the Illumina Federation. She is usually gentle, approachable, and a little lazy, but her alternate persona is quite rebellious.",
  str_item_intro_1400681 = "A member of the Courier Union who is responsible for the Rediesel Wrench area. She is confident, cute, brave, and dares to accept challenges. She likes to mess around while delivering letters and is a cute little ruffian.",
  str_item_intro_1400791 = "A rational, fair, and independent Lumo Tax Collector. She has a habit of converting the value of everything into gold for comparison purposes.",
  str_item_intro_1400811 = "A member of the Rediesel Wrench Loose Screws. He is self-confident, passionate, and naive, incapable of scheming. He wants to be number one in everything.",
  str_item_intro_1400831 = "An entourage member of the Illumina Federation Scientific Research Institution. She speaks like a mechanical maid, but she is actually a Replicant of a certain powerful living being.",
  str_item_intro_1601231 = "This Illumina Sheriff is often frightened to tears by even the slightest emergency, but she remains optimistic and works hard at her job in the name of justice.",
  str_item_intro_1601201 = "A noble girl born into a wealthy family, she is intelligent and likes nothing more than reading alone in her room. Her only friend is a giant suit of armor named Pompey, which she activated on her own.",
  str_item_intro_1500151 = "An Umbraton art dealer, Hachi knows all there is to know about fine art, while Gin is a painter of unparalleled skill. They share an unbreakable bond and work together as mercenaries.",
  str_item_intro_1501321 = "A resident of Northland's Pine Frost Valley. Loves all things honey. The flower vine on her body may be beautiful, but actually possesses special abilities.",
  str_item_intro_1601311 = "A Northlander with close ties with Bethlehem. Compassionate and well-versed in history. He believes that Northland is the last paradise for Aurorians, and wishes to protect it with his power.",
  str_item_intro_1601331 = "Tohru is an extremely ruthless dragon that fought gods one-on-one and almost died. After crushing on Kobayashi in an alien world, Tohru chose to live with her as her maid.",
  str_item_intro_1601341 = "A dragon like Tohru, with child-like appearance and personality. Banished from home due to pranks she pulled and has been following Tohru ever since.",
  str_item_intro_1501351 = "A dragon striving to resolve mortal conflicts. Once called the Witch of the Holy Sea. Honest and hardworking, she loves good food and is completely unable to resist sweets.",
  str_item_intro_1501361 = "Once a deity in charge of ancient cultures and civilizations. Very powerful, but also very lackadaisical and laid-back.",
  str_item_intro_1401371 = "Tohru's friend who guarded a treasure cave in another world. He is very hostile and cynical since he's seen too many greedy people.",
  str_item_intro_1601381 = "A researcher from the Illumina Federation. She is rational and very efficient at work, but lazy and casual in private. Fascinated by ancient technology, she travels around Astra all year round to investigate all sorts of ruins.",
  str_item_intro_1501391 = "She was born in Lumopolis and was a member of the Dawn Academy student council. She follows Florine everywhere and has fantastical ideas. Sometimes, she surprises people with what she says.",
  str_item_intro_1601401 = "Born in Lumopolis, she was the president of student council back in Dawn Academy. With a warm heart behind her cold appearance, she takes good care of her friends on her journey to becoming an outstanding knight.",
  str_item_intro_1601411 = "Born in the Rediesel Wrench, Ruby has always loved adventure stories growing up. Cheerful and vivacious by nature, she set out on her own adventure as soon as she learned enough knowledge and skills.",
  str_item_intro_1501421 = "A member of the Rediesel Wrench, she's heavily dependent on Ruby. She may come across as mean and bitter but behind her sharp tongue is actually a thoughtful and tender heart.",
  str_item_intro_1601431 = "A Cloud Island priestess who's learned and poised. Raised by the general who rules Cloud Island, she hopes to help the people with her strength.",
  str_item_intro_1501441 = "A tall woman from Cloud Island who was once saved by Rinne. She claims to be able to see \"things\" and is afraid of strangers.",
  str_item_intro_1601451 = "Born on Cloud Island, she lost her home due to the war and was later rescued and taught Ninjutsu. Her past has made her put on a cold outward appearance, but deep down, she's extremely loyal to her companions.",
  str_item_intro_1601461 = "Born on Cloud Island, she studied the \"Art of Qi\" with the Lin Guild. She possesses strong combat abilities, has a lively personality, and enjoys traveling around while fighting injustice.",
  str_item_intro_1501471 = "Born on Cloud Island, the twins are often seen selling Kaniya Ramen from their cart, and business has been booming. They hope to make money while at the same time exploring the limits of deliciousness.",
  str_item_intro_1201631 = "A Mysterious Creature from the north that's passionate about games. Whenever it comes across someone new, it'll always ask, \"esteemed master, do you accept commissions?\"",
  str_item_intro_1601481 = "A free-spirited member of the Rediesel Wrench exploration team who's always worked alone in investigating all kinds of information that might benefit Rediesel Wrench. She was once regarded as a legendary racer.",
  str_item_intro_1501491 = "The logistics manager of Rediesel Wrench. Though he does come across as disorganized, he's in fact very thoughtful and protective of everyone in Rediesel Wrench.",
  str_item_intro_1601501 = "A member of the True Order, quiet but very capable. She doesn't seem to have her own thoughts or any ambition. The purpose of her life is to receive and fulfill orders.",
  str_item_intro_1601511 = "A member of the True Order, usually rather apathetic unless triggered. He firmly believes that he was sent to this world to spread a certain nursery tale.",
  str_item_intro_1501521 = "A socially-inept, obstinate young girl who tries desperately to please the grown-ups around her in the True Order. She craves attention as a result of being emotionally neglected.",
  str_item_intro_1601551 = "After using the \"Chord Link\" device, though the appearance and abilities of Illumina Federation's Legion Commander have changed, he still remains a warmonger at heart.",
  str_item_intro_1601541 = "Illumina's Expedition Captain with a gentle personality. By a stroke of fate, she rescued the last Caelestite descendant trapped underground, opening a path to new and exciting adventures.",
  str_item_intro_1601531 = "Illumina Federation's veritable Grand Marshal. Not only is she courageous and skilled on the battlefield, she's also an honest and highly capable leader respected by all Illumina.",
  str_item_intro_1601561 = "Born into a Lumo Noble family in Umbraton, she appears to be hard to get along with but is actually fairly easy of approach... Well, kind of.",
  str_item_intro_1501571 = "Born on Cloud Island, she suffers many a setback during her early life. After moving to Astra for a better life, she somehow takes on a huge debt. All she wishes for is a stable job.",
  str_item_intro_1601581 = [[
A young man from another world with a special power called Persona.
Hidden behind a mask, he's only known by a code name, and gives off a special aura.
In his world, he was the leader of the sensational Phantom Thieves of Hearts.]],
  str_item_intro_1601591 = [[
A member of the Phantom Thieves from another world.
The gang's tactics genius, she plans her comrades' course of action.
Able to use the special power Persona.]],
  str_item_intro_1501601 = [[
A member of the Phantom Thieves from another world.
Of an eccentric disposition, this young man often appears detached and indifferent.
Able to use the special power Persona.]],
  str_item_intro_1501611 = [[
A young girl from the same world as the Phantom Thieves.
Temporarily working with them for various reasons.
Able to use the special power Persona.]],
  str_item_intro_1501621 = [[
A mysterious creature from another world. It looks like a cat but speaks like a human.
It guides the Phantom Thieves on various occasions.
Able to use the special power Persona.]],
  str_item_intro_1601641 = "Carleen de Schwartz. On her way to Harbor City, her powers change, giving her a more profound understanding of leadership.",
  str_item_intro_1501651 = "A genius engineer of Illumina. Introverted, shy, but eager to communicate with people, her dream is to create a powerful dynamic mecha.",
  str_item_intro_1601661 = "A little extrozoologist who is willful and stubborn but unexpectedly loves to cry. She is working hard to become an extrozoologist even greater than Vic.",
  str_item_intro_1601671 = "The ringmaster of The Illusionist & Old Bill's Circus, as well as a member of the True Order. Mysterious, spooky, and taciturn, his ambition is to become the greatest magician.",
  str_item_intro_1501681 = "A young girl who was forced to leave her hometown because of Eclipsite attacks. Pure of heart and lively, she has made it her mission to protect the Emerald, and she often performs as a guest at the circus to warm up the atmosphere.",
  str_item_intro_1501301 = "A member of the Troy family of Lumopolis. But why is his seat so low for someone of such high birth? Perhaps the answer lies in his personality.",
  str_item_intro_1501711 = "Seemingly aloof, but actually very responsible. Teamed up with Pollux to form the mercenary duo dubbed \"Raven's Blood\" in order to better defend the kids living in the church.",
  str_item_intro_1601701 = "Imposing and competent, she has a past that she'd rather leave behind. Now a staunch guardian of a church that shelters homeless children in the downtrodden Euphoria.",
  str_item_intro_1401691 = "An absurdly powerful young girl hailing from Umbraton. Beneath her cool and charismatic exterior beats a pure and determined heart, and she regards any task given to her as part of her training to become a true swashbuckler.",
  str_item_intro_1601721 = "A cute, cheery, and optimistic girl. To pursue her dream of working in the movies, she settled in Umbraton's Alleywood all by herself and found work in its booming film industry. Though she has been through countless hardships, she has never considered giving up.",
  str_item_intro_1601731 = "The head butler of the Andersen family in Umbraton. Graceful, courteous, and a perfectionist to a fault, he has sworn to repay his master's kindness by serving him with every ounce of his strength and loyalty.",
  str_item_intro_1601751 = "The Combat Cyborg known as Axelia is affiliated with the Illumina Federation. Despite her reputation, her physical condition is worrying in private.",
  str_item_intro_1501761 = "A Lumopolis combat medic who was once saved by a doctor called John; after which, she made up her mind to become a good doctor.",
  str_item_intro_1601771 = "Born in Umbraton, this young famous idol is graced with fortune, spreading her optimism and positivity to everyone she encounters.",
  str_item_intro_1601781 = "An extrozoologist who lives in seclusion in the forest. Although he often infuriates people with his words and actions and bullies his disciple Fia, he is kind to all wondrous beasts.",
  str_item_intro_1501801 = "Though she is currently only an intern reporter for a small newspaper agency, she is enthusiastic about interviewing anyone she can and has an ear for all the latest gossip. Her goal is to become the most famous journalist in Umbraton.",
  str_item_intro_1601811 = "Once Chief General of the kingdom of Zhao in Longzhou, now a wanderer. No matter when or where, he cares for naught but his own personal goals.",
  str_item_intro_1601821 = "Captain of The Shadowind. Aloof, decisive, what-you-see-is-what-you-get. Her goal is to build the greatest long-range ship and blaze the safest voyage route.",
  str_item_intro_1501831 = "A young doctor who studied under the great doctor Bucunzi. Small in stature but ambitious, he's a reliable doctor with a sharp tongue. That said, one compliment is enough to make him full of himself.",
  str_item_intro_1601841 = "A senior member of the Courier Union's Rediesel Wrench division. She is easygoing and disorganized, but also a very astute observer.",
  str_item_intro_1501851 = "Although she's just a rookie, she is also one of the few conscientious and responsible individuals in the Courier Union. However, her overly strict adherence to the union's rules sometimes leads to mistakes.",
  str_item_intro_1601861 = "A noble girl who has inherited her title, and she's a judge of the Hall of Justice as well. She also has a special constitution that makes her sleep all the time.",
  str_item_intro_1601891 = "An upright judge of Lumopolis who hates all evils, and he always treats others equally. At the same time, he has a stubborn and aloof side.",
  str_item_intro_1501901 = "An extremely talented judge of the Lumo Hall of Justice who doesn't have much ambition and only wants to live a happy and wealthy ordinary life.",
  str_item_intro_1601911 = "A lone wolf from Umbraton of demi-human descent, who often ends up embroiled in unnecessary misunderstandings due to her general lack of tact.",
  str_item_intro_1501931 = "Though born into a noble family, she has always walked her own path and followed her heart to become a probationary judge of Lumopolis.",
  str_item_intro_1601921 = "The captain of the Ironthorn Knights, he has a decisive personality and is both dignified and friendly. He seeks to change the decaying Lumopolis back to life.",
  str_item_intro_1601991 = "She was born into a family of Illumina soldiers and is now a senior intelligence officer of the Committee. Many plans are hidden deep within her eyes.",
  str_item_intro_1502001 = "A calm and reliable intelligence officer of the Illumina Federation who makes unexpected complaints occasionally. No one knows whether these complaints are made intentionally or unintentionally.",
  str_item_intro_1602011 = "A Lumopolis knight who lives a secluded life in Umbraton, she is in fact the  seldom-mentioned elder daughter of the Schwartz family—a pure and kind girl who longs for her father's recognition.",
  str_item_intro_1602021 = "In his prime, Schwartz, wielding a sword and crusading against the Eclipsites, was not only the newly-ascended ruler of Lumopolis, he was also a valiant warrior who fought on the frontlines to hold back the enemies of civilization.",
  str_item_intro_1502031 = "The Northern Envoy Jakine is enthusiastic and passionate in nature, but her unskillful divination and careless personality often land her in unforeseeable trouble.",
  str_item_intro_1602041 = "Everyone says she looks just like the deceased wife of the City Lord, but she doesn't seem to be her either. Joshua hopes to go to even more places in the world with her ideals...",
  str_item_intro_1502051 = "Blanc, who retired as the captain of the Nightwatch Guard many years ago, has donned her combat uniform again. Ms. Rot has returned!",
  str_item_intro_1602061 = "Born into affluence in Umbraton, she could have led a carefree life within the comforts of her home. However, she chose to venture out on her own, driven by an unwavering determination to make her dreams come true.",
  str_item_intro_1602071 = "The manager of Denuo Valley Resort who lives by the motto of \"living in the moment.\" He may come across as frivolous on the outside, but surprisingly, he is incredibly dependable when it comes to business.",
  str_item_intro_1502081 = "She's not only the navigator of Lepidoz but also the strategist behind the Rediesel Wrench. However, in the eyes of everyone, she appears more like a cheerful mascot than anything else...",
  str_item_intro_1400861 = "A member of the Dawn Academy of Lumopolis and a Funeral MC. She is positive and bold, yet gentle and delicate, and faces everything calmly with a smile.",
  str_item_intro_1400911 = "A gentle and friendly musician of Lumopolis who is easily drowned in her sad memories. She lost her family due to the war, so she lives in sorrow and finds it hard to let go of it.",
  str_item_intro_1500701 = "The maverick of Umbraton who possesses Dragon Power. She is a proud and arrogant person who is moody all the time. She always feels that the fate of her family rests on her shoulders.",
  str_item_intro_1500751 = "A Rediesel Wrench tech personnel who is highly confident in her comm tech. She likes to complain and yell at others in the Comm Channel, but she gets flustered when there are problems.",
  str_item_intro_1500841 = "The Underground Leader of Umbraton. He is decisive, carefree, and very loyal to those around him. He endured a series of trials and tribulations, winning his current prestige and status.",
  str_item_intro_1500881 = "A member of Rediesel Wrench who is usually in charge of recon work. She is timid, shy, and clumsy, and can't control her great power in battle because she gets too excited. Maggie is quite distressed by this too.",
  str_item_intro_1500901 = "The idol singer of Rediesel Wrench. Barbara looks gentle and nice on the surface but reveals her irritable side when she encounters an overly offensive fan.",
  str_item_intro_1500921 = "A member of the True Order who is honest and inflexible. She has a one-track mind, so she will focus on achieving a goal once she has identified it. She has a unique taste and often gets into arguments with others.",
  str_item_intro_1600601 = "Once a bounty hunter, Jona is a member of the Rediesel Wrench and an expert sharpshooter. She is unruly and doesn't take the world too seriously, but shows no mercy to her enemies. No one has ever seen her without her handcuffs.",
  str_item_intro_1600641 = "An ambitious Illumina Federation Guard Legion Commander who made an upright challenge for the leadership of the Illumina Federation. She is energetic, toils tirelessly to gain greater power, and has a strong desire to monopolize things.",
  str_item_intro_1600891 = "The Lumo Hall of Justice Chief Judge. She is both kind and gentle and upright and tough and has the spirit of self-dedication. A paranoid side of her exists in her heart, but she suppresses it.",
  str_item_intro_1601031 = "An interrogator from the True Order and ardent follower of Victoria, with pupils suppressed due to their \"Power of Doom.\"",
  str_item_intro_1500871 = "One of the militant nobles in Lumopolis, enjoying great prestige and power. Traditionalist and very responsible, but somewhat arrogant—though she's slowly improving.",
  str_item_intro_1401011 = "An Illumina officer responsible for communications. She treats her work with the utmost diligence and respect, despite the occasional pranks she plays.",
  str_item_intro_1401021 = "An ally of the Spearows in Umbraton, she's a free-spirit known for her lollipops and the electricity shooting from her hands.",
  str_item_intro_1500991 = "A wandering merc in Umbraton. Born with a curse that made her anemic, and must depend on her magic sword to survive.",
  str_item_intro_1501001 = "A True Order member. Born into an ancient noble family, she was chosen to guard the secret catacomb at a very young age. Well educated, she's intellectual but cold.",
  str_item_intro_1600931 = "An Illumina research officer in charge of life sciences. Seemingly a loafer and a slacker, she reveals a composed side during pivotal moments.",
  str_item_intro_1500981 = "Devoid of emotions due to a curse, but will seemingly trust the very first person she sees in a day. Now living in seclusion in Umbraton, working as an assassin for Istvan.",
  str_item_intro_1400621 = "A forest keeper from Northland. A handsome young man with aloof demeanors but a heart of gold, who yearns for friendship. Still relatively young, he looks somewhat boyish.",
  str_item_intro_1400951 = "Born with an animal body, she's a wandering mercenary who rants about everything.",
  str_item_intro_1300941 = "An innocent, kind, and naive patroller from Northland. She is used to patrolling alone in the cold, and brings spring and hope to the people.",
  str_item_intro_1600961 = "Born in Illumina, she wandered to Umbraton in search of her grandfather. She is rather absentminded and often deceived.",
  str_item_intro_1500971 = "An assassin in Umbraton who performs \"special\" tasks for Istvan. Before this, he was a skilled surgeon.",
  str_item_intro_1500561 = "A solitary Eclipsite hunter wandering Astra with a clear mind. He carries a hunting rifle and a notebook wherever he goes, ready to both hunt down Eclipsites and note the exploits in writing.",
  str_item_intro_1701071 = "Banished ancient hero. Transformed due to hatred for Eclipsites. Once a ferocious savage, but has regained calm and positive personality.",
  str_item_intro_1701081 = "Banished ancient hero. Transformed and gained great power, but caused a disaster from not being able to control it, and still wallows in guilt to this day.",
  str_item_intro_1701091 = "Banished ancient hero. Lost most of her emotions after getting transformed. Allegedly abandoned by the state she served after completing a mission.",
  str_item_intro_1701101 = "Banished ancient hero. Fighting Eclipsites at the frontline since childhood. A willful motormouth. Transformed but kept innocence.",
  str_item_intro_1501041 = "Dark powers caused her to lose sight in both eyes. Aloof and reserved on the surface, she's straightforward once she gets to know someone.",
  str_item_intro_1601051 = "Sinsa's younger sister who fell under Eclipsite influence and lost control as a child. She has regained her innocence after being healed.",
  str_item_intro_1500711 = "The proprietor of Odd Jobs who traveled from the Far East, eventually settling in Umbraton. An ally of Istvan, he's a standoffish nonconformist who does things with the utmost efficiency.",
  str_item_intro_1400671 = "A young, partially demi-human girl from Northland with black and white hair. Naive, playful, somewhat stubborn, very curious about her surroundings. Now traveling the world with two magic dolls.",
  str_item_intro_1601111 = "A member of the True Order who can control the powerful Crystal Domain to trap her enemies. However, her sanguineous crystals also take a significant toll on her mind, rendering her distant, silent, and often pessimistic.",
  str_item_intro_1601121 = "A free agent who lives in Umbraton and possesses great power over fire. Wild and direct, she enjoys pursuing new and exciting things.",
  str_item_intro_1501131 = "A musician and member of the True Order, although she appears warm and adorable on the outside, she would do anything to achieve her goal of finding the ultimate movement. She is very confident in her sense of musical understanding and despises the musical practices of Lumopolis.",
  str_item_intro_1501141 = "Although she appears to be no more than a bounty hunter, she is actually a member of the True Order. Elegant and always in a good mood, she is very fond of drinking gins and is currently trying to build an intelligence network for the True Order while trying to track down the whereabouts of a certain individual.",
  str_item_intro_1601151 = "A member of the Courier Union who specializes in serving the Lumopolis region. Quiet and elegant, she possesses the mysterious power to communicate with animals and plants, and is followed by several animals and countless fireflies wherever she goes.",
  str_item_intro_1601161 = "A good-tempered Rediesel Wrench technician who just doesn't know how to say no—a personality trait that often lands him in all manner of vexing predicaments. He is a master of repairing all kinds of machinery, but also strives to build a mecha of his own.",
  str_item_intro_1401271 = "Once an inhabitant of the Rediesel Desert, she later joined the True Order. Her abilities involve controlling magical scraps of paper to attack in battle. Though she usually comes across as being quite timid, her belief in the existence of the soul can be considered borderline fanatical.",
  str_item_intro_1601191 = "A new Illumina recruit. A genius in combat, but aloof, impulsive, and a poor communicator. She is eager to earn glory in battle and prove herself.",
  str_item_intro_1601221 = "A sniper-for-hire from Umbraton with exemplary shooting skills. Meticulous and budget-conscious, she is an avid antique collector and wishes to open her antique shop after procuring enough funds.",
  str_item_intro_1601171 = "A veteran who was once active on Illumina defensive line, who has now retired from the battlefield and serves the federation as a logistics officer. He may be a little rough around the edges, but his coarse exterior hides a noble and sentimental heart. One of the most reliable comrades you could hope for. They say that he sunk into depression due to his bloody past. Now, he emerged from the darkness of defeat, even stronger than he was before.",
  str_item_intro_1601211 = "A member of the True Order who is rebellious, rational, and takes nonsense from no one. She was originally a nun of the Lumopolis Temple, but after a tragic injustice changed her life, she became aware of the hypocrisy prevalent in Lumopolis, and left. She has devoted herself to exposing the city's true colors ever since.",
  str_item_intro_1300651 = "A member of the Courier Union in charge of Northland deliveries. An energetic, somewhat clumsy courier, her appearance and unique accent make her seem cute and innocent.",
  str_item_intro_1500551 = "A judge of the Lumo Hall of Justice, he is rather strait-laced, pragmatic, and resolute in his conviction. Now, in the name of justice, he is digging deeper into past cases to uncover a hidden truth.",
  str_item_intro_1601261 = "The head of Umbraton Guild Headquarters and Istvan's adopted daughter, she is his most trusted right hand. With her serious, stoic demeanor, she has a professional manner at all times.",
  str_item_intro_1601291 = "Deputy Commander of an Umbraton mercenary squad, and a man of honor who knows all that goes on in the town. He is now working hard to expand his mercenary forces.",
  str_item_intro_1602371 = "Rumored to be a descendant of the Mirage clan, she has a hard time retaining memories, yet remains optimistic and kind-hearted. Out of gratitude for being taken in by Harbor City, she is committed to helping others.",
  str_item_intro_1602381 = "Mithra, born into the Longinus clan, upholds a millennia-old duty to protect the secrets of the stars. Despite her quiet exterior and dark plumage, she conceals a sharp edge beneath her reserved nature.",
  str_item_intro_1702361 = "Claymore was the king's right hand man and the captain of the Silent Hunters. He upholds justice with unwavering will. Even without Lumina's favor, he forges a future with Star Power.",
  str_item_get_discovery = "{0}",
