  str_item_get_cloudgardensitem40 = "Made in the Hyacinth Tower after obtaining the blueprint in randomly-generated secret conversations when Aurorians are living quite comfortably in Cloud Gardens.",
  str_item_get_cloudgardensitem41 = "From the Winds in the Harbor event.",
