  str_item_get_cloudgardensitem43 = "Obtained from the Drift Box.",
  str_item_get_cloudgardensitem44 = "It'll appear with a Drift Box if you're lucky.",
  str_item_get_cloudgardensitem45 = "Obtained via fishing when Lumina is nearby.",
  str_item_get_cloudgardensitem46 = "Find clues about Special Fishing Points from Ms. Blanc in Cloud Gardens and obtain them by fishing in those spots.",
  str_item_get_cloudgardensitem47 = "Obtain at Cloud Gardens Branch",
  str_item_get_cloudgardensitem48 = "Made at the Hyacinth Tower after obtaining the blueprint from the Cloud Gardens Branch.",
