  str_item_get_cloudgardensitem50 = "Purchase the Special Event Book: Phase 10 Deluxe Edition to unlock.",
  str_item_get_cloudgardensitem51 = "Find clues about the Special Fishing Points from Angel in Cloud Gardens, and obtain them by fishing in those spots.",
  str_item_get_cloudgardensitem52 = "Obtained through Unique Tree Alteration",
  str_item_get_cloudgardensitem53 = "Find clues about Special Fishing Points from Korgon in Cloud Gardens and obtain them by fishing in those spots.",
  str_item_get_cloudgardensitem54 = "Purchase the Special Event Book: Phase 11 Deluxe Edition to unlock.",
  str_item_get_cloudgardensitem55 = "Obtained from the Under the Spotlight event",
  str_item_get_cloudgardensitem56 = "Obtained by defeating Carleen for the first time in a daily fishing battle",
  str_item_get_cloudgardensitem57 = "Find clues about Special Fishing Points from Dove in Cloud Gardens, then obtain these by fishing in those spots.",
  str_item_get_cloudgardensitem58 = "Find clues about Special Fishing Points from Eho in Cloud Gardens, then obtain these by fishing in those spots.",
