  str_item_5234040 = "\"Rediesel Foodfest\"",
  str_item_5234041 = "\"Into the Haunted House\"",
  str_item_5234042 = "\"Splendor Illumina!\"",
  str_item_5234031 = "Thorny Beast Statue",
  str_item_5234032 = "Three-Horned Beast Statue",
  str_item_5241014 = "Colorful Hot Air Balloon",
  str_item_5232007 = "Floating Shell Seat",
  str_item_5234035 = "Monument of Lines",
  str_item_5222001 = "Low Shrub Fence",
  str_item_5222002 = "High Shrub Fence",
  str_item_intro_5212001 = [[
"Now that I've sunken this ship, you're the next to go! Argh! Why are you sliding down my tentacle? Fine, I'll let you off this time since you look like you're having lots of fun!"
Supposedly, this slide was modeled after the tentacle of a sea monster. Exciting, isn't it?]],
  str_item_intro_5212002 = "I wonder who moved a ship's mast here. Either way, you'll be able to see very far into the distance if you climb up it. You can even shout out: \"Cap'n! Land ahoy!\" as if you're sailing out at sea.",
  str_item_intro_5212003 = "A light tent that stands stably on the soft sand of the beach. It is even made out of fireproof materials, probably because tourists like to start fires in tents for fun.",
  str_item_intro_5212004 = "This swing that is wide enough for two people to swing side by side is great for playing on the coast. You'll have fond memories of the soft sea breeze caressing your face while you sit on it.",
  str_item_intro_5212005 = "This sun lounger is made out of half of an abandoned boat. It looks like the whimsical creation of some sailors.",
  str_item_intro_5212006 = "A signpost for the beach. You can draw various patterns on it or leave messages on it, and many colorful flags can be tied to the stand to attract tourists' attention.",
  str_item_intro_5212007 = "In the spirit of recycling, some sailors disassembled half of a boat and used its boards to make a table and chairs. The keel was used to make a unique vine frame to provide shade from the sun.",
  str_item_intro_5212008 = "A slightly heavy umbrella that is difficult to carry around. The butt of its handle is pointed so that it can be stabbed into the ground and secured firmly there.",
  str_item_intro_5212009 = "This chair is designed to hug the body, making it very comfortable to lie on with lots of space to stretch your arms and legs satisfyingly.",
  str_item_intro_5212010 = "A light, handy table that tourists can move around freely so they can easily find a good spot on the beach for a good time with their friends.",
  str_item_intro_5212011 = "This chair will come in handy when you need a break from all your play! Sit on it and have a drink to recover your energy quickly.",
  str_item_intro_5212012 = "Huh? Aren't these stone pillars from beneath the sea? And coral? When was this brought onshore? Upon closer inspection, one can see that this is actually a skillfully made painted wooden fence. It is beautiful and emits a wonderful sea atmosphere.",
  str_item_intro_5212013 = "The fine sand paved in this area creates a strong seaside atmosphere that makes it seem like you're at the beach.",
  str_item_intro_5241018 = "There are miniature rocks and aquatic plants in this giant case, as well as a device that keeps the water circulating, creating an environment in which fish can swim safely.",
  str_item_intro_5241019 = "When looking at this colorful coral ornament atop its stone base, it almost feels like you're in the ocean and can see shoals of fishes swimming by...",
  str_item_intro_5241020 = "A relic from a mysterious ancient ruin. It is said to absorb the surrounding Lumina and emit harmless light, which makes it an ideal option for decoration, lighting, or sending signals to the distance.",
  str_item_intro_5212014 = "What a huge shell! It looks so big that it doesn't seem to be naturally occurring. If there'd been a pearl inside it, it definitely would've been a rare treasure. It may be a shell, but it was fitted with padding on the inside, making it a wonderful sofa.",
  str_item_intro_5212015 = "When this jellyfish-shaped balloon floats into the sky, its drooping ribbons become its \"tentacles,\" making it look like a real jellyfish floating in the sky.",
  str_item_intro_5212016 = "Don't let its appearance scare you! It just wants to light the way for you. See? There are no teeth inside its mouth.",
  str_item_intro_5212027 = "A high stool that perfectly complements longer tables. The adjustable height and swivel seat make it a favorite of many children.",
  str_item_intro_5212028 = "An indispensable green pot that complements other festive decorations.",
  str_item_intro_5212029 = "A specially painted row of fences used for partitioning during festivals. Feel free to put other decorations on it!",
  str_item_intro_5212030 = "A nursery specifically set up for the Windelion Festival, with matured dandelions just waiting to be released on the night of festivity.",
  str_item_intro_5212031 = "The structure might be simple and built with common wood, but it is durable due to reinforced parts. Other than being used for hanging lights, it can also act as a temporary shelter for small animals.",
  str_item_intro_5212032 = "Line these festive low columns up, and you get a fence.",
  str_item_intro_5234034 = "The stonework exterior seems somewhat crude, but the interior is extremely intricate, with a large space. Just open the lid to recycle the garbage inside easily.",
  str_item_intro_5212020 = "Perfect for the roadside. Passersby can place small items on it or modify it to their liking and turn it into a landmark.",
  str_item_intro_5212021 = "It looks big, but it is made of wood and hollow inside. Very light and can be moved quickly between locations, used mostly as secondary holiday decorations.",
  str_item_intro_5212022 = "Simple wooden pole with an apparently reinforced interior for many small animals to perch on. Probably good for others to lean on too, probably...",
  str_item_intro_5212023 = "Lightweight, with a special build to handle multiple lanterns at once. Used for illumination or as a statement piece in festivals.",
  str_item_intro_5212024 = "Composed of wooden poles and white fabric decorated with various vines, green leaves, and flowers. Mostly used in various festivals. It brings good luck if the curtain brushes you, or if the breeze blows a petal or leaf onto your shoulder.",
  str_item_intro_5212025 = "It's unknown who built the first nest for the festival, but it drew a lot of small animals. This then became an informal tradition for people in subsequent festivals. Rumor has it that the more small animals one attracts, the more blessings its builder shall receive.",
  str_item_intro_5212026 = "This table is somewhat heavy because it is made of solid wood with stone supports, supposedly to prevent it from collapsing should one choose to dance on it.",
  str_item_intro_5234021 = "It can be placed not only in a room but also in the cabinet in the suburbs. The wood is solid enough to withstand the sun and rain. It usually serves as temporary storage for objects currently not in use.",
  str_item_intro_5212018 = "Dangling colorful Windelion Doll popular with children during the Windelion Festival. Contained confetti that spills out after being knocked open. Bells or \"lucky coins\" are sometimes put inside to attract more kids.",
  str_item_intro_5212019 = "A giant drum big enough to allow for people to dance on it. The surface is thin, but strong enough not to break if you jump on it! Due to its special construction, its sound can be heard from very far away. The drum is also sensitive enough to respond to changes in the way people stamp on it and produce different sounds.",
  str_item_intro_5241021 = "Scaled beasts are not common, and the legendary Pangalo are even more rare! Hurry up and take a photo! You can pretend to be one of them yourself!",
  str_item_intro_1601881 = "Born a princess of the Ye Kingdom, Dantang is now held hostage in the Ji Kingdom. But she still maintains a serene demeanor as she immerses herself in studies, quietly waiting for a chance to return to her homeland.",
  str_item_intro_5212017 = "The specific purpose of this stone statue is unknown, but it is said to be a relic from ancient times. Many Caelestites would come for blessings and to make wishes during the Windelion Festival. It is said that the candles would listen and pass the wishes on to the statue so that it could help with its mysterious power.",
  str_item_intro_5271001 = "A massive swimming pool that occupies a large space and has a large capacity. The more, the merrier.",
  str_item_intro_5272001 = "A small cubicle with shower facilities, commonly found at swimming pools. It is used to clean the body and, more importantly, change clothes.",
  str_item_intro_5272002 = "Swimming is very tiring, so you should take a break if you get too tired. Why not experience the divine joy of getting an ice cream from this amazing automatic ice cream machine?",
  str_item_intro_5272003 = "Music is essential! It's easy to get bored playing in the water, so come hang out here to chill and dance to some tunes!",
  str_item_intro_5272004 = "This inflatable sofa is very comfortable to lie on. It becomes a small boat when placed in the water, and making it an excellent choice for both lounging and staying afloat.",
  str_item_intro_5272005 = "As it is inflated, this chair is extremely light. It can be carried around everywhere and even placed in your backpack after it is deflated, where it occupies almost no space.",
  str_item_intro_5272006 = "This is a blessing to all those who can't swim! Even landlubbers can float on the water and make some attempts to swim with this.",
  str_item_intro_5272007 = "A toy that works both outside a pool and inside one. When it's fully inflated, it can be treated as a bouncy ball. But the most important thing is that it doesn't sink in the water!",
  str_item_intro_5272008 = "Swimming is an extremely exhausting exercise, so lie down on this to recover your strength if necessary. This fish-shaped pillow is particularly comfortable and has strong beachy vibes.",
  str_item_intro_5272009 = "This umbrella is slightly large and inconvenient to carry around, but it is undoubtedly worth it to have one because it creates precious shade that protects you from direct sunlight when it's hot out.",
  str_item_intro_5272010 = "A decoration adorned with various shells from the ocean. If placed in the right place, it makes one feel like they're at the beach.",
  str_item_intro_5272011 = "Starfish are so popular that just a few of these ornaments is enough to attract the eyes of many.",
  str_item_intro_5272012 = "A display board that supposedly uses ancient technology to showcase different images automatically! There also seems to be a mysterious device that can be used to change the content displayed on it. It must've been used for something important...",
  str_item_intro_5271002 = "Designed by a certain Caelestite who loves the ocean. There are matching statues that supposedly bring the ocean's blessings! If you want to travel by sea, come here for a while. Maybe it'll be helpful!",
  str_item_intro_5272013 = "Seeing it in the ocean means your voyage will be bountiful! But do these creatures really exist? Or are they just a sailor's fantasy? In any case, at least this statue is beautiful and will catch the eyes of the youth.",
  str_item_intro_5272014 = "Out at sea, some lost octopuses climb onto ships by mistake and cannot return to the waters. When kind-hearted sailors release them, they often come back a few days later to give them a small gift, such as small pearls or coins that have been lost in the seas. This statue represents friendship and giving.",
  str_item_intro_5272015 = "Many people say that seeing jumping dolphins while sailing means that your voyage will be safe. I wonder if they bless those who travel on the land?",
  str_item_intro_5271003 = "With the right props, equipment, and camera angle, a director's artistic visions of even the most incredible places can become reality. From perilous dungeons to whimsical wonderlands, the greatest stories are realized before masterfully-crafted backdrops.",
  str_item_intro_5273001 = "Though it is only a backdrop, it still reflects the opulent magnificence of a royal palace when captured on film. Perfect for shooting period dramas that take place in the courts of rulers.",
  str_item_intro_5273002 = "At first glance, it looks like an expertly-crafted stone floor, but in reality, it's nothing more than a sheet of paper! As a prop-style \"floor,\" it can be switched out relatively quickly.",
  str_item_intro_5273003 = "Despite being a prop, this \"magic mirror\" is actually quite heavy (given that it is made of iron). Naturally, the gold plating and gemstones are fake, but the mirror does possess one peculiar property: its surface does not reflect anything! But how could this be? Perhaps it really is a magic mirror!",
  str_item_intro_5273004 = "A simple prop, and nothing more. After all, we can't transport a real glimmer tree from Northland; this is just a prop made of wood, paper, and ribbons and should never be gifted to Northlanders.",
  str_item_intro_5273005 = "A hardwood hanger in name only, it is actually made of cheap plywood. An acceptable substitute, given that it rarely holds clothes of any kind.",
  str_item_intro_5273006 = "A clay figure covered in a layer of pure-white sand. At first glance, it looks just like a real snowman, only this one holds its shape under the heat of the stage lights.",
  str_item_intro_5273007 = "A high-quality wooden prop created by skilled craftsmen. It looks no different than a real stone statue. Its light construction also makes it easy to move about the set.",
  str_item_intro_5273008 = "An old but genuine stuffed toy that has been washed and dried. Despite some parts of it appearing quite old and worn-out, from certain angles, one could still say it looks rather new.",
  str_item_intro_5273009 = "I-It floats! It actually floats! Is this really just a prop, or something more terrifying? Anyway, how it manages to float is unclear, but does a movie really need something so scary?",
  str_item_intro_5273010 = "Though it is only a backdrop attached to a wall, it still manages to fill people with a sense of dread. Could it be the shockingly-realistic painting style, or is the cabin in the backdrop just that scary? In any case, maybe the actors who perform in front of it aren't just acting when they scream.",
  str_item_intro_5273011 = "A floor prop used in conjunction with the haunted cabin backdrop. It seems to give off the musty smell of rotten floorboards when unrolled. Perfect for many horror films.",
  str_item_intro_5273012 = "An ancient grimoire replica that has been intentionally designed to look old, complete with written text and everything! To maintain an air of realism, each page contains the exact same text as the original in the exact same format; even the covers are carbon copies of one another! They look like part of a set. Nevertheless, the contents remain a mystery.",
  str_item_intro_5273013 = "A prop designed to float in mid-air. Perhaps it houses a balloon to keep it airborne? It is fastened to the floor with a wire to prevent it from drifting away.",
  str_item_intro_5273014 = "A slightly-used and unaltered toy that is utilized as a prop in various movies. It would usually provide joy and entertainment for children, but when used in horror films... it has quite the opposite effect.",
  str_item_intro_5273015 = "From the tombstone to the dirt mound it sits on, all of it is made entirely out of wood and paper. Light and portable, it can be produced in large quantities very quickly and adds a gloomy, haunted vibe to any scene.",
  str_item_intro_5273016 = "Prop voice transmitters, usually made of wood or metal, are completely useless for communicating through. When you watch a horror film and see a scene with a voice transmitter, it's usually the actor acting the character at both ends of the device themselves! Which must be exhausting.",
  str_item_intro_5273017 = "The ghostly mask portion of the cloak is perfect for horror films, but the hat... It looks like something people in the desert would wear. Perhaps this prop is trying to branch out into different roles as well?",
  str_item_intro_5273018 = "The pot and soil are real, but the flowers are not; they're made using dyed fabrics. Cheap and easy to make, these vibrant \"plants\" will never wither.",
  str_item_intro_5273019 = "When properly arranged, one can almost smell the aroma of fine wine or hear the clinking of glasses over soft music. Who knows how many famous scenes have been filmed in \"bars\" like this?",
  str_item_intro_5273020 = "The wooden floorboards appear much older than they actually are, and the holes only add to the effect. Its shabby appearance is actually quite suitable for bar settings.",
  str_item_intro_5273021 = "Perhaps one of the most expensive props (given that it is entirely real). It produces wonderful music when a record is placed on it. Due to its high price, screenwriters are often asked to avoid writing scenes that involve damaging the record player in any way. This restricts creativity slightly, but at least it can be used for lip-syncing in case an actor has a terrible singing voice! That's two birds with one stone!",
  str_item_intro_5273022 = "A bar counter made of plywood. Sturdy and reliable, but could never compare to a solid-wood counter in a real bar. The chairs, however, were bought from a real bar! And with a coat or two of fresh paint, they look good as new!",
  str_item_intro_5273023 = "Tables and chairs accentuate a bar's atmosphere. From their design to their adornments, anyone would agree that they belong in a bar. Just the sight of these props would tell actors that the upcoming scene takes place in a bar, all without any prompting from the director.",
  str_item_intro_5273024 = "Apparently some directors borrow furniture like this to film certain unconventional scenes. While this would be perfectly normal for the set of an office, is it really suitable for a bar set? It's almost as if it was borrowed from another studio due to a lack of funding...",
  str_item_intro_5273025 = "Real pianos are way too heavy, and often well outside of a studio's budget, so it's best to make do with a convincing prop! Besides, given the skill level of today's newest actors, there is little need to provide them with an actual piano...",
  str_item_intro_5273026 = "A hastily-constructed wooden stage. While not as sturdy as a real stage, it requires very little effort to build, and can be reconstructed quickly in the event that it breaks.",
  str_item_intro_5273027 = "This wooden blade rack is real, but the blades on it... are nothing more than props. Using them should be quite safe, considering they have no sharp edges; as such, they can be wielded in fight scenes without causing serious injury to the actors involved.",
  str_item_intro_5273028 = [[
In the sun-filled room, the desks and chairs are neatly arranged, and you can almost smell the scent of chalk.
This seat by the window in the second to the last row must be prepared for you.]],
  str_item_intro_5273029 = "A very common wooden floor that has been specially treated to make it more durable. Please change into indoor shoes before walking on it.",
  str_item_intro_5273030 = "The strange-looking cooking machine is also a gashapon machine. It's hard to tell what's inside until you open the item that falls out of it.",
  str_item_intro_5273031 = "A mysterious cooking device that is healthier than deep-frying. Even those who have never cooked before can use it easily.",
  str_item_intro_5273032 = [[
Bubbles keep rising inside it, and it is necessary to keep stirring it all the time to fully integrate the ingredients inside.
Who wouldn't love to have a beautiful girl do this job?]],
  str_item_intro_5273033 = "A barrel containing a mysterious liquid that exudes a faint ominous odor.",
  str_item_intro_5273034 = "A machine that works day and night to supply food and drinks, the savior of all lazy people.",
  str_item_intro_5273035 = "It takes a lot of skill to play this instrument, but it keeps making noise at night even if there's nobody there.",
  str_item_intro_5273036 = "This is just a prop. Don't eat it!",
  str_item_intro_5273037 = "An inn full of life, noise, and people of all sorts. Nobody knows who is there or what will happen there.",
  str_item_intro_5273038 = "A wooden floor that creaks when it is stepped on.",
  str_item_intro_5273039 = "The counter on which the cash register is placed in the inn. The boss always sits here, so you can come and chat with the boss if you feel lonely.",
  str_item_intro_5273040 = "An exquisite porcelain plate. It can be seen that the boss has good taste in decorations.",
  str_item_intro_5273041 = "A strange ornament. Maybe one of the guests gave it to the inn.",
  str_item_intro_5273042 = "Judging from the size of this specimen made from fish bones, this fish must have been very mighty when it was alive.",
  str_item_intro_5273043 = "A piece of crudely made wooden furniture. The furniture is always the first to suffer when there's a guest with a bad temper, so don't buy anything too expensive.",
  str_item_intro_5273044 = "Familiar tables and chairs that make you feel like you're at home.",
  str_item_intro_5273045 = "This furniture looks very warm and comfy. It must feel so good to lie inside this for the whole day in winter.",
  str_item_intro_5273046 = "The wine brewed by the boss releases a strong aroma when the lid is opened. Those who inhale it often fall into a trance and start crying over the things they regret in their lives.",
  str_item_intro_5273047 = "A souvenir from somewhere that gives the store an exotic feeling. Maybe some people will wonder if there are any memorable stories between the old boss and this grail from another land.",
  str_item_intro_5273049 = "Crows caw constantly in the rustling wind and the somber environment. The heroic warrior who walks alone here is destined to embark on a dangerous journey.",
  str_item_intro_5273050 = "There are many nameless places like this in troubled times. While sneaking about here, try not to crack the withered branches under your feet or leave traces of yourself.",
  str_item_intro_5273051 = "This looks like an ordinary cabinet no matter how you look at it, but a precious sword will pop out immediately once the mechanism is triggered. Please operate this under the supervision of an expert.",
  str_item_intro_5273052 = "A decorative sheet with reed patterns on it. If this is used to decorate a set, people will have the urge to gallop freely in it on horseback.",
  str_item_intro_5273053 = "A decorative sheet that creates the image of a wheat field. If this is used to decorate a set, will a samurai ambush people in it?",
  str_item_intro_5273054 = "A decorative sheet that has sunflower patterns on it. If this is used to decorate a set, maybe it'll even attract sunlight to it.",
  str_item_intro_5273055 = "A video player of mysterious origin that has an ancient-looking cloth under it. It seems that it will display some key information if a videotape is inserted into it.",
  str_item_intro_5273056 = "A map of mysterious origin. It looks like a military map used during times of war, and it seems to contain some key information.",
  str_item_intro_5273057 = "A mailbox of mysterious origin. No one knows how long it has been here. If you look closely at the scratches on the mailbox, you might see some key information left behind by people in the past.",
  str_item_intro_5234040 = "Rediesel Wrench's slick salesman Jomu has even posted advertisements here, of all places. They appear to be inviting everyone to participate in something called the \"Rediesel Foodfest,\" and claim that there are plenty of great deals to take advantage of. Although it's in the middle of the desert... Hopefully, the food won't be too exotic, right?",
  str_item_intro_5234041 = "Apparently a \"Stunning Debut Film by History's Youngest and Most Beautiful Genius Producer/Director/Actress/Camera Operator.\" It's supposed to be both hilarious and horrifying, which one can deduce from the billboard. How will it do at the box office? We'll just have to wait and see!",
  str_item_intro_5234042 = "A recruitment advertisement for the Illumina Federation. It exudes Illumina's opulence. \"The strongest and final line of defense. Stand with us in our struggle against the Eclipsite scourge!\" it says. Many people must have been spurred into action by this passionate call to arms.",
  str_item_intro_5234031 = "An animal that has spikes on its head and seems to be very irritable. Fortunately, it is just a sculpture.",
  str_item_intro_5234032 = "It looks very gentle even though it has long horns... For some reason, it makes you want to pet it.",
  str_item_intro_5241014 = "What happened here? How did it get so bloated? Even so, it can still fly and enable its users to experience the feeling of soaring in the sky.",
  str_item_intro_5232007 = "This stone seat's technology works in mysterious ways. It floats up after you sit on it, and even balances itself. Don't be afraid, try it out!",
  str_item_intro_5234035 = "The repetitive, methodical carvings on this ancient monument form wonderful patterns that are said to represent mathematical principles of some sort, but the exact details are unknown.",
  str_item_intro_5222001 = "Easy-to-grow shrubs that have been grown together to form a low wall. It serves a decorative purpose and can also be used as a partition.",
  str_item_intro_5222002 = "A wall formed from densely planted tall shrubs. It is usually used as an external wall in courtyards. It is said that many tall shrubs are planted together in some places to form a plant labyrinth.",
  str_item_condition_103 = "Unlocks after primary exploration of Undercity π",
