  str_item_3661026 = "Holiday Roast Turkey",
  str_item_intro_3661026 = [[
Furniture item. Can be placed in rooms on your Colossus.
Holidays are for feasting! This roast turkey is worthy of being the star of the day in terms of both appearance and taste. What are you waiting for?]],
  str_item_3661181 = "Colossus Clock",
  str_item_intro_3661181 = [[
Furniture item. Can be placed in rooms on your Colossus.
This wall clock was originally in the shape of an owl, but a certain merchant changed it to a Colossus instead because they thought it was too ordinary. It looks surprisingly good, but it's a shame its wings don't move.]],
  str_item_3661182 = "Metal Spoon Knight",
  str_item_intro_3661182 = [[
Furniture item. Can be placed in rooms on your Colossus.
Take this! Spoon attack! The Metal Spoon Knight is famous for being a glutton. Its belly is so big that even its armor must be custom-made! Look at the drool dripping from its mouth. Has it set its sights on someone's food?]],
  str_item_3661027 = "Goldie Fan Banner",
  str_item_intro_3661027 = [[
Furniture item. Can be placed in rooms on your Colossus.
Come give your all for Goldie! Let her music spread to every corner of the continent!]],
  str_item_3000289 = "Talent Mastery EXP",
  str_item_3000290 = "Talent Mastery Point",
  str_item_3661183 = "DJ Booth",
  str_item_intro_3661183 = [[
Furniture item. Can be placed in rooms on your Colossus.
A DJ booth with a built-in speaker system, featuring an array of buttons that allow its operator to make almost infinite sounds. With its constantly changing rhythms, it only takes one DJ to fuel the party atmosphere and immerse the crowd in mesmerizing music.]],
  str_item_3661184 = "Dream Girl Poster",
  str_item_intro_3661184 = "Furniture item. Can be placed in rooms on your Colossus.\nFollow your dreams! You too, can be like her—a girl who commands the stage, spreading love and hope to the whole continent! Never give up your dreams!",
  str_item_3661185 = "Tourdog Figurine",
  str_item_intro_3661185 = [[
Furniture item. Can be placed in rooms on your Colossus.
Always stand at the forefront of Umbraton's latest trends! Even as a figurine, Tourdog displays his visionary aesthetics at all times. Rumor has it that this figure is very popular among his followers, so make sure they don't get their hands on it!]],
  str_item_3661186 = "Mega Blaster",
  str_item_intro_3661186 = [[
Furniture item. Can be placed in rooms on your Colossus.
It is said that only the bravest dare to play this powerful musical instrument, as the sound it generates is strong enough to overwhelm a weak individual's frail constitution. Although it makes an awful racket, it is perfect for stunning crowds at jam-packed concerts.]],
  str_item_5259309 = "Potential Pendant",
  str_item_5259310 = "Hexing Stone",
  str_item_5259311 = "Mysterious Locked Box",
  str_item_5259410 = "Chaos Blade",
  str_item_5259411 = "Berserker Gauntlets",
  str_item_5259412 = "Bond Statue",
  str_item_5259505 = "Energy Belt",
  str_item_5259506 = "Berserker Soul",
  str_item_5259507 = "Sword of Light",
  str_item_5259513 = "Berserker Armor",
  str_item_5259514 = "War Goddess Statue",
  str_item_intro_5259301 = "Increases Chain Combo Damage when connecting 15 tiles or more.",
  str_item_intro_5259302 = "When calculating damage, allies ignore the negative effects of having their element countered.",
  str_item_intro_5259303 = "Immediately deals additional damage when inflicting Poisoned/Burning/Bleeding on enemies.",
  str_item_intro_5259304 = "Permanently increases allies' Max HP.",
  str_item_intro_5259305 = "Whenever HP drops below 50%, an HP recovery item will be generated on the field.",
  str_item_intro_5259306 = "Recovers HP at the start of each wave.",
  str_item_intro_5259307 = "Grants a shield at the start of every wave.",
  str_item_intro_5259308 = "Deals high damage to non-boss enemies around you every round.",
  str_item_intro_5259309 = "Reduces the cooldown of Special Caelestite Gear by 1.",
  str_item_intro_5259310 = "All allies and enemies lose a proportion of their HP every round.",
  str_item_intro_5259311 = "Grants a random additional Special Caelestite Gear.",
  str_item_intro_5259401 = "Increases the damage debuffed enemies take.",
  str_item_intro_5259402 = "Converts a percentage of Aurorians' excess healing into a shield.",
  str_item_intro_5259403 = [[
Poisons all allies and enemies in the area when an enemy dies.
Reduces the Poison damage taken by allies.]],
  str_item_intro_5259404 = "Increases the damage of Chain Combos when affected by a debuff.",
  str_item_intro_5259405 = "Has an extremely low chance of instantly killing non-boss enemies.",
  str_item_intro_5259406 = "Restores the HP of allies when an Active Skill kills an enemy.",
  str_item_intro_5259407 = "Increases all damage of allies when at Max HP.",
  str_item_intro_5259408 = [[
Restores the HP of allies when an enemy's Poison damage is triggered.
Reduces the chance that allies will be Poisoned.]],
  str_item_intro_5259409 = "Reflects damage back at enemies when they deal damage to allies.",
  str_item_intro_5259410 = "Increases the damage of allies when there are at least 3 Aurorians with different primary elements in the team.",
  str_item_intro_5259411 = "Aurorians' secondary elements deal damage with no damage reduction.",
  str_item_intro_5259412 = [[
Captain change chances +5.
Reduces the Active Skill cooldown of Aurorians who become Captain for the first time in this round by 1.]],
  str_item_intro_5259501 = "The Captain unleashes an additional Chain Combo at the beginning of the line.",
  str_item_intro_5259502 = "Generates an explosion effect every 5 normal attacks.",
  str_item_intro_5259503 = "Generates a small number of chromatic tiles within 1 surrounding cluster every round.",
  str_item_intro_5259504 = "Instantly defeats enemies who are under 10% HP.",
  str_item_intro_5259505 = "Speeds up Active Skill cooldowns when standing still.",
  str_item_intro_5259506 = "Converts the DEF of all allied Aurorians into ATK.",
  str_item_intro_5259507 = "The first tile in a line can be a different color from the subsequent tiles. These two different elements will both trigger Aurorians to take action.",
  str_item_intro_5259508 = "Treats Green tiles as chromatic tiles.",
  str_item_intro_5259509 = "Treats Blue tiles as chromatic tiles.",
  str_item_intro_5259510 = "Treats Red tiles as chromatic tiles.",
  str_item_intro_5259511 = "Treats Yellow tiles as chromatic tiles.",
  str_item_intro_5259512 = "Greatly increases the damage of allies, but each connection generates broken tiles.",
  str_item_intro_5259513 = "Increases the damage of Chain Combos as allies' HP decreases.",
  str_item_intro_5259514 = [[
Captain change chances +5.
Aurorians who have been the Captain this round will attack with their primary element regardless of the color of the connection.]],
  str_item_rpintro_5259301 = "Increases Chain Combo damage by 30% when allies connect 15 or more tiles.",
  str_item_rpintro_5259302 = "When dealing damage, allies ignore the damage reduction effect of having their element countered. When taking damage, allies ignore the bonus of having their element countered.",
  str_item_rpintro_5259303 = "When inflicting Poisoned/Burning/Bleeding on enemies, the target instantly loses HP by 50% of their attack. Can be triggered once per round on each target.",
  str_item_rpintro_5259304 = "Increases the Max HP of Aurorians in the team by 100% without changing the current HP.",
  str_item_rpintro_5259305 = "When allies' HP drops below 50%, a Bandage, which recovers 20% of Max HP when allies pass through it, will be generated at a random place on the field.",
  str_item_rpintro_5259306 = "Recovers 20% of Max HP at the start of each wave.",
  str_item_rpintro_5259307 = "Grants a shield equal to 40% of Max HP that lasts for 1 round at the start of every wave.",
  str_item_rpintro_5259308 = "Deals damage equal to 50% of Max HP to all non-boss enemies within 1 surrounding cluster at the start of every wave.",
  str_item_rpintro_5259309 = "Reduces the cooldown of Special Caelestite Gear by 1 in subsequent battles.",
  str_item_rpintro_5259310 = "All allies and enemies (including bosses) lose 7% of their current HP at the start of every round.",
  str_item_rpintro_5259311 = "Grants a random Special Caelestite Gear that you don't already have. This can be used in subsequent battles, and its cooldown is calculated separately.",
  str_item_rpintro_5259401 = "All damage taken by enemies who are debuffed or under debuff effects increases by 20%.",
  str_item_rpintro_5259402 = "Converts 100% of Aurorians' excess healing into a shield that lasts for 1 round.",
  str_item_rpintro_5259403 = "Inflicts 1 stack of Poison on all allies and enemies in the field whenever an enemy dies. Allies take -50% Poison damage.",
  str_item_rpintro_5259404 = "Increases Chain Combo damage by 30% when your team is affected by debuffs.",
  str_item_rpintro_5259405 = "Non-boss enemies have a 3% chance to die instantly when taking any damage.",
  str_item_rpintro_5259406 = "Allies recover HP equal to 15% of the caster's Max HP whenever an enemy is killed by an Active Skill.",
  str_item_rpintro_5259407 = "Increases all damage dealt by 20% when your team is at Max HP.",
  str_item_rpintro_5259408 = "Whenever enemies take Poison damage, allies recover HP equal to 100% of this Poison damage. Allies take -50% Poison damage.",
  str_item_rpintro_5259409 = "Reflects 100% of damage taken back at enemies when they deal damage to allies.",
  str_item_rpintro_5259410 = "Increases all damage dealt by allies by 25% when there are at least 3 Aurorians with different primary elements in your team.",
  str_item_rpintro_5259411 = "Aurorians' secondary elements deal damage with the same multiplier as their primary elements.",
  str_item_rpintro_5259412 = [[
Captain changes chances +5 when obtaining this item.
When switching Captains, the Active Skill cooldown of the new Captain is reduced by 1. Each Aurorian can only trigger this effect once every round.]],
  str_item_rpintro_5259501 = "Generates an image of Captain Aurorian at the starting spot. This image also unleashes Chain Combos in this round.",
  str_item_rpintro_5259502 = "Generates an explosion that attacks enemies when the normal attack combo is a multiple of 5.",
  str_item_rpintro_5259503 = "Converts 3 tiles within 1 surrounding cluster into chromatic tiles at the start of every round.",
  str_item_rpintro_5259504 = "Enemies who have less than 10% HP remaining will be instantly defeated.",
  str_item_rpintro_5259505 = "Reduces the cooldown of all Aurorians' Active Skills that are on cooldown by 1 if no connections are made in this round.",
  str_item_rpintro_5259506 = "Reduces the DEF of all Aurorians in your team to 0 and increases your ATK by the total amount of DEF reduced.",
  str_item_rpintro_5259507 = "The first tile in a line can be a different color from the subsequent tiles. These two different elements will both trigger Aurorians to take action.",
  str_item_rpintro_5259508 = "When connecting other colors, Green tiles can also be connected.",
  str_item_rpintro_5259509 = "When connecting other colors, Blue tiles can also be connected.",
  str_item_rpintro_5259510 = "When connecting other colors, Red tiles can also be connected.",
  str_item_rpintro_5259511 = "When connecting other colors, Yellow tiles can also be connected.",
  str_item_rpintro_5259512 = "Increases all damage dealt by allies by 25%, but the starting point of each connection will become a broken tile that cannot be moved on for 5 rounds.",
  str_item_rpintro_5259513 = "Increases Chain Combo damage by up to 80% according to the percentage of HP lost by allies.",
  str_item_rpintro_5259514 = [[
Captain change chances +5.
Aurorians who have been the Captain this round will attack with their primary element regardless of the color of the connection.]],
  str_item_intro_9994027 = "Increases all damage dealt by allies by 25% when there are at least 3 Aurorians with different primary elements in your team.",
  str_item_intro_9994028 = "Aurorians' secondary elements deal damage with no damage reduction.",
  str_item_intro_9994029 = [[
Captain change chances +3.
Reduces the Active Skill cooldown of Aurorians who become Captain for the first time in this round by 1.]],
  str_item_intro_9995019 = "Reduces the Active Skill's cooldown by 1 with 2 taps while standing still.",
  str_item_intro_9995020 = "Reduces the DEF of all Aurorians in your team to 50% and increases ATK by the amount of DEF reduced.",
  str_item_intro_9995021 = "Increases Chain Combo damage by up to 80% according to the percentage of HP lost by allies.",
  str_item_intro_9995022 = [[
Captain change chances +3.
Aurorians who have been the Captain this round will attack with their primary element regardless of the color of the connection.]],
  str_item_rpintro_9994027 = "A weapon that seems to be able to fuse with Lumina perfectly... This is rare indeed...",
  str_item_rpintro_9994028 = "It is said that a certain ancient warrior was defeated in battle because he couldn't exert the full power of his non-dominant hand. After the defeat, he had these gauntlets specially made. Sure enough, he was invincible in his upcoming battles.",
  str_item_rpintro_9994029 = "Hands are connected to your heart. Therefore, it can be said that two people who are holding hands have a spiritual connection with each other and will never be separated from each other.",
  str_item_rpintro_9995019 = "The astonishing power in this ancient relic allows its wearer to cast all sorts of powerful Luminatics faster, granting the wielder the ability to deal with various dangerous situations.",
  str_item_rpintro_9995020 = "As the old saying goes, \"he who lives by the sword dies by the sword.\" Although this makes it possible to defeat extremely powerful enemies, the premise is that you fight bravely without regard for your own safety...",
  str_item_rpintro_9995021 = "According to some tales passed on by word of mouth, this armor possesses great and terrifying power, making it a treasure to some and a curse to others.",
  str_item_rpintro_9995022 = "Some say that this statue does not depict a god but a legendary female warrior who can provide support in battle.",
  str_item_3661187 = "Longzhou Blessing Knot",
  str_item_intro_3661187 = [[
Furniture item. Can be placed in rooms on your Colossus.
A rope that has been skillfully woven into a square knot, a testament to the creativity of the weaver. Allegedly from Longzhou, where people hang it in their homes to protect their family from harm.]],
  str_item_3661188 = "High Hanging Lantern",
  str_item_intro_3661188 = [[
Furniture item. Can be placed in rooms on your Colossus.
A lantern rack from Longzhou with a unique wooden structure, from which a red lantern hangs. It seems to have the power to put people in another world in an instant.]],
  str_item_3661028 = "Starry Ornaments",
  str_item_intro_3661028 = [[
Furniture item. Can be placed in rooms on your Colossus.
Stars and galactic elements strung together on a string. One can admire a glimpse of the universe when it's lit up. It can be placed on a wall or hung up on a tree outdoors to create the illusion of a starry sky on a cloudy day.]],
  str_item_3010001 = "Star Flare (Limited)",
