A device that sends recruiting signals to attract Aurorians' attention and call them to be your partners.
This is a limited-time item. It will disappear after expiration. Please use it in time. Expiration Time: 04:00 on 9 February 2023 (UTC +0), 23:00 on 8 February 2023 (UTC -5).]],
