  str_item_3000301 = "Ingredient Pack",
  str_item_intro_3000301 = [[
A pack filled with various piled-up ingredients.
Can be used to make food.]],
  str_item_3000302 = "Rare Feathers",
  str_item_intro_3000302 = "The feathers of a mysterious unknown bird. Because of their bright colors, they are cherished by certain members of the Courier Union. Maybe you can exchange them for something.",
  str_item_3661189 = "Candlelight Roses",
  str_item_intro_3661189 = [[
Furniture item. Can be placed in rooms on your Colossus.
May the flowers never wither and the candlelight never go out, so that the beauty of this moment will remain in your heart forever.]],
  str_item_3661190 = "Confession Mailbox",
  str_item_intro_3661190 = [[
Furniture item. Can be placed in rooms on your Colossus.
Afraid to spill the secrets of your heart? Does a secret lie within your soul? If so, this mailbox is for you. It is patient, safe, and reliable, making for an excellent confidant.]],
  str_item_3661191 = "Mooncrown Teddy",
  str_item_intro_3661191 = [[
Furniture item. Can be placed in rooms on your Colossus.
Who could turn down such a cute bear, especially one with a love heart! If someone gives you this gift, it's obvious how they feel about you.]],
  str_item_3661192 = "Mooncrown Bouquet",
  str_item_intro_3661192 = [[
Furniture item. Can be placed in rooms on your Colossus.
Red and white flowers are symbols of passionate love and a pure heart. When you give this bouquet to your beloved, it's time to say those three little words.]],
  str_item_3661029 = "Heart Loveseat",
  str_item_intro_3661029 = [[
Furniture item. Can be placed in rooms on your Colossus.
A spacious and comfortable loveseat suitable for couples to relax together. If you don't have anyone to sit with, that's okay too. The feeling of being wrapped up in a big soft cushion can also make you feel like you're not alone...]],
  str_item_3661193 = "Pure White Wings",
  str_item_intro_3661193 = [[
Furniture item. Can be placed in rooms on your Colossus.
As it is said that angels are the guardians of love, some hang these white wings on the wall in the hope that they will find their true love soon.]],
  str_item_3661194 = "Swan Cake Tower",
  str_item_intro_3661194 = [[
Furniture item. Can be placed in rooms on your Colossus.
A cake decorated with exquisite swans. It looks more like a work of art than food... Are you sure you want to eat it?]],
  str_item_3661030 = "Floating Star",
  str_item_intro_3661030 = [[
Furniture item. Can be placed in rooms on your Colossus.
This seems more suitable as a balloon that appears in an amusement park instead of a decoration at home, but it looks quite special at home too. However, it will probably fly around everywhere if you don't tie it to something.]],
  str_item_3000308 = "Case Record",
  str_item_intro_3000308 = "I've recorded some traits of the culprit. Let's see if they'll help us uncover the truth...",
  str_item_3661195 = "Classic Gramophone",
  str_item_intro_3661195 = [[
Furniture item. Can be placed in rooms on your Colossus.
A classic gramophone said to have been popular in Umbraton several decades ago, it is a common fixture in the homes of many wealthy business people. It seems to have been created by an artisan of that period or someone who made great efforts to research and design its timbre and decoration, which immerse members of the older generation in the music and zeitgeist of the past.]],
  str_item_3661196 = "Clue Board",
  str_item_intro_3661196 = [[
Furniture item. Can be placed in rooms on your Colossus.
Not only can this board be used to draw various mind maps for analyzing a case from all angles, it is also the perfect place to paste important clues and photos of witnesses. It also conveniently exhibits information collected from various sources, facilitating easy access, deduction, and summarization and allowing you to uncover the truth and the culprit quickly.]],
  str_item_3661197 = "Detective's Coffee Table",
  str_item_intro_3661197 = [[
Furniture item. Can be placed in rooms on your Colossus.
Originally used for drinking afternoon tea and playing cards, this coffee table is now piled with books and papers related to criminal cases, along with a magnifying glass, pipe, and lantern placed next to them. It appears the owner must be a detective or at least a detective enthusiast.]],
  str_item_3661198 = "Detective's Coat Rack",
  str_item_intro_3661198 = "Furniture item. Can be placed in rooms on your Colossus.\nWhen going out to conduct an investigation, it is important for one to look the part. The overcoat can withstand the cold night air and can hold many items used when sniffing for clues, such as notebooks, magnifying glasses, and small weapons for self-defense. And the hat, of course, is not only good for protecting one from the wind—it also makes the wearer look more like a detective.",
  str_item_3661031 = "Deductive Reasoning Sofa",
  str_item_intro_3661031 = [[
Furniture item. Can be placed in rooms on your Colossus.
They say that some detectives can infer the truth of a case by sitting on a sofa and drawing on various clues collected by others. It seems that this sofa not only provides relaxation but also enhances the power of one's mind.]],
  str_item_3661199 = "Pipe Rack",
  str_item_intro_3661199 = [[
Furniture item. Can be placed in rooms on your Colossus.
A rack full of pipes. Even if you don't like the smell of tobacco, these uniquely shaped pipes are worth collecting.]],
  str_item_3661200 = "Floor-Standing Binoculars",
  str_item_intro_3661200 = [[
Furniture item. Can be placed in rooms on your Colossus.
The greatest feature of these binoculars is its ability to let you see everything in the distant surroundings. Its lens is very clear, but its metal lens barrel makes it so heavy that it must be placed on a special tripod to keep it stable.]],
  str_item_3661032 = "Secure Safe",
  str_item_intro_3661032 = [[
Furniture item. Can be placed in rooms on your Colossus.
"This is the safest and strongest prison for your goods on this continent," said the merchant. Sure enough, the large lock handle looks strong, and its heavy case looks impervious to most damage.]],
  str_item_3661033 = "Champion's Duck",
  str_item_intro_3661033 = [[
Furniture item. Can be placed in rooms on your Colossus.
This duck Gronru designed is the prize for the winner of her game! Incredibly cute, its golden appearance symbolizes a champion's honor.]],
  str_item_3661207 = "Carpet of Order",
  str_item_intro_3661207 = [[
Furniture item. Can be placed in rooms on your Colossus.
Above the clouds in the sky is the floating city. As Astra's light of civilization, this carpet is a symbol of identity and status and also represents order and rituals.]],
  str_item_3661208 = "Unfalling Banner",
  str_item_intro_3661208 = [[
Furniture item. Can be placed in rooms on your Colossus.
The symbol of the "everlasting unfalling city," its appearance on the continent means that Lumopolis' light of civilization shines brightly here.]],
  str_item_3661201 = "Tribute Harp",
  str_item_intro_3661201 = [[
Furniture item. Can be placed in rooms on your Colossus.
This harp is exclusively used during grand celebrations in Lumopolis. Preserved with a unique form of Luminatics, its tone remains flawlessly in tune. Only the most skilled musicians can play uplifting melodies with this instrument, which is perfect for praise songs.]],
  str_item_3661202 = "Flickering Hourglass",
  str_item_intro_3661202 = [[
Furniture item. Can be placed in rooms on your Colossus.
"Amidst the ebb and flow of light and darkness, only this artifact can precisely measure time." Rumored to hold the most exquisite grains of sand found on the continent, and through the calibration of unique Luminatics, the accuracy of this hourglass rivals that of the finest clocks.]],
  str_item_3661203 = "Fountain Above Clouds",
  str_item_intro_3661203 = [[
Furniture item. Can be placed in rooms on your Colossus.
In the courtyard high above the clouds, can you perceive the gentle sound of flowing water? Don't be astonished, for it originates from Lumopolis' Fountain Terrace. Blessed by the enchanting Luminatics, water appears to manifest out of nothingness, gracefully descending from one level to the next. Even from the heavens above, people can relish the captivating sight of this celestial waterfall.]],
  str_item_3661204 = "The Last Sword and Shield",
  str_item_intro_3661204 = [[
Furniture item. Can be placed in rooms on your Colossus.
As the unyielding city, Lumopolis stands as the ultimate bastion of civilization. This sword and shield embody the final pillar of this defense... They symbolize the duty, bravery, and unwavering determination to fight until the very end.]],
  str_item_3661034 = "Crystal Ball of Old Days",
  str_item_intro_3661034 = [[
Furniture item. Can be placed in rooms on your Colossus.
A hurried glance into the crystal reveals only your own reflection, but a close inspection unravels scenes from the past. The essence of cherished memories lingers before your eyes, inviting you to immerse yourself in their grasp...]],
  str_item_3000325 = "Crystal Teardrop",
  str_item_intro_3000325 = [[
It is said that these are tears shed by this world... They can only be obtained on that day and contain the truth of this world.
Use: Can be exchanged for supplies in Hall of Remembrance.
Source: Complete Main Story or Resource Raid stages that require Prism.]],
  str_item_3661205 = "Double-Arm Candlestick",
  str_item_intro_3661205 = [[
Furniture item. Can be placed in rooms on your Colossus.
"Light should be emitted in the dark to help people find their way." This sconce utilizes special Luminatics of Lumopolis. It can be mounted to walls automatically without hooks, and its candles won't be easily extinguished by the wind.]],
  str_item_3661206 = "Elegant Vase",
  str_item_intro_3661206 = [[
Furniture item. Can be placed in rooms on your Colossus.
The large vases, each expensive enough for commoners to live luxuriously for a few years, used by Lumo Nobles are known for their elegant shapes. However, they are merely decorations that come to a dime for a dozen in their opulent mansions.]],
  str_item_3661035 = "Dignified Formal Dress",
  str_item_intro_3661035 = [[
Furniture item. Can be placed in rooms on your Colossus.
This outfit is elegant and solemn enough for even the grandest of ceremonies, festivals or balls in Lumopolis where etiquette is held in the highest esteem. When worn by one with good looks and good taste, the wearer is bound to attract everyone's gaze and become the star of the crowd.]],
  str_item_3661209 = "Resort Sunshade Lounge",
  str_item_intro_3661209 = [[
Furniture item. Can be placed in rooms on your Colossus.
No holiday destination is complete without it, providing both relaxation and protection from the sun. Missing even one of the two pieces dampens the vacation spirit.]],
  str_item_3661210 = "Amusement Park Ad Wall",
  str_item_intro_3661210 = "Furniture item. Can be placed in rooms on your Colossus.\nSeemingly a must-have in every amusement park—colossal, eye-catching, adorned with captivating patterns that seem to beckon, \"Come and see! Don't miss out!\"",
  str_item_3661211 = "Resort Ice Cream Truck",
  str_item_intro_3661211 = [[
Furniture item. Can be placed in rooms on your Colossus.
Such pushcarts offer icy treats on the scorching days of summer. They serve as mini replenishment stations scattered across the amusement park, always attracting kids lingering around it and wanting more.]],
  str_item_3661212 = "Resort Spring Pony",
  str_item_intro_3661212 = [[
Furniture item. Can be placed in rooms on your Colossus.
A beloved amusement feature among kids. With springs beneath it mildly bouncing the rider up and down, it always prompts an endless chorus of excited shrieks from the little ones.]],
  str_item_3661213 = "Oasis Jet Ski",
  str_item_intro_3661213 = [[
Furniture item. Can be placed in rooms on your Colossus.
Water racing is possible even in the middle of the desert! Who would've thought! It's all thanks to the copious waters from the sprawling oasis that Jet Skis find their calling, spared from becoming relics of the past.]],
  str_item_3661214 = "Desert Cactus Plant",
  str_item_intro_3661214 = "Furniture item. Can be placed in rooms on your Colossus.\nThe most prevalent plant in the desert, remarkably adapted to arid conditions. It's seen as a symbol of tenacity, leading folks to transplant it into pots for home decor. But remember, never overwater it–it'll drown otherwise.",
  str_item_level_2905111 = "Energy Field",
  str_item_10000100 = "Water Aurorian Selection Box",
  str_item_10000101 = "Fire Aurorian Selection Box",
  str_item_10000102 = "Forest Aurorian Selection Box",
  str_item_10000103 = "Thunder Aurorian Selection Box",
  str_item_intro_10000100 = "After use, you can select one of the following 5-Star Aurorians to join your adventure. (<color=#ffffff>Noah, Hydrad, Barton, Kleken, Philyshy, Corax</color>)",
  str_item_intro_10000101 = "After use, you can select one of the following 5-Star Aurorians to join your adventure. (<color=#ffffff>Faust, Regina, Benny and Curo, Leona, Istvan, Maggie, Barbara</color>)",
  str_item_intro_10000102 = "After use, you can select one of the following 5-Star Aurorians to join your adventure. (<color=#ffffff>Louise, Robyn, Odi, Pact, Areia, Sikare, Cuscuta</color>)",
  str_item_intro_10000103 = "After use, you can select one of the following 5-Star Aurorians to join your adventure. (<color=#ffffff>Mia, Nemesis, Schwartz, Vivian, Keating, Dayna, Beverly</color>)",
  str_item_3000327 = "Claw Machine Token",
  str_item_intro_3000327 = "These tokens are used in Claw Machines and various other gaming facilities. Each one features Lorelei's cheerful smile, carrying her best wishes for every guest to have an enjoyable experience.",
  str_item_3000328 = "Denuo Pass Coin",
  str_item_intro_3000328 = [[
Coins circulated inside the Denuo Valley Resort. Due to its high craftsmanship and superior quality, it can be exchanged with other factions' currencies.
Use them wisely in the management mode to upgrade buildings.]],
