  str_item_intro_3410647 = "Contains: Yellow Order Box IV ×15, Yellow Order Box III ×25, Yellow Jasper III ×25, Yellow Jasper II ×10, Yellow Jasper I ×6, Nightium ×331,000, Coalition Order Box III ×8",
  str_item_intro_3000900 = "Soft cotton that is frequently used as stuffing or crafted into decorative ornaments.",
  str_item_intro_3000901 = "A common clothing material found in Astra, known for its strength, durability, and ease of dyeing.",
  str_item_intro_3000902 = "Dye. Sinsa only showed you this single barrel, but he mentioned that there are actually many more barrels of various colors.",
  str_item_intro_3000903 = "A button commonly used in tailoring. It feels cool to the touch and is often mistaken for coins by kids.",
  str_item_intro_3000904 = "It looks like an ordinary ball of yarn. Sinsa only showed you the black one, afraid you might mess up the color order if you played with it.",
  str_item_7000100 = "Tattered Sketchbook",
  str_item_7000101 = "Sketchbook Fragment: Doctor",
  str_item_7000102 = "Sketchbook Fragment: Empty Pot",
  str_item_7000103 = "Diagnostic Report",
  str_item_7000104 = "Tea Cup",
  str_item_7000105 = "White Toad",
  str_item_7000106 = "Worn-out Toy",
  str_item_7000107 = "Apology Letter",
  str_item_7000108 = "Damaged Ledger",
  str_item_7000109 = "Researcher's Notes",
  str_item_7000110 = "Adorable Wrench",
  str_item_7000111 = "Tiny Hair Band",
  str_item_7000112 = "Guidance Frog",
  str_item_7000113 = "Seed",
  str_item_7000114 = "Sketchbook Fragment: Dawn Flower",
  str_item_7000115 = "Sketchbook Fragment: Wrench",
  str_item_7000116 = "Sketchbook Fragment: Rediesel Boss",
  str_item_7000117 = "Sketchbook Fragment: Colossus",
  str_item_7000118 = "Sketchbook Fragment: Prince Lilypad",
  str_item_7000119 = "Complete Sketchbook",
  str_item_intro_7000100 = "A sketchbook with simple drawings, featuring an open page portraying a young girl joyfully seated with three individuals around her. Strangely, the heads of these people in the drawing have all been torn off.",
  str_item_intro_7000101 = "It seems this piece of paper was torn out of a picture book. It vaguely depicts the head of a mysterious woman wearing a white coat.",
  str_item_intro_7000102 = "Upon the piece of paper is the image of a ceramic flower pot containing a small mound of soil.",
  str_item_intro_7000103 = "A somewhat weathered piece of paper resembling a diagnostic report.",
  str_item_intro_7000104 = "An exquisitely crafted teacup, displaying significant value.",
  str_item_intro_7000105 = "A mysterious white little creature with an unknown origin. It shows a strong fondness for dandelions.",
  str_item_intro_7000106 = "A toy with a distinctive appearance. Though its basic design seems ordinary enough, it bears the hallmarks of exquisite craftsmanship.",
  str_item_intro_7000107 = "A wrinkled piece of paper filled with crooked handwriting. Despite its sloppy appearance, one can sense the writer's sincere intentions.",
  str_item_intro_7000108 = "An aged ledger that reveals the owner's lack of accounting habits. Instead of recording income and expenses, it serves as a vessel for capturing her gifted thoughts and ideas.",
  str_item_intro_7000109 = "A weathered notebook, belonging to someone of advanced years.",
  str_item_intro_7000110 = "A massive wrench embellished with adorable stickers.",
  str_item_intro_7000111 = "An intricately patterned headband that is small enough to be worn by a doll-sized creature.",
  str_item_intro_7000112 = "A white frog wearing a headband like a scarf, adding to its charm.",
  str_item_intro_7000113 = "A lonely seed, like a solemn vow, awaits discovery in the corner.",
  str_item_intro_7000114 = "A girl named after flowers that welcome the dawn. She is small and radiant like a blossom.",
  str_item_intro_7000115 = "A piece of paper featuring a drawing of an oversized wrench. Such a large tool must belong to someone tall and handsome.",
  str_item_intro_7000116 = "The leader of Rediesel Wrench, a figure striding through storms, confronting conspiracies, and laughing in the face of desperation. Beneath the iron exterior, gentleness still resides.",
  str_item_intro_7000117 = "A legendary dragon-shaped Colossus, depicted with adorable strokes resembling an elegant figure, yet one cannot help but admire its pure white wings.",
  str_item_intro_7000118 = "The white messenger from the outside world.",
  str_item_intro_7000119 = "A sketchbook with a cute art style, showcasing a few people laughing joyfully.",
  str_item_sub_intro_7000100 = "\"These were meant to be happy memories, yet they are riddled with holes... Who exactly did I draw on them back then?\"",
  str_item_sub_intro_7000101 = "\"Hey, who was so careless as to tear off the doctor's face? It got nibbled by a small animal? Well, then I can't do anything about it.\"",
  str_item_sub_intro_7000102 = "\"I also have these pottery basins at home! I have quite a collection because I really like them... though I can't remember the exact reason why I liked them.\"",
  str_item_sub_intro_7000103 = "\"Fear, anger, pain... All the negative factors affecting your physical and psychological state have been successfully eliminated. Congratulations, you're now a healthy child.\"",
  str_item_sub_intro_7000104 = "\"Apart from me, the doctor has other patients to attend to. There's a noble young lady from Lumopolis who adores black tea and carries a small teacup everywhere... I hope she has recovered by now.\"",
  str_item_sub_intro_7000105 = "\"What's wrong with toads? I adore toads the most! ... Huh? You're not a toad?\"",
  str_item_sub_intro_7000106 = "\"To my beloved, when we cannot be by her side, may these small trinkets bring her joy...\"",
  str_item_sub_intro_7000107 = "\"We must refrain from using foul language in front of ***. Let's all hold each other accountable. Anyone who breaks this rule will have to eat eighteen bottles of hot sauce raw, and I am no exception.\"",
  str_item_sub_intro_7000108 = "\"I must say, I am profoundly surprised by its intensity. I once believed that **'s level represented the limit of what seeds could achieve, and that the true breakthrough should lie in **'s influence on one's personality. However, the raw, violent, and unimaginable power of ** has captivated me. I am astonished that seeds can wield such abilities. This strength, this power, is precisely what **** needs. I now yearn for the power of ** to reshape the world.\"",
  str_item_sub_intro_7000109 = "\"As we reached the scene, we were utterly shocked by the devastating traces of destruction. We speculated that an individual unleashed immense energy, obliterating all facilities and buildings from underground to the surface... It's difficult to fathom what kind of monster could possess such power...\"",
  str_item_sub_intro_7000110 = "\"These flower-patterned stickers look familiar... Did I put them on?\"",
  str_item_sub_intro_7000111 = "\"A white headband with black stripes... where have I seen it before...\"",
  str_item_sub_intro_7000112 = "\"What message do you have for me? Will you guide me, a lost soul, along the path?\"",
  str_item_sub_intro_7000113 = "\"If you take the flowers away from my world, my heart will sink even deeper into a far-reaching abyss, I suppose.\"",
  str_item_sub_intro_7000114 = "\"I want to go back and plant flowers all over Red-Eye Gorge.\"",
  str_item_sub_intro_7000115 = "\"With such skills, can you truly capture the awesomeness of this wrench... If anyone dares to criticize it, they might actually experience the wrench's power...\"",
  str_item_sub_intro_7000116 = "\"He always manages to find me!\"",
  str_item_sub_intro_7000117 = "\"Guess what kind of person can control such a magnificent Colossus... Are you kidding me! I wasn't mocking Lepidoz at all! This is so unfairrrrrrrr—\"",
  str_item_sub_intro_7000118 = "\"Stay alive, and we'll meet again.\"",
  str_item_sub_intro_7000119 = "\"The real world and genuine happiness.\"",
