  str_item_intro_7000200 = [[
A uniquely designed magnifying glass with distinctive coloring, an indispensable tool in investigations.

]],
  str_item_intro_7000201 = [[
A glistening gilded quill that feels weighty in your hand.

]],
  str_item_intro_7000202 = [[
A perfect grade report from Dawn Academy, showcasing top-notch performance.

]],
  str_item_intro_7000203 = [[
A cane tucked away in a corner, seemingly inconspicuous, evoking memories of Irridon's childhood.

]],
  str_item_intro_7000204 = [[
A precedent left by Judge Rodell Novek, mirroring his own frigid and unrelenting nature.

]],
  str_item_intro_7000205 = [[
A confidential investigation report authored by Irridon's father, long before the Baron's will trial, he knew of the hidden intentions behind the will.

]],
  str_item_intro_7000206 = [[
A precedent left by Judge Rodell Novek, with a verdict resulting in the eradication of an entire family.

]],
  str_item_sub_intro_7000200 = "\"Is it just my imagination, or is this magnifying glass really calling my name? Well, that can't be possible. But this magnifying glass looks oddly familiar... Could it be mine? What's happening to me? How come I can't even remember something like this?\"",
  str_item_sub_intro_7000201 = "\"Why is it? Why can't I ever win their approval, be it my father or my peers...\"",
  str_item_sub_intro_7000202 = "\"Did I not try my best...?\"",
  str_item_sub_intro_7000203 = "\"How much effort does it take to forget those gloomy moments from my childhood?\"",
  str_item_sub_intro_7000204 = "\"Should I carry forward the mindset behind this ruling...\"",
  str_item_sub_intro_7000205 = "\"Wh-What have I done...?\"",
  str_item_sub_intro_7000206 = "\"I believe... I have the answer of my own.\"",
  str_item_7000300 = "Obtain Evidence",
  str_item_7000301 = "Obtain Testimony",
  str_item_7000302 = "Obtain Evidence",
  str_item_7000303 = "Obtain Testimony",
  str_item_7000304 = "Obtain Statute",
  str_item_7000305 = "Obtain Statute",
  str_item_7000306 = "Obtain Evidence",
  str_item_7000307 = "Obtain Evidence",
  str_item_7000308 = "Obtain Testimony",
  str_item_7000309 = "Obtain Testimony",
  str_item_7000310 = "Obtain Statute",
  str_item_7000311 = "Obtain Statute",
  str_item_7000312 = "Obtain Evidence",
  str_item_7000313 = "Obtain Evidence",
  str_item_7000314 = "Obtain Testimony",
  str_item_7000315 = "Obtain Testimony",
  str_item_7000316 = "Obtain Statute",
  str_item_7000317 = "Obtain Statute",
  str_item_7000318 = "Golden Weight",
  str_item_7000319 = "Golden Weight",
  str_item_7000320 = "Golden Weight",
  str_item_intro_7000300 = "Nodirri doesn't seem to have the emblem on her.",
  str_item_intro_7000301 = "A testimony from a student council member: Pam's family is facing financial hardship.",
  str_item_intro_7000302 = "There is a competitive relationship between Nodirri and Pam.",
  str_item_intro_7000303 = "Testimony from the old gatekeeper: Nodirri visited the self-study room before.",
  str_item_intro_7000304 = "Crime against Property",
  str_item_intro_7000305 = "Offense against Public Order",
  str_item_intro_7000306 = "Grandfather's will has been confirmed to be genuine.",
  str_item_intro_7000307 = "Jerry's fingerprints were found on the tools used by Grandfather for suicide.",
  str_item_intro_7000308 = "Neighbor's testimony: Grandfather mentioned wanting to pass everything down to his granddaughter.",
  str_item_intro_7000309 = "Witness's testimony: No anomalies were observed when Grandfather drafted his will.",
  str_item_intro_7000310 = "Forgery of Documents",
  str_item_intro_7000311 = "Will Inheritance Law",
  str_item_intro_7000312 = "The Pyrrhus family emblem found in Gautier's room.",
  str_item_intro_7000313 = "Curses written by Mirren Gautier in his sketchbook.",
  str_item_intro_7000314 = "Gautier family captured Pyrrhus family members for experiments.",
  str_item_intro_7000315 = "The Pyrrhus family is still researching Sanguine Crystals.",
  str_item_intro_7000316 = "Treason",
  str_item_intro_7000317 = "Crime of Spreading Rumors",
  str_item_intro_7000318 = "Evidence found for the Dawn Emblem Theft Case!",
  str_item_intro_7000319 = "Evidence found for Grandfather's Will Case!",
  str_item_intro_7000320 = "Evidence found for the Gautier Family Treason Case!",
  str_item_sub_intro_7000300 = "Upon hearing Pam's account of the case, Nodirri becomes visibly enraged. She steps closer to Pam, firing off a barrage of questions about why she would defame her in such a way. To prove her innocence, Nodirri willingly allows Irridon to search her, and, as expected, nothing incriminating is discovered.",
  str_item_sub_intro_7000301 = "On the way to the self-study room, Irridon is discreetly approached by a member of the student council, who passionately shares his perspective, \"Pam's family was never some high-ranking noble house, and her parents haven't held any official public positions. Lately, it appears they're facing financial difficulties for some reason!\"",
  str_item_sub_intro_7000302 = "On the school's bulletin board, Irridon comes across an announcement from the Lumopolis Temple: this year, they've accepted two in-training nuns, Pam and Nodirri. However, only one of them will ultimately have the chance to remain at the temple.",
  str_item_sub_intro_7000303 = "Irridon reaches the vicinity of the self-study room and spots an aged gatekeeper dozing off nearby. Clearly, the gatekeeper hasn't forgotten Irridon, having received help from Irridon several times during school. The gatekeeper mentions that today, apart from Pam, only Nodirri entered the study room. He found it strange at the time why Nodirri used a handkerchief to open the door. \"Maybe she's a germophobe; I didn't think much of it at the time.\"",
  str_item_sub_intro_7000304 = "The theft of significant property, when the stolen amount is substantial, is punishable by imprisonment ranging from three to ten years and a fine.",
  str_item_sub_intro_7000305 = "Publicly insulting or intentionally defaming others, with severe circumstances, can lead to imprisonment for up to three years and a fine.",
  str_item_sub_intro_7000306 = "Jerry presents Irridon with the will he has in hand, and after a meticulous comparison and analysis, Irridon confirms that the will of Pam's grandfather is indeed written by himself. In the will, the grandfather leaves his title and wealth to Jerry, stating, \"I've lived long enough, and I have no regrets.\" Irridon pays close attention to this statement, as it appears that the grandfather hinted at his intention for suicide when writing the will.",
  str_item_sub_intro_7000307 = "Irridon reaches Pam's grandfather's residence and finds that he ended his own life using a small fruit knife. However, upon a close inspection of the knife, Irridon identifies Jerry's fingerprints on it. Jerry explains that he often prepares meals, so having his fingerprints on cutlery is not unusual. Irridon reevaluates the situation and confirms the grandfather's suicide.",
  str_item_sub_intro_7000308 = "Irridon knocks on the door of the grandfather's neighbor, and the neighbor tells Irridon that, although the grandfather often lamented his son's inadequacies, he frequently boasted about his granddaughter. The grandfather had even publicly stated that he intended to pass his title and wealth to his granddaughter, leaving nothing for his son.",
  str_item_sub_intro_7000309 = "The witness to the will is a well-educated old servant. The old servant expresses immense honor for being invited by the grandfather to be the witness. Just as the words leave the old servant's mouth, he suddenly feels like he misspoke. A bit embarrassed, the servant continues to explain that there was nothing unusual when the grandfather drafted the will, and he had repeatedly confirmed that these were indeed the grandfather's true intentions.",
  str_item_sub_intro_7000310 = "Forgery of public or private documents for fraudulent activities is punishable by imprisonment ranging from three to ten years and a fine.",
  str_item_sub_intro_7000311 = "Legally valid wills must be followed in distributing property as per their content.",
  str_item_sub_intro_7000312 = "Irridon sneaks into the room belonging to the Gautier family in Lower Lumopolis, carefully searching through it. To her surprise, she discovers an emblem of the Pyrrhus family hidden in a corner. Both the Gautier and Pyrrhus families were exiled to Lower Lumopolis due to the Sanguine Crystal case. Is it possible that these two families are collaborating on a rebellion? Irridon dares not dwell on it further. \"Pam is also a member of the Pyrrhus family...\"",
  str_item_sub_intro_7000313 = "Irridon comes across another dilapidated house, and inside, she finds a sketchbook signed \"Mirren Gautier.\" The book contains some abstract patterns that Irridon finds challenging to comprehend. Irridon squints, and amidst the patterns, she discovers a small line of text: \"Why do you treat me like this... Why, WHY?! I'm gonna take charge of my own fate again... even if it means I have to use their strength.\"",
  str_item_sub_intro_7000314 = "A strange Eclipsite abruptly appears on the street. Without any hesitation, Irridon advances and pierces the Eclipsite's chest, leaving it to collapse on the ground. But suddenly, as if awakening from a daze, the Eclipsite raises its hand in the direction of the crowd, seemingly struggling to say something. Irridon approaches, hearing the Eclipsite's murmurs, \"Gautier... seeking revenge... against Pyrrhus... they... captured us... for experiment... they're planning... a rebellion!\"",
  str_item_sub_intro_7000315 = "While Irridon contemplates her next move for the investigation, a ragged passerby approaches discreetly. He claims to know everything about recent happenings in Lower Lumopolis, revealing that the Pyrrhus family is still conducting research on Sanguine Crystals. Irridon asks why he's sharing this information, and the passerby parts his lips, revealing his darkened teeth and saying, \"Can you get me back to the Lumopolis Courtyard?\"",
  str_item_sub_intro_7000316 = "Deliberately plotting or attempting to overthrow the rule of Lumopolis will result in a life sentence, with the possibility of the death penalty for severe cases.",
  str_item_sub_intro_7000317 = "Spreading false rumors about others intentionally will lead to imprisonment for up to one year and a fine.",
  str_item_sub_intro_7000318 = "Based on evidence and witness statements, Irridon deduces that Nodirri is the culprit who stole the Dawn Emblem.",
  str_item_sub_intro_7000319 = "You deem the will valid, and the servant Jerry will inherit Pam's grandfather's title and all his wealth...",
  str_item_sub_intro_7000320 = "You have collected comprehensive evidence and testimonies, confirming that Mirren Gautier abducted members of the Pyrrhus house for experimentation and had rebellious intentions.",
  str_item_7000400 = "Old Key",
  str_item_7000401 = "Dayna's Cookies",
  str_item_7000402 = "Blueprint for New Home",
  str_item_7000403 = "Stately Trombone",
  str_item_7000404 = "New Music Sheet",
  str_item_7000405 = "Dayna's Portrait",
  str_item_7000406 = "Robyn's Portrait",
  str_item_7000407 = "Lady in the Teapot's Portrait",
  str_item_7000408 = "White Dolphin's Portrait",
  str_item_intro_7000400 = "Key to the attic given to Connolly by her aunt. Use it carefully so the ancient lock won't squeak and disturb others.\n",
  str_item_intro_7000401 = "Cookies that Connolly brought for Dayna but stolen by merman guards. These are unsweetened as per Dayna's request.\n",
  str_item_intro_7000402 = "Draft for the Aqua Lord's keep. That's probably not correct, but Queen Connolly reserves all rights of interpretation.\n",
  str_item_intro_7000403 = "This new music instrument townspeople found for Connolly can play louder and more authoritative sounds to convey anger.\n",
  str_item_intro_7000404 = "The Aqua Score that Connolly found in the old attic, now signed with a new name.\n",
  str_item_intro_7000405 = "A portrait of Dayna painted by an artist in an undersea town, currently placed in an empty seat by Queen Connolly as a prop when rehearsing her speech.\n",
  str_item_intro_7000406 = "A portrait of Robyn painted by an artist in an undersea town, currently placed in an empty seat by Queen Connolly as a prop when rehearsing her speech.\n",
  str_item_intro_7000407 = "A portrait of a mystery consultant painted by an artist in an undersea town, currently placed in an empty seat by Queen Connolly as a prop when rehearsing her speech.\n",
  str_item_intro_7000408 = "A portrait of a friendly fish painted by an artist in an undersea town, currently placed in an empty seat by Queen Connolly as a prop when rehearsing her speech.\n",
  str_item_sub_intro_7000400 = "\"She sleeps in the attic, eating what others refused. Speaking in soft whispers, hiding in the far corners! Sweeping the room during the day, playing the instrument at night. Comforting her lonely heart with music!\"",
  str_item_sub_intro_7000401 = "\"My cookies! Connolly gave me that! Why wouldn't the filthy lackeys spare even the cookies!\"",
  str_item_sub_intro_7000402 = "\"Otherworld the of... aesthetics great the... in revel!\"",
  str_item_sub_intro_7000403 = "\"Pain and sorrow... will see salvation in music!\"",
  str_item_sub_intro_7000404 = "\"It once expressed the desire for me to give it a new name. I pondered long and hard. Rubinstein, Salieri, Leopold, Dvorak... Those were all its favorites... What, something more intimate?\"",
  str_item_sub_intro_7000405 = "\"I was being too caustic, you said? How could I not be when I was standing up for my siblings?\"",
  str_item_sub_intro_7000406 = "\"Yes, a fish did call me flat and hardly noticeable before... But that's exactly how I survive...\"",
  str_item_sub_intro_7000407 = "\"You want me to come out of retirement? Well, that's going to cost you.\"",
  str_item_sub_intro_7000408 = "\"Who am I to Queen Connolly, you ask? That's confidential!\"",
  str_item_7000801 = "Antique",
  str_item_intro_7000801 = "Antiques found on every corner of Twin Pavilions Bay. The cultural artifacts of Longzhou are highly valued in other countries, but some are obtained through honest transactions involving orders and corresponding payment, while others are stolen in the shadows by thieves.",
  str_item_6030101 = "Miniature Sketchbook",
  str_item_6030102 = "Smile Temperature",
  str_item_6030103 = "Eve's Dawn",
  str_item_6030104 = "Lumopolis Temple",
  str_item_6030105 = "Art of Balance",
  str_item_6030106 = "Innocent Prayer",
  str_item_6030107 = "Aqua Sign",
  str_item_6030108 = "Solo of Love",
  str_item_6030109 = "Wonderful Home",
  str_item_6030110 = "Wisteria Dreams",
  str_item_6030111 = "The Flower and the Magic Sword",
  str_item_6030112 = "Boat of Dreams",
  str_item_6030113 = "His Watchful Gaze",
  str_item_6030114 = "Her Sacred Pledge",
  str_item_6030115 = "Regal Sword",
  str_item_6030116 = "Sweet Locomotive",
  str_item_6030117 = "Hunting Stone's New Look",
  str_item_6030118 = "Cream Forest",
  str_item_6030119 = "Soldier Dogtag",
  str_item_6030120 = "Light of Starlight",
  str_item_6030121 = "Illumina Banner",
  str_item_6030122 = "Nikinis's Thought",
  str_item_6030123 = "Nepolis's Wish",
  str_item_6030124 = "Northland Mirror",
  str_item_intro_6030101 = [[
Stand By Me Medallion.
The tiny sketchbook depicts childish patterns, but it cannot conceal the feelings of reluctance and attachment within, making it hard to part with.]],
  str_item_intro_6030102 = [[
Stand By Me Medallion.
Even if doomsday arrives, he will always prepare water at the right temperature for his younger sister.]],
  str_item_intro_6030103 = [[
Stand By Me Medallion.
In those dark years, this flower was her dawn.]],
  str_item_intro_6030104 = [[
Stand By Me Medallion.
An acknowledgment from the Lumopolis Temple.]],
  str_item_intro_6030105 = [[
Stand By Me Medallion.
Irridon's keen gaze spares no unbalanced scales.]],
  str_item_intro_6030106 = [[
Stand By Me Medallion.
Back then, Paloma was still willing to believe...]],
  str_item_intro_6030107 = [[
Stand By Me Medallion.
This is the appreciation from the great Aqua Lord! You mortals, stretch your limbs to receive my grace!]],
  str_item_intro_6030108 = [[
Stand By Me Medallion.
I played this solo with the hope of my family members, the care from my companions, as well as... love and courage.]],
  str_item_intro_6030109 = [[
Stand By Me Medallion.
I looked only for a shelter, but to my surprise, I made it a wonderful home.]],
  str_item_intro_6030110 = [[
Stand By Me Medallion.
Is this warmth I feel right now the radiance of the morning sun or your warmth after passing through the sharp thorns?]],
  str_item_intro_6030111 = [[
Stand By Me Medallion.
Very few people know that the chaste tree flower also blooms. However, it is smaller than a wisteria flower, is a faint lavender color, and looks like the swordfighter's skirt.]],
  str_item_intro_6030112 = [[
Stand By Me Medallion.
When she passes by the babbling Gold River one day, she will remember the boat ride in her dreams and look forward to sharing a boat with a certain person.]],
  str_item_intro_6030113 = [[
Stand By Me Medallion.
"You're the reason why the world is worth my protection."]],
  str_item_intro_6030114 = [[
Stand By Me Medallion.
"You're the reason why I want to protect this world."]],
  str_item_intro_6030115 = [[
Stand By Me Medallion.
It has been imbued with an extraordinary strength through the infusion of Regal's love. Perhaps this is the sole reason why she can remain by his side in a different form.]],
  str_item_intro_6030116 = [[
A Stand By Me Medallion.
When it leaves, it seems like a cold and unfeeling machine. Only when it returns does its sweet nature become apparent.]],
  str_item_intro_6030117 = [[
A Stand By Me Medallion.
Since getting rid of it is impossible... It may as well serve as a unique fashion accessory.]],
  str_item_intro_6030118 = [[
A Stand By Me Medallion.
Trees flowing with thick cream and flowers bearing the sweetest fruits... The perfect place for a picnic, should the opportunity ever arise.]],
  str_item_intro_6030119 = [[
Stand By Me Medallion.
Every tag represents one life. May all these resplendent souls rest in peace.]],
  str_item_intro_6030120 = [[
Stand By Me Medallion.
Who are this person's parents? Does this person have any children or siblings? The name inscribed on stone remains silent while reflecting the path ahead.]],
  str_item_intro_6030121 = [[
Stand By Me Medallion.
Banners flutter in the wind as the call to arms sounds. Astra's most selfless defenders advance fearlessly, never retreating as they keep the darkness at bay.]],
  str_item_intro_6030122 = [[
Stand By Me Medallion.
"All I want is to stay beside my sister..."]],
  str_item_intro_6030123 = [[
Stand By Me Medallion.
"All I desire is for my little sister to survive..."]],
  str_item_intro_6030124 = [[
Stand By Me Medallion.
This mirror has witnessed the fall of too many things. Perhaps it's time for it to see something new.]],
  str_item_6130101 = "Stand By Me Memorial Slate",
  str_item_6130102 = "Stand By Me Mirrorplate",
  str_item_6130103 = "Stand By Me Concert Board",
  str_item_6130104 = "Stand By Me Dream Board",
  str_item_6130105 = "Board of Shared Gazes",
  str_item_6130106 = "Stand By Me Board",
  str_item_6130107 = "Stand By Me Military Board",
  str_item_6130108 = "Stand By Me Poem Board",
  str_item_intro_6130101 = [[
Stand By Me Commemorative Board.
It's over; the past is gone. Let's return home.]],
  str_item_intro_6130102 = [[
Stand By Me Commemorative Board.
The one in the mirror, let's wake up together.]],
  str_item_intro_6130103 = [[
Stand By Me Commemorative Board.
My mind has never been so strong, and my voice has never been so melodious.]],
  str_item_intro_6130104 = [[
Stand By Me Commemorative Board.
She fights against the curse every day after she wakes up in the morning, but her dreams are bright: she will welcome the faint morning light in a neat and bustling city.]],
  str_item_intro_6130105 = [[
Stand By Me Commemorative Board.
Though a thousand years may have faded like dust, dissipating into nothingness, my heart remains steadfast.]],
  str_item_intro_6130106 = [[
A Stand By Me Commemorative Board.
Clickety-clack, clickety-clack! Clinging to the tracks, the train rushes through a bright dream. It charges past the Cream Forest, past a spring of honey, and past the brewing regrets of a lone traveler...]],
  str_item_intro_6130107 = [[
Stand By Me Commemorative Board.
"I am willing to be tempered countless times, for I firmly believe these trials shall lead me to Illumina's light. The sharpened full-metal bullet encapsulates our unwavering aspirations."]],
  str_item_intro_6130108 = [[
Stand By Me Commemorative Board.
"Her body is entombed in snow, her soul is bound by the mirror, and her face is crowned with wilted blooms, but her love never withers away."]],
  str_item_3001000 = "Dream Shards",
  str_item_intro_3001000 = "Fragments obtained from a story where reality and illusion intertwine, recounting traces of the real world. They can be exchanged for item rewards in the store Authentic Dreamscapes.",
  str_item_get_3001000 = "Dream - Theme Store Tokens Expiry Conversion",
  str_item_3001001 = "Metamorpha",
  str_item_intro_3001001 = "A keepsake left behind after facing challenges and experiencing growth. It can be exchanged for item rewards in Dream - Awakening in the Storm - Memory Workshop.",
  str_item_get_3001001 = "Dream - Awakening in the Storm stage",
  str_item_3001002 = "Sediment Shard",
  str_item_intro_3001002 = "Fragments obtained after facing challenges and experiencing growth. They can be exchanged for item rewards in Dream - Awakening in the Storm - Memory Workshop.",
  str_item_get_3001002 = "Dream - Awakening in the Storm stage",
  str_item_3001003 = "Wit",
  str_item_intro_3001003 = "The key factor for Eve to remain rational and clear-minded, enabling her to confront the Omen in Awakening in the Storm. The Wit point will replenish by 3 points each day at 05:00 (UTC+0) or 00:00 (UTC-5) (No points will be given if the limit is reached).",
  str_item_get_3001003 = "Auto recovery over time",
  str_item_3001004 = "Ripples of Joy",
  str_item_intro_3001004 = "Eve's favorite cup holds only ordinary water, but it fuels her strength. Collect and upgrade the \"Smiles Lead to Happiness\" level.",
  str_item_get_3001004 = "Obtain by clear Nightmare stages in Dream with 3-Star for the first time.",
  str_item_3001005 = "Counterweights of Soul",
  str_item_intro_3001005 = "A weight obtained during the quest for one's true self to balance the scales of life. Can be used to exchange item rewards in Dream - Trials Amongst Golden Ripples - Trial Auction.",
  str_item_get_3001005 = "Dream - Trials Amongst Golden Ripples Stage",
  str_item_3001006 = "Candle of Justice",
  str_item_intro_3001006 = "A starry candle flame left behind on the path of pursuing justice in one's heart. Can be used to exchange item rewards in Dream - Trials Amongst Golden Ripples - Trial Auction.",
  str_item_get_3001006 = "Dream - Trials Amongst Golden Ripples Stage",
  str_item_3001007 = "Wit",
  str_item_intro_3001007 = "As the key to helping one maintain rationality and clarity, it will be consumed during exploration but can gradually replenish over time.",
  str_item_get_3001007 = "Auto recovery over time",
  str_item_3001008 = "Light of Justice",
  str_item_intro_3001008 = "The light of justice that Irridon has reclaimed through her own efforts. Accumulate it to level up the Truth Focus.",
  str_item_get_3001008 = "Obtain by clear Nightmare stages in Dream with 3-Star for the first time.",
  str_item_3001010 = "Echoing Seashell",
  str_item_intro_3001010 = "Inside this seashell echoing melodies are the fragments of ancient music sheet redeemable for prizes in Dream: Connolly's Underwater Fantasia Sea Bubbles Cafe.",
  str_item_get_3001010 = "Dream: Connolly's Underwater Fantasia Stage",
  str_item_3001011 = "Delicious Fluorophora",
  str_item_intro_3001011 = "Glowing algae in the corner of the ocean floor used to make a certain wildly popular deep-sea beverage. Redeemable for prizes in Dream: Connolly's Underwater Fantasia Sea Bubbles Cafe.",
  str_item_get_3001011 = "Dream: Connolly's Underwater Fantasia Stage",
  str_item_3001012 = "Wit",
  str_item_intro_3001012 = "As the key to helping one maintain rationality and clarity, it will be consumed during exploration but can gradually replenish over time.",
  str_item_get_3001012 = "Dream: Connolly's Underwater Fantasia Stage",
  str_item_3001013 = "Study of the Pact",
  str_item_intro_3001013 = "Connolly's attempt to comprehend everything described by the Aqua Lord and make sense of the profound wisdom. Accumulate to improve Aqua Connection level.",
  str_item_get_3001013 = "Obtain by clear Nightmare stages in Dream with 3-Star for the first time.",
  str_item_3001014 = "Wisteria Hairpin",
  str_item_intro_3001014 = "A hairpin made of small tough flowers that can be used to redeem item rewards in Dream - Sword Song Under a Canopy of Dreams - Verdant Exchange.",
  str_item_get_3001014 = "Dream - Sword Song Under a Canopy of Dreams Stages",
  str_item_3001015 = "Ancient Copper Coin",
  str_item_intro_3001015 = "A rusty ancient coin from the East that is no longer used as a form of currency over time. Can be used to redeem item rewards in Sword Song Under a Canopy of Dreams - Verdant Exchange.",
  str_item_get_3001015 = "Dream - Sword Song Under a Canopy of Dreams Stages",
  str_item_3001016 = "Wit",
  str_item_intro_3001016 = "As the key to helping one maintain rationality and clarity, it will be consumed during exploration but can gradually replenish over time.",
  str_item_get_3001016 = "Dream - Sword Song Under a Canopy of Dreams Stages",
  str_item_3001017 = "Sword-Forging Will",
  str_item_intro_3001017 = "Each battle is a chance to improve a swordfighter's swordsmanship. Constant improvement will lead to a qualitative change. Accumulate to improve Sword Heart level.",
  str_item_get_3001017 = "Obtain by clear Nightmare stages in Dream with 3-Star for the first time.",
  str_item_3001018 = "Working Capital",
  str_item_intro_3001018 = "As the people of Umbraton would say, the Indigo Guild started out as just a shell guild, but it's not the style of its founder to say no to money, so why not operate it like a proper guild?",
  str_item_3001019 = "Auspicious Energy",
  str_item_intro_3001019 = "The Auspicious Energy obtained from commercial monetary and financial transactions can be used to improve Feng Shui and slay evil.",
  str_item_3001021 = "Silver Wreath",
  str_item_intro_3001021 = "The olive branch wreath symbolizes victory and peace. Redeemable for prizes in Dream - A Thousand-Year Vigil - Northwind Market.",
  str_item_get_3001021 = "Dream - A Thousand-Year Vigil",
  str_item_3001022 = "Watcher's Coin",
  str_item_intro_3001022 = "Bronze Coin crafted to commemorate the triumph of the Northwind Legion. Redeemable for prizes in Dream - A Thousand-Year Vigil - Northwind Market.",
  str_item_get_3001022 = "Dream - A Thousand-Year Vigil",
  str_item_3001023 = "Wit",
  str_item_intro_3001023 = "As the key to helping one maintain rationality and clarity, it will be consumed during exploration but can gradually replenish over time.",
  str_item_get_3001023 = "Auto recovery over time",
  str_item_3001024 = "Fragrant Wheat Ear",
  str_item_intro_3001024 = "The comforting fragrance of wheat, symbolizing promises for a bright future, is a constant reminder to the soul within the sword—do not depart yet. Accumulate to level up the Sword Soul.",
  str_item_3001025 = "Temple Fragment",
  str_item_intro_3001025 = "With a thunderous crash, one side of the temple collapses, turning the intricately carved stones and precious vessels offered inside into scattered fragments. Yet, these fragments still retain some value.",
  str_item_3001026 = "Pop Rocks Candy",
  str_item_intro_3001026 = "A strange candy made from a rare plant. Can be used to exchange for rewards in Dream - Weird & Wacky Foodie Paradise - Delicacy Delivery.",
  str_item_get_3001026 = "Dream - Weird & Wacky Foodie Paradise Stage",
  str_item_3001027 = "Cream Wood",
  str_item_intro_3001027 = "A special type of lumber harvested from the trees of the Cream Forest. Can be used to exchange for rewards in Dream - Weird & Wacky Foodie Paradise - Delicacy Delivery.",
  str_item_get_3001027 = "Dream - Weird & Wacky Foodie Paradise Stage",
  str_item_3001028 = "Wit",
  str_item_intro_3001028 = "As the key to helping one maintain rationality and clarity, it will be consumed during exploration but can gradually replenish over time.",
  str_item_get_3001028 = "Auto recovery over time",
  str_item_3001029 = "Cherished Heart",
  str_item_intro_3001029 = "A product of Pact's unabashed concern and calling... Though the Hunting Stone never asked for it. Gather more to increase the Hunting Stone's level.",
  str_item_3001030 = "Fine Tableware",
  str_item_intro_3001030 = "An exquisite work of art crafted by a master. Can be used to make a high-quality dish even more appealing.",
  str_item_3001031 = "Phospherus Badge",
  str_item_intro_3001031 = "An old Illumina badge, a collector's item of profound significance. The medal itself isn't valuable, but it's become a priceless treasure due to the glory of the hero who earned it. Bestowing such a medal upon a hero is but a small token of gratitude. Can be redeemed for item rewards in Dream - Evanescing Night By Starlight - Dream Distribution.",
  str_item_get_3001031 = "Dream: Evanescing Night By Starlight",
  str_item_3001032 = "Illumina Voucher",
  str_item_intro_3001032 = "Vouchers popular in Illumina. Points are earned depending on the duration of work and service, which can be used to redeem various resources. Can be redeemed for item rewards in Dream - Evanescing Night By Starlight - Dream Distribution.",
  str_item_get_3001032 = "Dream: Evanescing Night By Starlight",
  str_item_3001033 = "Wit",
  str_item_intro_3001033 = "As the key to helping one maintain rationality and clarity, it will be consumed during exploration but can gradually replenish over time.",
  str_item_get_3001033 = "Auto recovery over time",
  str_item_3001034 = "Whistle",
  str_item_intro_3001034 = "Soldiers are so used to the shrill screech of the whistle that they actually can't feel secure without it. Collect enough to increase Sharpened Round's level.",
  str_item_3001035 = "Wargames",
  str_item_intro_3001035 = "A rare form of entertainment in Illumina, retaining the elements of combat. This exquisite war game conveys the heart of its creator.",
  str_item_3001036 = "Dried Flower Bookmark",
  str_item_intro_3001036 = "A self-made bookmark the girl used while reading. Accompanied by flowers, she flipped through countless books of fables, searching for traces of her fragmented past. Can be used to exchange for rewards in Dream - Through the Looking Glass Winter Sonnet - Nameless Market.",
  str_item_get_3001036 = "Dream - Through the Looking Glass Winter Sonnet Stages",
  str_item_3001037 = "Mirror Shard",
  str_item_intro_3001037 = "These shards are extensions of the magic mirror's strength, and within them lies the essence of the mirror world's structure. Every piece forms a small fractured domain. Can be used to exchange for rewards in Dream - Through the Looking Glass Winter Sonnet - Nameless Market.",
  str_item_get_3001037 = "Dream - Through the Looking Glass Winter Sonnet Stages",
  str_item_3001038 = "Wit",
  str_item_intro_3001038 = "As the key to helping one maintain rationality and clarity, it will be consumed during exploration but can gradually replenish over time.",
  str_item_get_3001038 = "Auto recovery over time",
  str_item_3001039 = "Mirror Dimension Blossom",
  str_item_intro_3001039 = "Nikinis' power often manifests in the form of flowers, and the Mirror Dimension is no exception.",
  str_item_3001040 = "Northland Fables Collection",
  str_item_intro_3001040 = "Nikinis is searching for her lost memories, and even while seeking help from others, she never gives up on the clues within herself.",
  str_item_not_enough_plm = "Insufficient Firethorn Fruits",
  str_item_3751396 = "Dark Circles Behind Sunglasses",
  str_item_3751397 = "Church Lady in Twilight",
  str_item_3751551 = "Woes of the New Grand Marshal",
  str_item_intro_3751396 = "May the light shines upon Twilight, dispelling the shadows lingering there.",
  str_item_intro_3751397 = "Dark circles? Not at all.",
  str_item_intro_3751551 = "Can't we have a conversation that doesn't involve work reports?",
  str_item_3000131 = "Twilight Symphony Special Star Flare",
  str_item_intro_3000131 = [[
Can be used to recruit once from the Twilight Symphony exclusive recruitment event.
This item eventually expires and will not be converted into another item; please remember to use it before the end of the Twilight Symphony exclusive recruitment event.]],
  str_item_10000992 = "Kleken United Box",
  str_item_intro_10000992 = "Allows Kleken to join your adventure.",
  str_item_1000099 = "Kleken United Box",
  str_item_intro_1000099 = "Allows Kleken to join your adventure.",
  str_item_3755023 = "Adorable Doggy Muppet",
  str_item_3755024 = "Frog?",
  str_item_3755025 = "Dawn Flower",
  str_item_intro_3755023 = [[
Unlocks the corresponding avatar.
*whines*... Do you like it?]],
  str_item_intro_3755024 = [[
Unlocks the corresponding avatar.
Dandelion? Don't run away from me!]],
  str_item_intro_3755025 = [[
Unlocks the corresponding avatar frame.
Small as the white flower is, it represents the dawn...]],
  str_item_3661219 = "Fiat Knight Portrait",
  str_item_intro_3661219 = [[
Furniture item. Can be placed in rooms on your Colossus.
A portrait crafted in the image of Irridon during her days as a knight, seemingly a gift a young girl couldn't deliver.
"Lady Irridon, I sincerely thank you for your ongoing help and care. I hope you will continue to embrace the values of justice and compassion, guiding Lumopolis towards a brighter future."]],
  str_item_3661220 = "Innocent Nun Portrait",
  str_item_intro_3661220 = [[
Furniture item. Can be placed in rooms on your Colossus.
A portrait crafted in the image of Paloma during her days as a nun, seemingly a gift a father couldn't give.
"Pam, may you forever stay innocent and kind, and may our family always find happiness."]],
  str_item_3751039 = "Unwavering Resolve",
  str_item_3751040 = "Light's End",
  str_item_3751041 = "Triumph Hymn",
  str_item_3751398 = "Thirst for Knowledge",
  str_item_3751399 = "Might of Guardian",
  str_item_3751400 = "What did you say?",
  str_item_intro_3751039 = [[
Unlocks the corresponding Avatar.
"Denier, Reinhardt... Whatever happens, may we each find our own path."]],
  str_item_intro_3751040 = "Unlocks the corresponding Avatar.\n\"I have no intention of and interest in making enemies—They're just obstacles in my path.\"",
  str_item_intro_3751041 = "Unlocks the corresponding Avatar.\n\"The Enlightened Illumination can be anyone—you, me, whoever—as long as they guide the Aurorians through the challenges.\"",
  str_item_intro_3751398 = [[
Unlocks the corresponding Avatar.
"Oh, the night sky... it's like an infinite library, housing all the world's secrets."]],
  str_item_intro_3751399 = [[
Unlocks the corresponding Avatar.
"Maybe one day, I can truly wield this power that fate has granted me with finesse."]],
  str_item_intro_3751400 = [[
Unlocks the corresponding Avatar.
"Huh?"]],
  str_item_3751552 = "Taboo Subject",
  str_item_intro_3751552 = [[
Unlocks the corresponding avatar.
"No more of that ice pop joke!"]],
  str_item_3751553 = "Joyful Tweety",
  str_item_intro_3751553 = [[
Unlocks the corresponding avatar.
"With the holidays approaching, I've got my vacation plans all set. Wanna know what Tweety's plan is?"]],
  str_item_3763034 = "Sweet Surprise",
  str_item_intro_3763034 = [[
Unlocks the corresponding avatar frame.
Zarya was worried that the bitter cold of Northland might be too much for you, so she gave you her hat.]],
  str_item_3661215 = "Writing Desk",
  str_item_intro_3661215 = [[
Furniture item. Can be placed in rooms on your Colossus.
A tasteful wooden writing desk that brings peace of mind at work.]],
  str_item_3661216 = "Small Coffee Table",
  str_item_intro_3661216 = [[
Furniture item. Can be placed in rooms on your Colossus.
A small wooden coffee table. A section of the surface is made of marble, lending it an air of refinement.]],
  str_item_3661217 = "Owl Side Table",
  str_item_intro_3661217 = [[
Furniture item. Can be placed in rooms on your Colossus.
An owl perches upon this small table as though gazing into the distance.]],
  str_item_3661218 = "Magic Broomstick",
  str_item_intro_3661218 = [[
Furniture item. Can be placed in rooms on your Colossus.
Some legends say that if you sit on it, it'll fly high into the air. Where could such an idea have possibly come from?]],
  str_item_5234055 = "Boat Ornament",
  str_item_intro_5234055 = "A small and brightly colored boat, erected upright and used as a decoration. Can the mere sight of it truly inspire the urge to set sail for faraway lands?",
  str_item_3661052 = "Ephemeral Firefly",
  str_item_intro_3661052 = [[
Furniture item. Can be placed in rooms on your Colossus.
It can only float in the air and is completely unable to move around... So what is it for? For hanging things on? Handrails?]],
  str_item_3000338 = "Ancient Remain",
  str_item_intro_3000338 = "Fragments of some ancient relic scattered across the land over countless years. If someone were willing to acknowledge their value, they might also be willing to pay a certain amount of remuneration to acquire them.",
  str_item_3751401 = "Brock's Basketball",
  str_item_3751402 = "Table Tennis Rookie Vice",
  str_item_3751403 = "Esports Pro Gronru",
  str_item_3751404 = "Master Marksman Charon",
  str_item_intro_3751401 = [[
Unlocks the corresponding avatar.
Check out my three-step layup! Yargh! Why did it have to bounce straight off the backboard?!]],
  str_item_intro_3751402 = [[
Unlocks the corresponding avatar.
Sport is life! Even if I am a rookie, I'll give all I've got on the ping pong table!]],
  str_item_intro_3751403 = [[
Unlocks the corresponding avatar.
When it comes to gaming, I won't ever let myself fall behind! Just watch me own those noobs at the next big esports competition!]],
  str_item_intro_3751404 = [[
Unlocks the corresponding avatar.
Didn't you know? I always perform magnificently on the shooting range too!]],
  str_item_3440011 = "Casket of Light",
  str_item_intro_3440011 = "Open to obtain one of the following at random: Nightium ×10,000, Nightium ×5,000, General Jasper II ×2, General Jasper I ×3, Sublime ×100, or Sublime ×50.",
  str_item_3440012 = "Box of Enlightenment",
  str_item_intro_3440012 = "Open to obtain one of the following at random: Nightium ×5,000, Nightium ×2,000, Nightium ×1,000, General Jasper II ×1, General Jasper I ×2, or Sublime ×30.",
  str_item_3440013 = "Casket of Sea",
  str_item_intro_3440013 = "Open to obtain one of the following at random: Anonymous Gift II ×1, Coalition Order Box III ×2, Nightium ×20,000, or General Jasper II ×4.",
  str_item_3440019 = "Casket of the Sea",
  str_item_intro_3440019 = "Open to obtain one of the following at random: Anonymous Gift II ×1, Coalition Order Box III ×2, Nightium ×20,000, or General Jasper II ×4.",
  str_item_3755036 = "Justice Knight Irridon",
  str_item_intro_3755036 = [[
Unlocks the corresponding avatar.
"I'm not letting any clues slip through!"]],
  str_item_3755037 = "Pam's Cuisine.",
  str_item_intro_3755037 = [[
Unlocks the corresponding avatar.
"It might not look fancy, but trust me, it tastes fantastic!"]],
  str_item_6110001 = "Stand By Me Artboard",
  str_item_intro_6110001 = [[
Stand By Me Commemorative Board.
The pattern on the board conjures images of distant visitors brought here by the sea breeze, accompanied by the gentle melody of pipa and the rustling of banners...]],
  str_item_3661221 = "Souvenir Train Model",
  str_item_intro_3661221 = [[
A gift for the audience of Charon's film premiere. This magnificent mini locomotive, as well as the famous actor's stunning performance, impressed the viewers a lot.
"Remember this sensation!"]],
  str_item_3000027 = "Heart Voucher",
  str_item_3000028 = "Heart Balloon",
  str_item_intro_3000027 = [[
Use it to vote for the Aurorian you like in the Outfit Voting Event.
"Will my fondness be felt by them?"]],
  str_item_intro_3000028 = [[
Use it to vote for the Outfit you like in the Outfit Voting Event.
"Please hand to the receiver with care, or your love might just drift away into the sky."]],
  str_item_3661222 = "Clarinet Girl Portrait",
  str_item_3661223 = "Aqua Queen Portrait",
  str_item_intro_3661222 = [[
Furniture item. Can be placed in rooms on your Colossus.
This item was originally produced as a special teapot for coffee shops, but it didn't get good reviews because of its design of having water discharge from the mouth.
"D-Don't use my appearance for something like this!"]],
  str_item_intro_3661223 = [[
Furniture item. Can be placed in rooms on your Colossus.
A fine portrait of the queen, hollowed out to reduce its weight. Someone suggested that design could be used to develop a container for Fluorophora juice, but the queen sternly rejected it.
"Ugh, why... does this always happen to me...?"]],
  str_item_3661224 = "Medical Locker",
  str_item_3661225 = "Sickbed",
  str_item_3661226 = "Cart",
  str_item_3661227 = "Row of Seats",
  str_item_intro_3661224 = [[
Furniture item. Can be placed in rooms on your Colossus.
A wooden storage locker with various bottles and jars in it. Hopefully these serums can ease the suffering of others.]],
  str_item_intro_3661225 = [[
Furniture item. Can be placed in rooms on your Colossus.
A bed made specially for patients. Come here to take a rest if you feel unwell.]],
  str_item_intro_3661226 = [[
Furniture item. Can be placed in rooms on your Colossus.
A simple medical cart. It is extremely important even though it has limited space.]],
  str_item_intro_3661227 = [[
Furniture item. Can be placed in rooms on your Colossus.
A row of seats. Maybe you can relieve your anxiety by chatting with the companions sitting around you.]],
  str_item_5234056 = "Quiet Courtyard",
  str_item_intro_5234056 = "A wonderful place for cooling off and resting. You can come here if you feel troubled by anything.",
  str_item_3000344 = "Collection Jar",
  str_item_intro_3000344 = "How much more do I need to collect before I can stop...?",
  str_item_3000345 = "Fun Voucher",
  str_item_intro_3000345 = "These ordinary-looking draw vouchers made by the Umbraton Guild are the designated currency of the Blind Box Surprise game.",
  str_item_3661228 = "Furnace-Forged Crab",
  str_item_3661229 = "Fortune Ship Model",
  str_item_intro_3661228 = [[
Furniture item. Can be placed in rooms on your Colossus.
Originally crafted by Xuan Ji to assist artisans in mechanical forging, this Longzhou automaton has lost its mobility after years of use. However, it still makes for a distinctive decorative piece.]],
  str_item_intro_3661229 = [[
Furniture item. Can be placed in rooms on your Colossus.
On the fortune ships that Longzhou folks send off to sea, numerous wishes are imbued. For example, the copper coins and mirrors embedded at the joints create the layout of the Seven Stars following the Moon, signifying good fortune and a prosperous journey. Although this one is merely a model fashioned by Xuan Ji, it doesn't skimp on the necessary details and heartfelt wishes.]],
  str_item_3763035 = "Healing Elixir",
  str_item_intro_3763035 = [[
Unlocks the corresponding avatar frame.
"Don't worry, it won't harm you..."]],
  str_item_3751554 = "Weakened",
  str_item_intro_3751554 = [[
Unlocks the corresponding Avatar.
"Cough, cough... I-I'm fine... just need a little rest."]],
  str_item_3751555 = "Heart of Gratitude",
  str_item_intro_3751555 = [[
Unlocks the corresponding Avatar.
"It's my treat today!"]],
  str_item_3751405 = "Caring Healer",
  str_item_intro_3751405 = [[
Unlocks the corresponding Avatar.
"Please, have a seat, and let me check it out."]],
  str_item_3751406 = "Strength Prevails",
  str_item_intro_3751406 = [[
Unlocks the corresponding Avatar.
"I'll hunt down anyone who dares owe you money and not pay up!"]],
  str_item_3751407 = "Deepsea Relic",
  str_item_intro_3751407 = [[
Unlocks the corresponding Avatar.
A treasure buried deep in the ocean.
It withstands constant wear and erosion from seawater, all in the hope of one day resurfacing on land.]],
  str_item_3751408 = "Xuan Ji's Invitation",
  str_item_intro_3751408 = [[
Unlocks the corresponding Avatar.
"The Caelestites held some similar beliefs as those of my own people. Would you be interested in visiting Ye for a cultural exchange?"]],
  str_item_3751556 = "Copperforge Mechanism",
  str_item_intro_3751556 = [[
Unlocks the corresponding Avatar.
"A creation of machinery without practical function. If you find it aesthetically pleasing, then it's worth having."]],
  str_item_3751409 = "Raining Gold",
  str_item_intro_3751409 = [[
Unlocks the corresponding avatar.
"Although this isn't even 1% of my wealth, there's no reason to say no to free money."]],
  str_item_3751410 = "The Shadowlord's Break",
  str_item_intro_3751410 = [[
Unlocks the corresponding avatar.
"It's almost the holidays. I should relax a little."]],
  str_item_3751557 = "Checkmate",
  str_item_intro_3751557 = [[
Unlocks the corresponding avatar.
"Don't hesitate. Take your enemies by surprise and win."]],
  str_item_3751558 = "Lucky Coin",
  str_item_intro_3751558 = [[
Unlocks the corresponding avatar.
"This lucky coin is for you, who are guaranteed to be blessed with luck in the coming year."]],
  str_item_3763036 = "Mist Snake",
  str_item_intro_3763036 = [[
Unlocks the corresponding avatar frame.
This coiling smoky snake will eventually devour everything.]],
  str_item_3751411 = "Come Drink Tea",
  str_item_intro_3751411 = [[
Unlocks the corresponding avatar.
"It's three o'clock. Do you want a cup of tea?"]],
  str_item_3751559 = "Blooming Cherry Blossom",
  str_item_intro_3751559 = [[
Unlocks the corresponding avatar.
"A strange color is cast on Hiiro's face, probably by the color of cherry blossoms that have bloomed early in a distant place."]],
  str_item_3751560 = "Geek Croquette",
  str_item_intro_3751560 = [[
Unlocks the corresponding avatar.
"Wisdom satiates me, not food."]],
  str_item_3751412 = "Wise Commander",
  str_item_intro_3751412 = [[
Unlocks the corresponding avatar.
"The Aurorians are their own enemy."]],
  str_item_3763037 = "Sakura Gift",
  str_item_intro_3763037 = [[
Unlocks the corresponding avatar frame.
The bloodline of the Sakura Family has been silently guarding Hiiro on behalf of the rest of the clan.]],
  str_item_3751561 = "Tiger Rub",
  str_item_3751562 = "Not Spicy",
  str_item_3751563 = "Mild",
  str_item_3751564 = "Moderate",
  str_item_3751565 = "Astra Spicy",
  str_item_intro_3751561 = [[
Unlocks the corresponding avatar.
"Who can resist the urge to rub their head against such a cute little tiger with such delicious powers?"]],
  str_item_intro_3751562 = [[
Unlocks the corresponding avatar.
"This level of spiciness is nothing to Rediesel Wrench."]],
  str_item_intro_3751563 = [[
Unlocks the corresponding avatar.
"The people of Ye are fond of spicy dishes. Although ultra spicy is a little too much for Dantang, she is an excellent cook and can understand the beauty of this taste."]],
  str_item_intro_3751564 = [[
Unlocks the corresponding avatar.
"You must always eat in an elegant manner! Carleen keeps reminding herself that she can't forget the dinner etiquette of the Lumo Knights just because of the stimulation in her mouth."]],
  str_item_intro_3751565 = [[
Unlocks the corresponding avatar.
"Ahhhhhhhhh! Astra spicy! That's the first thing the starling said after eating the chili sauce."]],
