  str_item_9997034 = "Shatterboots",
  str_item_9997039 = "Lucky Coin",
  str_item_9997040 = "Double Echoes",
  str_item_9997041 = "Floating Icer",
  str_item_9997042 = "Floating Scorcher",
  str_item_9997043 = "Floating Forestwrath",
  str_item_9997044 = "Floating Thunder",
  str_item_9997045 = "Daybreak Dish",
  str_item_9997046 = "Stun Crystal",
  str_item_9997047 = "Magic Lumina Box",
  str_item_intro_9997004 = "Reload a bandage on the field when a battle begins.",
  str_item_intro_9997005 = "Grants a Shield by 20% of Max HP that lasts for 2 rounds at the beginning of the battle.",
  str_item_intro_9997008 = "Restores HP to 30% at the beginning of the battle if current HP is lower than 30%.",
  str_item_intro_9997009 = "Lose 7% of current HP at the beginning of each round. After that, deals damage equal to 150% of the team's average ATK to enemies within 2 surrounding clusters.",
  str_item_intro_9997010 = "Increases Aurorians' Active Skill damage by 50%. Lose 8% of current HP each time an Active Skill is cast.",
  str_item_intro_9997011 = "Increases Chain Combo damage by up to 40% according to the percentage of HP lost by allies.",
  str_item_intro_9997012 = "Increases Aurorian damage by 20% when the current HP is higher than 70%.",
  str_item_intro_9997013 = "When attacking 3 or more enemies at the same time, casts a thunderbolt that attacks all enemies, dealing damage equal to 100% of the team's average ATK.",
  str_item_intro_9997014 = "Generates 1 chromatic tile randomly on the field at the beginning of each round.",
  str_item_intro_9997015 = "When removing at least 15 tiles at once with a tap, increases Aurorians' Chain Combo damage by 30%. The Chain Combo can't be cast if less than 8 tiles are removed at once.",
  str_item_intro_9997016 = "The closer they are to an enemy, the higher the damage of Aurorians' Chain Combo, increasing it up to 20%.",
  str_item_intro_9997017 = "The farther they are from an enemy, the higher the damage of Aurorians' Chain Combo, increasing it by up to 30%.",
  str_item_intro_9997018 = "Detonator Aurorians have a 30% chance to cast the Chain Combo 1 additional time.",
  str_item_intro_9997019 = "Increases the number of targets of Sniper Aurorians' Chain Combo by 1.",
  str_item_intro_9997020 = "Supporter Aurorians +25% regeneration effects from Chain Combos and Active Skills in battle.",
  str_item_intro_9997021 = "At the beginning of the battle, reduces Converter Aurorians' Active Skill cooldown by 1.",
  str_item_intro_9997023 = "When the Active Skills or Chain Combo Skills cast by Aurorians deal damage, there is a 30% chance to immediately settle the target's Poisoned/Burning/Bleeding effects once.",
  str_item_intro_9997024 = "All damage taken by enemies who are debuffed or under debuff effects increases by 20%.",
  str_item_intro_9997025 = "Defeats enemies under 7% HP.",
  str_item_intro_9997026 = "After tapping to remove tiles, if Aurorians have not cast the Chain Combo in this round, reduces the cooldown of all Aurorian's Active Skill by 1.",
  str_item_intro_9997027 = "Converts a percentage of Aurorians' excess healing into one stack of Shield that lasts for 1 round.",
  str_item_intro_9997028 = "When a Poisoned/Burning/Bleeding enemy is defeated, inflicts another random enemy on the battlefield with 1 stack of Poisoned.",
  str_item_intro_9997029 = "Reduces the number of tiles that need to be removed to trigger the faction support skill by 5.",
  str_item_intro_9997030 = "When an Aurorian casts an Active Skill, reduces the cooldown of the Active Skills of Aurorians who have a bond with them by 1.",
  str_item_intro_9997031 = "Reduces the cooldown of the first Active Skill cast in battle by 2.",
  str_item_intro_9997033 = "An indicator spawns randomly in the battlefield at the beginning of each round. After destroying this indicator, Chain Combo damage is increased by 25% in this round.",
  str_item_intro_9997035 = "Aurorians gain 2% Life Drain when dealing damage and lose 15% of their current HP at the beginning of each round.",
  str_item_intro_9997003 = "Restores 10% of Max HP after winning a battle.",
  str_item_intro_9997006 = "Increases the Max HP of all Aurorians by 3% after winning a battle.",
  str_item_intro_9997007 = "Increases the DEF of all Aurorians by 1.5% after winning a battle.",
  str_item_intro_9997032 = "Increases the ATK of all Aurorians by 1% after winning a battle.",
  str_item_intro_9997022 = "Total number of rounds +10 when obtaining this item. ",
  str_item_intro_9997036 = "When tapping to remove tiles, there is a 25% chance to increase the number of removal attempts by 1.",
  str_item_intro_9997037 = "When tapping to remove tiles, randomly inflicts 1 stack of Poisoned, Bleeding, or Burning to the enemies within range of the removed tiles.",
  str_item_intro_9997038 = "When tapping to remove tiles, deals damage equal to 120% of the team's average ATK to the enemies within range of the removed tiles.",
  str_item_intro_9997034 = "Enemies receive damage equal to 150% of the team's average ATK once for every tile they move on within the area of tiles that have been tapped on and will be removed in this round.",
  str_item_intro_9997039 = "At the beginning of the battle, 1 random Special Caelestite Gear can be used once.",
  str_item_intro_9997040 = "Obtain Special Caelestite Gear: Converts 2 selected tiles to chromatic tiles. This can be used once for every 60 tiles that are removed.",
  str_item_intro_9997041 = "Obtain Special Caelestite Gear: Selects a 3×3 area and removes all Blue tiles within it. This can be used once for every 50 tiles that are removed.",
  str_item_intro_9997042 = "Obtain Special Caelestite Gear: Selects a 3×3 area and removes all Red tiles within it. This can be used once for every 50 tiles that are removed.",
  str_item_intro_9997043 = "Obtain Special Caelestite Gear: Selects a 3×3 area and removes all Green tiles within it. This can be used once for every 50 tiles that are removed.",
  str_item_intro_9997044 = "Obtain Special Caelestite Gear: Selects a 3×3 area and removes all Yellow tiles within it. This can be used once for every 50 tiles that are removed.",
  str_item_intro_9997045 = "Obtain Special Caelestite Gear: Resets all tiles on the battlefield. This can be used once for every 80 tiles that are removed.",
  str_item_intro_9997046 = "Obtain Special Caelestite Gear: Selects 1 color and resets all tiles of this color from the battlefield. This can be used once for every 80 tiles that are removed.",
  str_item_intro_9997047 = "Obtain Special Caelestite Gear: Selects 1 tile and removes the 4 nearest tiles of the same color. This can be used once for every 60 tiles that are removed.",
  str_item_rpintro_9997004 = "Auxiliary for recovery potion to help heal the wounded.",
  str_item_rpintro_9997005 = "Classic old-era weapon etched with blessed glyphs and particularly effective against nimble enemies.",
  str_item_rpintro_9997008 = "Perfectly preserved statue that provides healing power to its bearer.",
  str_item_rpintro_9997009 = "Old-era item that both curses the user and bestows equal power in return.",
  str_item_rpintro_9997010 = "Allegedly a mystery item from the previous apocalyptic war. It carries a powerful curse that is strong enough to seriously wound opponents.",
  str_item_rpintro_9997011 = "Put this on to turn agony into strength and, ultimately, attain victory.",
  str_item_rpintro_9997012 = "Carry it and you will be protected by the Goddess of Victory, winning you all of your battles.",
  str_item_rpintro_9997013 = "Famous blade from the old era, enchanted with the power of thunder. The explosive wrath is apparent upon drawing.",
  str_item_rpintro_9997014 = "A gem that shines in every color, splendid and ever-changing.",
  str_item_rpintro_9997015 = "Old-era great sword that when held, you can feel the power within you grow.",
  str_item_rpintro_9997016 = "Classic old-era weapon etched with blessed glyphs and particularly effective against nimble enemies.",
  str_item_rpintro_9997017 = "Classic old-era weapon etched with blessed glyphs and particularly effective against nimble enemies.",
  str_item_rpintro_9997018 = "Ancient short, keen blade made from old-era superalloy.",
  str_item_rpintro_9997019 = "The lenses glow in battle, blinding the opponent while protecting the wearer from it. Auxiliary equipment.",
  str_item_rpintro_9997020 = "Old-era paint able to absorb Lumina.",
  str_item_rpintro_9997021 = "Old-era creation that seems very pretty but carries terrifying power, dropping enemies like falling flowers with explosions.",
  str_item_rpintro_9997023 = "Relic from the old era, possibly strongly cursed. Wearer becomes lethal with toxins.",
  str_item_rpintro_9997024 = "Famous old-era sword. Wielder can feel godlike power.",
  str_item_rpintro_9997025 = "It can sense enemy's life force and end those who are near death's door when carried closely.",
  str_item_rpintro_9997026 = "A very form-fitting belt that provides the wearer with the necessary Lumina when activated under certain requirements.",
  str_item_rpintro_9997027 = "Unknown device from the old era that can sense and convert overflowing Lumina into protective force field for the wearer.",
  str_item_rpintro_9997028 = "Purportedly a cursed item made by a mighty warrior to ensure the doom of all enemies.",
  str_item_rpintro_9997029 = "Talisman for the old era, able to secure Lumina on a micro level, dealing great damage to enemies.",
  str_item_rpintro_9997030 = "Old-era item to regenerate a certain amount of Lumina for bonded Aurorians.",
  str_item_rpintro_9997031 = "Use this old-era item to quickly regain a portion of lost Lumina.",
  str_item_rpintro_9997033 = "Device for storing and replenishing Lumina.",
  str_item_rpintro_9997035 = "Oversized blade with palpable nastiness. Likely used for death duels in ancient times. There will be blood when used.",
  str_item_rpintro_9997003 = "Candle giving off warm glows that can heal wounded Aurorians.",
  str_item_rpintro_9997006 = "A lost statuette from the old era made from high-grade materials. Durable, light, and blesses those who carry it.",
  str_item_rpintro_9997007 = "Ancient shield from the old era, in perfect oval and supposedly infused with the power of the sun to deflect all lethal strikes.",
  str_item_rpintro_9997032 = "Old-era badge with wondrous setup to secure Lumina on a micro level, improving combat prowess.",
  str_item_rpintro_9997022 = "Lost and forgotten sleeping bag. Helps recover strength.",
  str_item_rpintro_9997036 = "Seemingly written by ancient scholars, it details the nuances in element counter effect and provides effective strategic suggestions.",
  str_item_rpintro_9997037 = "Ancient painting by an anonymous painter that portrayed the atrocity of the plague. The artist also died in the pandemic, after which it possessed terrifying power...",
  str_item_rpintro_9997038 = "A weapon that seems to be able to fuse with Lumina perfectly... This is rare indeed...",
  str_item_rpintro_9997034 = "Old-time item created specifically to deal with pursuers. Leaves Lumina on the trail that detonates later to kill the pursuers.",
  str_item_rpintro_9997039 = "Mysterious ancient coin that occasionally boosts the speed of its Aurorian owner, granting more agility.",
  str_item_rpintro_9997040 = "Rare red orchids specially developed in the old era. They always appear, blossom, and wither in pairs. Seems to form a bond with the wearer and assist in combat.",
  str_item_rpintro_9997041 = "Seemingly miniaturized Colossus from the old era that assists the owner in battle.",
  str_item_rpintro_9997042 = "Seemingly miniaturized Colossus from the old era that assists the owner in battle.",
  str_item_rpintro_9997043 = "Seemingly miniaturized Colossus from the old era that assists the owner in battle.",
  str_item_rpintro_9997044 = "Seemingly miniaturized Colossus from the old era that assists the owner in battle.",
  str_item_rpintro_9997045 = "Old-era item that creates mysterious bonds between two combatants.",
  str_item_rpintro_9997046 = "Coarse crystal with slightly cracked surface that indicates excess Lumina within. Just a soft touch can unleash enough Lumina to stun enemies in a battle.",
  str_item_rpintro_9997047 = "Old-era technology. It stores much more Lumina than the small size indicates.",
  str_item_3000349 = "Cloudrover Token",
  str_item_intro_3000349 = "A token that can be exchanged for benefits from the Cloudrover Guild. Only loyal customers have the chance to get this.",
  str_item_3000134 = "Avaricious Lachesis Special Star Flare",
  str_item_intro_3000134 = [[
Can be used to recruit once from the current exclusive recruitment.
This item will expire, so please use it before the end of the current Avaricious Lachesis exclusive recruitment, or else it will disappear. It will not be converted into another item when it expires.]],
  str_item_3420133 = "2.5-Year Recruitment Kit",
  str_item_intro_3420133 = [[
Choose an Aurorian from the following 6-star Aurorian list to fight beside you: <color=#ffffff>Dantang, Zarya, Antony, Lorelei, Cena, Joshua, Schwartz: Almighty Clamor, Yingel, Leo, Hati, Tina, Leyn, Jeriah, Mu Yuebai, Zhong Xu, Vic, Axelia, Lilica, Minos, Pollux, Jeno, Fia, Carleen: Smoldering Soul, Nina, Barton: Deft Blades, Giles, Lenore, Azure, Yao, Amemori, Rinne, Florine, Ruby, Siobhan, Novio, Hedy, Bethel, Luke, Paloma, Gram, Revy, Smokey, Fleur, Beryl, Hiiro, Sinsa, Eve, Uriel, Carleen, Sharona, Sariel, Raphael, Connolly, Charon, Eicy, Victoria, Jona, Nikinis, Gabriel, Migard, Michael, Gronru, Irridon, Wrath.</color>.
Note: This kit will expire at 09:00, 28 February 2024 (UTC+0), 04:00, 28 February 2024 (UTC-5). Claim it on time, or it will be automatically converted into 3,000 Lumamber and sent to you via your in-game mailbox.]],
  str_item_3661231 = "Shadow Throne",
  str_item_intro_3661231 = [[
Furniture item. Can be placed in rooms on your Colossus.
The Cloudrover Guild specially made this luxurious and domineering chair out of stiff leather for Istvan. As it is such a gimmicky product, there has been no shortage of buyers despite its costly price tag.]],
  str_item_3661232 = "Cloudrover Airship Model",
  str_item_intro_3661232 = [[
Furniture item. Can be placed in rooms on your Colossus.
Given the popularity of the Cloudrover Airship, a one-stop destination that meets all your tourism, shopping, recreation, and vacation needs, it's natural that models of this airship are available in various sizes for customers to purchase. Although this particular model isn't the largest one, it is made with the most exquisite workmanship.]],
  str_item_3661233 = "Festive Lights",
  str_item_intro_3661233 = [[
Furniture item. Can be placed in rooms on your Colossus.
Illuminate dark spaces with rows of these colored lights. Hopefully, their faint light will give you some warmth on this day worth celebrating.]],
  str_item_3661234 = "Festive Gift Box",
  str_item_intro_3661234 = [[
Furniture item. Can be placed in rooms on your Colossus.
The Aurorians have given you this thoughtful gift. Although it isn't worth much, its true value lies in the hard work and effort it represents. May this gift bring you good luck in the coming year.]],
  str_item_5234057 = "Ice Chariot",
  str_item_intro_5234057 = "An ornamental chariot made out of ice. Its crystalline appearance is extremely soothing and relaxing.",
  str_item_3661236 = "Outfit-Changing Swordfighter Portrait",
  str_item_3661237 = "Boating Swordfighter Portrait",
  str_item_3661241 = "Bool's Fan",
  str_item_3661242 = "Plant Lamp",
  str_item_intro_3661236 = [[
Furniture item. Can be placed in rooms on your Colossus.
The handiwork of a certain artisan, this doll can change into another random outfit quickly at the press of a button. It's said that this doll is inspired by a type of performance art of Longzhou.
"If I want to play the role of a person from Longzhou... would I also need to learn how to change my outfit instantly like this?"]],
  str_item_intro_3661237 = [[
Furniture item. Can be placed in rooms on your Colossus.
To commemorate the successful cooperation with the swordfighter, the artisan made a portrait based on the swordfighter's stance when completing a quest.
"You want to leave the seat on the other side of the boat empty? Sure, just tell me when you want to add someone there."]],
  str_item_intro_3661241 = [[
Furniture item. Can be placed in rooms on your Colossus.
This fan is used exclusively in the laboratory of Illumina scientists. Its legs can be bent flexibly or attached to surfaces. Some say that this fan is inspired by a robot called Bool.]],
  str_item_intro_3661242 = [[
Furniture item. Can be placed in rooms on your Colossus.
An exquisitely designed lamp that provides plants with the light they need to grow and creates a warm and natural mood indoors.]],
  str_item_3000352 = "Caelestite Feather",
  str_item_intro_3000352 = "This unique looking feather is said to be extremely valuable to the Caelestites.",
  str_item_3661243 = "Dumpling Sofa",
  str_item_3661244 = "New Year Artwork: The Dragon",
  str_item_3661238 = "Firecracker Decor",
  str_item_3661239 = "New Year Pendant",
  str_item_3661240 = "Quaint Shelf",
  str_item_intro_3661243 = [[
Furniture item. Can be placed in rooms on your Colossus.
Dumpling-shaped lazy sofa, with a voice box that was once alive with chants:
"Dumplings, a myriad of dumplings!"
"Let's all make dumplings together!"
Now, the voice device has been removed by noise-weary Aurorians, restoring tranquility inside the Colossus.]],
  str_item_intro_3661244 = [[
Furniture item. Can be placed in rooms on your Colossus.
A New Year's painting of the Dragon Maiden, a popular Ji Kingdom festive item. But this "artistic portrait" given by Chen'ni is the only one that accurately portrays the appearance of the Dragon Maiden.]],
  str_item_intro_3661238 = [[
Furniture item. Can be placed in rooms on your Colossus.
As Longzhou's traditional festival nears, to let our Longzhou friends on the Colossus feel the festive atmosphere, everyone on the Colossus hangs the jointly-made firecracker decorations, hoping to ward off misfortune and invite good luck.]],
  str_item_intro_3661239 = [[
Furniture item. Can be placed in rooms on your Colossus.
Currently a best-seller in Twin Pavilions Bay, it is a must-have Longzhou decoration during festive times, symbolizing hope for a bright future.]],
  str_item_intro_3661240 = [[
Furniture item. Can be placed in rooms on your Colossus.
Crafted by Twin Pavilions Bay artisans, this wooden shelf is intricately carved and designed for both storage and admiration, enriching the Colossus' chambers with a touch of classic elegance.]],
  str_item_intro_3763039 = [[
Unlocks the corresponding avatar frame.
"The peach blossoms are delicate and graceful, radiating their resplendent beauty. And fortune comes, in their vibrant embrace."]],
  str_item_intro_3751417 = [[
Unlocks the corresponding avatar.
"Caelestite received a special hat as a New Year's gift and happily put it on!"]],
  str_item_intro_3751566 = [[
Unlocks the corresponding avatar.
"Chen'ni bestows blessings, granting wealth and prosperity!"
Can the Dragon Maiden, revered as a sea deity, truly bestow happiness to the mundane world? Chen'ni may not know, but she's determined to try!]],
  str_item_intro_3751567 = [[
Unlocks the corresponding avatar.
"My palate is the standard!"
As Astra's envoy, the Navigator is super experienced in food tasting, boasting a refined palate.]],
  str_item_intro_3763038 = [[
Unlocks the corresponding avatar frame.
"Collect all the Spring Cards to summon the divine dragon!"
Not sure if it's true, but this card-collecting craze made Longzhou's New Year a lot more fun.]],
  str_item_intro_3751413 = "Unlocks the corresponding avatar.\n\"I've got a long list of things I'd like to see—the giant mechanized armor on Azurite, the noisy shows in the desert, the intense underground fight-offs...\"\nEven a deity has many wishes for the New Year.",
  str_item_intro_3751414 = [[
Unlocks the corresponding avatar.
Watch out for the Nian beast of Umbraton, a real man-eater with long horns! Check out "Forbidden Temple Fair," Alleywood's latest horror film, coming this spring!
"So... what's my part again...?"]],
  str_item_intro_3751415 = [[
Unlocks the corresponding avatar.
"Here you go, just a little something I whipped up... I can make things other than popsicles, you know!"
The only thing Zarya successfully made after countless failures, with extra sweetness to manifest her feelings.]],
  str_item_intro_3751416 = [[
Unlocks the corresponding avatar.
Hoping today's reunion brings you sense of home and strength. It's the same sky above us, wherever we are.]],
  str_item_intro_3751568 = [[
Unlocks the corresponding avatar.
"Though many express their fondness for me, I find the Navigator the most special. We truly share a heart-to-heart connection!"]],
  str_item_intro_3751569 = [[
Unlocks the corresponding avatar.
"Hand heart, really?... Okay, take this gesture of mine and be thankful... but don't get too carried away!"]],
  str_item_3763039 = "Blossom of Fortune",
  str_item_3751417 = "Caelestite with Dragon Hat",
  str_item_3751566 = "Longzhou Dragon Maiden in Dragon Year",
  str_item_3751567 = "Foodie Envoy",
  str_item_3763038 = "Springtime Dragon Soar",
  str_item_3751413 = "New Year Wish",
  str_item_3751414 = "Festive Ensemble",
  str_item_3751415 = "Sweet Delight",
  str_item_3751416 = "Big Reunion",
  str_item_3751568 = "Fleur's Regard",
  str_item_3751569 = "Zarya's Regard",
  str_item_3763041 = "Thousand-Day Crown",
  str_item_3751420 = "Mooncrown Knight's Day",
  str_item_3751419 = "Spanning a Thousand Nights",
  str_item_3751570 = "Burning Limbo",
  str_item_3763040 = "Final Blaze",
  str_item_3751421 = "Thousand-Day Heart",
  str_item_3751422 = "Lovedrop Arrow",
  str_item_intro_3751421 = [[
Unlocks the corresponding avatar.
"Navigator, this way!"
Love has been your constant companion in this journey for a thousand days. Keep forging ahead with the blessings of all!]],
  str_item_intro_3751422 = [[
Unlocks the corresponding avatar.
"Seize the moment; today could be the turning point in our fate!"]],
  str_item_intro_3763041 = [[
Unlocks the corresponding avatar frame.
"Those who are steadfast shall be rewarded with glory!"
Thanks for your guidance and protection throughout a thousand days of perseverance and companionship. Look forward to future adventures together.]],
  str_item_intro_3751420 = [[
Unlocks the corresponding avatar.
"Do you also want to participate in the special trial of Mooncrown Day?"]],
  str_item_intro_3751419 = [[
Unlocks the corresponding avatar.
Navigator, thanks for accompanying me for a thousand days under this sky. Please continue to guide me in the future!]],
  str_item_intro_3751570 = [[
Unlocks the corresponding avatar.
"You want to be in the Limbo with me? Take my hand then, and let our hopes burn bright!"]],
  str_item_intro_3763040 = [[
Unlocks the corresponding avatar frame.
"My outfit will burst into flame when the potion wears off. Will you follow the last trail of the blaze to me?"]],
  str_item_3751042 = "Traveler's Messages",
  str_item_3751043 = "Fruits of Training",
  str_item_3751044 = "Truth Endures",
  str_item_3751045 = "Guardian on the Journey",
  str_item_3751046 = "Tea Party Regular",
  str_item_3751047 = "My Story",
  str_item_3751048 = "Brothers in Arms",
  str_item_3751573 = "Hiding Fox",
  str_item_3763042 = "Top Croaker",
  str_item_intro_3751042 = [[
Unlocks the corresponding avatar.
"I understand how tough the path is for a Navigator. Keep up the good work."]],
  str_item_intro_3751043 = [[
Unlocks the corresponding avatar.
"Holding out for this long is truly commendable. Let's keep training together in the future!"]],
  str_item_intro_3751044 = [[
Unlocks the corresponding avatar.
"Always remember: no matter how time changes, truth endures."]],
  str_item_intro_3751045 = [[
Unlocks the corresponding avatar.
"In the journeys to come, I'll always keep you safe."]],
  str_item_intro_3751046 = [[
Unlocks the corresponding avatar.
"How many times have I treated you to afternoon tea?"]],
  str_item_intro_3751047 = [[
Unlocks the corresponding avatar.
"I've shared my story with you; what's yours?"]],
  str_item_intro_3751048 = [[
Unlocks the corresponding avatar.
"After so much time together, we're already true brothers!"]],
  str_item_intro_3751573 = [[
Unlocks the corresponding avatar.
"Are you done hiding?" "Not yet."]],
  str_item_intro_3763042 = [[
Unlocks the corresponding avatar frame.
"Looks somewhat familiar."]],
  str_item_intro_3751423 = [[
Unlocks the corresponding Avatar.
"Ribbit! Ribbit!! Ribbit!!!"]],
  str_item_intro_3751424 = [[
Unlocks the corresponding avatar.
"What should I do... The answer has always been in my heart?"]],
  str_item_3751423 = "Prince Lilypad",
  str_item_3751424 = "Answers Beneath the Lighthouse",
  str_item_3440014 = "Wonder Bag",
  str_item_intro_3440014 = "I am just a poor frog who has given you all my life savings.",
  str_item_intro_3440015 = "The rewards offered in the super value fortune bag are often deceptive.",
  str_item_intro_3440016 = "Good luck ascends in a stair-step manner, much like my life.",
  str_item_intro_3440017 = "Draw one more time; it feels like we're getting close to the guaranteed reward.",
  str_item_intro_3440018 = "This is my last attempt! Then I'll just tap Back, close the screen, and exit the game.",
  str_item_3751574 = "Introducing: Goldie the Idol",
  str_item_intro_3751574 = [[
Unlocks the corresponding Avatar.
"All eyes are on her; she is the epitome of perfection and radiance, the ultimate idol."]],
  str_item_3751425 = "Idol's Weariness",
  str_item_intro_3751425 = [[
Unlocks the corresponding Avatar.
"Yawn! I feel so sleepy from the moment I changed into these pajamas."]],
  str_item_3763043 = "Marshmallow I Picked",
  str_item_intro_3763043 = [[
Unlocks the corresponding Avatar Frame.
"The graceful figure charms with its adorable fluff, ensnaring another in its enchanting web."]],
  str_item_3751572 = "Where's Father",
  str_item_intro_3751572 = [[
Unlocks the corresponding avatar.
"Father, please inform me of your current location."]],
  str_item_3751571 = "Blessing of Smiles",
  str_item_intro_3751571 = [[
Unlocks the corresponding avatar.
"I gift this component to Father, wishing his expression aligns with the one displayed on the screen."]],
  str_item_3751429 = "Hello Toto",
  str_item_intro_3751429 = [[
Unlocks the corresponding avatar.
"Hello, Toto! The warm Colossus shelters every broken-hearted laborer."]],
  str_item_3751430 = "Badges and Honor",
  str_item_3751577 = "Eagleeye Squad, assemble!",
  str_item_3751578 = "Carnival Confetti",
  str_item_3751579 = "Eternal Companionship",
  str_item_3763046 = "Great Blessings",
  str_item_3763047 = "Koinobori",
  str_item_intro_3751430 = [[
Unlocks the corresponding avatar.
"Very good. I didn't tarnish my honor today."]],
  str_item_intro_3751577 = [[
Unlocks the corresponding avatar.
"Your gaze must be keen like a hawk's gaze, your attacks must be as sharp as its talons, and your movements must be as fast as its flapping wings."]],
  str_item_intro_3751578 = [[
Unlocks the corresponding avatar.
"Say it with me: HAPPY CARNIVAL!"]],
  str_item_intro_3751579 = [[
Unlocks the corresponding avatar.
"May all things in this world lend themselves to the realization of your wishes for all of eternity."]],
  str_item_intro_3763046 = [[
Unlocks the corresponding avatar frame.
"I wish everything goes your way. I wish you are unstoppable. I wish you achieve everything you desire. I wish you always persevere. I wish you always be with me so that we can share even more happy moments together!"]],
  str_item_intro_3763047 = [[
Unlocks the corresponding avatar frame.
This totem banner that is popular throughout Cloud Island is a symbol of growth and courage.]],
  str_item_3751581 = "Touching Sensations",
  str_item_3751582 = "Yum-Yum",
  str_item_3751580 = "Hidden Fangs Owner",
  str_item_intro_3751581 = [[
Unlocks the corresponding Avatar.
"Oh, is this... what it feels like to be loved by someone?"]],
  str_item_intro_3751582 = [[
Unlocks the corresponding Avatar.
"One more bite... Yes, one more bite!"]],
  str_item_intro_3751580 = [[
Unlocks the corresponding Avatar.
"I'm the owner of Hidden Fangs in Umbraton. Welcome to the gaming world!"]],
  str_item_3751436 = "Determined Gaze",
  str_item_3751583 = "Flames of Rebellion",
  str_item_3751584 = "Honored Guest",
  str_item_3751585 = "Toast to Our Friendship",
  str_item_3763048 = "Illumina's Future Prospects",
  str_item_3763049 = "Secret Tomb Key",
  str_item_intro_3751436 = [[
Unlocks the corresponding avatar.
"It's wonderful to have you all here!"]],
  str_item_intro_3751583 = [[
Unlocks the corresponding avatar.
"You'll need to be stronger. Stronger than the strongest Aurorians in the world."]],
  str_item_intro_3751584 = [[
Unlocks the corresponding avatar.
"Even if I die today, I still want to see your true face."]],
  str_item_intro_3751585 = [[
Unlocks the corresponding avatar.
"Approaching him is perfectly acceptable, but I ask that you conduct yourselves with a bit more dignity. After all, he's here at my request."]],
  str_item_intro_3763048 = [[
Unlocks the corresponding avatar frame.
"But don't worry. Nothing can ever stay the same, and while some changes can really weigh us down, more often than not, change is exciting."]],
  str_item_intro_3763049 = [[
Unlocks the corresponding avatar frame.
"Can one reveal the secrets guarded by the Black Box by the faint light of a mere candle?"]],
  str_item_3751438 = "Truth Insight",
  str_item_3751586 = "Enlightened One",
  str_item_3763050 = "Shining Road",
  str_item_intro_3751438 = [[
Unlocks the corresponding avatar.
"Truth seekers are like those who chase far-off stars; they require sincere eyes to see the light."]],
  str_item_intro_3751586 = [[
Unlocks the corresponding avatar.
"I confess! I atone! I... I am the one blessed by truth."]],
  str_item_intro_3763050 = [[
Unlocks the corresponding avatar frame.
"May the Truth bless you, and may your life henceforth shine bright."]],
  str_item_3751426 = "Ryza's Aura",
  str_item_3751427 = "Klaudia's Smile",
  str_item_3751428 = "Patricia's Tenacity",
  str_item_3751575 = "Toward a New Adventure",
  str_item_3751576 = "Splendid Summer Flower",
  str_item_3751587 = "Ambitious Naval King",
  str_item_3751588 = "Water Drone",
  str_item_3763044 = "Sparkling Reverie",
  str_item_3763045 = "Glistening Sea Breeze",
  str_item_3763051 = "Capture The Summer",
  str_item_3763052 = "Filthy Rich",
  str_item_3763053 = "Oath Angel",
  str_item_3751444 = "Please Have Fun",
  str_item_3751443 = "The Elf at Sea",
  str_item_3751589 = "Fairy Tale Princess",
  str_item_3751594 = "Acheron Hunter",
  str_item_3751593 = "Gilded Serpent",
  str_item_3751592 = "Oath Reader",
  str_item_3751591 = "Claymore",
  str_item_intro_3751594 = [[
Unlocks the corresponding avatar.
"Black wings slice through the sky over the Acheron like a sharp blade."]],
  str_item_intro_3751593 = [[
Unlocks the corresponding avatar.
"Whether it's business or just for fun, with enough gold, I'm at your service!"]],
  str_item_intro_3751592 = [[
Unlocks the corresponding avatar.
"The millennia-old oath shall not be forgotten. A token of the Longinus clan's gratitude, granted only to those who complete a true hero's journey."]],
  str_item_intro_3751591 = "Unlocks the corresponding avatar.\n\"Show no mercy—my blade is here to guard the tales of the stars.\"",
  str_item_intro_3763052 = [[
Unlocks the corresponding avatar frame.
"Gold is blinding!"]],
  str_item_intro_3763053 = [[
Unlocks the corresponding avatar frame.
"Black wings are the keepers of a millennium-old oath."]],
  str_item_intro_3751444 = [[
Unlocks the corresponding avatar.
"Look at the competitors, fully engaged and striving for their ranks. Please enjoy this game and show your support!"]],
  str_item_intro_3751443 = [[
Unlocks the corresponding avatar.
"I'm fond of water and love swimming. Should I join the competition and have some fun with everyone?"]],
  str_item_intro_3751589 = [[
Unlocks the corresponding avatar.
"I want to have a beautiful dream, where there's no sorrow and happiness lasts forever..."]],
  str_item_intro_3751426 = [[
Unlocks the corresponding avatar.
"What's this? How touching..."]],
  str_item_intro_3751427 = [[
Unlocks the corresponding avatar.
"Welcome back. How was your adventure? Did you see anything particularly interesting?"]],
  str_item_intro_3751428 = [[
Unlocks the corresponding avatar.
"Ah, sorry for letting you see such an embarrassing side of me. I'll be sure to keep my composure next time."]],
  str_item_intro_3751575 = [[
Unlocks the corresponding avatar.
"Off to a new adventure!"]],
  str_item_intro_3751576 = [[
Unlocks the corresponding avatar.
"Spending the summer with friends is the best!"]],
  str_item_intro_3751587 = [[
Unlocks the corresponding avatar.
"Since this stubbornness can conquer the land, facing the sea shouldn't be a problem... right?"]],
  str_item_intro_3751588 = [[
Unlocks the corresponding avatar.
"Beep-beep, activating water navigation mode..."]],
  str_item_intro_3763044 = [[
Unlocks the corresponding avatar frame.
"Everyone who bathes in this light will feel their hearts becoming brighter."]],
  str_item_intro_3763045 = [[
Unlocks the corresponding avatar frame.
"Coming to Astra is the most surprising accident this summer!"]],
  str_item_intro_3763051 = "Unlocks the corresponding avatar frame.\n\"A fashionable swim ring that makes one long for the sea at first glance. Don't miss the fleeting summer—act quickly and use it to embrace the season!\"",
  str_item_3661248 = "Ancient Hero's Statue",
  str_item_3661249 = "Ancient Officer's Statue",
  str_item_intro_3661248 = [[
Furniture item. Can be placed in rooms on your Colossus.
An ancient statue, recently unearthed and identified as a civilian warrior honored in bygone times based on its attire and headgear. Archaeologists note that only nobles had the right to commission their statues during that era, which means he must have earned feats so remarkable that folks created this statue in admiration.
"I shall protect the world she cherished!"]],
  str_item_intro_3661249 = [[
Furniture item. Can be placed in rooms on your Colossus.
An ancient statue, recently unearthed and identified as a high-ranking officer in the military based on its attire and headgear. Archaeologists note that military officers were almost exclusively of noble birth during that era. So, unlike the statue of a civilian warrior, this one likely came from the hands of a sculptor dedicated to serving nobility.
"Leave the rest to me; I will take care of it."]],
  str_item_3661250 = "Snow Fox Statue",
  str_item_3661251 = "Pine Candlestick",
  str_item_3661252 = "Robyn's Bookshelf",
  str_item_3661253 = "Collector's Stereo",
  str_item_3661254 = "Leisure Low Table",
  str_item_intro_3661250 = [[
Furniture item. Can be placed in rooms on your Colossus.
A beloved statue among the Northlanders, supposedly modeled after a guard of the Northland, created to honor a significant comrade lost in battle.]],
  str_item_intro_3661251 = [[
Furniture item. Can be placed in rooms on your Colossus.
Made from the finest pine wood, this atmospheric candlestick releases a delicate pine fragrance, aiding in relaxation and sleep.]],
  str_item_intro_3661252 = [[
Furniture item. Can be placed in rooms on your Colossus.
A simple-shaped bookshelf made of high-quality wood, it exudes a subtle fragrance.]],
  str_item_intro_3661253 = [[
Furniture item. Can be placed in rooms on your Colossus.
An elegant stereo perfect for solemn events. Its tone color is more suitable for a ceremonial procession rather than the heavy metal music Ansia loves.]],
  str_item_intro_3661254 = [[
Furniture item. Can be placed in rooms on your Colossus.
A stylish and budget-friendly table perfect for leisure moments of urban residents, a bestseller anywhere.]],
  str_item_3661256 = "Vintage Clock",
  str_item_3661257 = "Decorative Painting Moonlit Night",
  str_item_3661258 = "Harehound Plushie",
  str_item_3661260 = "Rediesel Grill",
  str_item_intro_3661256 = [[
Furniture item. Can be placed in rooms on your Colossus.
The metal frame of this clock is elegantly crafted, and its face has been specially treated to produce a bronze luster over time.]],
  str_item_intro_3661257 = [[
Furniture item. Can be placed in rooms on your Colossus.
A beautiful decorative painting of the moon set against the night sky. From the center of the painting, it emits a soft and gentle glow.]],
  str_item_intro_3661258 = [[
Furniture item. Can be placed in rooms on your Colossus.
A beagle-shaped doll. Its eyes seem to say, "I see it, I want it, and I gotta have it!"]],
  str_item_intro_3661260 = "Furniture item. Can be placed in rooms on your Colossus.\nThe most common grill found in the Rediesel Wrench's camps. Though largely constructed out of scrap metal, this grill gives food an irresistibly charred flavor—Or at least the Rediesel Wrench seems to think so.",
  str_item_3661265 = "Elegant Traveler's Portrait",
  str_item_3661266 = "Grotesque Carrot Statue",
  str_item_intro_3661265 = [[
Furniture item. Can be placed in rooms on your Colossus.
Legends speak of a traveler who built the sweet town of Folta in a land of endless milk and honey...
"Where exactly is this town? Could it be... In a completely different world?"]],
  str_item_intro_3661266 = [[
Furniture item. Can be placed in rooms on your Colossus.
For children who hate eating carrots, its glowing, green eyes and sharp claws are more terrifying than any Eclipsite...
"Po... But I'm Popo, a poor, little carrot..."]],
  str_item_3661267 = "Retro Arcade Game",
  str_item_intro_3661267 = [[
Furniture item. Can be placed in rooms on your Colossus.
"If I'm going to stay aboard the Colossus, then I have to bring this along... Or else I won't survive."
When presented with such a request, the Navigator was more than willing to risk a few pulled muscles to accommodate his friend.]],
  str_item_3661268 = "Pixel Sunglasses Wall Decoration",
  str_item_intro_3661268 = [[
Furniture item. Can be placed in rooms on your Colossus.
"You've lost, Yingel. Leave the spoils behind."
A hard-earned prize obtained after defeating Yingel. It looks like some merchandise from a game.]],
  str_item_3661271 = "Doll Storage Box",
  str_item_intro_3661271 = "Furniture item. Can be placed in rooms on your Colossus.\nFor plushie collectors who tend to lose track of their belongings, this is quite possibly the greatest invention in the world.",
  str_item_3661272 = "Cat Paw Clock",
  str_item_intro_3661272 = [[
Furniture item. Can be placed in rooms on your Colossus.
A supremely adorable wall clock in the shape of a cat's paw. It's almost a shame to have to hang something so squishably soft on the wall.]],
  str_item_3661273 = "Freshman Podium",
  str_item_intro_3661273 = [[
Furniture item. Can be placed in rooms on your Colossus.
A certain rumor is currently spreading through Illumina: new students who shout out their dreams from a podium will go on to become respected heroes someday.]],
  str_item_3661274 = "Cast Iron Fireplace",
  str_item_intro_3661274 = [[
Furniture item. Can be placed in rooms on your Colossus.
A cast iron fireplace produced in the Illumina Federation. Aside from its respectable heating capabilities, its quaint appearance and warm flames bring an undeniable coziness to any room.]],
  str_item_3661275 = "Mat of Enlightenment",
  str_item_intro_3661275 = [[
Furniture item. Can be placed in rooms on your Colossus.
High-end bedding from Varaki Town. Comfortable and cozy, it has a distinctly classical air. Disciples of the True Order regard it as a bed of divine revelation.]],
  str_item_3661276 = "Mirror of Tomorrow",
  str_item_intro_3661276 = [[
Furniture item. Can be placed in rooms on your Colossus.
"Those who seek the truth shall peer into this ancient wooden mirror and behold visions of what is yet to come." Seriously, who comes up with this stuff...?]],
  str_item_3661277 = "Brave Soldier's Portrait",
  str_item_intro_3661277 = [[
Furniture item. Can be placed in rooms on your Colossus.
The overwhelming roar of the attacking Eclipsites drowned out even the signal of the bugle to charge. But when one heroic soldier hoisted the standard and advanced, thousands of others followed close behind.
"Dedicated to those fearless heroes who bravely gave their lives."]],
  str_item_3661278 = "Statue of the Doomsday Bell",
  str_item_intro_3661278 = "Furniture item. Can be placed in rooms on your Colossus.\nA repulsive, terrifying statue. Its malevolent appearance leads people to believe that it was created as an enemy of the world.\nIt's said that as it lumbered forward, the metal armor it wore clanged together dully — the sunset bell's spiteful requiem.",
  str_item_3661262 = "Ruins Guardian Model",
  str_item_intro_3661262 = [[
Furniture item. Can be placed in rooms on your Colossus.
A model crafted by Fleur, who is always thinking about the guardian of the ruins.
"It could probably be considered a type of mecha!"]],
  str_item_3661263 = "Alchemy Cauldron",
  str_item_intro_3661263 = [[
Furniture item. Can be placed in rooms on your Colossus.
With this, Ryza's Atelier on the Colossus can finally open for business!]],
  str_item_3661264 = "Adventure Afterimage",
  str_item_intro_3661264 = [[
Furniture item. Can be placed in rooms on your Colossus.
Let's reminisce about this summer once it's over!]],
  str_item_3661279 = "Summer Breeze Helm",
  str_item_intro_3661279 = [[
Furniture item. Can be placed in rooms on your Colossus.
With both hands placed upon it, one can almost feel the caress of the sea breeze, perfectly capturing the fresh essence of the summer ocean. An essential piece of furniture for any sailing enthusiast.]],
  str_item_3661280 = "Summer Breeze Swim Ring",
  str_item_intro_3661280 = [[
Furniture item. Can be placed in rooms on your Colossus.
Designed with a classic color scheme and sturdy structure, whether placed in the home or used at sea, it is always a delightful sight.]],
  str_item_3661281 = "Summer Breeze Banner",
  str_item_intro_3661281 = [[
Furniture item. Can be placed in rooms on your Colossus.
A simple yet elegant decorative banner, suitable for any space requiring a nautical touch.]],
  str_item_3661282 = "Seabird Keeper Conch",
  str_item_intro_3661282 = [[
Furniture item. Can be placed in rooms on your Colossus.
"Big conch, toot-toot-toot. Seagulls hear it and fall from the sky."
Not sure about the origin, but this song has been spreading on the Colossus.]],
  str_item_3661283 = "Breezy Bubble Blaster",
  str_item_intro_3661283 = [[
Furniture item. Can be placed in rooms on your Colossus.
A bubble gun fixed on a base, it seems to blow bubbles upon a single press.
"What a casual prop! Hopefully it won't put everyone to sleep."]],
  str_item_3661284 = "White Narcissus Portrait",
  str_item_intro_3661284 = [[
Furniture item. Can be placed in rooms on your Colossus.
Nikinis loves to grow narcissus flowers. She cares deeply for her plants and will toss anyone who tramples them into the Lake Mirror.]],
  str_item_3661285 = "Pure Lily Portrait",
  str_item_intro_3661285 = [[
Furniture item. Can be placed in rooms on your Colossus.
Nepolis enjoys growing lilies. She often harvests them to give as gifts, leaving only their sweet fragrance behind.]],
  str_item_3661286 = "Stellar Radiance",
  str_item_intro_3661286 = "Furniture item. Can be placed in rooms on your Colossus.\nMithra's painting—the fleeting smile of Achilles.\nUnyielding star, may you and your companions shine bright again.",
  str_item_3661287 = "Dual Blades",
  str_item_intro_3661287 = [[
Furniture item. Can be placed in rooms on your Colossus.
Replicas of the weapons used by the Silent Hunter's captain and vice-captain.
Behold! This is the pinnacle of pioneering and the determination to guard! That's what the Silent Hunters are all about.]],
  str_item_3661288 = "Predator Stand",
  str_item_intro_3661288 = [[
Furniture item. Can be placed in rooms on your Colossus.
A perch Mithra set up for the predator.
They might look chill up there, but those claws are no joke.]],
  str_item_3661289 = "Starbound Unity",
  str_item_intro_3661289 = [[
Furniture item. Can be placed in rooms on your Colossus.
An old piece that has been restored.
If the stars that streak across the sky could one day find where they belong in the gentleness of time...
May you receive belated happiness.]],
  str_item_3661290 = "Moonlit Melody",
  str_item_intro_3661290 = [[
Furniture item. Can be placed in rooms on your Colossus.
A melody by Ludweiss, a Caelestite.
It's pure and graceful like moonlight, with a hint of unshakable sorrow. May you receive belated happiness.]],
