  str_item_9998074 = "Blaster",
  str_item_9998075 = "Dazzling Caltrops",
  str_item_9998076 = "Absorbent Paint",
  str_item_intro_9998002 = "At the start of each round, randomly inflicts 1 stack of Poison, Bleeding, or Burning on all enemies on the field; the effect is repeated 4 times. Reduces damage dealt by Aurorians by 15%.",
  str_item_intro_9998003 = "All damage taken by enemies who are debuffed or under debuff effects increases by 20%.",
  str_item_intro_9998004 = "When removing tiles, randomly inflicts 1 stack of Poison, Bleeding, or Burning on the enemies within range of the removed tiles; the effect is repeated 5 times.",
  str_item_intro_9998005 = "When a Poisoned/Burning/Bleeding enemy is defeated, inflicts 1 stack of Poison, Bleeding, and Burning on all remaining enemies on the field.",
  str_item_intro_9998006 = "Increases the damage received by enemies from Poison, Bleeding, or Burning by 100%.",
  str_item_intro_9998007 = "When successfully inflicting Poison, Burning, or Bleeding on enemies, the target immediately loses 1% of their current HP.",
  str_item_intro_9998008 = "Grants the Special Caelestite Gear: Consumes 2 rounds to cast a Lv.2 faction support skill once instantly. Can only be used once each round.",
  str_item_intro_9998009 = "The closer to the enemy, the higher the damage of Aurorians' Chain Combo, with a maximum increase of 30%.",
  str_item_intro_9998010 = "Grants Detonator Aurorians a 30% chance to cast an additional Chain Combo; for each tile removed this round, the trigger chance increases by 1%.",
  str_item_intro_9998011 = "The Captain fights based on their own element only, dealing 100% more damage.",
  str_item_intro_9998012 = "When the team leader casts a Chain Combo, generates a shadow at the position about to be removed, and releases a Chain Combo at the same time.",
  str_item_intro_9998013 = "After the next victory, grants 2 additional chances to select Enlightenment Gear in the next battle, effective once.",
  str_item_intro_9998014 = "Grants a chance to reshuffle when selecting Enlightenment Gear, available for use 8 times.",
  str_item_intro_9998015 = "Removes the initial Special Caelestite Gear and immediately grants 2 chances for Enlightenment Gear selection.",
  str_item_intro_9998016 = "When an Aurorian attacks 3 or more enemies with an Active Skill at the same time, casts a thunderbolt that attacks all enemies, dealing damage equal to 200% of the team's average ATK.",
  str_item_intro_9998017 = "After changing the Captain, the new Captain's Active Skill cooldown is reduced by 1 round. The same Aurorian can trigger it a maximum of once per round.",
  str_item_intro_9998018 = "Makes the team invincible for 1 round when the team's HP drops to 1%, then restores 20% of the Max HP. This effect can only be triggered once every battle, up to a total of 2 times.",
  str_item_intro_9998019 = "Restores 35% of the team's lost HP after winning a battle.",
  str_item_intro_9998020 = "Reloads a bandage on the field at the beginning of the battle.",
  str_item_intro_9998021 = "Increases Aurorians' damage by 15% when the team's current HP is higher than 90%.",
  str_item_intro_9998022 = "Grants a shield equal to 40% of Max HP that lasts for 2 rounds at the start of each wave.",
  str_item_intro_9998023 = "Restores HP to 50% at the beginning of the battle if current HP is lower than 50%.",
  str_item_intro_9998024 = "Supporter Aurorians +40% regeneration effects from Chain Combos and Active Skills in battle.",
  str_item_intro_9998025 = "For each primary element of Aurorians in the team, increases the damage dealt by Aurorians by 6%, with a maximum increase of 24%.",
  str_item_intro_9998026 = "When Aurorians deal damage, ignores the damage reduction effect of having their element countered. When taking damage, ignores the bonus of having their element countered.",
  str_item_intro_9998027 = "Aurorian's secondary element deals damage with the same multiplier as their primary element.",
  str_item_intro_9998028 = "Enables Bonded Aurorians to ignore the elements of tiles to be removed when casting the Chain Combo.",
  str_item_intro_9998029 = "For each set of Bonded Aurorians, restores 5% of the team's Max HP at the start of each round.",
  str_item_intro_9998030 = "For each set of Bonded Aurorians, there is a 40% chance to gain 1 additional charge for Special Caelestite Gear when removing tiles. Triggered independently when there are multiple sets of Bonds.",
  str_item_intro_9998031 = "Bonded Aurorians inherit 20% of each other's Basic ATK.",
  str_item_intro_9998032 = "When an Aurorian casts an Active Skill, reduces the cooldown of their bonded Aurorians' Active Skills by 1 round. Can be triggered up to 5 times per battle.",
  str_item_intro_9998033 = "Reduces the cooldown of the 1st Active Skill cast in each battle by 2 rounds immediately after it's cast.",
  str_item_intro_9998034 = "After tapping to remove tiles, if Aurorians have not cast the Chain Combo in this round, reduces the cooldown of all Aurorian's Active Skill by 1.",
  str_item_intro_9998035 = "The farther Aurorians are from an enemy, the higher the damage of their Chain Combo, with a maximum increase of 50%.",
  str_item_intro_9998036 = "Increases the number of targets of Sniper Aurorians' Chain Combo by 2.",
  str_item_intro_9998037 = "Aurorians gain 3% Life Drain when dealing damage and lose 10% of their current HP at the start of each round.",
  str_item_intro_9998038 = "The lower the current HP, the higher the damage of Aurorian's Chain Combo, with a maximum increase of 50%.",
  str_item_intro_9998039 = "All allies and enemies lose 7% of their current HP at the start of each round.",
  str_item_intro_9998040 = "When Aurorian's current HP is at 50%, increases the damage dealt by the Aurorian by 30%; for each 1% of HP difference, this boost decreases by 5%.",
  str_item_intro_9998041 = "Lose 7% of current HP at the beginning of each round. After that, deals damage equal to 150% of the team's average ATK to enemies within 2 surrounding clusters.",
  str_item_intro_9998042 = "At the beginning of the battle, loses 70% of its current HP and deals damage to all enemies equal to 300% of this loss.",
  str_item_intro_9998043 = "Increases Aurorians' Active Skill damage by 80%. Lose 8% of current HP each time an Active Skill is cast.",
  str_item_intro_9998044 = "Ignores the number of tiles tapped and removed and enables Aurorians to cast their highest-level Chain Combo each time after the removal.",
  str_item_intro_9998045 = "At the beginning of the battle, gains 1 usage chance for all the Special Caelestite Gear.",
  str_item_intro_9998046 = "Each usage of the Special Caelestite Gear triggers a Lv.1 faction Support skill once; effective 2 times per battle.",
  str_item_intro_9998047 = "Expands the effective range of the initial Special Caelestite Gear to 5×5; gains 1 usage chance after accumulating 40 energy points.",
  str_item_intro_9998048 = "Increases the recharge efficiency of the Special Caelestite Gear's usage chance by 50%.",
  str_item_intro_9998049 = "Defeats enemies under 9% HP.",
  str_item_intro_9998050 = "Increases the damage dealt by Aurorians by 20%; doubles the round consumption.",
  str_item_intro_9998051 = "Reduces the DEF of all Aurorians in the team to zero and turns 50% of their Basic DEF into ATK.",
  str_item_intro_9998052 = "Increases the Max HP of all Aurorians by 2% for each piece of Enlightenment Gear owned.",
  str_item_intro_9998053 = "Increases the DEF of all Aurorians by 1.5% for each piece of Enlightenment Gear owned.",
  str_item_intro_9998054 = "Increases the ATK of all Aurorians by 1% for each piece of Enlightenment Gear owned.",
  str_item_intro_9998055 = "A Damage Boost Trap spawns randomly on the battlefield at the start of each round. After destroying this trap, Chain Combo damage is increased by 35% in this round.",
  str_item_intro_9998056 = "At the start of each wave, an Energy Candy Jar randomly spawns on the battlefield, which grants 1 usage chance for a random Special Caelestite Gear upon destruction.",
  str_item_intro_9998057 = "Increases the number of all removable items on the battlefield to 2 upon spawning.",
  str_item_intro_9998058 = "At the start of each wave, a Mobile Energizer randomly spawns on the battlefield, which grants 3 extra rounds upon removal.",
  str_item_intro_9998059 = "At the start of each round, shatters the tile beneath, increasing damage dealt by Aurorians by 15%.",
  str_item_intro_9998060 = "Reset the effectiveness count of all Enlightenment Gear to their initial state.",
  str_item_intro_9998061 = "Grants the Special Caelestite Gear: Converts all tiles on the field to chromatic tiles. Comes with 2 usage chances upon acquisition.",
  str_item_intro_9998062 = "Increases Chain Combo damage to enemies within range of the removed tiles by 35%.",
  str_item_intro_9998063 = "When tapping to remove tiles, deals damage equal to 150% of the team's average ATK to the enemies within range of the removed tiles.",
  str_item_intro_9998064 = "When tapping to remove tiles, grants a shield equal to 0.5% of Max HP for each tile removed, lasting for 1 round.",
  str_item_intro_9998065 = "When removing at least 15 tiles at once with a tap, increases Aurorians' Chain Combo damage by 30%. The Chain Combo can't be cast if less than 7 tiles are removed at once.",
  str_item_intro_9998066 = "Increases the Basic ATK of the Aurorian with the lowest ATK in the team by 60%.",
  str_item_intro_9998067 = "Reduces the number of tiles needed to trigger faction support skills: reduces 5 for Lv.1 faction support skills; reduces 10 for Lv.2 faction support skills.",
  str_item_intro_9998068 = "Enables faction support skills to knock enemies back by 1 tile.",
  str_item_intro_9998069 = "At the start of each round, for each Aurorian in the team belonging to the same faction as the faction support skill, all Special Caelestite Gear gains 3 charges.",
  str_item_intro_9998070 = "Grants the Life Drain effect to faction support skills; for each Aurorian of that faction in the team, grants an extra 5% of Life Drain.",
  str_item_intro_9998071 = "When tapping to remove tiles, each tile removed increases the final damage of the faction support skill by 5% for the current round.",
  str_item_intro_9998072 = "For each Aurorian in the team belonging to the same faction as the faction support skill, increases the final damage of the faction support skill by 25%.",
  str_item_intro_9998073 = "For each Aurorian in the team belonging to the same faction as the faction support skill, increases the Basic DEF and Max HP of all Aurorians by 3%.",
  str_item_intro_9998074 = "Increases the damage of Aurorians' Active Skills by 100%; only the Ascension I of Chain Combo can be cast.",
  str_item_intro_9998075 = "At the start of each round, converts 1 tile beneath 2 random enemies on the field to chromatic.",
  str_item_intro_9998076 = "When an enemy is eliminated, converts 1 tile beneath it to the same element as the Captain.",
  str_item_4090264 = "Bewitching Night Spell",
  str_item_intro_4090264 = [[
Navigator, I don't wanna be an Aurorian anymore.
Unable to bear the void, Uriel wishes to change her form of existence with a magical potion. Yet, the concoction leads not to the expected change, but to a whimsical tipsy. Gone is her customary despondency and aloofness, replaced by a newfound zestful spirit, craving thrilling adventures with you. How will you navigate through this unexpected turn of events?]],
  str_item_3400132 = "Linked Minds, Ribbit",
  str_item_intro_3400132 = [[
Unlocks the background: Linked Minds, Ribbit
The frog's remarkable ability lies in its conscious connection to all things, and through this gift, the frog takes on the vital duty of healing its companions...]],
