  str_item_intro_9011001 = "At the start of the round, deals 4,444 fixed damage to all enemies and eliminates those with less than 6% HP.",
  str_item_intro_9011002 = "Generates chromatic tiles in the surrounding area each round, with the quantity equal to the number of Primary Element types of Aurorians in the team. The skill is executed 2 times more at the beginning of the battle.",
  str_item_intro_9011003 = "Converts all tiles to chromatic on the third round of battle. After the tile connection ends, all chromatic tiles will be cleared.",
  str_item_intro_9011004 = "Increases the damage dealt by Aurorians with HP equal to their maximum by 15%.",
  str_item_intro_9011005 = "After completing the Dream Devourer stage, gains interest equivalent to 30% of your current Dream Coin holdings.",
  str_item_intro_9011006 = "One-time use: Gains 2 Dream Bombs.",
  str_item_intro_9011007 = "The more Dream Coins you possess, the higher damage your normal attacks deal.",
  str_item_intro_9011008 = "The first tile in a line may have a different color from the subsequent ones, allowing both types of Aurorians to join the battle.",
  str_item_intro_9011009 = "Randomizes all unequipped Dream Orbs into new ones (with no lower level than the original) and each Dream Orb has a 30% chance to increase in rating.",
  str_item_intro_9011010 = "When the color of the tiles connected matches the Captain's element, the Dream Orb gains 1 charge for every 2 connected tiles.",
  str_item_intro_9011011 = "When Dream Orb skills deal damage, perform two random calculations within a range and choose the higher value as the damage dealt, widening the damage fluctuation range by 10%.",
  str_item_intro_9011012 = "Defaults the rating of the subsequently obtained Dream Orbs to 1-star.",
  str_item_intro_9011013 = "When selecting a Dream Divination Card, decreases the available choices by 1 but doubles the reward effects from cards.",
  str_item_intro_9011014 = "Decreases the Max HP of all Aurorians by 20% after entering combat but increases the number of selectable Dream Divination Card by +1 during actions.",
  str_item_intro_9011015 = "Before connecting tiles, whenever an Aurorian moves, deals damage to a diamond-shaped area at the landing spot, averaging 150% of their ATK. Moreover, the Dream Orb gains 1 charge for each circle of movement.",
  str_item_intro_9011016 = "When Converter and Supporter Aurorians' Chain Combos deal damage, randomly inflicts one stack of Poisoned, Bleeding, or Burning on the target.",
  str_item_intro_9011017 = "When dealing damage to Poisoned, Bleeding, or Burning enemies, increases the damage for each effect.",
  str_item_intro_9011018 = "After inflicting one stack of Poisoned, Bleeding, or Burning on the target, there is a chance to apply another stack of random debuff. This effect can trigger repeatedly, with the probability halved each time.",
  str_item_intro_9011019 = "When an enemy dies, randomly applies one stack of Poisoned, Bleeding, or Burning to all enemies.",
  str_item_intro_9011020 = "When launching normal attacks, the Captain deals additional Fire damage equal to 50% of the team's overall ATK.",
  str_item_intro_9011021 = "When launching normal attacks, the Captain deals additional Thunder damage equal to 50% of the team's overall ATK.",
  str_item_intro_9011022 = "When launching normal attacks, the Captain deals additional Forest damage equal to 50% of the team's overall ATK.",
  str_item_intro_9011023 = "When launching normal attacks, the Captain deals additional Water damage equal to 50% of the team's overall ATK.",
  str_item_intro_9011024 = "At the start of each round, converts the nearest 3 red tiles into chromatic tiles.",
  str_item_intro_9011025 = "At the start of each round, converts the nearest 3 yellow tiles into chromatic tiles.",
  str_item_intro_9011026 = "At the start of each round, converts the nearest 3 green tiles into chromatic tiles.",
  str_item_intro_9011027 = "At the start of each round, converts the nearest 3 blue tiles into chromatic tiles.",
  str_item_intro_9011028 = "At the start of each round, converts up to 1 tile under each enemy into chromatic.",
  str_item_intro_9011029 = "When taking damage, converts 3 tiles within 2 surrounding clusters into chromatic.",
  str_item_intro_9011030 = "At the start of each round, Aurorians with lower HP recover in proportion to their lost HP.",
  str_item_intro_9011031 = "Upon victory in battle, all Aurorians restore 20% of their HP.",
  str_item_intro_9011032 = "If there are Dark Tiles obtained in the current round, gains 1 stack of Battle Spirit.",
  str_item_intro_9011033 = "Supporter Aurorians gain 1 stack of Battle Spirit when casting Active Skills or Chain Combos to heal the team.",
  str_item_intro_9011034 = "When Aurorians' Active Skills knock back or pull over enemies, gain Battle Spirit stacks based on the number of affected targets. This effect can be triggered up to 3 times per round.",
  str_item_intro_9011035 = "Gains 1 stack of Battle Spirit whenever monsters are inflicted with Poisoned, Bleeding, or Burning. This effect can be triggered up to 4 times per round.",
  str_item_intro_9011036 = "Gains Dream Coins equal to 4 times the level whenever Dream Level increases.",
  str_item_intro_9011037 = "Gains Dream Coins equal to 7 times the increment whenever the Dream Interest increases.",
  str_item_intro_9011038 = "Gains 4 Dream Coins for each Eclipsite defeated in battle.",
  str_item_intro_9011039 = "One-time use: Draws 5 Dream Divination Cards from your deck and obtains Dream Interest equal to the sum of their steps.",
  str_item_intro_9011040 = "Obtains two rewards simultaneously in the Treasure Dream Realm.",
  str_item_intro_9011041 = "Gains 30 Dream EXP every time traversing a Dangerous Dream Realm.",
  str_item_intro_9011042 = "Decreases the prices of purchasable items and reduces the cost of re-randomizing Dream Gear, Aurorians, and items by 35%.",
  str_item_intro_9011043 = "Upon acquisition, Aurorians dispatched in the Unexplored Dream Realms return immediately, and the yielding of Dream Coins and Dream Interest from the dispatch are doubled.",
  str_item_intro_9011044 = "Gains 40 Dream EXP every time passing through a camp.",
  str_item_intro_9011045 = "One-time use: All Aurorians lose 70% of their current HP; gains 25 Dream EXP for each Aurorian losing HP.",
  str_item_intro_9011046 = "One-time use: Consumes half of the current Dream Coins and gains 2 Dream EXP for each Dream Coin consumed.",
  str_item_intro_9011047 = "Significantly increases the damage of Aurorians' Active Skills; Aurorians lose HP when dealing damage.",
  str_item_9011048 = "Blaster",
  str_item_9011049 = "Stomper",
  str_item_9011050 = "Kingslayer",
  str_item_9011051 = "Wallbreaker",
  str_item_9011052 = "Paralyzer",
  str_item_9011053 = "Thunderstriker",
  str_item_intro_9011048 = "Activates the <link=\"1005\"><color=#98500f><u>Algorithm Upgrade Module</u></color></link>; the fewer enemies on the field, the higher the final damage.",
  str_item_intro_9011049 = "Activates the <link=\"1005\"><color=#98500f><u>Algorithm Upgrade Module</u></color></link>; The Captain gains 3 <link=\"1006\"><color=#98500f><u>Overload Points</u></color></link> when launching a normal attack.",
  str_item_intro_9011050 = "Activates the <link=\"1005\"><color=#98500f><u>Algorithm Upgrade Module</u></color></link>; Aurorians' Active Skill: generates 4 <link=\"1006\"><color=#98500f><u>Overload Points</u></color></link> for each enemy hit.",
  str_item_intro_9011051 = "Activates the <link=\"1005\"><color=#98500f><u>Algorithm Upgrade Module</u></color></link>; at the start of the round, the lower the team's HP, the more <link=\"1006\"><color=#98500f><u>Overload Points</u></color></link> are gained.",
  str_item_intro_9011052 = "Activates the <link=\"1005\"><color=#98500f><u>Algorithm Upgrade Module</u></color></link>; gains 8 <link=\"1006\"><color=#98500f><u>Overload Points</u></color></link> every time taking damage.",
  str_item_intro_9011053 = "Activates the <link=\"1005\"><color=#98500f><u>Algorithm Upgrade Module</u></color></link>; increases the trigger threshold of Data Bomb to 120 <link=\"1006\"><color=#98500f><u>Overload Points</u></color></link>, dealing more damage to large-sized monsters.",
  str_item_intro_9011054 = "No longer enters the Aurora Time; instead, gains +1ms value each time when it's supposed to enter Aurora Time, and receives 5 Gold (the Aurora Time disrupted by monster waves or battle victory also counts).",
  str_item_intro_9011055 = "When an enemy dies, converts up to 1 tile beneath it into a Dark Tile.",
  str_item_intro_9011056 = "At the start of the round, converts the 2 nearest tiles of the same element as the Captain's into Dark Tiles.",
  str_item_intro_9011057 = "Increases the number of options provided during Dream Gear selection by 1.",
  str_item_intro_9011058 = "The first refresh of Dream Gear options is free.",
  str_item_intro_9011059 = "For each piece of Dream Gear owned, increases the ATK of Detonator and Sniper Aurorians by 0.5%",
  str_item_intro_9011060 = "For each piece of Dream Gear owned, increases the DEF of Converter and Supporter Aurorians by 2%.",
  str_item_intro_9011061 = "For each piece of Dream Gear owned, increases the Max HP of all Aurorians by 1.5%.",
  str_item_intro_9011062 = "At the start of each round, generates 1 clock (up to 1 can exist at a time), reducing the cooldown rounds of the Aurorian's skill with the highest cooldown by 1.",
  str_item_intro_9011063 = "Inflicts <link=\"1010\"><color=#98500f><u>Blinded</u></color></link> on targets that receive damage.",
  str_item_intro_9011064 = "Every time taking damage, all Aurorians gain a 5% damage bonus, up to a maximum of 30% (resets at the end of the battle).",
  str_item_intro_9011065 = "Increases the damage of normal attacks by 30%. This effect expires after taking damage.",
  str_item_intro_9011066 = "Halves the DEF of all Aurorians and increases their own ATK by the amount of DEF reduced.",
  str_item_intro_9011067 = "Generates an image of Captain Aurorian at the starting spot. This image also unleashes Chain Combos in this round.",
  str_item_intro_9011068 = "Increases damage by 3.5% for each Aurorian with different Primary Elements in the team.",
  str_item_intro_9011069 = "Secondary Elements can deal damage based on the multiplier of Primary Elements, with an additional increase in the multiplier when the primary and secondary elements are the same.",
  str_item_intro_9011070 = "The previous Captain can be deployed in battle regardless of the elements of the tiles connected.",
  str_item_intro_9011071 = [[
Captain changes chances +2 in each battle.
When switching Captains, the Active Skill cooldown of the new Captain is reduced by 1. Each Aurorian can only trigger this effect once every round.]],
  str_item_intro_9011072 = "After each tile connection or movement, the starting tile must be of the same element as the Captain's.",
  str_item_intro_9011073 = "Increases the damage dealt by all allies by 15% but converts the starting tile of each line connected into a broken tile that cannot be traversed for 8 rounds.",
  str_item_intro_9011074 = "When Aurorians' Active Skills knock back or pull over an enemy, deal 3,000 fixed damage for each tile the target traverses.",
  str_item_intro_9011075 = "All Aurorians' Breakthrough Levels +1 (Does not apply to Aurorians whose Breakthrough Level has reached the maximum).",
  str_item_intro_9011076 = "One-time use: Selects any Aurorian to join the team; raises this Aurorian's Breakthrough Level to its maximum.",
  str_item_intro_9011077 = "Detonator Aurorians inflict 1 stack of <link=\"1003\"><color=#98500f><u>Meltdown</u></color></link> on the target hit by their Chain Combos.",
  str_item_intro_9011078 = "Detonator Aurorians' Active Skills have a 40% chance to inflict <link=\"1011\"><color=#98500f><u>Paralyzed</u></color></link> on the target.",
  str_item_intro_9011079 = "Expands the range of Detonator Aurorians' highest-level Chain Combos to 2 clusters.",
  str_item_intro_9011080 = "Detonator Aurorians' normal attacks deal extra DEF-ignoring damage and additionally inflict damage equal to 10% of the Aurorian's lost HP on the target.",
  str_item_intro_9011081 = "Detonator Aurorians' normal attacks have a 30% chance to deal 150% damage.",
  str_item_intro_9011082 = "For each Detonator Aurorian deployed, increases the damage dealt by all Detonator Aurorians' Chain Combos by 4%.",
  str_item_intro_9011083 = "Normal attacks of Sniper Aurorians inflict <link=\"1004\"><color=#98500f><u>Wisdom</u></color></link> equal to 20% of their ATK on targets.",
  str_item_intro_9011084 = "Increases the damage dealt by Chain Combos of Sniper Aurorians to monsters occupying multiple tiles.",
  str_item_intro_9011085 = "Expands the range of Sniper Aurorians' single-target Chain Combos by 2 clusters and increases the number of targets by 1.",
  str_item_intro_9011086 = "Increases the damage of Sniper Aurorians' Chain Combos based on their HP lost, with a maximum increase of 50%.",
  str_item_intro_9011087 = "Active Skills of Sniper Aurorians have a 30% chance to inflict <link=\"1012\"><color=#98500f><u>Frightened</u></color></link> on targets.",
  str_item_intro_9011088 = "For each Sniper Aurorian deployed, increases the damage dealt by all Sniper Aurorians' normal attacks by 5%.",
