  str_item_intro_8800103 = "Dew taken from the summit of cedar peaks, so pure it seems to cleanse one's spirit.",
  str_item_intro_8800102 = "A flower that blooms in the cold, exuding a faint, delicate fragrance.",
  str_item_intro_8800101 = "Ubiquitous ice chunks that produce cold when gathered in large numbers.",
  str_item_intro_8800203 = "Spicy and advanced grease that embodies the passion and vigor of Rediesel.",
  str_item_intro_8800202 = "Stones with molten oil coursing over their surfaces.",
  str_item_intro_8800201 = "Rough orange grains of sand, still warm from the desert.",
  str_item_intro_8800303 = "A lush branch, coursing with astonishing vitality.",
  str_item_intro_8800302 = "Soft, airy fluff that spreads seeds of hope with the wind.",
  str_item_intro_8800301 = "Plain green seeds, waiting to sprout.",
  str_item_intro_8800403 = "A precious, rare crystal, glowing with the brilliance of dawn.",
  str_item_intro_8800402 = "A yellow gem, crackling with thunder's power.",
  str_item_intro_8800401 = "An inconspicuous ore, somewhat denser than usual rocks.",
  str_item_intro_8800113 = "Nutritive essence that invigorates both plants and animals.",
  str_item_intro_8800213 = "Tender and sweet, each mouthful is a delight.",
  str_item_intro_8800313 = "A charming Windelion Doll with both visual appeal and tactile pleasure, with the potential to be a popular gift.",
  str_item_intro_8800413 = "A crystal orb emitting a captivating glow, ideal for home decor.",
  str_item_intro_8800112 = "A fast-acting ointment for sprains and bruises. It's a must-have for home and travel.",
  str_item_intro_8800212 = "It minimizes friction and smoothens surfaces, suitable for multiple uses.",
  str_item_intro_8800312 = "A vibrant, eco-friendly potted plant that thrives in sunny places.",
  str_item_intro_8800412 = "An incredibly sharp knife. It cuts everything with ease, preferred by craftsmen.",
  str_item_intro_8800111 = "It's suitable for cooling items and also safe to drink.",
  str_item_intro_8800211 = "High-powered explosive that must be handled with caution.",
  str_item_intro_8800311 = "Durable and plain hemp cloth, suitable for many purposes.",
  str_item_intro_8800411 = "A modest ornament that exudes subtle charm.",
  str_item_intro_8800123 = "A recipe detailing the requirements to craft the Nutrient Supplement.",
  str_item_intro_8800223 = "A recipe detailing the requirements to craft the Yummy Cake.",
  str_item_intro_8800323 = "A recipe detailing the requirements to craft the Ornate Windelion Doll.",
  str_item_intro_8800423 = "A recipe detailing the requirements to craft the Crystal Bauble.",
  str_item_intro_8800122 = "A recipe detailing the requirements to craft the External Ointment.",
  str_item_intro_8800222 = "A recipe detailing the requirements to craft the Lubricant Elixir.",
  str_item_intro_8800322 = "A recipe detailing the requirements to craft the Water-Retaining Plant.",
  str_item_intro_8800422 = "A recipe detailing the requirements to craft the Razor-Edged Knife.",
  str_item_intro_8800121 = "A recipe detailing the requirements to craft the Cooling Water.",
  str_item_intro_8800221 = "A recipe detailing the requirements to craft the Dynamite Block.",
  str_item_intro_8800321 = "A recipe detailing the requirements to craft the Burlap Strip.",
  str_item_intro_8800421 = "A recipe detailing the requirements to craft the Copper Pendant.",
  str_item_8800005 = "Ancient Fragment",
  str_item_intro_8800005 = "Originally part of a ruin, this stone fragment is marked by the passage of time.",
  str_item_8800006 = "Exploration Carrier",
  str_item_intro_8800006 = "Carrier designed for alchemy material exploration, with 2 units replenished daily at 05:00 of the server time.",
  str_item_8800008 = "Atelier Fund",
  str_item_intro_8800008 = "Profits from the Mini Atelier. With Klaudia's help, this store will surely make a name in Astra!",
  str_item_8800010 = "SP",
